fn parse_args(args: &[String]) -> Result<LayerTracePlanArgs> {
    if args.get(1).map(String::as_str) != Some("bitnet-reference-layer-trace-plan") {
        bail!("parse_args called for unexpected command");
    }

    let mut cpp_root = PathBuf::from(DEFAULT_CPP_ROOT);
    let mut rust_transformer = PathBuf::from(DEFAULT_RUST_TRANSFORMER);
    let mut output = Some(PathBuf::from(DEFAULT_OUTPUT));
    let mut format = "human".to_string();
    let mut i = 2usize;
    while i < args.len() {
        let key = args[i].as_str();
        i += 1;
        let mut value = || -> Result<String> {
            let value = args.get(i).with_context(|| format!("{key} requires a value"))?.clone();
            i += 1;
            Ok(value)
        };
        match key {
            "--cpp-root" => cpp_root = PathBuf::from(value()?),
            "--rust-transformer" => rust_transformer = PathBuf::from(value()?),
            "--output" => output = Some(PathBuf::from(value()?)),
            "--format" => format = value()?,
            other => bail!("unknown bitnet-reference-layer-trace-plan option {other}"),
        }
    }

    Ok(LayerTracePlanArgs { cpp_root, rust_transformer, output, format })
}

fn parse_run_args(args: &[String]) -> Result<LayerTraceRunArgs> {
    if args.get(1).map(String::as_str) != Some("bitnet-reference-layer-trace-run") {
        bail!("parse_run_args called for unexpected command");
    }
    let mut reference_root = PathBuf::from(DEFAULT_REFERENCE_ROOT);
    let mut cpp_root = PathBuf::from(DEFAULT_CPP_ROOT);
    let mut patch = PathBuf::from(DEFAULT_PATCH);
    let mut plan = PathBuf::from(DEFAULT_REFERENCE_PLAN);
    let mut sidecar = PathBuf::from(DEFAULT_SIDECAR);
    let mut trace_layer = None::<usize>;
    let mut first_values_limit = None::<usize>;
    let mut rope_scalar_trace = None::<PathBuf>;
    let mut rope_scalar_layer = None::<usize>;
    let mut rope_scalar_kv_head = None::<usize>;
    let mut rope_scalar_token = None::<usize>;
    let mut rope_scalar_dim = None::<usize>;
    let mut output = Some(PathBuf::from(DEFAULT_RUN_OUTPUT));
    let mut format = "human".to_string();
    let mut i = 2usize;
    while i < args.len() {
        let key = args[i].as_str();
        i += 1;
        let mut value = || -> Result<String> {
            let value = args.get(i).with_context(|| format!("{key} requires a value"))?.clone();
            i += 1;
            Ok(value)
        };
        match key {
            "--reference-root" => reference_root = PathBuf::from(value()?),
            "--cpp-root" => cpp_root = PathBuf::from(value()?),
            "--patch" => patch = PathBuf::from(value()?),
            "--plan" => plan = PathBuf::from(value()?),
            "--sidecar" => sidecar = PathBuf::from(value()?),
            "--trace-layer" => {
                trace_layer = Some(value()?.parse().context("--trace-layer must be an integer")?)
            }
            "--first-values-limit" => {
                first_values_limit =
                    Some(value()?.parse().context("--first-values-limit must be an integer")?)
            }
            "--rope-scalar-trace" => rope_scalar_trace = Some(PathBuf::from(value()?)),
            "--rope-scalar-layer" => {
                rope_scalar_layer =
                    Some(value()?.parse().context("--rope-scalar-layer must be an integer")?)
            }
            "--rope-scalar-kv-head" => {
                rope_scalar_kv_head =
                    Some(value()?.parse().context("--rope-scalar-kv-head must be an integer")?)
            }
            "--rope-scalar-token" => {
                rope_scalar_token =
                    Some(value()?.parse().context("--rope-scalar-token must be an integer")?)
            }
            "--rope-scalar-dim" => {
                rope_scalar_dim =
                    Some(value()?.parse().context("--rope-scalar-dim must be an integer")?)
            }
            "--output" => output = Some(PathBuf::from(value()?)),
            "--format" => format = value()?,
            other => bail!("unknown bitnet-reference-layer-trace-run option {other}"),
        }
    }
    let rope_scalar_trace = match (
        rope_scalar_trace,
        rope_scalar_layer,
        rope_scalar_kv_head,
        rope_scalar_token,
        rope_scalar_dim,
    ) {
        (None, None, None, None, None) => None,
        (Some(path), Some(layer), Some(kv_head), Some(token), Some(dim)) => {
            Some(ReferenceRopeScalarTraceArgs { path, layer, kv_head, token, dim })
        }
        _ => bail!(
            "--rope-scalar-trace requires --rope-scalar-layer, --rope-scalar-kv-head, --rope-scalar-token, and --rope-scalar-dim"
        ),
    };
    Ok(LayerTraceRunArgs {
        reference_root,
        cpp_root,
        patch,
        plan,
        sidecar,
        trace_layer,
        first_values_limit,
        rope_scalar_trace,
        output,
        format,
    })
}

