fn attention_norm_f64_selected_historical_k_rope_source_frontier(
    selected_key_bucket_source_frontier: &Value,
) -> Value {
    let source_classification =
        selected_key_bucket_source_frontier.pointer("/classification").and_then(Value::as_str);
    let historical_row = selected_key_bucket_source_frontier
        .pointer("/first_historical_source_row")
        .unwrap_or(&Value::Null);
    let historical_classification =
        historical_row.pointer("/classification").and_then(Value::as_str);
    let probe = historical_row.pointer("/post_rope_epsilon_probe").unwrap_or(&Value::Null);
    let post_rope_bucket =
        probe.pointer("/post_rope_bucket/f16_bucket_match").and_then(Value::as_bool);
    let projection_bucket =
        probe.pointer("/projection_bucket/f16_bucket_match").and_then(Value::as_bool);
    let paired_projection_bucket =
        probe.pointer("/paired_projection_bucket/f16_bucket_match").and_then(Value::as_bool);
    let replay_bucket = probe.pointer("/replay_bucket/f16_bucket_match").and_then(Value::as_bool);
    let capture_delta = probe.pointer("/post_rope/capture_delta").and_then(Value::as_f64);
    let runtime_replay_delta =
        probe.pointer("/post_rope/runtime_replay_delta").and_then(Value::as_f64);
    let reference_replay_minus_capture =
        probe.pointer("/post_rope/reference_replay_minus_capture").and_then(Value::as_f64);
    let rust_replay_minus_capture =
        probe.pointer("/post_rope/rust_replay_minus_capture").and_then(Value::as_f64);
    let projection_buckets_stable =
        projection_bucket == Some(true) && paired_projection_bucket == Some(true);
    let replay_bucket_stable = replay_bucket == Some(true);
    let tiny_capture_delta = capture_delta.is_some_and(|delta| delta.abs() <= 1.0e-6);
    let runtime_replay_clean = runtime_replay_delta.is_some_and(|delta| delta.abs() <= 1.0e-12);
    let rust_replay_capture_clean =
        rust_replay_minus_capture.is_some_and(|delta| delta.abs() <= 1.0e-12);
    let reference_replay_capture_delta_present =
        reference_replay_minus_capture.is_some_and(|delta| delta.abs() > 0.0);

    let classification = if source_classification
        != Some("f64_selected_key_bucket_source_projection_rope_boundary")
    {
        "f64_selected_historical_k_rope_source_no_projection_rope_boundary"
    } else if historical_row.is_null() || probe.is_null() {
        "f64_selected_historical_k_rope_source_missing_probe"
    } else if historical_classification == Some("selected_key_historical_reference_rope_delta")
        && projection_buckets_stable
        && replay_bucket_stable
        && post_rope_bucket == Some(false)
        && tiny_capture_delta
        && runtime_replay_clean
        && rust_replay_capture_clean
        && reference_replay_capture_delta_present
    {
        "f64_selected_historical_k_rope_source_reference_capture_midpoint"
    } else if !projection_buckets_stable {
        "f64_selected_historical_k_rope_source_projection_bucket_crossing"
    } else if !replay_bucket_stable {
        "f64_selected_historical_k_rope_source_runtime_replay_bucket_crossing"
    } else if post_rope_bucket == Some(false) {
        "f64_selected_historical_k_rope_source_post_rope_bucket_crossing"
    } else if historical_classification
        == Some("selected_key_historical_projection_rope_source_clean")
    {
        "f64_selected_historical_k_rope_source_clean"
    } else {
        "f64_selected_historical_k_rope_source_unpinned"
    };

    let next_diagnostic = match classification {
        "f64_selected_historical_k_rope_source_reference_capture_midpoint" => {
            "inspect reference post-RoPE capture/serialization precision for the selected historical K row before changing runtime math"
        }
        "f64_selected_historical_k_rope_source_projection_bucket_crossing" => {
            "localize selected historical K pre-RoPE projection bucket drift before changing RoPE or score math"
        }
        "f64_selected_historical_k_rope_source_runtime_replay_bucket_crossing" => {
            "pin selected historical K RoPE replay arithmetic before changing runtime math"
        }
        "f64_selected_historical_k_rope_source_post_rope_bucket_crossing" => {
            "pin selected historical K post-RoPE capture policy before changing runtime math"
        }
        "f64_selected_historical_k_rope_source_clean" => {
            "move downstream because the selected historical K RoPE source is clean"
        }
        "f64_selected_historical_k_rope_source_missing_probe" => {
            "capture selected historical K post-RoPE epsilon probe before runtime changes"
        }
        "f64_selected_historical_k_rope_source_no_projection_rope_boundary" => {
            "localize selected key bucket source before historical K RoPE attribution"
        }
        _ => {
            "keep selected historical K RoPE source diagnostic-only until the exact capture policy is pinned"
        }
    };

    json!({
        "diagnostic_only": true,
        "claim_allowed": false,
        "policy": "F64 selected historical K RoPE source frontier is compact diagnostic-only evidence for whether the selected key bucket drift is projection input drift, RoPE replay arithmetic, or post-RoPE capture/serialization near an F16 midpoint; it does not change runtime math and does not promote reference parity, A770 semantic quality, attention score residency, softmax residency, selected attention, resident KV, value-mix residency, full residency, performance, or completion",
        "classification": classification,
        "selected_key_bucket_source_classification": source_classification,
        "historical_source_classification": historical_classification,
        "head": historical_row.pointer("/head").cloned().unwrap_or(Value::Null),
        "kv_head": historical_row.pointer("/kv_head").cloned().unwrap_or(Value::Null),
        "key_slot": historical_row.pointer("/key_slot").cloned().unwrap_or(Value::Null),
        "query_token": historical_row.pointer("/query_token").cloned().unwrap_or(Value::Null),
        "contributor_dim": historical_row.pointer("/contributor_dim").cloned().unwrap_or(Value::Null),
        "variant_id": probe.pointer("/variant_id").cloned().unwrap_or(Value::Null),
        "probe_dim": probe.pointer("/probe_dim").cloned().unwrap_or(Value::Null),
        "paired_dim": probe.pointer("/paired_dim").cloned().unwrap_or(Value::Null),
        "output_component": probe.pointer("/output_component").cloned().unwrap_or(Value::Null),
        "projection_buckets_stable": projection_buckets_stable,
        "projection_bucket_match": projection_bucket,
        "paired_projection_bucket_match": paired_projection_bucket,
        "replay_bucket_stable": replay_bucket_stable,
        "replay_bucket_match": replay_bucket,
        "post_rope_bucket_match": post_rope_bucket,
        "tiny_capture_delta": tiny_capture_delta,
        "runtime_replay_clean": runtime_replay_clean,
        "rust_replay_capture_clean": rust_replay_capture_clean,
        "reference_replay_capture_delta_present": reference_replay_capture_delta_present,
        "capture_delta": capture_delta,
        "runtime_replay_delta": runtime_replay_delta,
        "reference_replay_minus_capture": reference_replay_minus_capture,
        "rust_replay_minus_capture": rust_replay_minus_capture,
        "post_rope_bucket": probe.pointer("/post_rope_bucket").cloned().unwrap_or(Value::Null),
        "projection_bucket": probe.pointer("/projection_bucket").cloned().unwrap_or(Value::Null),
        "paired_projection_bucket": probe.pointer("/paired_projection_bucket").cloned().unwrap_or(Value::Null),
        "replay_bucket": probe.pointer("/replay_bucket").cloned().unwrap_or(Value::Null),
        "selected_dim_values": historical_row.pointer("/selected_dim_values").cloned().unwrap_or(Value::Null),
        "reference_projection_record": historical_row.pointer("/reference_projection_record").cloned().unwrap_or(Value::Null),
        "reference_post_rope_record": historical_row.pointer("/reference_post_rope_record").cloned().unwrap_or(Value::Null),
        "rust_projection_record": historical_row.pointer("/rust_projection_record").cloned().unwrap_or(Value::Null),
        "rust_post_rope_record": historical_row.pointer("/rust_post_rope_record").cloned().unwrap_or(Value::Null),
        "next_diagnostic": next_diagnostic,
    })
}

fn attention_norm_f64_selected_k_capture_precision_frontier(
    selected_historical_k_rope_source_frontier: &Value,
) -> Value {
    let source_classification = selected_historical_k_rope_source_frontier
        .pointer("/classification")
        .and_then(Value::as_str);
    let reference_post_rope_record = selected_historical_k_rope_source_frontier
        .pointer("/reference_post_rope_record")
        .unwrap_or(&Value::Null);
    let rust_post_rope_record = selected_historical_k_rope_source_frontier
        .pointer("/rust_post_rope_record")
        .unwrap_or(&Value::Null);
    let reference_capture = value_f64(
        selected_historical_k_rope_source_frontier,
        "/selected_dim_values/reference_post_rope",
    );
    let rust_capture = value_f64(
        selected_historical_k_rope_source_frontier,
        "/selected_dim_values/rust_post_rope",
    );
    let midpoint = value_f64(
        selected_historical_k_rope_source_frontier,
        "/post_rope_bucket/f16_bucket_midpoint",
    );
    let left_minus_midpoint = value_f64(
        selected_historical_k_rope_source_frontier,
        "/post_rope_bucket/left_minus_midpoint",
    );
    let right_minus_midpoint = value_f64(
        selected_historical_k_rope_source_frontier,
        "/post_rope_bucket/right_minus_midpoint",
    );
    let reference_replay_minus_capture =
        value_f64(selected_historical_k_rope_source_frontier, "/reference_replay_minus_capture");
    let rust_replay_minus_capture =
        value_f64(selected_historical_k_rope_source_frontier, "/rust_replay_minus_capture");
    let post_rope_bucket_match =
        value_bool(selected_historical_k_rope_source_frontier, "/post_rope_bucket_match");
    let runtime_replay_clean =
        value_bool(selected_historical_k_rope_source_frontier, "/runtime_replay_clean");
    let rust_replay_capture_clean =
        value_bool(selected_historical_k_rope_source_frontier, "/rust_replay_capture_clean");
    let reference_record_present =
        reference_post_rope_record.pointer("/present").and_then(Value::as_bool).unwrap_or(false);
    let rust_record_present =
        rust_post_rope_record.pointer("/present").and_then(Value::as_bool).unwrap_or(false);
    let reference_capture_minus_midpoint =
        reference_capture.zip(midpoint).map(|(capture, midpoint)| capture - midpoint);
    let rust_capture_minus_midpoint =
        rust_capture.zip(midpoint).map(|(capture, midpoint)| capture - midpoint);
    let reference_capture_is_midpoint =
        reference_capture_minus_midpoint.is_some_and(|delta| delta.abs() <= 1.0e-12);
    let rust_capture_is_above_midpoint =
        rust_capture_minus_midpoint.is_some_and(|delta| delta > 0.0 && delta <= 1.0e-6);
    let reference_replay_capture_delta_present =
        reference_replay_minus_capture.is_some_and(|delta| delta.abs() > 0.0);
    let rust_capture_matches_replay =
        rust_replay_minus_capture.is_some_and(|delta| delta.abs() <= 1.0e-12);

    let classification = if source_classification
        != Some("f64_selected_historical_k_rope_source_reference_capture_midpoint")
    {
        "f64_selected_k_capture_precision_not_midpoint_frontier"
    } else if !reference_record_present || !rust_record_present {
        "f64_selected_k_capture_precision_metadata_missing"
    } else if reference_capture_is_midpoint
        && rust_capture_is_above_midpoint
        && post_rope_bucket_match == Some(false)
        && runtime_replay_clean == Some(true)
        && rust_replay_capture_clean == Some(true)
        && reference_replay_capture_delta_present
    {
        "f64_selected_k_reference_capture_midpoint_with_trace_metadata"
    } else if post_rope_bucket_match == Some(false) {
        "f64_selected_k_capture_precision_bucket_crossing_unpinned"
    } else {
        "f64_selected_k_capture_precision_clean_or_unrelated"
    };

    let next_diagnostic = match classification {
        "f64_selected_k_reference_capture_midpoint_with_trace_metadata" => {
            "inspect the reference post-RoPE trace capture path or capture pre-serialization values before changing Rust runtime math"
        }
        "f64_selected_k_capture_precision_metadata_missing" => {
            "attach reference and Rust post-RoPE trace metadata before interpreting the midpoint capture"
        }
        "f64_selected_k_capture_precision_bucket_crossing_unpinned" => {
            "pin whether the selected post-RoPE bucket crossing is capture precision, source tensor dtype, or view layout"
        }
        "f64_selected_k_capture_precision_not_midpoint_frontier" => {
            "localize selected historical K RoPE source before capture precision attribution"
        }
        _ => "move downstream because selected K capture precision is not the active bucket source",
    };

    json!({
        "diagnostic_only": true,
        "claim_allowed": false,
        "policy": "F64 selected K capture precision frontier is diagnostic-only evidence for whether the selected historical K post-RoPE bucket drift is tied to reference trace capture at an F16 midpoint; it does not change runtime math and does not promote reference parity, A770 semantic quality, attention score residency, softmax residency, selected attention, resident KV, value-mix residency, full residency, performance, or completion",
        "classification": classification,
        "source_classification": source_classification,
        "head": selected_historical_k_rope_source_frontier.pointer("/head").cloned().unwrap_or(Value::Null),
        "kv_head": selected_historical_k_rope_source_frontier.pointer("/kv_head").cloned().unwrap_or(Value::Null),
        "key_slot": selected_historical_k_rope_source_frontier.pointer("/key_slot").cloned().unwrap_or(Value::Null),
        "query_token": selected_historical_k_rope_source_frontier.pointer("/query_token").cloned().unwrap_or(Value::Null),
        "contributor_dim": selected_historical_k_rope_source_frontier.pointer("/contributor_dim").cloned().unwrap_or(Value::Null),
        "reference_capture": reference_capture,
        "rust_capture": rust_capture,
        "f16_midpoint": midpoint,
        "reference_capture_minus_midpoint": reference_capture_minus_midpoint,
        "rust_capture_minus_midpoint": rust_capture_minus_midpoint,
        "reference_capture_is_midpoint": reference_capture_is_midpoint,
        "rust_capture_is_above_midpoint": rust_capture_is_above_midpoint,
        "left_minus_midpoint": left_minus_midpoint,
        "right_minus_midpoint": right_minus_midpoint,
        "reference_replay_minus_capture": reference_replay_minus_capture,
        "rust_replay_minus_capture": rust_replay_minus_capture,
        "reference_replay_capture_delta_present": reference_replay_capture_delta_present,
        "rust_capture_matches_replay": rust_capture_matches_replay,
        "post_rope_bucket_match": post_rope_bucket_match,
        "post_rope_bucket": selected_historical_k_rope_source_frontier.pointer("/post_rope_bucket").cloned().unwrap_or(Value::Null),
        "reference_post_rope_record": reference_post_rope_record.clone(),
        "rust_post_rope_record": rust_post_rope_record.clone(),
        "reference_projection_record": selected_historical_k_rope_source_frontier.pointer("/reference_projection_record").cloned().unwrap_or(Value::Null),
        "rust_projection_record": selected_historical_k_rope_source_frontier.pointer("/rust_projection_record").cloned().unwrap_or(Value::Null),
        "next_diagnostic": next_diagnostic,
    })
}

fn attention_norm_f64_selected_k_json_precision_frontier(
    selected_k_capture_precision_frontier: &Value,
    reference_json_text: Option<&str>,
) -> Value {
    let source_classification =
        selected_k_capture_precision_frontier.pointer("/classification").and_then(Value::as_str);
    let record = selected_k_capture_precision_frontier
        .pointer("/reference_post_rope_record")
        .unwrap_or(&Value::Null);
    let record_name = record.pointer("/name").and_then(Value::as_str);
    let contributor_dim = value_u64(selected_k_capture_precision_frontier, "/contributor_dim");
    let key_slot = value_u64(selected_k_capture_precision_frontier, "/key_slot");
    let token_count = record
        .pointer("/shape")
        .and_then(Value::as_array)
        .and_then(|shape| shape.get(1))
        .and_then(Value::as_u64);
    let first_value_index =
        contributor_dim.zip(key_slot).zip(token_count).and_then(|((dim, token), token_count)| {
            dim.checked_mul(token_count).and_then(|base| base.checked_add(token))
        });
    let reference_capture = value_f64(selected_k_capture_precision_frontier, "/reference_capture");
    let midpoint = value_f64(selected_k_capture_precision_frontier, "/f16_midpoint");
    let raw_decimal = reference_json_text.zip(record_name).zip(first_value_index).and_then(
        |((text, name), index)| {
            raw_first_value_decimal_for_record(text, name, usize::try_from(index).ok()?)
        },
    );
    let raw_source_bits_u32 = reference_json_text.zip(record_name).zip(first_value_index).and_then(
        |((text, name), index)| {
            raw_first_value_u32_for_record(
                text,
                name,
                "first_value_bits_u32",
                usize::try_from(index).ok()?,
            )
        },
    );
    let parsed_f64 = raw_decimal.as_deref().and_then(|raw| raw.parse::<f64>().ok());
    let parsed_f32 = parsed_f64.map(|value| value as f32);
    let reference_capture_f32 = reference_capture.map(|value| value as f32);
    let midpoint_f32 = midpoint.map(|value| value as f32);
    let parsed_f32_bits = parsed_f32.map(f32_bits_hex);
    let reference_capture_f32_bits = reference_capture_f32.map(f32_bits_hex);
    let midpoint_f32_bits = midpoint_f32.map(f32_bits_hex);
    let raw_source_bits_hex = raw_source_bits_u32.map(u32_bits_hex);
    let parsed_matches_reference_capture_bits = parsed_f32
        .zip(reference_capture_f32)
        .is_some_and(|(parsed, capture)| parsed.to_bits() == capture.to_bits());
    let parsed_matches_midpoint_bits = parsed_f32
        .zip(midpoint_f32)
        .is_some_and(|(parsed, midpoint)| parsed.to_bits() == midpoint.to_bits());
    let source_bits_match_parsed_value =
        raw_source_bits_u32.zip(parsed_f32).is_some_and(|(bits, parsed)| bits == parsed.to_bits());
    let source_bits_match_reference_capture = raw_source_bits_u32
        .zip(reference_capture_f32)
        .is_some_and(|(bits, capture)| bits == capture.to_bits());
    let source_bits_match_midpoint = raw_source_bits_u32
        .zip(midpoint_f32)
        .is_some_and(|(bits, midpoint)| bits == midpoint.to_bits());
    let decimal_parse_minus_capture =
        parsed_f64.zip(reference_capture).map(|(parsed, capture)| parsed - capture);
    let decimal_parse_minus_midpoint =
        parsed_f64.zip(midpoint).map(|(parsed, midpoint)| parsed - midpoint);

    let mut blocked_reasons = Vec::<String>::new();
    if reference_json_text.is_none() {
        blocked_reasons.push("reference_json_text_missing".to_string());
    }
    if record_name.is_none() {
        blocked_reasons.push("reference_post_rope_record_name_missing".to_string());
    }
    if contributor_dim.is_none() {
        blocked_reasons.push("contributor_dim_missing".to_string());
    }
    if key_slot.is_none() {
        blocked_reasons.push("key_slot_missing".to_string());
    }
    if token_count.is_none() {
        blocked_reasons.push("reference_post_rope_token_count_missing".to_string());
    }
    if first_value_index.is_none() {
        blocked_reasons.push("reference_first_value_index_unavailable".to_string());
    }
    if raw_decimal.is_none() && blocked_reasons.is_empty() {
        blocked_reasons.push("reference_raw_decimal_missing".to_string());
    }
    if parsed_f64.is_none() && raw_decimal.is_some() {
        blocked_reasons.push("reference_raw_decimal_parse_failed".to_string());
    }
    if reference_capture.is_none() {
        blocked_reasons.push("reference_capture_missing".to_string());
    }
    if midpoint.is_none() {
        blocked_reasons.push("f16_midpoint_missing".to_string());
    }
    blocked_reasons.sort_unstable();
    blocked_reasons.dedup();

    let classification = if source_classification
        != Some("f64_selected_k_reference_capture_midpoint_with_trace_metadata")
    {
        "f64_selected_k_json_precision_not_active_frontier"
    } else if !blocked_reasons.is_empty() {
        "f64_selected_k_json_precision_unavailable"
    } else if raw_source_bits_u32.is_some()
        && source_bits_match_parsed_value
        && source_bits_match_reference_capture
        && source_bits_match_midpoint
    {
        "f64_selected_k_reference_source_bits_preserve_midpoint_capture"
    } else if raw_source_bits_u32.is_some() && !source_bits_match_parsed_value {
        "f64_selected_k_json_decimal_changes_reference_source_bits"
    } else if parsed_matches_reference_capture_bits && parsed_matches_midpoint_bits {
        "f64_selected_k_json_decimal_preserves_midpoint_capture"
    } else if parsed_matches_reference_capture_bits {
        "f64_selected_k_json_decimal_preserves_reference_capture"
    } else {
        "f64_selected_k_json_decimal_changes_reference_capture"
    };
    let next_diagnostic = match classification {
        "f64_selected_k_json_decimal_preserves_midpoint_capture" => {
            "inspect reference tensor capture/storage precision before changing Rust runtime math; JSON decimal serialization preserves the selected midpoint capture"
        }
        "f64_selected_k_reference_source_bits_preserve_midpoint_capture" => {
            "inspect the reference tensor capture path before first-value bit emission; source f32 bits and JSON decimal both preserve the selected midpoint capture"
        }
        "f64_selected_k_json_decimal_changes_reference_source_bits" => {
            "fix or bypass reference JSON numeric serialization before interpreting the selected K capture midpoint"
        }
        "f64_selected_k_json_decimal_preserves_reference_capture" => {
            "inspect whether the reference captured value is truly an F16 midpoint or a non-midpoint reference value"
        }
        "f64_selected_k_json_decimal_changes_reference_capture" => {
            "fix or bypass reference JSON numeric serialization before interpreting the selected K capture midpoint"
        }
        "f64_selected_k_json_precision_unavailable" => {
            "supply a direct reference sidecar JSON with first_values text or add reference f32-bit capture metadata"
        }
        "f64_selected_k_json_precision_not_active_frontier" => {
            "localize selected K capture precision before JSON precision attribution"
        }
        _ => "keep selected K JSON precision diagnostic-only",
    };

    json!({
        "diagnostic_only": true,
        "claim_allowed": false,
        "policy": "F64 selected K JSON precision frontier is diagnostic-only evidence for whether the reference sidecar decimal text preserves or changes the selected post-RoPE capture value; it does not change reference instrumentation, Rust runtime math, or promote reference parity, A770 semantic quality, attention score residency, softmax residency, selected attention, resident KV, value-mix residency, full residency, performance, or completion",
        "classification": classification,
        "source_classification": source_classification,
        "record_name": record_name,
        "layout": record.pointer("/layout").cloned().unwrap_or(Value::Null),
        "contributor_dim": contributor_dim,
        "key_slot": key_slot,
        "token_count": token_count,
        "first_value_index": first_value_index,
        "raw_decimal": raw_decimal,
        "parsed_f64": parsed_f64,
        "parsed_f32": parsed_f32,
        "parsed_f32_bits": parsed_f32_bits,
        "reference_source_bits_u32": raw_source_bits_u32,
        "reference_source_bits_hex": raw_source_bits_hex,
        "reference_capture": reference_capture,
        "reference_capture_f32_bits": reference_capture_f32_bits,
        "f16_midpoint": midpoint,
        "f16_midpoint_f32_bits": midpoint_f32_bits,
        "parsed_matches_reference_capture_bits": parsed_matches_reference_capture_bits,
        "parsed_matches_midpoint_bits": parsed_matches_midpoint_bits,
        "source_bits_match_parsed_value": source_bits_match_parsed_value,
        "source_bits_match_reference_capture": source_bits_match_reference_capture,
        "source_bits_match_midpoint": source_bits_match_midpoint,
        "decimal_parse_minus_capture": decimal_parse_minus_capture,
        "decimal_parse_minus_midpoint": decimal_parse_minus_midpoint,
        "blocked_reasons": blocked_reasons,
        "next_diagnostic": next_diagnostic,
    })
}

fn attention_norm_f64_selected_k_capture_path_frontier(
    selected_k_capture_precision_frontier: &Value,
    selected_k_json_precision_frontier: &Value,
    reference_json_text: Option<&str>,
) -> Value {
    let source_classification =
        selected_k_json_precision_frontier.pointer("/classification").and_then(Value::as_str);
    let record = selected_k_capture_precision_frontier
        .pointer("/reference_post_rope_record")
        .unwrap_or(&Value::Null);
    let record_name =
        selected_k_json_precision_frontier.pointer("/record_name").and_then(Value::as_str);
    let stage = record.pointer("/stage").and_then(Value::as_str);
    let dtype = record.pointer("/dtype").and_then(Value::as_str);
    let graph_op = record.pointer("/graph_op").and_then(Value::as_str);
    let dim = value_u64(selected_k_json_precision_frontier, "/contributor_dim");
    let key_slot = value_u64(selected_k_json_precision_frontier, "/key_slot");
    let token_count = value_u64(selected_k_json_precision_frontier, "/token_count")
        .or_else(|| json_array_u64(record, "/shape", 1));
    let head_dim = json_array_u64(record, "/shape", 0);
    let kv_head_count = json_array_u64(record, "/full_shape", 1);
    let kv_head = stage.and_then(parse_kcur_history_kv_head);
    let first_value_index = value_u64(selected_k_json_precision_frontier, "/first_value_index");
    let computed_first_values_index =
        dim.zip(key_slot).zip(token_count).and_then(|((dim, token), token_count)| {
            dim.checked_mul(token_count).and_then(|base| base.checked_add(token))
        });
    let source_tensor_flat_index =
        dim.zip(key_slot).zip(head_dim).zip(kv_head).zip(kv_head_count).and_then(
            |((((dim, token), head_dim), kv_head), kv_head_count)| {
                head_dim.checked_mul(kv_head).and_then(|head_base| {
                    head_dim.checked_mul(kv_head_count).and_then(|stride| {
                        stride.checked_mul(token).and_then(|token_base| {
                            dim.checked_add(head_base).and_then(|base| base.checked_add(token_base))
                        })
                    })
                })
            },
        );
    let raw_source_tensor_flat_index = reference_json_text
        .zip(record_name)
        .zip(first_value_index)
        .and_then(|((text, name), index)| {
            raw_first_value_u64_for_record(
                text,
                name,
                "first_value_source_indices_u64",
                usize::try_from(index).ok()?,
            )
        });
    let raw_direct_source_bits_u32 = reference_json_text
        .zip(record_name)
        .zip(first_value_index)
        .and_then(|((text, name), index)| {
            raw_first_value_u32_for_record(
                text,
                name,
                "first_value_source_bits_u32",
                usize::try_from(index).ok()?,
            )
        });
    let raw_storage_offset = reference_json_text.zip(record_name).zip(first_value_index).and_then(
        |((text, name), index)| {
            raw_first_value_u64_for_record(
                text,
                name,
                "first_value_storage_offsets_u64",
                usize::try_from(index).ok()?,
            )
        },
    );
    let raw_storage_source_bits_u32 = reference_json_text
        .zip(record_name)
        .zip(first_value_index)
        .and_then(|((text, name), index)| {
            raw_first_value_u32_for_record(
                text,
                name,
                "first_value_storage_source_bits_u32",
                usize::try_from(index).ok()?,
            )
        });
    let source_bits_present = selected_k_json_precision_frontier
        .pointer("/reference_source_bits_u32")
        .and_then(Value::as_u64)
        .is_some();
    let reference_source_bits_u32 =
        value_u64(selected_k_json_precision_frontier, "/reference_source_bits_u32")
            .and_then(|bits| u32::try_from(bits).ok());
    let source_tensor_index_matches_emitted = raw_source_tensor_flat_index
        .zip(source_tensor_flat_index)
        .is_some_and(|(emitted, computed)| emitted == computed);
    let direct_source_bits_match_reference_source_bits = raw_direct_source_bits_u32
        .zip(reference_source_bits_u32)
        .is_some_and(|(direct, source)| direct == source);
    let storage_source_bits_match_direct_source_bits = raw_storage_source_bits_u32
        .zip(raw_direct_source_bits_u32)
        .is_some_and(|(storage, direct)| storage == direct);
    let capture_path_pinned = source_classification
        == Some("f64_selected_k_reference_source_bits_preserve_midpoint_capture")
        && stage.is_some_and(|stage| stage.starts_with("kcur_history_kv_head"))
        && dtype == Some("f32")
        && graph_op == Some("ROPE")
        && first_value_index == computed_first_values_index
        && source_tensor_flat_index.is_some()
        && source_bits_present;
    let direct_source_pinned = capture_path_pinned
        && source_tensor_index_matches_emitted
        && direct_source_bits_match_reference_source_bits;
    let storage_source_pinned = direct_source_pinned
        && raw_storage_offset.is_some()
        && storage_source_bits_match_direct_source_bits;

    let mut blocked_reasons = Vec::<String>::new();
    if source_classification
        != Some("f64_selected_k_reference_source_bits_preserve_midpoint_capture")
    {
        blocked_reasons.push("selected_k_source_bits_frontier_not_pinned".to_string());
    }
    if stage.is_none() {
        blocked_reasons.push("reference_post_rope_stage_missing".to_string());
    }
    if !stage.is_some_and(|stage| stage.starts_with("kcur_history_kv_head")) {
        blocked_reasons.push("reference_post_rope_stage_not_kcur_history".to_string());
    }
    if dtype != Some("f32") {
        blocked_reasons.push("reference_post_rope_dtype_not_f32".to_string());
    }
    if graph_op != Some("ROPE") {
        blocked_reasons.push("reference_post_rope_graph_op_not_rope".to_string());
    }
    if dim.is_none() {
        blocked_reasons.push("selected_contributor_dim_missing".to_string());
    }
    if key_slot.is_none() {
        blocked_reasons.push("selected_key_slot_missing".to_string());
    }
    if token_count.is_none() {
        blocked_reasons.push("reference_token_count_missing".to_string());
    }
    if head_dim.is_none() {
        blocked_reasons.push("reference_head_dim_missing".to_string());
    }
    if kv_head.is_none() {
        blocked_reasons.push("reference_kv_head_missing_from_stage".to_string());
    }
    if kv_head_count.is_none() {
        blocked_reasons.push("reference_kv_head_count_missing".to_string());
    }
    if first_value_index != computed_first_values_index {
        blocked_reasons.push("first_values_index_formula_mismatch".to_string());
    }
    if source_tensor_flat_index.is_none() {
        blocked_reasons.push("source_tensor_flat_index_unavailable".to_string());
    }
    if !source_bits_present {
        blocked_reasons.push("reference_source_bits_missing".to_string());
    }
    if raw_source_tensor_flat_index.is_none() {
        blocked_reasons.push("reference_direct_source_index_missing".to_string());
    }
    if raw_direct_source_bits_u32.is_none() {
        blocked_reasons.push("reference_direct_source_bits_missing".to_string());
    }
    if raw_storage_offset.is_none() {
        blocked_reasons.push("reference_storage_source_offset_missing".to_string());
    }
    if raw_storage_source_bits_u32.is_none() {
        blocked_reasons.push("reference_storage_source_bits_missing".to_string());
    }
    if raw_source_tensor_flat_index.is_some()
        && source_tensor_flat_index.is_some()
        && !source_tensor_index_matches_emitted
    {
        blocked_reasons.push("reference_direct_source_index_mismatch".to_string());
    }
    if raw_direct_source_bits_u32.is_some()
        && reference_source_bits_u32.is_some()
        && !direct_source_bits_match_reference_source_bits
    {
        blocked_reasons.push("reference_direct_source_bits_mismatch".to_string());
    }
    if raw_storage_source_bits_u32.is_some()
        && raw_direct_source_bits_u32.is_some()
        && !storage_source_bits_match_direct_source_bits
    {
        blocked_reasons.push("reference_storage_source_bits_mismatch".to_string());
    }
    blocked_reasons.sort_unstable();
    blocked_reasons.dedup();

    let classification = if storage_source_pinned {
        "f64_selected_k_reference_storage_source_value_preserves_midpoint_capture"
    } else if direct_source_pinned {
        "f64_selected_k_reference_direct_source_value_preserves_midpoint_capture"
    } else if capture_path_pinned {
        "f64_selected_k_reference_capture_path_pinned_to_kcur_history_tensor_value"
    } else if source_classification
        != Some("f64_selected_k_reference_source_bits_preserve_midpoint_capture")
    {
        "f64_selected_k_capture_path_not_active_frontier"
    } else {
        "f64_selected_k_capture_path_unpinned"
    };
    let next_diagnostic = match classification {
        "f64_selected_k_reference_storage_source_value_preserves_midpoint_capture" => {
            "inspect the reference graph producer before Kcur tensor materialization, because storage-source bits, direct source bits, and copied Kcur history bits all preserve the selected midpoint"
        }
        "f64_selected_k_reference_direct_source_value_preserves_midpoint_capture" => {
            "inspect the reference tensor value before trace values-vector extraction, because direct source bits and copied Kcur history bits both preserve the selected midpoint"
        }
        "f64_selected_k_reference_capture_path_pinned_to_kcur_history_tensor_value" => {
            "inspect the reference tensor value before the Kcur history copy, because sidecar JSON and emitted source bits both preserve the copied midpoint"
        }
        "f64_selected_k_capture_path_not_active_frontier" => {
            "pin selected K source bits before capture-path attribution"
        }
        _ => "attach missing Kcur history capture metadata before changing Rust runtime math",
    };

    let mut result = json!({
        "diagnostic_only": true,
        "claim_allowed": false,
        "policy": "Selected K capture-path frontier is diagnostic-only evidence for how the reference Kcur history sidecar value is copied before JSON and f32-bit emission; it does not change reference instrumentation, Rust runtime math, or promote reference parity, A770 semantic quality, attention score residency, softmax residency, selected attention, resident KV, value-mix residency, full residency, performance, or completion",
        "classification": classification,
        "source_classification": source_classification,
        "record_name": selected_k_json_precision_frontier.pointer("/record_name").cloned().unwrap_or(Value::Null),
        "stage": stage,
        "dtype": dtype,
        "graph_op": graph_op,
        "graph_index": record.pointer("/graph_index").cloned().unwrap_or(Value::Null),
        "shape": record.pointer("/shape").cloned().unwrap_or(Value::Null),
        "full_shape": record.pointer("/full_shape").cloned().unwrap_or(Value::Null),
        "sample_offset": record.pointer("/sample_offset").cloned().unwrap_or(Value::Null),
        "token_axis": record.pointer("/token_axis").cloned().unwrap_or(Value::Null),
        "view_source_present": record.pointer("/view_source_present").cloned().unwrap_or(Value::Null),
        "view_offset": record.pointer("/view_offset").cloned().unwrap_or(Value::Null),
        "values_available": record.pointer("/values_available").cloned().unwrap_or(Value::Null),
        "first_values_len": record.pointer("/first_values_len").cloned().unwrap_or(Value::Null),
        "layout": "dim_major_token_minor",
        "capture_path": "reference_kcur_history_copy_from_values_vector",
        "copy_formula": "first_values[dim * token_count + token] = values[dim + head_dim * kv_head + head_dim * kv_head_count * token]",
        "contributor_dim": dim,
        "key_slot": key_slot,
        "token_count": token_count,
        "head_dim": head_dim,
        "kv_head": kv_head,
        "kv_head_count": kv_head_count,
        "first_value_index": first_value_index,
        "computed_first_values_index": computed_first_values_index,
        "first_values_index_matches_formula": first_value_index == computed_first_values_index,
        "source_tensor_flat_index": source_tensor_flat_index,
        "emitted_source_tensor_flat_index": raw_source_tensor_flat_index,
        "source_tensor_index_matches_emitted": source_tensor_index_matches_emitted,
        "reference_source_bits_u32": selected_k_json_precision_frontier.pointer("/reference_source_bits_u32").cloned().unwrap_or(Value::Null),
        "reference_source_bits_hex": selected_k_json_precision_frontier.pointer("/reference_source_bits_hex").cloned().unwrap_or(Value::Null),
        "direct_source_bits_u32": raw_direct_source_bits_u32,
        "direct_source_bits_hex": raw_direct_source_bits_u32.map(u32_bits_hex),
        "direct_source_bits_match_reference_source_bits": direct_source_bits_match_reference_source_bits,
        "source_bits_present": source_bits_present,
        "blocked_reasons": blocked_reasons,
        "next_diagnostic": next_diagnostic,
    });
    if let Some(object) = result.as_object_mut() {
        object.insert("storage_source_offset".to_string(), json!(raw_storage_offset));
        object.insert("storage_source_bits_u32".to_string(), json!(raw_storage_source_bits_u32));
        object.insert(
            "storage_source_bits_hex".to_string(),
            json!(raw_storage_source_bits_u32.map(u32_bits_hex)),
        );
        object.insert(
            "storage_source_bits_match_direct_source_bits".to_string(),
            json!(storage_source_bits_match_direct_source_bits),
        );
    }
    result
}

fn attention_norm_f64_selected_k_graph_producer_frontier(
    selected_k_capture_path_frontier: &Value,
    reference_records: &[ReferenceTraceRecord],
) -> Value {
    let source_classification =
        selected_k_capture_path_frontier.pointer("/classification").and_then(Value::as_str);
    let graph_index = selected_k_capture_path_frontier
        .pointer("/reference_post_rope_record/graph_index")
        .or_else(|| selected_k_capture_path_frontier.pointer("/graph_index"))
        .and_then(Value::as_i64);
    let graph_op = selected_k_capture_path_frontier.pointer("/graph_op").and_then(Value::as_str);
    let kcur_rope_record = graph_index.and_then(|graph_index| {
        reference_records.iter().find(|record| {
            record.stage == "Kcur"
                && record.graph_index == Some(graph_index)
                && record.graph_op.as_deref() == graph_op
                && reference_record_has_graph_sources(record)
        })
    });
    let kcur_rope_source_names =
        kcur_rope_record.map(reference_graph_source_names).unwrap_or_default();
    let pre_rope_projection_record = reference_records.iter().find(|record| {
        record.stage == "Kcur"
            && record.graph_op.as_deref() == Some("MUL_MAT")
            && reference_record_has_graph_sources(record)
            && reference_graph_source_names(record).iter().any(|name| name == "blk.0.attn_k.weight")
    });
    let pre_rope_source_names =
        pre_rope_projection_record.map(reference_graph_source_names).unwrap_or_default();
    let rope_sources_include_reshaped_kcur =
        kcur_rope_source_names.iter().any(|name| name == "Kcur-0 (reshaped)");
    let rope_sources_include_inp_pos = kcur_rope_source_names.iter().any(|name| name == "inp_pos");
    let pre_rope_sources_include_attn_k_weight =
        pre_rope_source_names.iter().any(|name| name == "blk.0.attn_k.weight");
    let pre_rope_sources_include_attn_norm =
        pre_rope_source_names.iter().any(|name| name == "attn_norm-0");

    let mut blocked_reasons = Vec::<String>::new();
    if source_classification
        != Some("f64_selected_k_reference_storage_source_value_preserves_midpoint_capture")
    {
        blocked_reasons.push("selected_k_storage_source_frontier_not_pinned".to_string());
    }
    if graph_index.is_none() {
        blocked_reasons.push("reference_post_rope_graph_index_missing".to_string());
    }
    if graph_op != Some("ROPE") {
        blocked_reasons.push("reference_post_rope_graph_op_not_rope".to_string());
    }
    if kcur_rope_record.is_none() {
        blocked_reasons.push("reference_kcur_rope_graph_record_missing".to_string());
    }
    if kcur_rope_record.is_some() && kcur_rope_source_names.is_empty() {
        blocked_reasons.push("reference_kcur_rope_graph_sources_missing".to_string());
    }
    if !rope_sources_include_reshaped_kcur {
        blocked_reasons.push("reference_kcur_rope_reshaped_kcur_source_missing".to_string());
    }
    if !rope_sources_include_inp_pos {
        blocked_reasons.push("reference_kcur_rope_inp_pos_source_missing".to_string());
    }
    if pre_rope_projection_record.is_none() {
        blocked_reasons.push("reference_kcur_pre_rope_projection_record_missing".to_string());
    }
    if !pre_rope_sources_include_attn_k_weight {
        blocked_reasons.push("reference_kcur_pre_rope_weight_source_missing".to_string());
    }
    if !pre_rope_sources_include_attn_norm {
        blocked_reasons.push("reference_kcur_pre_rope_attn_norm_source_missing".to_string());
    }
    blocked_reasons.sort_unstable();
    blocked_reasons.dedup();

    let classification = if source_classification
        != Some("f64_selected_k_reference_storage_source_value_preserves_midpoint_capture")
    {
        "f64_selected_k_graph_producer_not_active_frontier"
    } else if blocked_reasons.is_empty() {
        "f64_selected_k_reference_graph_producer_pinned_to_rope_and_projection_sources"
    } else {
        "f64_selected_k_reference_graph_producer_unpinned"
    };
    let next_diagnostic = match classification {
        "f64_selected_k_reference_graph_producer_pinned_to_rope_and_projection_sources" => {
            "inspect the selected pre-RoPE K projection source value and RoPE numeric policy, because Kcur storage is produced from pinned ROPE and K projection graph sources"
        }
        "f64_selected_k_graph_producer_not_active_frontier" => {
            "pin selected K storage-source bits before graph-producer attribution"
        }
        _ => "attach missing Kcur graph producer provenance before changing Rust runtime math",
    };

    json!({
        "diagnostic_only": true,
        "claim_allowed": false,
        "policy": "Selected K graph-producer frontier is diagnostic-only provenance for the reference Kcur tensor that already contains the selected midpoint storage bits; it does not change reference instrumentation, Rust runtime math, or promote reference parity, A770 semantic quality, attention score residency, softmax residency, selected attention, resident KV, value-mix residency, full residency, performance, or completion",
        "classification": classification,
        "source_classification": source_classification,
        "selected_record_name": selected_k_capture_path_frontier.pointer("/record_name").cloned().unwrap_or(Value::Null),
        "selected_graph_index": graph_index,
        "selected_graph_op": graph_op,
        "kcur_rope_record_present": kcur_rope_record.is_some(),
        "kcur_rope_graph_index": kcur_rope_record.and_then(|record| record.graph_index),
        "kcur_rope_graph_source_count": kcur_rope_source_names.len(),
        "kcur_rope_graph_source_names": kcur_rope_source_names,
        "rope_sources_include_reshaped_kcur": rope_sources_include_reshaped_kcur,
        "rope_sources_include_inp_pos": rope_sources_include_inp_pos,
        "pre_rope_projection_record_present": pre_rope_projection_record.is_some(),
        "pre_rope_projection_graph_index": pre_rope_projection_record.and_then(|record| record.graph_index),
        "pre_rope_projection_graph_source_count": pre_rope_source_names.len(),
        "pre_rope_projection_graph_source_names": pre_rope_source_names,
        "pre_rope_sources_include_attn_k_weight": pre_rope_sources_include_attn_k_weight,
        "pre_rope_sources_include_attn_norm": pre_rope_sources_include_attn_norm,
        "blocked_reasons": blocked_reasons,
        "next_diagnostic": next_diagnostic,
    })
}

fn attention_norm_f64_selected_k_rope_capture_policy_frontier(
    selected_historical_k_rope_source_frontier: &Value,
    selected_k_capture_path_frontier: &Value,
    selected_k_graph_producer_frontier: &Value,
) -> Value {
    let rope_classification = selected_historical_k_rope_source_frontier
        .pointer("/classification")
        .and_then(Value::as_str);
    let capture_classification =
        selected_k_capture_path_frontier.pointer("/classification").and_then(Value::as_str);
    let graph_classification =
        selected_k_graph_producer_frontier.pointer("/classification").and_then(Value::as_str);
    let projection_buckets_stable =
        value_bool(selected_historical_k_rope_source_frontier, "/projection_buckets_stable");
    let replay_bucket_stable =
        value_bool(selected_historical_k_rope_source_frontier, "/replay_bucket_stable");
    let post_rope_bucket_match =
        value_bool(selected_historical_k_rope_source_frontier, "/post_rope_bucket_match");
    let runtime_replay_clean =
        value_bool(selected_historical_k_rope_source_frontier, "/runtime_replay_clean");
    let rust_replay_capture_clean =
        value_bool(selected_historical_k_rope_source_frontier, "/rust_replay_capture_clean");
    let reference_replay_capture_delta_present = value_bool(
        selected_historical_k_rope_source_frontier,
        "/reference_replay_capture_delta_present",
    );
    let storage_source_bits_match_direct_source_bits = value_bool(
        selected_k_capture_path_frontier,
        "/storage_source_bits_match_direct_source_bits",
    );
    let graph_producer_pinned = graph_classification
        == Some("f64_selected_k_reference_graph_producer_pinned_to_rope_and_projection_sources");
    let rope_midpoint_pinned = rope_classification
        == Some("f64_selected_historical_k_rope_source_reference_capture_midpoint");
    let storage_midpoint_pinned = capture_classification
        == Some("f64_selected_k_reference_storage_source_value_preserves_midpoint_capture")
        && storage_source_bits_match_direct_source_bits == Some(true);

    let mut blocked_reasons = Vec::<String>::new();
    if !graph_producer_pinned {
        blocked_reasons.push("selected_k_graph_producer_not_pinned".to_string());
    }
    if !rope_midpoint_pinned {
        blocked_reasons.push("selected_k_rope_midpoint_not_pinned".to_string());
    }
    if !storage_midpoint_pinned {
        blocked_reasons.push("selected_k_storage_midpoint_not_pinned".to_string());
    }
    if projection_buckets_stable != Some(true) {
        blocked_reasons.push("selected_k_projection_buckets_not_stable".to_string());
    }
    if replay_bucket_stable != Some(true) {
        blocked_reasons.push("selected_k_replay_bucket_not_stable".to_string());
    }
    if post_rope_bucket_match != Some(false) {
        blocked_reasons.push("selected_k_post_rope_bucket_not_split".to_string());
    }
    if runtime_replay_clean != Some(true) {
        blocked_reasons.push("selected_k_runtime_replay_not_clean".to_string());
    }
    if rust_replay_capture_clean != Some(true) {
        blocked_reasons.push("selected_k_rust_replay_capture_not_clean".to_string());
    }
    if reference_replay_capture_delta_present != Some(true) {
        blocked_reasons.push("selected_k_reference_replay_capture_delta_missing".to_string());
    }
    blocked_reasons.sort_unstable();
    blocked_reasons.dedup();

    let classification = if graph_producer_pinned
        && rope_midpoint_pinned
        && storage_midpoint_pinned
        && blocked_reasons.is_empty()
    {
        "f64_selected_k_reference_rope_capture_policy_pinned_to_midpoint_storage"
    } else if !graph_producer_pinned {
        "f64_selected_k_rope_capture_policy_graph_producer_unpinned"
    } else if !rope_midpoint_pinned {
        "f64_selected_k_rope_capture_policy_rope_midpoint_unpinned"
    } else if !storage_midpoint_pinned {
        "f64_selected_k_rope_capture_policy_storage_midpoint_unpinned"
    } else {
        "f64_selected_k_rope_capture_policy_unpinned"
    };
    let next_diagnostic = match classification {
        "f64_selected_k_reference_rope_capture_policy_pinned_to_midpoint_storage" => {
            "instrument the selected reference ROPE producer component before tensor storage, because projection inputs and replay are bucket-stable while reference ROPE materialization lands exactly on the F16 midpoint"
        }
        "f64_selected_k_rope_capture_policy_graph_producer_unpinned" => {
            "pin selected K graph producer provenance before ROPE capture-policy attribution"
        }
        "f64_selected_k_rope_capture_policy_rope_midpoint_unpinned" => {
            "pin selected historical K RoPE midpoint evidence before capture-policy attribution"
        }
        "f64_selected_k_rope_capture_policy_storage_midpoint_unpinned" => {
            "pin selected K storage-source bits before capture-policy attribution"
        }
        _ => {
            "keep selected K ROPE capture policy diagnostic-only until all midpoint and producer evidence is pinned"
        }
    };

    json!({
        "diagnostic_only": true,
        "claim_allowed": false,
        "policy": "Selected K ROPE capture-policy frontier is diagnostic-only evidence for whether the selected reference K bucket drift is already isolated to reference ROPE materialization/capture near an F16 midpoint; it does not change runtime math or promote reference parity, A770 semantic quality, attention score residency, softmax residency, selected attention, resident KV, value-mix residency, full residency, performance, or completion",
        "classification": classification,
        "rope_classification": rope_classification,
        "capture_classification": capture_classification,
        "graph_classification": graph_classification,
        "graph_producer_pinned": graph_producer_pinned,
        "rope_midpoint_pinned": rope_midpoint_pinned,
        "storage_midpoint_pinned": storage_midpoint_pinned,
        "variant_id": selected_historical_k_rope_source_frontier.pointer("/variant_id").cloned().unwrap_or(Value::Null),
        "output_component": selected_historical_k_rope_source_frontier.pointer("/output_component").cloned().unwrap_or(Value::Null),
        "contributor_dim": selected_historical_k_rope_source_frontier.pointer("/contributor_dim").cloned().unwrap_or(Value::Null),
        "paired_dim": selected_historical_k_rope_source_frontier.pointer("/paired_dim").cloned().unwrap_or(Value::Null),
        "key_slot": selected_historical_k_rope_source_frontier.pointer("/key_slot").cloned().unwrap_or(Value::Null),
        "kv_head": selected_historical_k_rope_source_frontier.pointer("/kv_head").cloned().unwrap_or(Value::Null),
        "projection_buckets_stable": projection_buckets_stable,
        "replay_bucket_stable": replay_bucket_stable,
        "post_rope_bucket_match": post_rope_bucket_match,
        "runtime_replay_clean": runtime_replay_clean,
        "rust_replay_capture_clean": rust_replay_capture_clean,
        "reference_replay_capture_delta_present": reference_replay_capture_delta_present,
        "reference_replay_minus_capture": selected_historical_k_rope_source_frontier.pointer("/reference_replay_minus_capture").cloned().unwrap_or(Value::Null),
        "storage_source_bits_hex": selected_k_capture_path_frontier.pointer("/storage_source_bits_hex").cloned().unwrap_or(Value::Null),
        "direct_source_bits_hex": selected_k_capture_path_frontier.pointer("/direct_source_bits_hex").cloned().unwrap_or(Value::Null),
        "reference_source_bits_hex": selected_k_capture_path_frontier.pointer("/reference_source_bits_hex").cloned().unwrap_or(Value::Null),
        "kcur_rope_graph_source_names": selected_k_graph_producer_frontier.pointer("/kcur_rope_graph_source_names").cloned().unwrap_or(Value::Null),
        "pre_rope_projection_graph_source_names": selected_k_graph_producer_frontier.pointer("/pre_rope_projection_graph_source_names").cloned().unwrap_or(Value::Null),
        "selected_dim_values": selected_historical_k_rope_source_frontier.pointer("/selected_dim_values").cloned().unwrap_or(Value::Null),
        "blocked_reasons": blocked_reasons,
        "next_diagnostic": next_diagnostic,
    })
}

fn attention_norm_f64_selected_k_rope_producer_storage_frontier(
    selected_k_rope_capture_policy_frontier: &Value,
    selected_k_capture_path_frontier: &Value,
    scalar_trace_records: Option<&[Value]>,
) -> Value {
    let capture_policy_classification =
        selected_k_rope_capture_policy_frontier.pointer("/classification").and_then(Value::as_str);
    let layer = selected_k_capture_path_frontier
        .pointer("/reference_post_rope_record/layer")
        .or_else(|| selected_k_capture_path_frontier.pointer("/layer"))
        .and_then(Value::as_i64)
        .unwrap_or(0);
    let kv_head = selected_k_capture_path_frontier.pointer("/kv_head").and_then(Value::as_i64);
    let token = selected_k_capture_path_frontier.pointer("/key_slot").and_then(Value::as_i64);
    let dim = selected_k_capture_path_frontier.pointer("/contributor_dim").and_then(Value::as_i64);
    let storage_bits = value_u64(selected_k_capture_path_frontier, "/storage_source_bits_u32");
    let direct_bits = value_u64(selected_k_capture_path_frontier, "/direct_source_bits_u32");
    let scalar_record = scalar_trace_records.and_then(|records| {
        records.iter().find(|record| {
            record.pointer("/stage").and_then(Value::as_str) == Some("kcur_rope_scalar_probe")
                && record
                    .pointer("/tensor_name")
                    .and_then(Value::as_str)
                    .is_some_and(|name| name.starts_with("Kcur"))
                && record.pointer("/layer").and_then(Value::as_i64) == Some(layer)
                && record.pointer("/kv_head").and_then(Value::as_i64) == kv_head
                && record.pointer("/token").and_then(Value::as_i64) == token
                && record.pointer("/dim").and_then(Value::as_i64) == dim
        })
    });
    let before_bits = scalar_record
        .and_then(|record| record.pointer("/before_store_bits_u32"))
        .and_then(Value::as_u64);
    let after_bits = scalar_record
        .and_then(|record| record.pointer("/after_store_bits_u32"))
        .and_then(Value::as_u64);
    let before_matches_storage =
        before_bits.zip(storage_bits).is_some_and(|(left, right)| left == right);
    let after_matches_storage =
        after_bits.zip(storage_bits).is_some_and(|(left, right)| left == right);
    let storage_matches_direct =
        storage_bits.zip(direct_bits).is_some_and(|(left, right)| left == right);

    let mut blocked_reasons = Vec::<String>::new();
    if capture_policy_classification
        != Some("f64_selected_k_reference_rope_capture_policy_pinned_to_midpoint_storage")
    {
        blocked_reasons.push("selected_k_rope_capture_policy_not_pinned".to_string());
    }
    if scalar_trace_records.is_none() {
        blocked_reasons.push("reference_rope_scalar_trace_missing".to_string());
    }
    if scalar_record.is_none() {
        blocked_reasons.push("selected_k_rope_scalar_probe_missing".to_string());
    }
    if storage_bits.is_none() {
        blocked_reasons.push("selected_k_storage_source_bits_missing".to_string());
    }
    if before_bits.is_none() {
        blocked_reasons.push("selected_k_before_store_bits_missing".to_string());
    }
    if after_bits.is_none() {
        blocked_reasons.push("selected_k_after_store_bits_missing".to_string());
    }
    blocked_reasons.sort_unstable();
    blocked_reasons.dedup();

    let classification = if capture_policy_classification
        != Some("f64_selected_k_reference_rope_capture_policy_pinned_to_midpoint_storage")
    {
        "selected_k_rope_producer_storage_not_active_frontier"
    } else if scalar_record.is_none() {
        "selected_k_rope_scalar_probe_missing"
    } else if before_matches_storage && after_matches_storage {
        "selected_k_midpoint_produced_before_store"
    } else if !before_matches_storage && after_matches_storage {
        "selected_k_midpoint_introduced_at_store_or_materialization"
    } else if before_bits.is_some() && after_bits.is_some() && storage_bits.is_some() {
        "selected_k_rope_scalar_probe_storage_mismatch"
    } else {
        "selected_k_rope_producer_storage_unpinned"
    };
    let next_diagnostic = match classification {
        "selected_k_midpoint_produced_before_store" => {
            "inspect reference ROPE scalar arithmetic inputs because the selected midpoint exists before tensor storage"
        }
        "selected_k_midpoint_introduced_at_store_or_materialization" => {
            "inspect reference ROPE tensor storage/materialization because scalar before-store bits differ from stored Kcur bits"
        }
        "selected_k_rope_scalar_probe_missing" => {
            "rerun reference trace with BITNET_RS_REFERENCE_ROPE_SCALAR_TRACE and selected layer/head/token/dim env vars"
        }
        "selected_k_rope_producer_storage_not_active_frontier" => {
            "pin selected K ROPE capture-policy frontier before interpreting scalar producer storage evidence"
        }
        _ => {
            "keep selected K ROPE producer/storage evidence diagnostic-only until scalar and storage bits are pinned"
        }
    };

    json!({
        "diagnostic_only": true,
        "claim_allowed": false,
        "policy": "Selected K ROPE producer/storage frontier is diagnostic-only evidence for whether the selected reference K midpoint exists before ROPE tensor storage or is introduced by storage/materialization; it does not change runtime math or promote reference parity, A770 semantic quality, attention score residency, softmax residency, selected attention, resident KV, value-mix residency, full residency, performance, or completion",
        "classification": classification,
        "capture_policy_classification": capture_policy_classification,
        "layer": layer,
        "kv_head": kv_head,
        "token": token,
        "dim": dim,
        "scalar_trace_present": scalar_trace_records.is_some(),
        "scalar_record_present": scalar_record.is_some(),
        "producer_before_store_bits_u32": before_bits,
        "producer_before_store_bits_hex": before_bits.map(|bits| u32_bits_hex(bits as u32)),
        "producer_after_store_bits_u32": after_bits,
        "producer_after_store_bits_hex": after_bits.map(|bits| u32_bits_hex(bits as u32)),
        "storage_source_bits_u32": storage_bits,
        "storage_source_bits_hex": storage_bits.map(|bits| u32_bits_hex(bits as u32)),
        "direct_source_bits_u32": direct_bits,
        "direct_source_bits_hex": direct_bits.map(|bits| u32_bits_hex(bits as u32)),
        "before_store_matches_storage": before_matches_storage,
        "after_store_matches_storage": after_matches_storage,
        "storage_matches_direct": storage_matches_direct,
        "scalar_record": scalar_record.cloned().unwrap_or(Value::Null),
        "blocked_reasons": blocked_reasons,
        "next_diagnostic": next_diagnostic,
    })
}

fn attention_norm_f64_selected_k_rope_scalar_arithmetic_frontier(
    selected_k_rope_producer_storage_frontier: &Value,
) -> Value {
    let producer_classification = selected_k_rope_producer_storage_frontier
        .pointer("/classification")
        .and_then(Value::as_str);
    let scalar_record =
        selected_k_rope_producer_storage_frontier.pointer("/scalar_record").filter(|record| {
            !record.is_null()
                && record
                    .pointer("/tensor_name")
                    .and_then(Value::as_str)
                    .is_some_and(|name| name.starts_with("Kcur"))
        });
    let component =
        scalar_record.and_then(|record| record.pointer("/component")).and_then(Value::as_str);
    let before_bits =
        value_u64(selected_k_rope_producer_storage_frontier, "/producer_before_store_bits_u32");
    let storage_bits =
        value_u64(selected_k_rope_producer_storage_frontier, "/storage_source_bits_u32");
    let direct_bits =
        value_u64(selected_k_rope_producer_storage_frontier, "/direct_source_bits_u32");
    let x0_bits = scalar_record.and_then(|record| value_u64(record, "/x0_bits_u32"));
    let x1_bits = scalar_record.and_then(|record| value_u64(record, "/x1_bits_u32"));
    let cos_theta_bits = scalar_record.and_then(|record| value_u64(record, "/cos_theta_bits_u32"));
    let sin_theta_bits = scalar_record.and_then(|record| value_u64(record, "/sin_theta_bits_u32"));
    let term0_bits = scalar_record.and_then(|record| value_u64(record, "/term0_bits_u32"));
    let term1_bits = scalar_record.and_then(|record| value_u64(record, "/term1_bits_u32"));
    let arithmetic_replay_bits =
        scalar_record.and_then(|record| value_u64(record, "/arithmetic_replay_bits_u32"));
    let arithmetic_replay_matches_before =
        arithmetic_replay_bits.zip(before_bits).is_some_and(|(left, right)| left == right);
    let arithmetic_replay_matches_storage =
        arithmetic_replay_bits.zip(storage_bits).is_some_and(|(left, right)| left == right);
    let before_matches_storage =
        before_bits.zip(storage_bits).is_some_and(|(left, right)| left == right);
    let storage_matches_direct =
        storage_bits.zip(direct_bits).is_some_and(|(left, right)| left == right);

    let mut blocked_reasons = Vec::<String>::new();
    if producer_classification != Some("selected_k_midpoint_produced_before_store") {
        blocked_reasons.push("selected_k_rope_producer_storage_not_pinned".to_string());
    }
    if scalar_record.is_none() {
        blocked_reasons.push("selected_k_rope_scalar_kcur_record_missing".to_string());
    }
    if component.is_none() {
        blocked_reasons.push("selected_k_rope_scalar_component_missing".to_string());
    }
    if x0_bits.is_none() || x1_bits.is_none() {
        blocked_reasons.push("selected_k_rope_scalar_input_bits_missing".to_string());
    }
    if cos_theta_bits.is_none() || sin_theta_bits.is_none() {
        blocked_reasons.push("selected_k_rope_scalar_trig_bits_missing".to_string());
    }
    if term0_bits.is_none() || term1_bits.is_none() {
        blocked_reasons.push("selected_k_rope_scalar_term_bits_missing".to_string());
    }
    if arithmetic_replay_bits.is_none() {
        blocked_reasons.push("selected_k_rope_scalar_arithmetic_replay_bits_missing".to_string());
    }
    if before_bits.is_none() {
        blocked_reasons.push("selected_k_before_store_bits_missing".to_string());
    }
    if storage_bits.is_none() {
        blocked_reasons.push("selected_k_storage_source_bits_missing".to_string());
    }
    blocked_reasons.sort_unstable();
    blocked_reasons.dedup();

    let classification =
        if producer_classification != Some("selected_k_midpoint_produced_before_store") {
            "selected_k_rope_scalar_arithmetic_not_active_frontier"
        } else if scalar_record.is_none()
            || component.is_none()
            || x0_bits.is_none()
            || x1_bits.is_none()
            || cos_theta_bits.is_none()
            || sin_theta_bits.is_none()
            || term0_bits.is_none()
            || term1_bits.is_none()
            || arithmetic_replay_bits.is_none()
            || before_bits.is_none()
        {
            "selected_k_rope_scalar_arithmetic_inputs_missing"
        } else if arithmetic_replay_matches_before && arithmetic_replay_matches_storage {
            "selected_k_rope_scalar_arithmetic_replay_pins_midpoint"
        } else if arithmetic_replay_bits.is_some() && before_bits.is_some() {
            "selected_k_rope_scalar_term_split_replay_differs_from_before_store"
        } else {
            "selected_k_rope_scalar_arithmetic_unpinned"
        };

    let next_diagnostic = match classification {
        "selected_k_rope_scalar_arithmetic_replay_pins_midpoint" => {
            "localize the selected reference ROPE scalar input pair and trig bits because the emitted scalar arithmetic replay already produces the midpoint before storage"
        }
        "selected_k_rope_scalar_term_split_replay_differs_from_before_store" => {
            "pin reference ROPE direct expression evaluation or contraction policy because term-split scalar replay differs from the before-store value"
        }
        "selected_k_rope_scalar_arithmetic_inputs_missing" => {
            "rerun selected K scalar probe with x0/x1/trig/term/replay bit fields before interpreting scalar arithmetic"
        }
        "selected_k_rope_scalar_arithmetic_not_active_frontier" => {
            "pin selected K producer/storage frontier before interpreting scalar arithmetic"
        }
        _ => {
            "keep selected K scalar arithmetic diagnostic-only until f32/f64 arithmetic and storage bits are pinned"
        }
    };

    json!({
        "diagnostic_only": true,
        "claim_allowed": false,
        "policy": "Selected K ROPE scalar arithmetic frontier is diagnostic-only evidence for whether the reference scalar x0/x1/trig operation itself produces the selected F16 midpoint before tensor storage; it does not change runtime math or promote reference parity, A770 semantic quality, attention score residency, softmax residency, selected attention, resident KV, value-mix residency, full residency, performance, or completion",
        "classification": classification,
        "producer_storage_classification": producer_classification,
        "component": component,
        "x0_bits_u32": x0_bits,
        "x0_bits_hex": x0_bits.map(|bits| u32_bits_hex(bits as u32)),
        "x1_bits_u32": x1_bits,
        "x1_bits_hex": x1_bits.map(|bits| u32_bits_hex(bits as u32)),
        "cos_theta_bits_u32": cos_theta_bits,
        "cos_theta_bits_hex": cos_theta_bits.map(|bits| u32_bits_hex(bits as u32)),
        "sin_theta_bits_u32": sin_theta_bits,
        "sin_theta_bits_hex": sin_theta_bits.map(|bits| u32_bits_hex(bits as u32)),
        "term0_bits_u32": term0_bits,
        "term0_bits_hex": term0_bits.map(|bits| u32_bits_hex(bits as u32)),
        "term1_bits_u32": term1_bits,
        "term1_bits_hex": term1_bits.map(|bits| u32_bits_hex(bits as u32)),
        "arithmetic_replay_bits_u32": arithmetic_replay_bits,
        "arithmetic_replay_bits_hex": arithmetic_replay_bits.map(|bits| u32_bits_hex(bits as u32)),
        "producer_before_store_bits_u32": before_bits,
        "producer_before_store_bits_hex": before_bits.map(|bits| u32_bits_hex(bits as u32)),
        "storage_source_bits_u32": storage_bits,
        "storage_source_bits_hex": storage_bits.map(|bits| u32_bits_hex(bits as u32)),
        "direct_source_bits_u32": direct_bits,
        "direct_source_bits_hex": direct_bits.map(|bits| u32_bits_hex(bits as u32)),
        "arithmetic_replay_matches_before_store": arithmetic_replay_matches_before,
        "arithmetic_replay_matches_storage": arithmetic_replay_matches_storage,
        "before_store_matches_storage": before_matches_storage,
        "storage_matches_direct": storage_matches_direct,
        "scalar_record": scalar_record.cloned().unwrap_or(Value::Null),
        "blocked_reasons": blocked_reasons,
        "next_diagnostic": next_diagnostic,
    })
}

fn attention_norm_f64_selected_k_rope_direct_expression_frontier(
    selected_k_rope_scalar_arithmetic_frontier: &Value,
) -> Value {
    let scalar_classification = selected_k_rope_scalar_arithmetic_frontier
        .pointer("/classification")
        .and_then(Value::as_str);
    let scalar_record = selected_k_rope_scalar_arithmetic_frontier
        .pointer("/scalar_record")
        .filter(|record| !record.is_null());
    let component =
        scalar_record.and_then(|record| record.pointer("/component")).and_then(Value::as_str);
    let term_split_bits = scalar_record
        .and_then(|record| value_u64(record, "/term_split_replay_bits_u32"))
        .or_else(|| {
            scalar_record.and_then(|record| value_u64(record, "/arithmetic_replay_bits_u32"))
        })
        .or_else(|| {
            value_u64(selected_k_rope_scalar_arithmetic_frontier, "/arithmetic_replay_bits_u32")
        });
    let direct_expression_bits = scalar_record
        .and_then(|record| value_u64(record, "/direct_expression_bits_u32"))
        .or_else(|| scalar_record.and_then(|record| value_u64(record, "/before_store_bits_u32")))
        .or_else(|| {
            value_u64(selected_k_rope_scalar_arithmetic_frontier, "/producer_before_store_bits_u32")
        });
    let fma_x0_product_contracted_bits =
        scalar_record.and_then(|record| value_u64(record, "/fma_x0_product_contracted_bits_u32"));
    let fma_x1_product_contracted_bits =
        scalar_record.and_then(|record| value_u64(record, "/fma_x1_product_contracted_bits_u32"));
    let storage_bits =
        value_u64(selected_k_rope_scalar_arithmetic_frontier, "/storage_source_bits_u32");
    let active_frontier = matches!(
        scalar_classification,
        Some("selected_k_rope_scalar_term_split_replay_differs_from_before_store")
            | Some("selected_k_rope_scalar_arithmetic_replay_pins_midpoint")
    );
    let direct_matches_term_split =
        direct_expression_bits.zip(term_split_bits).is_some_and(|(left, right)| left == right);
    let direct_matches_x0_product_contracted = direct_expression_bits
        .zip(fma_x0_product_contracted_bits)
        .is_some_and(|(left, right)| left == right);
    let direct_matches_x1_product_contracted = direct_expression_bits
        .zip(fma_x1_product_contracted_bits)
        .is_some_and(|(left, right)| left == right);
    let direct_matches_storage =
        direct_expression_bits.zip(storage_bits).is_some_and(|(left, right)| left == right);

    let mut blocked_reasons = Vec::<String>::new();
    if !active_frontier {
        blocked_reasons.push("selected_k_rope_scalar_arithmetic_frontier_not_active".to_string());
    }
    if scalar_record.is_none() {
        blocked_reasons.push("selected_k_rope_scalar_record_missing".to_string());
    }
    if component.is_none() {
        blocked_reasons.push("selected_k_rope_scalar_component_missing".to_string());
    }
    if term_split_bits.is_none() {
        blocked_reasons.push("selected_k_rope_term_split_replay_bits_missing".to_string());
    }
    if direct_expression_bits.is_none() {
        blocked_reasons.push("selected_k_rope_direct_expression_bits_missing".to_string());
    }
    if fma_x0_product_contracted_bits.is_none() {
        blocked_reasons.push("selected_k_rope_fma_x0_product_contracted_bits_missing".to_string());
    }
    if fma_x1_product_contracted_bits.is_none() {
        blocked_reasons.push("selected_k_rope_fma_x1_product_contracted_bits_missing".to_string());
    }
    blocked_reasons.sort_unstable();
    blocked_reasons.dedup();

    let classification = if !active_frontier {
        "selected_k_rope_direct_expression_not_active_frontier"
    } else if scalar_record.is_none()
        || component.is_none()
        || term_split_bits.is_none()
        || direct_expression_bits.is_none()
        || fma_x0_product_contracted_bits.is_none()
        || fma_x1_product_contracted_bits.is_none()
    {
        "selected_k_rope_direct_expression_inputs_missing"
    } else if direct_matches_term_split {
        "selected_k_rope_direct_expression_matches_term_split"
    } else if direct_matches_x0_product_contracted {
        "selected_k_rope_direct_expression_matches_x0_product_contracted"
    } else if direct_matches_x1_product_contracted {
        "selected_k_rope_direct_expression_matches_x1_product_contracted"
    } else {
        "selected_k_rope_direct_expression_contraction_unpinned"
    };

    let next_diagnostic = match classification {
        "selected_k_rope_direct_expression_matches_term_split" => {
            "the selected reference ROPE direct expression matches term-split replay; inspect scalar input/trig source drift before runtime math changes"
        }
        "selected_k_rope_direct_expression_matches_x0_product_contracted" => {
            "the selected reference ROPE direct expression matches x0-product contraction; compare Rust ROPE contraction policy before runtime math changes"
        }
        "selected_k_rope_direct_expression_matches_x1_product_contracted" => {
            "the selected reference ROPE direct expression matches x1-product contraction; compare Rust ROPE contraction policy before runtime math changes"
        }
        "selected_k_rope_direct_expression_contraction_unpinned" => {
            "extend the selected K ROPE scalar probe with additional expression variants before changing runtime math"
        }
        "selected_k_rope_direct_expression_inputs_missing" => {
            "rerun the selected K scalar probe with term-split, direct-expression, and contracted-expression bit fields"
        }
        "selected_k_rope_direct_expression_not_active_frontier" => {
            "pin the selected K scalar arithmetic frontier before interpreting direct-expression contraction policy"
        }
        _ => {
            "keep selected K direct-expression policy diagnostic-only until scalar bits are pinned"
        }
    };

    json!({
        "diagnostic_only": true,
        "claim_allowed": false,
        "policy": "Selected K ROPE direct-expression frontier is diagnostic-only evidence for deciding whether the reference scalar midpoint comes from term-split replay, a contracted product form, or another expression policy; it does not change runtime math or promote reference parity, A770 semantic quality, attention score residency, softmax residency, selected attention, resident KV, value-mix residency, full residency, performance, or completion",
        "classification": classification,
        "scalar_arithmetic_classification": scalar_classification,
        "component": component,
        "term_split_replay_bits_u32": term_split_bits,
        "term_split_replay_bits_hex": term_split_bits.map(|bits| u32_bits_hex(bits as u32)),
        "direct_expression_bits_u32": direct_expression_bits,
        "direct_expression_bits_hex": direct_expression_bits.map(|bits| u32_bits_hex(bits as u32)),
        "fma_x0_product_contracted_bits_u32": fma_x0_product_contracted_bits,
        "fma_x0_product_contracted_bits_hex": fma_x0_product_contracted_bits.map(|bits| u32_bits_hex(bits as u32)),
        "fma_x1_product_contracted_bits_u32": fma_x1_product_contracted_bits,
        "fma_x1_product_contracted_bits_hex": fma_x1_product_contracted_bits.map(|bits| u32_bits_hex(bits as u32)),
        "storage_source_bits_u32": storage_bits,
        "storage_source_bits_hex": storage_bits.map(|bits| u32_bits_hex(bits as u32)),
        "direct_expression_matches_term_split": direct_matches_term_split,
        "direct_expression_matches_x0_product_contracted": direct_matches_x0_product_contracted,
        "direct_expression_matches_x1_product_contracted": direct_matches_x1_product_contracted,
        "direct_expression_matches_storage": direct_matches_storage,
        "scalar_record": scalar_record.cloned().unwrap_or(Value::Null),
        "blocked_reasons": blocked_reasons,
        "next_diagnostic": next_diagnostic,
    })
}

fn attention_norm_f64_selected_k_rope_rust_expression_policy_frontier(
    selected_k_rope_direct_expression_frontier: &Value,
    rust_records: &BTreeMap<String, RustTraceRecord>,
) -> Value {
    let reference_classification = selected_k_rope_direct_expression_frontier
        .pointer("/classification")
        .and_then(Value::as_str);
    let scalar_record = selected_k_rope_direct_expression_frontier
        .pointer("/scalar_record")
        .filter(|record| !record.is_null());
    let layer =
        scalar_record.and_then(|record| value_u64(record, "/layer")).map(|value| value as usize);
    let kv_head =
        scalar_record.and_then(|record| value_u64(record, "/kv_head")).map(|value| value as usize);
    let token =
        scalar_record.and_then(|record| value_u64(record, "/token")).map(|value| value as usize);
    let dim =
        scalar_record.and_then(|record| value_u64(record, "/dim")).map(|value| value as usize);
    let paired_dim = scalar_record
        .and_then(|record| value_u64(record, "/paired_dim"))
        .map(|value| value as usize);
    let component =
        scalar_record.and_then(|record| record.pointer("/component")).and_then(Value::as_str);
    let cos_theta_bits = scalar_record.and_then(|record| value_u64(record, "/cos_theta_bits_u32"));
    let sin_theta_bits = scalar_record.and_then(|record| value_u64(record, "/sin_theta_bits_u32"));
    let reference_direct_bits =
        value_u64(selected_k_rope_direct_expression_frontier, "/direct_expression_bits_u32");
    let reference_term_split_bits =
        value_u64(selected_k_rope_direct_expression_frontier, "/term_split_replay_bits_u32");
    let reference_x0_contracted_bits = value_u64(
        selected_k_rope_direct_expression_frontier,
        "/fma_x0_product_contracted_bits_u32",
    );
    let reference_x1_contracted_bits = value_u64(
        selected_k_rope_direct_expression_frontier,
        "/fma_x1_product_contracted_bits_u32",
    );

    let projection_stage =
        kv_head.map(|head| format!("attention_k_projection_kv_head{head}_ref_layout"));
    let before_store_stage =
        kv_head.map(|head| format!("attention_k_before_cache_store_kv_head{head}_ref_layout"));
    let projection_record = projection_stage.as_ref().and_then(|stage| rust_records.get(stage));
    let before_store_record = before_store_stage.as_ref().and_then(|stage| rust_records.get(stage));
    let dim_count = projection_record.and_then(|record| record.shape.first().copied());
    let token_count = projection_record.and_then(|record| record.shape.get(1).copied());
    let selected_index =
        dim.zip(token_count).zip(token).map(|((dim, tokens), token)| dim * tokens + token);
    let paired_index =
        paired_dim.zip(token_count).zip(token).map(|((dim, tokens), token)| dim * tokens + token);
    let rust_x0 = projection_record
        .zip(selected_index)
        .and_then(|(record, index)| record.first_values.get(index).copied());
    let rust_x1 = projection_record
        .zip(paired_index)
        .and_then(|(record, index)| record.first_values.get(index).copied());
    let rust_output = before_store_record
        .zip(selected_index)
        .and_then(|(record, index)| record.first_values.get(index).copied());
    let cos_theta = cos_theta_bits.map(|bits| f32::from_bits(bits as u32));
    let sin_theta = sin_theta_bits.map(|bits| f32::from_bits(bits as u32));
    let lower_component = component == Some("lower_x0_cos_minus_x1_sin");
    let upper_component = component == Some("upper_x0_sin_plus_x1_cos");

    let rust_variants =
        match (rust_x0, rust_x1, cos_theta, sin_theta, lower_component, upper_component) {
            (Some(x0), Some(x1), Some(cos), Some(sin), true, _) => {
                let term0 = x0 * cos;
                let term1 = x1 * sin;
                Some((term0 - term1, x0.mul_add(cos, -term1), (-x1).mul_add(sin, term0)))
            }
            (Some(x0), Some(x1), Some(cos), Some(sin), _, true) => {
                let term0 = x0 * sin;
                let term1 = x1 * cos;
                Some((term0 + term1, x0.mul_add(sin, term1), x1.mul_add(cos, term0)))
            }
            _ => None,
        };
    let rust_term_split_bits = rust_variants.map(|(term_split, _, _)| term_split.to_bits() as u64);
    let rust_x0_contracted_bits =
        rust_variants.map(|(_, x0_contracted, _)| x0_contracted.to_bits() as u64);
    let rust_x1_contracted_bits =
        rust_variants.map(|(_, _, x1_contracted)| x1_contracted.to_bits() as u64);
    let rust_output_bits = rust_output.map(|value| value.to_bits() as u64);

    let rust_output_matches_reference_direct =
        rust_output_bits.zip(reference_direct_bits).is_some_and(|(left, right)| left == right);
    let rust_output_matches_term_split =
        rust_output_bits.zip(rust_term_split_bits).is_some_and(|(left, right)| left == right);
    let rust_output_matches_x0_contracted =
        rust_output_bits.zip(rust_x0_contracted_bits).is_some_and(|(left, right)| left == right);
    let rust_output_matches_x1_contracted =
        rust_output_bits.zip(rust_x1_contracted_bits).is_some_and(|(left, right)| left == right);
    let rust_term_split_matches_reference_term_split = rust_term_split_bits
        .zip(reference_term_split_bits)
        .is_some_and(|(left, right)| left == right);
    let rust_x0_contracted_matches_reference_x0 = rust_x0_contracted_bits
        .zip(reference_x0_contracted_bits)
        .is_some_and(|(left, right)| left == right);
    let rust_x1_contracted_matches_reference_x1 = rust_x1_contracted_bits
        .zip(reference_x1_contracted_bits)
        .is_some_and(|(left, right)| left == right);

    let active_frontier = matches!(
        reference_classification,
        Some("selected_k_rope_direct_expression_matches_x0_product_contracted")
            | Some("selected_k_rope_direct_expression_matches_x1_product_contracted")
            | Some("selected_k_rope_direct_expression_matches_term_split")
    );
    let mut blocked_reasons = Vec::<String>::new();
    if !active_frontier {
        blocked_reasons.push("selected_k_rope_direct_expression_frontier_not_active".to_string());
    }
    if scalar_record.is_none() {
        blocked_reasons.push("selected_k_rope_reference_scalar_record_missing".to_string());
    }
    if layer.is_none()
        || kv_head.is_none()
        || token.is_none()
        || dim.is_none()
        || paired_dim.is_none()
    {
        blocked_reasons.push("selected_k_rope_reference_position_identity_missing".to_string());
    }
    if component.is_none() || (!lower_component && !upper_component) {
        blocked_reasons.push("selected_k_rope_reference_component_missing".to_string());
    }
    if cos_theta_bits.is_none() || sin_theta_bits.is_none() {
        blocked_reasons.push("selected_k_rope_reference_trig_bits_missing".to_string());
    }
    if projection_record.is_none() {
        blocked_reasons.push("rust_selected_k_projection_record_missing".to_string());
    }
    if before_store_record.is_none() {
        blocked_reasons.push("rust_selected_k_before_store_record_missing".to_string());
    }
    if selected_index.is_none() || paired_index.is_none() {
        blocked_reasons.push("rust_selected_k_index_missing".to_string());
    }
    if rust_x0.is_none() || rust_x1.is_none() {
        blocked_reasons.push("rust_selected_k_projection_inputs_missing".to_string());
    }
    if rust_output.is_none() {
        blocked_reasons.push("rust_selected_k_before_store_output_missing".to_string());
    }
    if rust_variants.is_none() {
        blocked_reasons.push("rust_selected_k_expression_variants_missing".to_string());
    }
    blocked_reasons.sort_unstable();
    blocked_reasons.dedup();

    let classification = if !active_frontier {
        "rust_selected_k_rope_expression_not_active_frontier"
    } else if !blocked_reasons.is_empty() {
        "rust_selected_k_rope_expression_inputs_missing"
    } else if rust_output_matches_reference_direct && rust_output_matches_x0_contracted {
        "rust_selected_k_rope_expression_matches_reference_x0_product_contracted"
    } else if rust_output_matches_reference_direct && rust_output_matches_x1_contracted {
        "rust_selected_k_rope_expression_matches_reference_x1_product_contracted"
    } else if rust_output_matches_reference_direct && rust_output_matches_term_split {
        "rust_selected_k_rope_expression_matches_reference_term_split"
    } else if rust_output_matches_term_split {
        "rust_selected_k_rope_expression_matches_term_split_not_reference"
    } else if rust_output_matches_x0_contracted {
        "rust_selected_k_rope_expression_matches_x0_product_contracted_not_reference"
    } else if rust_output_matches_x1_contracted {
        "rust_selected_k_rope_expression_matches_x1_product_contracted_not_reference"
    } else {
        "rust_selected_k_rope_expression_policy_unpinned"
    };

    let next_diagnostic = match classification {
        "rust_selected_k_rope_expression_matches_reference_x0_product_contracted"
        | "rust_selected_k_rope_expression_matches_reference_x1_product_contracted"
        | "rust_selected_k_rope_expression_matches_reference_term_split" => {
            "Rust selected-K ROPE expression policy matches the reference direct-expression policy for this scalar; rerun downstream score and probability diagnostics before runtime math changes"
        }
        "rust_selected_k_rope_expression_matches_term_split_not_reference"
        | "rust_selected_k_rope_expression_matches_x0_product_contracted_not_reference"
        | "rust_selected_k_rope_expression_matches_x1_product_contracted_not_reference" => {
            "Rust selected-K ROPE expression policy differs from the reference direct-expression policy; pin this scalar in Rust trace capture before any runtime fix"
        }
        "rust_selected_k_rope_expression_policy_unpinned" => {
            "extend Rust selected-K ROPE expression variants before changing runtime math"
        }
        "rust_selected_k_rope_expression_inputs_missing" => {
            "rerun Rust trace capture with full selected K projection and before-store samples"
        }
        "rust_selected_k_rope_expression_not_active_frontier" => {
            "pin reference selected-K direct-expression frontier before comparing Rust policy"
        }
        _ => {
            "keep Rust selected-K ROPE expression policy diagnostic-only until scalar bits are pinned"
        }
    };

    let mut object = serde_json::Map::new();
    object.insert("diagnostic_only".to_string(), json!(true));
    object.insert("claim_allowed".to_string(), json!(false));
    object.insert("policy".to_string(), json!("Rust selected-K ROPE expression policy frontier is diagnostic-only evidence comparing existing Rust trace samples against the reference selected-K direct-expression policy; it does not change runtime math or promote reference parity, A770 semantic quality, attention score residency, softmax residency, selected attention, resident KV, value-mix residency, full residency, performance, or completion"));
    object.insert("classification".to_string(), json!(classification));
    object.insert(
        "reference_direct_expression_classification".to_string(),
        json!(reference_classification),
    );
    object.insert("layer".to_string(), json!(layer));
    object.insert("kv_head".to_string(), json!(kv_head));
    object.insert("token".to_string(), json!(token));
    object.insert("dim".to_string(), json!(dim));
    object.insert("paired_dim".to_string(), json!(paired_dim));
    object.insert("component".to_string(), json!(component));
    object.insert("projection_stage".to_string(), json!(projection_stage));
    object.insert("before_store_stage".to_string(), json!(before_store_stage));
    object.insert("dim_count".to_string(), json!(dim_count));
    object.insert("token_count".to_string(), json!(token_count));
    object.insert("selected_index".to_string(), json!(selected_index));
    object.insert("paired_index".to_string(), json!(paired_index));
    object.insert("rust_x0_bits_u32".to_string(), json!(rust_x0.map(|value| value.to_bits())));
    object.insert(
        "rust_x0_bits_hex".to_string(),
        json!(rust_x0.map(|value| u32_bits_hex(value.to_bits()))),
    );
    object.insert("rust_x1_bits_u32".to_string(), json!(rust_x1.map(|value| value.to_bits())));
    object.insert(
        "rust_x1_bits_hex".to_string(),
        json!(rust_x1.map(|value| u32_bits_hex(value.to_bits()))),
    );
    object.insert("cos_theta_bits_u32".to_string(), json!(cos_theta_bits));
    object.insert(
        "cos_theta_bits_hex".to_string(),
        json!(cos_theta_bits.map(|bits| u32_bits_hex(bits as u32))),
    );
    object.insert("sin_theta_bits_u32".to_string(), json!(sin_theta_bits));
    object.insert(
        "sin_theta_bits_hex".to_string(),
        json!(sin_theta_bits.map(|bits| u32_bits_hex(bits as u32))),
    );
    object.insert("rust_term_split_bits_u32".to_string(), json!(rust_term_split_bits));
    object.insert(
        "rust_term_split_bits_hex".to_string(),
        json!(rust_term_split_bits.map(|bits| u32_bits_hex(bits as u32))),
    );
    object
        .insert("rust_x0_product_contracted_bits_u32".to_string(), json!(rust_x0_contracted_bits));
    object.insert(
        "rust_x0_product_contracted_bits_hex".to_string(),
        json!(rust_x0_contracted_bits.map(|bits| u32_bits_hex(bits as u32))),
    );
    object
        .insert("rust_x1_product_contracted_bits_u32".to_string(), json!(rust_x1_contracted_bits));
    object.insert(
        "rust_x1_product_contracted_bits_hex".to_string(),
        json!(rust_x1_contracted_bits.map(|bits| u32_bits_hex(bits as u32))),
    );
    object.insert("rust_before_store_bits_u32".to_string(), json!(rust_output_bits));
    object.insert(
        "rust_before_store_bits_hex".to_string(),
        json!(rust_output_bits.map(|bits| u32_bits_hex(bits as u32))),
    );
    object.insert("reference_direct_expression_bits_u32".to_string(), json!(reference_direct_bits));
    object.insert(
        "reference_direct_expression_bits_hex".to_string(),
        json!(reference_direct_bits.map(|bits| u32_bits_hex(bits as u32))),
    );
    object.insert("reference_term_split_bits_u32".to_string(), json!(reference_term_split_bits));
    object.insert(
        "reference_term_split_bits_hex".to_string(),
        json!(reference_term_split_bits.map(|bits| u32_bits_hex(bits as u32))),
    );
    object.insert(
        "reference_x0_product_contracted_bits_u32".to_string(),
        json!(reference_x0_contracted_bits),
    );
    object.insert(
        "reference_x0_product_contracted_bits_hex".to_string(),
        json!(reference_x0_contracted_bits.map(|bits| u32_bits_hex(bits as u32))),
    );
    object.insert(
        "reference_x1_product_contracted_bits_u32".to_string(),
        json!(reference_x1_contracted_bits),
    );
    object.insert(
        "reference_x1_product_contracted_bits_hex".to_string(),
        json!(reference_x1_contracted_bits.map(|bits| u32_bits_hex(bits as u32))),
    );
    object.insert(
        "rust_output_matches_reference_direct".to_string(),
        json!(rust_output_matches_reference_direct),
    );
    object.insert(
        "rust_output_matches_term_split".to_string(),
        json!(rust_output_matches_term_split),
    );
    object.insert(
        "rust_output_matches_x0_product_contracted".to_string(),
        json!(rust_output_matches_x0_contracted),
    );
    object.insert(
        "rust_output_matches_x1_product_contracted".to_string(),
        json!(rust_output_matches_x1_contracted),
    );
    object.insert(
        "rust_term_split_matches_reference_term_split".to_string(),
        json!(rust_term_split_matches_reference_term_split),
    );
    object.insert(
        "rust_x0_contracted_matches_reference_x0".to_string(),
        json!(rust_x0_contracted_matches_reference_x0),
    );
    object.insert(
        "rust_x1_contracted_matches_reference_x1".to_string(),
        json!(rust_x1_contracted_matches_reference_x1),
    );
    object.insert("blocked_reasons".to_string(), json!(blocked_reasons));
    object.insert("next_diagnostic".to_string(), json!(next_diagnostic));
    Value::Object(object)
}

fn json_array_u64(value: &Value, pointer: &str, index: usize) -> Option<u64> {
    value.pointer(pointer).and_then(Value::as_array)?.get(index)?.as_u64()
}

fn parse_kcur_history_kv_head(stage: &str) -> Option<u64> {
    let suffix = stage.strip_prefix("kcur_history_kv_head")?;
    let digits = suffix.chars().take_while(|ch| ch.is_ascii_digit()).collect::<String>();
    if digits.is_empty() { None } else { digits.parse::<u64>().ok() }
}

fn raw_first_value_decimal_for_record(
    text: &str,
    record_name: &str,
    index: usize,
) -> Option<String> {
    let name_json = serde_json::to_string(record_name).ok()?;
    let name_pos = find_json_key_string_value(text, "name", &name_json)?;
    raw_array_value_for_record_at(text, name_pos, "first_values", index)
}

fn raw_first_value_u32_for_record(
    text: &str,
    record_name: &str,
    key: &str,
    index: usize,
) -> Option<u32> {
    let name_json = serde_json::to_string(record_name).ok()?;
    let name_pos = find_json_key_string_value(text, "name", &name_json)?;
    raw_array_value_for_record_at(text, name_pos, key, index)?.parse::<u32>().ok()
}

fn raw_first_value_u64_for_record(
    text: &str,
    record_name: &str,
    key: &str,
    index: usize,
) -> Option<u64> {
    let name_json = serde_json::to_string(record_name).ok()?;
    let name_pos = find_json_key_string_value(text, "name", &name_json)?;
    raw_array_value_for_record_at(text, name_pos, key, index)?.parse::<u64>().ok()
}

fn raw_array_value_for_record_at(
    text: &str,
    record_start: usize,
    key: &str,
    index: usize,
) -> Option<String> {
    let key_json = serde_json::to_string(key).ok()?;
    let array_key = text[record_start..].find(&key_json)? + record_start;
    let array_start = text[array_key..].find('[')? + array_key + 1;
    let array_end = text[array_start..].find(']')? + array_start;
    text[array_start..array_end].split(',').nth(index).map(|raw| raw.trim().to_string())
}

fn find_json_key_string_value(text: &str, key: &str, value_json: &str) -> Option<usize> {
    let key_json = serde_json::to_string(key).ok()?;
    let mut search_start = 0usize;
    while let Some(relative_pos) = text[search_start..].find(&key_json) {
        let key_pos = search_start + relative_pos;
        let mut cursor = key_pos + key_json.len();
        cursor = skip_ascii_whitespace(text, cursor);
        if text.as_bytes().get(cursor).copied() != Some(b':') {
            search_start = key_pos + key_json.len();
            continue;
        }
        cursor = skip_ascii_whitespace(text, cursor + 1);
        if text[cursor..].starts_with(value_json) {
            return Some(key_pos);
        }
        search_start = key_pos + key_json.len();
    }
    None
}

fn skip_ascii_whitespace(text: &str, mut cursor: usize) -> usize {
    while text.as_bytes().get(cursor).is_some_and(|byte| byte.is_ascii_whitespace()) {
        cursor += 1;
    }
    cursor
}

fn f32_bits_hex(value: f32) -> String {
    format!("0x{:08x}", value.to_bits())
}

fn u32_bits_hex(bits: u32) -> String {
    format!("0x{bits:08x}")
}

fn attention_norm_f64_score_history_residual_frontier(
    score_raw_history: &Value,
    score_raw_live_tail: &Value,
    score_input_attribution: &Value,
    key_score_input_delta: &Value,
    key_score_input_history_delta: &Value,
    query_score_input_history_delta: &Value,
    score_key_history_effect: &Value,
    score_kcur_f16_effect: &Value,
    key_kcur_cache_boundary: &Value,
    query_rope_delta: &Value,
) -> Value {
    let raw_material_count = value_u64(score_raw_history, "/material_mismatch_count").unwrap_or(0);
    let raw_missing_count = value_u64(score_raw_history, "/missing_rust_head_count").unwrap_or(0);
    let raw_live_material_count =
        value_u64(score_raw_live_tail, "/live_material_mismatch_count").unwrap_or(0);
    let score_input_missing_count =
        value_u64(score_input_attribution, "/missing_input_count").unwrap_or(0);
    let score_input_compared_count =
        value_u64(score_input_attribution, "/compared_count").unwrap_or(0);
    let key_current_missing_count =
        value_u64(key_score_input_delta, "/missing_head_count").unwrap_or(0);
    let key_history_missing_count =
        value_u64(key_score_input_history_delta, "/missing_head_count").unwrap_or(0);
    let query_history_missing_count =
        value_u64(query_score_input_history_delta, "/missing_head_count").unwrap_or(0);
    let key_history_bucket_mismatch_count =
        value_u64(key_score_input_history_delta, "/total_f16_bucket_mismatch_count").unwrap_or(0);
    let query_history_bucket_mismatch_count =
        value_u64(query_score_input_history_delta, "/total_f16_bucket_mismatch_count").unwrap_or(0);
    let key_history_max_abs =
        value_f64(key_score_input_history_delta, "/max_abs_delta").unwrap_or(0.0);
    let query_history_max_abs =
        value_f64(query_score_input_history_delta, "/max_abs_delta").unwrap_or(0.0);
    let key_current_max_abs = value_f64(key_score_input_delta, "/max_abs_delta").unwrap_or(0.0);
    let score_key_best_abs =
        value_f64(score_key_history_effect, "/max_best_abs_delta").unwrap_or(0.0);
    let score_key_actual_abs =
        value_f64(score_key_history_effect, "/max_actual_score_delta_abs").unwrap_or(0.0);
    let score_kcur_shift_abs =
        value_f64(score_kcur_f16_effect, "/max_shift_explanation_abs_delta").unwrap_or(0.0);
    let score_kcur_actual_abs =
        value_f64(score_kcur_f16_effect, "/max_actual_score_delta_abs").unwrap_or(0.0);
    let key_kcur_boundary_clean =
        key_kcur_cache_boundary.pointer("/classification").and_then(Value::as_str)
            == Some("key_kcur_cache_boundary_clean");
    let query_rope_max_abs = value_f64(query_rope_delta, "/delta/max_abs_delta")
        .or_else(|| value_f64(query_rope_delta, "/max_abs_delta"))
        .unwrap_or(0.0);
    let score_history_drift_present = raw_material_count > 0 || raw_live_material_count > 0;
    let missing_inputs = raw_missing_count
        + score_input_missing_count
        + key_current_missing_count
        + key_history_missing_count
        + query_history_missing_count;
    let qk_history_bucket_drift =
        key_history_bucket_mismatch_count > 0 || query_history_bucket_mismatch_count > 0;
    let qk_history_numeric_drift = key_history_max_abs > 1.0e-6 || query_history_max_abs > 1.0e-6;
    let current_key_numeric_drift = key_current_max_abs > 1.0e-6;
    let score_key_effect_residual = score_key_best_abs > 1.0e-6;
    let score_kcur_effect_residual = score_kcur_shift_abs > 1.0e-6;

    let classification = if missing_inputs > 0 || score_input_compared_count == 0 {
        "f64_score_history_frontier_missing_inputs"
    } else if !score_history_drift_present {
        "f64_score_history_frontier_clean"
    } else if qk_history_bucket_drift {
        "f64_score_history_frontier_qk_score_input_history_bucket_drift"
    } else if qk_history_numeric_drift {
        "f64_score_history_frontier_qk_score_input_history_numeric_drift"
    } else if current_key_numeric_drift {
        "f64_score_history_frontier_current_key_score_input_drift"
    } else if score_key_effect_residual || score_kcur_effect_residual {
        "f64_score_history_frontier_qk_f16_probe_residual"
    } else {
        "f64_score_history_frontier_raw_score_residual_unpinned"
    };

    let next_diagnostic = match classification {
        "f64_score_history_frontier_missing_inputs" => {
            "capture missing f64 score, Q/K score-input, and score-effect rows before changing score math"
        }
        "f64_score_history_frontier_clean" => {
            "raw f64 score history is clean; inspect probability formation or value-mix source rows"
        }
        "f64_score_history_frontier_qk_score_input_history_bucket_drift" => {
            "localize selected f64 score row Q/K score-input bucket drift before changing score accumulation or softmax"
        }
        "f64_score_history_frontier_qk_score_input_history_numeric_drift" => {
            "localize selected f64 score row Q/K score-input numeric drift before changing score accumulation or softmax"
        }
        "f64_score_history_frontier_current_key_score_input_drift" => {
            "localize current key score-input drift before changing raw score math"
        }
        "f64_score_history_frontier_qk_f16_probe_residual" => {
            "pin the remaining Q/K F16 score-input residual before changing production score math"
        }
        _ => {
            "drill into the first material f64 raw score row before changing score, softmax, or value-mix math"
        }
    };

    json!({
        "diagnostic_only": true,
        "claim_allowed": false,
        "policy": "F64 raw score-history residual frontier is diagnostic-only evidence for choosing the next score-formation optic after f64 attention RMSNorm clears the selected K bucket; it does not promote runtime math changes, reference parity, A770 semantic quality, attention score residency, selected attention, resident KV, softmax residency, value-mix residency, full residency, performance, or completion",
        "classification": classification,
        "score_history_drift_present": score_history_drift_present,
        "missing_inputs": missing_inputs,
        "raw_material_mismatch_count": raw_material_count,
        "raw_live_material_mismatch_count": raw_live_material_count,
        "raw_missing_rust_head_count": raw_missing_count,
        "score_input_compared_count": score_input_compared_count,
        "score_input_missing_count": score_input_missing_count,
        "key_current_missing_count": key_current_missing_count,
        "key_history_missing_count": key_history_missing_count,
        "query_history_missing_count": query_history_missing_count,
        "key_history_f16_bucket_mismatch_count": key_history_bucket_mismatch_count,
        "query_history_f16_bucket_mismatch_count": query_history_bucket_mismatch_count,
        "key_history_max_abs_delta": key_history_max_abs,
        "query_history_max_abs_delta": query_history_max_abs,
        "key_current_max_abs_delta": key_current_max_abs,
        "score_key_history_best_variant_counts": score_key_history_effect.pointer("/best_variant_counts").cloned().unwrap_or(Value::Null),
        "score_key_history_max_actual_score_delta_abs": score_key_actual_abs,
        "score_key_history_max_best_abs_delta": score_key_best_abs,
        "score_kcur_f16_reference_best_counts": score_kcur_f16_effect.pointer("/reference_best_counts").cloned().unwrap_or(Value::Null),
        "score_kcur_f16_rust_best_counts": score_kcur_f16_effect.pointer("/rust_best_counts").cloned().unwrap_or(Value::Null),
        "score_kcur_f16_max_actual_score_delta_abs": score_kcur_actual_abs,
        "score_kcur_f16_max_shift_explanation_abs_delta": score_kcur_shift_abs,
        "key_kcur_cache_boundary_clean": key_kcur_boundary_clean,
        "query_rope_max_abs_delta": query_rope_max_abs,
        "first_material_score_head": compact_head_delta_row(score_raw_history.pointer("/first_material_head").unwrap_or(&Value::Null)),
        "first_live_material_score_head": compact_head_delta_row(score_raw_live_tail.pointer("/first_live_material_head").unwrap_or(&Value::Null)),
        "first_material_key_history_head": compact_head_delta_row(key_score_input_history_delta.pointer("/first_material_head").unwrap_or(&Value::Null)),
        "first_material_query_history_head": compact_head_delta_row(query_score_input_history_delta.pointer("/first_material_head").unwrap_or(&Value::Null)),
        "next_diagnostic": next_diagnostic,
    })
}

fn compact_head_delta_row(row: &Value) -> Value {
    if row.is_null() {
        return Value::Null;
    }

    json!({
        "head": row.pointer("/head").cloned().unwrap_or(Value::Null),
        "kv_head": row.pointer("/kv_head").cloned().unwrap_or(Value::Null),
        "status": row.pointer("/status").cloned().unwrap_or(Value::Null),
        "material_mismatch": row.pointer("/material_mismatch").cloned().unwrap_or(Value::Null),
        "reference_stage": row.pointer("/reference_stage").cloned().unwrap_or(Value::Null),
        "rust_stage": row.pointer("/rust_stage").cloned().unwrap_or(Value::Null),
        "delta": row.pointer("/delta").cloned().unwrap_or(Value::Null),
        "live_delta": row.pointer("/live_delta").cloned().unwrap_or(Value::Null),
        "scope": row.pointer("/scope").cloned().unwrap_or(Value::Null),
    })
}

fn first_material_mismatch_summary(
    reference_records: &[ReferenceTraceRecord],
    rust_records: &BTreeMap<String, RustTraceRecord>,
    mapping: &[(&str, &str)],
) -> Value {
    let mut first_material_mismatch = Value::Null;
    let mut compared_count = 0usize;
    let mut material_mismatch_count = 0usize;
    let mut scope_mismatch_count = 0usize;
    let mut missing_reference_count = 0usize;
    let mut missing_rust_count = 0usize;
    let mut first_scope_mismatch = Value::Null;

    for (reference_stage, rust_stage) in mapping {
        let candidates = reference_records
            .iter()
            .filter(|record| record.stage == *reference_stage)
            .collect::<Vec<_>>();
        let rust = rust_records.get(*rust_stage);
        let reference = rust
            .and_then(|rust| {
                candidates
                    .iter()
                    .copied()
                    .find(|record| record.nelements == rust.num_elements as u64)
            })
            .or_else(|| candidates.first().copied());

        if reference.is_none() {
            missing_reference_count += 1;
        }
        if rust.is_none() {
            missing_rust_count += 1;
        }

        let mut status = "missing";
        let mut rms_abs_delta = None::<f64>;
        let mut first_values_delta = Value::Null;
        let mut full_first_values_match = false;
        let mut rms_material = false;
        let mut rms_material_ignored_due_to_full_first_values_match = false;
        let mut material_mismatch = reference.is_none() || rust.is_none();
        let scope_mismatch = trace_scope_mismatch(reference, rust);
        let has_scope_mismatch = scope_mismatch.is_some();
        if let (Some(reference), Some(rust)) = (reference, rust) {
            compared_count += 1;
            let element_count_match = reference.nelements == rust.num_elements as u64;
            let dtype_match = trace_dtype_compatible(&reference.dtype, &rust.dtype);
            rms_abs_delta = reference.rms.map(|rms| (rms - rust.rms).abs());
            rms_material = rms_abs_delta.is_some_and(|delta| delta > 1.0e-4);
            if !reference.first_values.is_empty() && !rust.first_values.is_empty() {
                first_values_delta = compare_prefix(
                    &reference.first_values,
                    &rust.first_values,
                    reference.first_values.len().min(rust.first_values.len()),
                );
                full_first_values_match = reference.first_values.len() as u64
                    == reference.nelements
                    && rust.first_values.len() == rust.num_elements
                    && first_values_delta
                        .pointer("/count_match")
                        .and_then(Value::as_bool)
                        .unwrap_or(false)
                    && first_values_delta
                        .pointer("/sha256_match")
                        .and_then(Value::as_bool)
                        .unwrap_or(false);
            }
            if has_scope_mismatch {
                material_mismatch = false;
                status = "scope_mismatch";
            } else {
                rms_material_ignored_due_to_full_first_values_match =
                    rms_material && full_first_values_match;
                material_mismatch = !element_count_match
                    || !dtype_match
                    || (rms_material && !full_first_values_match);
                status = if material_mismatch { "material_mismatch" } else { "summary_match" };
            }
        }
        if has_scope_mismatch {
            scope_mismatch_count += 1;
        }
        if material_mismatch {
            material_mismatch_count += 1;
        }

        let row = json!({
            "reference_stage": reference_stage,
            "rust_stage": rust_stage,
            "status": status,
            "candidate_reference_records": candidates.len(),
            "reference": reference.map(reference_record_summary),
            "rust": rust.map(rust_record_summary),
            "rms_abs_delta": rms_abs_delta,
            "rms_material": rms_material,
            "full_first_values_match": full_first_values_match,
            "rms_material_ignored_due_to_full_first_values_match": rms_material_ignored_due_to_full_first_values_match,
            "first_values_delta": first_values_delta,
            "scope_mismatch": has_scope_mismatch,
            "scope": scope_mismatch,
            "material_mismatch": material_mismatch,
        });
        if has_scope_mismatch && first_scope_mismatch.is_null() {
            first_scope_mismatch = row.clone();
        }
        if material_mismatch && first_material_mismatch.is_null() {
            first_material_mismatch = row;
        }
    }

    json!({
        "diagnostic_only": true,
        "claim_allowed": false,
        "compared_stage_count": compared_count,
        "material_mismatch_count": material_mismatch_count,
        "scope_mismatch_count": scope_mismatch_count,
        "missing_reference_count": missing_reference_count,
        "missing_rust_count": missing_rust_count,
        "first_scope_mismatch": first_scope_mismatch,
        "first_material_mismatch": first_material_mismatch,
    })
}

fn value_u64(value: &Value, pointer: &str) -> Option<u64> {
    value.pointer(pointer).and_then(Value::as_u64)
}

fn prefix_token_relative_position(frontier: &Value, token: usize) -> Value {
    for pointer in [
        "/earliest_earlier_prefix_token",
        "/max_earlier_prefix_token",
        "/sampled_current_token_row",
    ] {
        let Some(row) = frontier.pointer(pointer) else {
            continue;
        };
        if row
            .pointer("/token")
            .and_then(Value::as_u64)
            .and_then(|value| usize::try_from(value).ok())
            == Some(token)
        {
            return row.pointer("/relative_position").cloned().unwrap_or(Value::Null);
        }
    }
    Value::Null
}

fn dim_major_record_token_delta(
    reference: &ReferenceTraceRecord,
    rust: &RustTraceRecord,
    token: usize,
) -> Result<Value> {
    let reference_dim_count = dim_major_dim_count(reference)?;
    let reference_token_count = dim_major_token_count(reference)?;
    let (rust_dim_count, rust_token_count) =
        rust_dim_major_shape_counts(rust).context("rust history shape is not dim-major")?;
    let reference_token = slice_dim_major_token(
        &reference.first_values,
        reference_dim_count,
        reference_token_count,
        token,
    )?;
    let rust_token =
        slice_dim_major_token(&rust.first_values, rust_dim_count, rust_token_count, token)?;
    let mut delta = compare_vectors(&reference_token, &rust_token);
    if let Some(object) = delta.as_object_mut() {
        object.insert("layout".to_string(), json!("dim_major_token_minor"));
        object.insert("token".to_string(), json!(token));
        object.insert("reference_dim_count".to_string(), json!(reference_dim_count));
        object.insert("reference_token_count".to_string(), json!(reference_token_count));
        object.insert("rust_dim_count".to_string(), json!(rust_dim_count));
        object.insert("rust_token_count".to_string(), json!(rust_token_count));
    }
    Ok(delta)
}

fn dim_major_record_token_f16_delta(
    reference: &ReferenceTraceRecord,
    rust: &RustTraceRecord,
    token: usize,
) -> Result<Value> {
    let reference_dim_count = dim_major_dim_count(reference)?;
    let reference_token_count = dim_major_token_count(reference)?;
    let (rust_dim_count, rust_token_count) =
        rust_dim_major_shape_counts(rust).context("rust history shape is not dim-major")?;
    let reference_token = slice_dim_major_token(
        &reference.first_values,
        reference_dim_count,
        reference_token_count,
        token,
    )?;
    let rust_token =
        slice_dim_major_token(&rust.first_values, rust_dim_count, rust_token_count, token)?;
    let mut delta = f16_bucket_delta(&reference_token, &rust_token);
    if let Some(object) = delta.as_object_mut() {
        object.insert("layout".to_string(), json!("dim_major_token_minor"));
        object.insert("token".to_string(), json!(token));
        object.insert("reference_dim_count".to_string(), json!(reference_dim_count));
        object.insert("reference_token_count".to_string(), json!(reference_token_count));
        object.insert("rust_dim_count".to_string(), json!(rust_dim_count));
        object.insert("rust_token_count".to_string(), json!(rust_token_count));
    }
    Ok(delta)
}

fn layer_prefix_ffn_norm_boundary(
    reference_records: &[ReferenceTraceRecord],
    rust_records: &[RustTraceRecord],
    frontier: &Value,
    layer: usize,
) -> Value {
    let targets = prefix_stage_targets(frontier);
    let reference_input =
        find_reference_trace_record(reference_records, "ffn_inp_history_ref_layout", Some(layer));
    let rust_input = find_rust_trace_record(
        rust_records,
        "post_attention_residual_history_ref_layout",
        Some(layer),
    );
    let reference_output =
        find_reference_trace_record(reference_records, "ffn_norm_history_ref_layout", Some(layer));
    let rust_output =
        find_rust_trace_record(rust_records, "post_ffn_norm_history_ref_layout", Some(layer));

    let mut rows = Vec::<Value>::new();
    let mut missing_stage_count = 0usize;
    let mut delta_unavailable_count = 0usize;
    let mut clean_input_material_output_count = 0usize;
    let mut material_output_count = 0usize;
    let mut first_clean_input_material_output = Value::Null;

    for (token, labels) in targets {
        let input_delta = reference_input.zip(rust_input).and_then(|(reference, rust)| {
            dim_major_record_token_delta(reference, rust, token).ok()
        });
        let output_delta = reference_output.zip(rust_output).and_then(|(reference, rust)| {
            dim_major_record_token_delta(reference, rust, token).ok()
        });
        let input_delta_unavailable =
            reference_input.is_some() && rust_input.is_some() && input_delta.is_none();
        let output_delta_unavailable =
            reference_output.is_some() && rust_output.is_some() && output_delta.is_none();
        let input_material = input_delta.as_ref().is_some_and(delta_has_material_numeric_delta);
        let output_material = output_delta.as_ref().is_some_and(delta_has_material_numeric_delta);
        let input_max_abs =
            input_delta.as_ref().map(|delta| delta_metric(delta, "/max_abs_delta")).unwrap_or(0.0);
        let output_max_abs =
            output_delta.as_ref().map(|delta| delta_metric(delta, "/max_abs_delta")).unwrap_or(0.0);
        let amplification_ratio =
            if input_max_abs > 0.0 { Some(output_max_abs / input_max_abs) } else { None };
        let clean_input_material_output = !input_material && output_material;
        let boundary_classification = if reference_input.is_none()
            || rust_input.is_none()
            || reference_output.is_none()
            || rust_output.is_none()
        {
            "missing_stage"
        } else if input_delta_unavailable || output_delta_unavailable {
            "delta_unavailable"
        } else if clean_input_material_output {
            "ffn_norm_output_amplification"
        } else if input_material && output_material {
            "ffn_input_already_material"
        } else if input_material {
            "ffn_input_material_without_output"
        } else {
            "ffn_norm_boundary_clean"
        };

        if reference_input.is_none()
            || rust_input.is_none()
            || reference_output.is_none()
            || rust_output.is_none()
        {
            missing_stage_count += 1;
        }
        if input_delta_unavailable || output_delta_unavailable {
            delta_unavailable_count += 1;
        }
        if output_material {
            material_output_count += 1;
        }
        if clean_input_material_output {
            clean_input_material_output_count += 1;
        }

        let row = json!({
            "layer": layer,
            "token": token,
            "labels": labels,
            "relative_position": prefix_token_relative_position(frontier, token),
            "reference_input_stage": "ffn_inp_history_ref_layout",
            "rust_input_stage": "post_attention_residual_history_ref_layout",
            "reference_output_stage": "ffn_norm_history_ref_layout",
            "rust_output_stage": "post_ffn_norm_history_ref_layout",
            "input_present": reference_input.is_some() && rust_input.is_some(),
            "output_present": reference_output.is_some() && rust_output.is_some(),
            "input_delta": input_delta.unwrap_or(Value::Null),
            "output_delta": output_delta.unwrap_or(Value::Null),
            "input_delta_unavailable": input_delta_unavailable,
            "output_delta_unavailable": output_delta_unavailable,
            "input_material": input_material,
            "output_material": output_material,
            "input_material_mismatch": input_material,
            "output_material_mismatch": output_material,
            "clean_input_material_output": clean_input_material_output,
            "boundary_classification": boundary_classification,
            "amplification_ratio": amplification_ratio,
        });
        if clean_input_material_output && first_clean_input_material_output.is_null() {
            first_clean_input_material_output = row.clone();
        }
        rows.push(row);
    }

    let mut blocked_reasons = Vec::<String>::new();
    if rows.is_empty() {
        blocked_reasons.push("prefix_ffn_norm_target_missing".to_string());
    }
    if missing_stage_count > 0 {
        blocked_reasons.push("prefix_ffn_norm_stage_missing".to_string());
    }
    if delta_unavailable_count > 0 {
        blocked_reasons.push("prefix_ffn_norm_delta_unavailable".to_string());
    }
    if clean_input_material_output_count > 0 {
        blocked_reasons.push("prefix_ffn_norm_clean_input_material_output_present".to_string());
    }
    if material_output_count > 0 {
        blocked_reasons.push("prefix_ffn_norm_output_delta_present".to_string());
    }
    blocked_reasons.sort_unstable();
    blocked_reasons.dedup();

    let next_action = if rows.is_empty() {
        "capture prefix frontier target tokens before interpreting FFN norm boundary deltas"
    } else if missing_stage_count > 0 || delta_unavailable_count > 0 {
        "capture complete FFN norm input/output history samples for prefix frontier tokens"
    } else if clean_input_material_output_count > 0 {
        "replay GGML and Rust FFN RMSNorm for the clean-input material-output prefix token"
    } else if material_output_count > 0 {
        "localize upstream FFN input drift before replaying FFN RMSNorm"
    } else {
        "prefix FFN norm boundary is not the active material drift"
    };

    json!({
        "diagnostic_only": true,
        "claim_allowed": false,
        "layer": layer,
        "policy": "Layer prefix FFN norm boundary deltas are diagnostic-only evidence for deciding whether to replay FFN RMSNorm for an earlier prefix token; they do not promote reference parity, A770 semantic quality, selected attention, resident KV, attention score residency, softmax residency, value-mix residency, full residency, performance, or completion",
        "layout": "dim_major_token_minor",
        "source_frontier": {
            "active_frontier": frontier.pointer("/active_frontier").cloned().unwrap_or(Value::Null),
            "selected_current_token": frontier.pointer("/selected_current_token").cloned().unwrap_or(Value::Null),
            "current_history_consistency_clean": frontier.pointer("/current_history_consistency_clean").cloned().unwrap_or(Value::Null),
        },
        "target_token_count": rows.len(),
        "missing_stage_count": missing_stage_count,
        "delta_unavailable_count": delta_unavailable_count,
        "material_output_count": material_output_count,
        "clean_input_material_output_count": clean_input_material_output_count,
        "first_clean_input_material_output": first_clean_input_material_output,
        "rows": rows,
        "current_blocked_reasons": blocked_reasons,
        "next_action": next_action,
    })
}

fn layer_current_token(
    reference_records: &[ReferenceTraceRecord],
    rust_records: &[RustTraceRecord],
    layer: usize,
) -> Option<u64> {
    find_reference_trace_record(reference_records, "l_out", Some(layer))
        .and_then(reference_sampled_token_index)
        .or_else(|| {
            find_rust_trace_record(rust_records, "post_layer", Some(layer))
                .and_then(|record| record.seq.map(|seq| seq as u64))
        })
}

fn accumulate_token_drift(
    delta: &Value,
    boundary: &str,
    reference_stage: &str,
    token_summaries: &mut BTreeMap<usize, TokenDriftSummary>,
) {
    let Some(rows) = delta.pointer("/token_mismatch_counts").and_then(Value::as_array) else {
        return;
    };
    for row in rows {
        let Some(token) = row
            .pointer("/token")
            .and_then(Value::as_u64)
            .and_then(|token| usize::try_from(token).ok())
        else {
            continue;
        };
        let mismatch_count = row.pointer("/mismatch_count").and_then(Value::as_u64).unwrap_or(0);
        let max_abs_delta = row.pointer("/max_abs_delta").and_then(Value::as_f64).unwrap_or(0.0);
        let entry = token_summaries.entry(token).or_insert_with(|| TokenDriftSummary {
            token,
            stage_count: 0,
            total_mismatch_count: 0,
            max_abs_delta: 0.0,
            first_stage: reference_stage.to_string(),
            first_boundary: boundary.to_string(),
        });
        entry.stage_count += 1;
        entry.total_mismatch_count = entry.total_mismatch_count.saturating_add(mismatch_count);
        entry.max_abs_delta = entry.max_abs_delta.max(max_abs_delta);
    }
}

fn token_drift_summary_json(summary: &TokenDriftSummary, selected_token: Option<u64>) -> Value {
    let relative_position = selected_token
        .map(|selected| {
            if summary.token < selected as usize {
                "before_sampled_current"
            } else if summary.token == selected as usize {
                "sampled_current"
            } else {
                "after_sampled_current"
            }
        })
        .unwrap_or("unknown");
    json!({
        "token": summary.token,
        "relative_position": relative_position,
        "stage_count": summary.stage_count,
        "total_mismatch_count": summary.total_mismatch_count,
        "max_abs_delta": summary.max_abs_delta,
        "first_boundary": summary.first_boundary,
        "first_reference_stage": summary.first_stage,
    })
}

fn token_drift_summary_json_for_max(summary: &TokenDriftSummary) -> Value {
    json!({
        "token": summary.token,
        "stage_count": summary.stage_count,
        "total_mismatch_count": summary.total_mismatch_count,
        "max_abs_delta": summary.max_abs_delta,
        "first_boundary": summary.first_boundary,
        "first_reference_stage": summary.first_stage,
    })
}

fn layer_current_history_consistency(
    reference_records: &[ReferenceTraceRecord],
    rust_records: &[RustTraceRecord],
    layer: usize,
) -> Value {
    const STAGE_MAPPING: &[(&str, &str, &str, &str, &str)] = &[
        (
            "ffn_inp",
            "ffn_inp_history_ref_layout",
            "post_attention_residual",
            "post_attention_residual_history_ref_layout",
            "ffn_input",
        ),
        (
            "ffn_norm",
            "ffn_norm_history_ref_layout",
            "post_ffn_norm",
            "post_ffn_norm_history_ref_layout",
            "ffn_norm_output",
        ),
        (
            "ffn_up",
            "ffn_up_history_ref_layout",
            "post_ffn_up_proj",
            "post_ffn_up_proj_history_ref_layout",
            "ffn_up_projection",
        ),
        (
            "ffn_gate",
            "ffn_gate_history_ref_layout",
            "post_ffn_gate_proj",
            "post_ffn_gate_proj_history_ref_layout",
            "ffn_gate_projection",
        ),
        (
            "ffn_sqr(relu)",
            "ffn_relu_sqr_history_ref_layout",
            "post_ffn_gate_activation",
            "post_ffn_gate_activation_history_ref_layout",
            "ffn_relu_squared",
        ),
        (
            "ffn_gate_par",
            "ffn_gate_par_history_ref_layout",
            "post_swiglu",
            "post_swiglu_history_ref_layout",
            "ffn_parallel_product",
        ),
        (
            "ffn_out",
            "ffn_out_history_ref_layout",
            "post_swiglu",
            "post_swiglu_history_ref_layout",
            "ffn_swiglu_output",
        ),
        (
            "ffn_sub_norm",
            "ffn_sub_norm_history_ref_layout",
            "post_ffn_subnorm",
            "post_ffn_subnorm_history_ref_layout",
            "ffn_subnorm_output",
        ),
        (
            "ffn_down",
            "ffn_down_history_ref_layout",
            "post_down_proj",
            "post_down_proj_history_ref_layout",
            "ffn_down_projection",
        ),
        (
            "l_out",
            "l_out_history_ref_layout",
            "post_layer",
            "post_layer_history_ref_layout",
            "layer_output",
        ),
    ];

    let selected_token = layer_current_token(reference_records, rust_records, layer);
    let mut rows = Vec::<Value>::new();
    let mut missing_stage_count = 0usize;
    let mut reference_mismatch_count = 0usize;
    let mut rust_mismatch_count = 0usize;
    let mut reference_delta_unavailable_count = 0usize;
    let mut rust_delta_unavailable_count = 0usize;
    let mut first_reference_mismatch = Value::Null;
    let mut first_rust_mismatch = Value::Null;

    for (
        reference_current_stage,
        reference_history_stage,
        rust_current_stage,
        rust_history_stage,
        boundary,
    ) in STAGE_MAPPING
    {
        let reference_current =
            find_reference_trace_record(reference_records, reference_current_stage, Some(layer));
        let reference_history =
            find_reference_trace_record(reference_records, reference_history_stage, Some(layer));
        let rust_current = find_rust_trace_record(rust_records, rust_current_stage, Some(layer));
        let rust_history = find_rust_trace_record(rust_records, rust_history_stage, Some(layer));
        if reference_current.is_none()
            || reference_history.is_none()
            || rust_current.is_none()
            || rust_history.is_none()
        {
            missing_stage_count += 1;
        }

        let reference_delta =
            selected_token.and_then(|token| usize::try_from(token).ok()).and_then(|token| {
                reference_current.zip(reference_history).and_then(|(current, history)| {
                    current_history_token_delta_reference(current, history, token).ok()
                })
            });
        let rust_delta =
            selected_token.and_then(|token| usize::try_from(token).ok()).and_then(|token| {
                rust_current.zip(rust_history).and_then(|(current, history)| {
                    current_history_token_delta_rust(current, history, token).ok()
                })
            });
        let reference_mismatch =
            reference_delta.as_ref().is_some_and(delta_has_material_numeric_delta);
        let rust_mismatch = rust_delta.as_ref().is_some_and(delta_has_material_numeric_delta);
        let reference_delta_unavailable = selected_token.is_some()
            && reference_current.is_some()
            && reference_history.is_some()
            && reference_delta.is_none();
        let rust_delta_unavailable = selected_token.is_some()
            && rust_current.is_some()
            && rust_history.is_some()
            && rust_delta.is_none();
        if reference_mismatch {
            reference_mismatch_count += 1;
        }
        if rust_mismatch {
            rust_mismatch_count += 1;
        }
        if reference_delta_unavailable {
            reference_delta_unavailable_count += 1;
        }
        if rust_delta_unavailable {
            rust_delta_unavailable_count += 1;
        }

        let row = json!({
            "layer": layer,
            "boundary": boundary,
            "selected_token": selected_token,
            "reference": {
                "current_stage": reference_current_stage,
                "history_stage": reference_history_stage,
                "current_present": reference_current.is_some(),
                "history_present": reference_history.is_some(),
                "current": reference_current.map(reference_record_summary).unwrap_or(Value::Null),
                "history": reference_history.map(reference_record_summary).unwrap_or(Value::Null),
                "current_vs_history_token": reference_delta.unwrap_or(Value::Null),
                "delta_unavailable": reference_delta_unavailable,
                "material_mismatch": reference_mismatch,
            },
            "rust": {
                "current_stage": rust_current_stage,
                "history_stage": rust_history_stage,
                "current_present": rust_current.is_some(),
                "history_present": rust_history.is_some(),
                "current": rust_current.map(rust_record_summary).unwrap_or(Value::Null),
                "history": rust_history.map(rust_record_summary).unwrap_or(Value::Null),
                "current_vs_history_token": rust_delta.unwrap_or(Value::Null),
                "delta_unavailable": rust_delta_unavailable,
                "material_mismatch": rust_mismatch,
            },
        });
        if reference_mismatch && first_reference_mismatch.is_null() {
            first_reference_mismatch = row.clone();
        }
        if rust_mismatch && first_rust_mismatch.is_null() {
            first_rust_mismatch = row.clone();
        }
        rows.push(row);
    }

    let mut blocked_reasons = Vec::<String>::new();
    if selected_token.is_none() {
        blocked_reasons.push("sampled_current_token_unavailable".to_string());
    }
    if missing_stage_count > 0 {
        blocked_reasons.push("current_history_stage_missing".to_string());
    }
    if reference_mismatch_count > 0 {
        blocked_reasons.push("reference_current_history_token_delta_present".to_string());
    }
    if rust_mismatch_count > 0 {
        blocked_reasons.push("rust_current_history_token_delta_present".to_string());
    }
    if reference_delta_unavailable_count > 0 {
        blocked_reasons.push("reference_current_history_token_delta_unavailable".to_string());
    }
    if rust_delta_unavailable_count > 0 {
        blocked_reasons.push("rust_current_history_token_delta_unavailable".to_string());
    }
    blocked_reasons.sort_unstable();
    blocked_reasons.dedup();

    let next_action = if selected_token.is_none() || missing_stage_count > 0 {
        "capture missing current/history stages before interpreting sampled-token history consistency"
    } else if reference_delta_unavailable_count > 0 || rust_delta_unavailable_count > 0 {
        "capture complete current/history samples before treating sampled-token history consistency as clean"
    } else if reference_mismatch_count > 0 || rust_mismatch_count > 0 {
        "localize why sampled-current-token full-prefix history diverges from current-token stage records"
    } else {
        "sampled-current-token current/history consistency is clean; continue with earlier prefix tokens"
    };

    json!({
        "diagnostic_only": true,
        "claim_allowed": false,
        "layer": layer,
        "policy": "Layer current/history consistency is diagnostic-only evidence for whether sampled-current-token full-prefix history records match current-token stage records; it does not promote reference parity, A770 semantic quality, selected attention, resident KV, attention score residency, softmax residency, value-mix residency, full residency, performance, or completion",
        "layout": "dim_major_token_minor",
        "selected_current_token": selected_token,
        "compared_stage_count": STAGE_MAPPING.len().saturating_sub(missing_stage_count),
        "missing_stage_count": missing_stage_count,
        "reference_mismatch_count": reference_mismatch_count,
        "rust_mismatch_count": rust_mismatch_count,
        "reference_delta_unavailable_count": reference_delta_unavailable_count,
        "rust_delta_unavailable_count": rust_delta_unavailable_count,
        "first_reference_mismatch": first_reference_mismatch,
        "first_rust_mismatch": first_rust_mismatch,
        "rows": rows,
        "current_blocked_reasons": blocked_reasons,
        "next_action": next_action,
    })
}

fn current_history_token_delta_reference(
    current: &ReferenceTraceRecord,
    history: &ReferenceTraceRecord,
    token: usize,
) -> Result<Value> {
    let dim_count = dim_major_dim_count(history)?;
    let token_count = dim_major_token_count(history)?;
    let history_token =
        slice_dim_major_token(&history.first_values, dim_count, token_count, token)?;
    Ok(compare_vectors(&current.first_values, &history_token))
}

fn current_history_token_delta_rust(
    current: &RustTraceRecord,
    history: &RustTraceRecord,
    token: usize,
) -> Result<Value> {
    let (dim_count, token_count) =
        rust_dim_major_shape_counts(history).context("rust history shape is not dim-major")?;
    let history_token =
        slice_dim_major_token(&history.first_values, dim_count, token_count, token)?;
    Ok(compare_vectors(&current.first_values, &history_token))
}

fn layer_attention_output_history_boundary_delta(
    reference_records: &[ReferenceTraceRecord],
    rust_records: &[RustTraceRecord],
    layer: usize,
) -> Value {
    const STAGE_MAPPING: &[(&str, &str, &str)] = &[
        (
            "attn_value_mix_history_ref_layout",
            "attention_value_mix_merged_history_ref_layout",
            "attention_value_mix_merged_history",
        ),
        (
            "attn_sub_norm_history_ref_layout",
            "post_attention_subnorm_history_ref_layout",
            "attention_subnorm_history",
        ),
        (
            "attn_o_out_history_ref_layout",
            "post_o_proj_history_ref_layout",
            "attention_output_projection_history",
        ),
        (
            "ffn_inp_history_ref_layout",
            "post_attention_residual_history_ref_layout",
            "attention_residual_history",
        ),
    ];

    let mut rows = Vec::<Value>::new();
    let mut compared_count = 0usize;
    let mut missing_reference_count = 0usize;
    let mut missing_rust_count = 0usize;
    let mut material_mismatch_count = 0usize;
    let mut first_material_boundary = Value::Null;

    for (reference_stage, rust_stage, boundary) in STAGE_MAPPING {
        let reference =
            find_reference_trace_record(reference_records, reference_stage, Some(layer));
        let rust = find_rust_trace_record(rust_records, rust_stage, Some(layer));
        if reference.is_none() {
            missing_reference_count += 1;
        }
        if rust.is_none() {
            missing_rust_count += 1;
        }

        let mut status = match (reference.is_some(), rust.is_some()) {
            (false, false) => "missing_both",
            (false, true) => "missing_reference",
            (true, false) => "missing_rust",
            (true, true) => "summary_match",
        };
        let mut delta = Value::Null;
        let mut material_mismatch = false;

        if let (Some(reference), Some(rust)) = (reference, rust) {
            compared_count += 1;
            delta = dim_major_history_record_delta(reference, rust);
            material_mismatch = delta_has_material_numeric_delta(&delta);
            if material_mismatch {
                status = "material_mismatch";
                material_mismatch_count += 1;
            }
        }

        let row = json!({
            "layer": layer,
            "boundary": boundary,
            "reference_stage": reference_stage,
            "rust_stage": rust_stage,
            "status": status,
            "reference": reference.map(reference_record_summary).unwrap_or(Value::Null),
            "rust": rust.map(rust_record_summary).unwrap_or(Value::Null),
            "delta": delta,
            "material_mismatch": material_mismatch,
        });
        if material_mismatch && first_material_boundary.is_null() {
            first_material_boundary = row.clone();
        }
        rows.push(row);
    }

    json!({
        "diagnostic_only": true,
        "claim_allowed": false,
        "layer": layer,
        "policy": "Layer attention-output full-history boundary deltas are diagnostic-only evidence for locating where attention residual drift enters; they do not promote reference parity, A770 semantic quality, selected attention, resident KV, attention score residency, softmax residency, value-mix residency, full residency, performance, or completion",
        "layout": "dim_major_token_minor",
        "compared_count": compared_count,
        "missing_reference_count": missing_reference_count,
        "missing_rust_count": missing_rust_count,
        "material_mismatch_count": material_mismatch_count,
        "first_material_boundary": first_material_boundary,
        "rows": rows,
    })
}

fn layer_attention_norm_history_drift(
    reference_records: &[ReferenceTraceRecord],
    rust_records: &[RustTraceRecord],
    layer: usize,
) -> Value {
    let reference_input = find_reference_trace_record(
        reference_records,
        "attn_norm_input_history_ref_layout",
        Some(layer),
    );
    let rust_input = find_rust_trace_record(
        rust_records,
        "attention_norm_input_history_ref_layout",
        Some(layer),
    );
    let reference_output =
        find_reference_trace_record(reference_records, "attn_norm_history_ref_layout", Some(layer));
    let rust_output =
        find_rust_trace_record(rust_records, "attention_v_input_history_ref_layout", Some(layer));

    let input_delta = reference_input
        .zip(rust_input)
        .map(|(reference, rust)| dim_major_history_record_delta(reference, rust));
    let output_delta = reference_output
        .zip(rust_output)
        .map(|(reference, rust)| dim_major_history_record_delta(reference, rust));
    let input_material = input_delta.as_ref().is_some_and(delta_has_material_numeric_delta);
    let output_material = output_delta.as_ref().is_some_and(delta_has_material_numeric_delta);
    let input_max_abs = input_delta.as_ref().map(|delta| delta_metric(delta, "/max_abs_delta"));
    let output_max_abs = output_delta.as_ref().map(|delta| delta_metric(delta, "/max_abs_delta"));
    let max_abs_reduction_ratio = match (input_max_abs, output_max_abs) {
        (Some(input), Some(output)) if input > 0.0 => Some(output / input),
        _ => None,
    };

    let mut blocked_reasons = Vec::<String>::new();
    if reference_input.is_none() {
        blocked_reasons.push("reference_attention_norm_input_history_missing".to_string());
    }
    if rust_input.is_none() {
        blocked_reasons.push("rust_attention_norm_input_history_missing".to_string());
    }
    if reference_output.is_none() {
        blocked_reasons.push("reference_attention_norm_output_history_missing".to_string());
    }
    if rust_output.is_none() {
        blocked_reasons.push("rust_attention_norm_output_history_missing".to_string());
    }
    if reference_input.is_some() && rust_input.is_some() && input_delta.is_none() {
        blocked_reasons.push("attention_norm_input_history_delta_unavailable".to_string());
    }
    if reference_output.is_some() && rust_output.is_some() && output_delta.is_none() {
        blocked_reasons.push("attention_norm_output_history_delta_unavailable".to_string());
    }
    if input_material {
        blocked_reasons.push("attention_norm_input_history_delta_present".to_string());
    }
    if output_material {
        blocked_reasons.push("attention_norm_output_history_delta_present".to_string());
    }
    if !input_material && output_material {
        blocked_reasons.push("attention_norm_output_delta_without_input_history_delta".to_string());
    }
    if input_material && output_material {
        blocked_reasons
            .push("attention_norm_input_history_delta_feeds_value_projection_input".to_string());
    }
    if input_material && !output_material {
        blocked_reasons
            .push("attention_norm_input_delta_reduced_below_material_threshold".to_string());
    }
    blocked_reasons.sort_unstable();
    blocked_reasons.dedup();

    let next_action = if blocked_reasons.iter().any(|reason| {
        reason == "reference_attention_norm_input_history_missing"
            || reason == "rust_attention_norm_input_history_missing"
            || reason == "reference_attention_norm_output_history_missing"
            || reason == "rust_attention_norm_output_history_missing"
    }) {
        "capture the missing layer-scoped attention-norm history stages before interpreting the value-projection input drift"
    } else if input_material && output_material {
        "localize the previous-layer output history delta that feeds this layer's attention-norm input"
    } else if output_material {
        "inspect attention RMSNorm history replay because output history diverges without an input-history delta"
    } else if input_material {
        "attention RMSNorm reduces the input-history delta below the material threshold; continue with downstream score/value sensitivity"
    } else {
        "layer attention-norm history is not the active material drift; continue downstream"
    };

    json!({
        "diagnostic_only": true,
        "claim_allowed": false,
        "layer": layer,
        "policy": "Layer attention-norm history drift is diagnostic-only evidence for whether full-prefix layer input drift reaches the K/V projection input; it does not promote reference parity, A770 semantic quality, selected attention, resident KV, attention score residency, softmax residency, value-mix residency, full residency, performance, or completion",
        "layout": "dim_major_token_minor",
        "input_history": {
            "boundary": "attention_norm_input_history",
            "reference_stage": "attn_norm_input_history_ref_layout",
            "rust_stage": "attention_norm_input_history_ref_layout",
            "reference": reference_input.map(reference_record_summary).unwrap_or(Value::Null),
            "rust": rust_input.map(rust_record_summary).unwrap_or(Value::Null),
            "reference_present": reference_input.is_some(),
            "rust_present": rust_input.is_some(),
            "delta": input_delta.unwrap_or(Value::Null),
            "material_mismatch": input_material,
        },
        "output_history": {
            "boundary": "attention_norm_output_history",
            "reference_stage": "attn_norm_history_ref_layout",
            "rust_stage": "attention_v_input_history_ref_layout",
            "reference": reference_output.map(reference_record_summary).unwrap_or(Value::Null),
            "rust": rust_output.map(rust_record_summary).unwrap_or(Value::Null),
            "reference_present": reference_output.is_some(),
            "rust_present": rust_output.is_some(),
            "delta": output_delta.unwrap_or(Value::Null),
            "material_mismatch": output_material,
        },
        "transition": {
            "input_material_mismatch": input_material,
            "output_material_mismatch": output_material,
            "input_max_abs_delta": input_max_abs,
            "output_max_abs_delta": output_max_abs,
            "max_abs_reduction_ratio": max_abs_reduction_ratio,
        },
        "current_blocked_reasons": blocked_reasons,
        "next_action": next_action,
    })
}

fn layer_attention_norm_input_source_delta(
    reference_records: &[ReferenceTraceRecord],
    rust_records: &[RustTraceRecord],
    layer: usize,
) -> Value {
    let Some(previous_layer) = layer.checked_sub(1) else {
        return json!({
            "diagnostic_only": true,
            "claim_allowed": false,
            "layer": layer,
            "policy": "Layer attention-norm input source deltas are diagnostic-only current-token handoff evidence; they do not promote reference parity, A770 semantic quality, selected attention, resident KV, attention score residency, softmax residency, value-mix residency, full residency, performance, or completion",
            "current_blocked_reasons": ["layer_has_no_previous_layer"],
        });
    };
    let reference_previous =
        find_reference_trace_record(reference_records, "l_out", Some(previous_layer));
    let rust_previous = find_rust_trace_record(rust_records, "post_layer", Some(previous_layer));
    let reference_input_history = find_reference_trace_record(
        reference_records,
        "attn_norm_input_history_ref_layout",
        Some(layer),
    );
    let rust_input_history = find_rust_trace_record(
        rust_records,
        "attention_norm_input_history_ref_layout",
        Some(layer),
    );

    let selected_token = reference_input_history
        .and_then(reference_sampled_token_index)
        .or_else(|| rust_input_history.and_then(|record| record.seq.map(|seq| seq as u64)));
    let reference_input_token =
        selected_token.and_then(|token| usize::try_from(token).ok()).and_then(|token| {
            reference_input_history.and_then(|record| reference_dim_major_token(record, token).ok())
        });
    let rust_input_token =
        selected_token.and_then(|token| usize::try_from(token).ok()).and_then(|token| {
            rust_input_history.and_then(|record| rust_dim_major_token(record, token).ok())
        });

    let reference_handoff_delta = reference_previous
        .zip(reference_input_token.as_ref())
        .map(|(previous, input)| compare_vectors(&previous.first_values, input));
    let rust_handoff_delta = rust_previous
        .zip(rust_input_token.as_ref())
        .map(|(previous, input)| compare_vectors(&previous.first_values, input));
    let previous_output_delta = reference_previous
        .zip(rust_previous)
        .map(|(reference, rust)| compare_vectors(&reference.first_values, &rust.first_values));
    let input_token_delta = reference_input_token
        .as_ref()
        .zip(rust_input_token.as_ref())
        .map(|(reference, rust)| compare_vectors(reference, rust));

    let reference_handoff_material =
        reference_handoff_delta.as_ref().is_some_and(delta_has_material_numeric_delta);
    let rust_handoff_material =
        rust_handoff_delta.as_ref().is_some_and(delta_has_material_numeric_delta);
    let previous_output_material =
        previous_output_delta.as_ref().is_some_and(delta_has_material_numeric_delta);
    let input_token_material =
        input_token_delta.as_ref().is_some_and(delta_has_material_numeric_delta);
    let handoff_clean = reference_handoff_delta
        .as_ref()
        .is_some_and(|delta| !delta_has_material_numeric_delta(delta))
        && rust_handoff_delta
            .as_ref()
            .is_some_and(|delta| !delta_has_material_numeric_delta(delta));

    let mut blocked_reasons = Vec::<String>::new();
    if reference_previous.is_none() {
        blocked_reasons.push("reference_previous_layer_l_out_missing".to_string());
    }
    if rust_previous.is_none() {
        blocked_reasons.push("rust_previous_layer_post_layer_missing".to_string());
    }
    if reference_input_history.is_none() {
        blocked_reasons.push("reference_attention_norm_input_history_missing".to_string());
    }
    if rust_input_history.is_none() {
        blocked_reasons.push("rust_attention_norm_input_history_missing".to_string());
    }
    if selected_token.is_none() {
        blocked_reasons.push("attention_norm_input_source_selected_token_missing".to_string());
    }
    if reference_input_token.is_none() {
        blocked_reasons.push("reference_attention_norm_input_token_unavailable".to_string());
    }
    if rust_input_token.is_none() {
        blocked_reasons.push("rust_attention_norm_input_token_unavailable".to_string());
    }
    if reference_handoff_material {
        blocked_reasons
            .push("reference_previous_layer_to_attention_norm_input_handoff_delta".to_string());
    }
    if rust_handoff_material {
        blocked_reasons
            .push("rust_previous_layer_to_attention_norm_input_handoff_delta".to_string());
    }
    if previous_output_material {
        blocked_reasons.push("previous_layer_output_current_token_delta_present".to_string());
    }
    if input_token_material {
        blocked_reasons.push("attention_norm_input_current_token_delta_present".to_string());
    }
    if handoff_clean && previous_output_material && input_token_material {
        blocked_reasons.push("previous_layer_output_delta_feeds_attention_norm_input".to_string());
    }
    blocked_reasons.sort_unstable();
    blocked_reasons.dedup();

    let next_action = if blocked_reasons.iter().any(|reason| {
        reason == "reference_previous_layer_l_out_missing"
            || reason == "rust_previous_layer_post_layer_missing"
            || reason == "reference_attention_norm_input_history_missing"
            || reason == "rust_attention_norm_input_history_missing"
            || reason == "attention_norm_input_source_selected_token_missing"
    }) {
        "capture the missing previous-layer output or current-layer input history before interpreting the handoff"
    } else if reference_handoff_material || rust_handoff_material {
        "inspect inter-layer trace/handoff semantics because previous-layer output does not match the current-layer attention-norm input token"
    } else if handoff_clean && previous_output_material && input_token_material {
        "localize the previous layer's current-token output drift; the layer handoff itself is clean for the sampled token"
    } else if input_token_material {
        "attention-norm input token differs without a matching previous-layer output delta; inspect layer-input history serialization"
    } else {
        "current-token layer handoff is clean and not the active drift; continue with full-prefix history coverage"
    };

    json!({
        "diagnostic_only": true,
        "claim_allowed": false,
        "layer": layer,
        "previous_layer": previous_layer,
        "policy": "Layer attention-norm input source deltas are diagnostic-only current-token handoff evidence; they do not promote reference parity, A770 semantic quality, selected attention, resident KV, attention score residency, softmax residency, value-mix residency, full residency, performance, or completion",
        "scope": {
            "kind": "current_token_handoff",
            "selected_token": selected_token,
            "full_prefix_previous_layer_history_compared": false,
            "limitation": "This section checks the sampled-token handoff using previous-layer current output plus the current-layer input history token; it does not replace full-prefix previous-layer history comparison.",
        },
        "reference_handoff": {
            "previous_stage": "l_out",
            "input_stage": "attn_norm_input_history_ref_layout",
            "previous": reference_previous.map(reference_record_summary).unwrap_or(Value::Null),
            "input_history": reference_input_history.map(reference_record_summary).unwrap_or(Value::Null),
            "input_token": reference_input_token.as_ref().map(|values| row_report(values)).unwrap_or(Value::Null),
            "previous_vs_input_token": reference_handoff_delta.unwrap_or(Value::Null),
            "material_mismatch": reference_handoff_material,
        },
        "rust_handoff": {
            "previous_stage": "post_layer",
            "input_stage": "attention_norm_input_history_ref_layout",
            "previous": rust_previous.map(rust_record_summary).unwrap_or(Value::Null),
            "input_history": rust_input_history.map(rust_record_summary).unwrap_or(Value::Null),
            "input_token": rust_input_token.as_ref().map(|values| row_report(values)).unwrap_or(Value::Null),
            "previous_vs_input_token": rust_handoff_delta.unwrap_or(Value::Null),
            "material_mismatch": rust_handoff_material,
        },
        "cross_runtime": {
            "previous_layer_output_delta": previous_output_delta.unwrap_or(Value::Null),
            "attention_norm_input_token_delta": input_token_delta.unwrap_or(Value::Null),
            "previous_layer_output_material_mismatch": previous_output_material,
            "attention_norm_input_token_material_mismatch": input_token_material,
            "handoff_clean": handoff_clean,
        },
        "current_blocked_reasons": blocked_reasons,
        "next_action": next_action,
    })
}

fn dim_major_history_record_delta(
    reference: &ReferenceTraceRecord,
    rust: &RustTraceRecord,
) -> Value {
    let dim_count = dim_major_dim_count(reference).ok();
    let token_count = dim_major_token_count(reference).ok();
    match (dim_count, token_count) {
        (Some(dim_count), Some(token_count)) if dim_count > 0 && token_count > 0 => {
            dim_major_token_value_delta(
                &reference.first_values,
                &rust.first_values,
                dim_count,
                token_count,
            )
        }
        _ => compare_vectors(&reference.first_values, &rust.first_values),
    }
}

fn rust_dim_major_shape_counts(record: &RustTraceRecord) -> Option<(usize, usize)> {
    Some((
        record.shape.first().copied().filter(|dim| *dim > 0)?,
        record.shape.get(1).copied().filter(|dim| *dim > 0)?,
    ))
}

fn dim_major_rect_values(
    values: &[f32],
    source_dim_count: usize,
    source_token_count: usize,
    dim_count: usize,
    token_count: usize,
) -> Vec<f32> {
    let mut out = Vec::with_capacity(dim_count.saturating_mul(token_count));
    for dim in 0..dim_count.min(source_dim_count) {
        for token in 0..token_count.min(source_token_count) {
            let index = dim * source_token_count + token;
            if let Some(value) = values.get(index) {
                out.push(*value);
            }
        }
    }
    out
}

fn dim_major_tail_values(
    values: &[f32],
    source_dim_count: usize,
    source_token_count: usize,
    start_dim: usize,
) -> Vec<f32> {
    let mut out = Vec::new();
    for dim in start_dim.min(source_dim_count)..source_dim_count {
        for token in 0..source_token_count {
            let index = dim * source_token_count + token;
            if let Some(value) = values.get(index) {
                out.push(*value);
            }
        }
    }
    out
}

