fn rust_cache_stage_heads<'a>(
    rust_records: &'a BTreeMap<String, RustTraceRecord>,
    stage_prefix: &str,
) -> BTreeMap<usize, &'a RustTraceRecord> {
    rust_records
        .iter()
        .filter_map(|(stage, record)| {
            parse_stage_head(stage, stage_prefix).map(|head| (head, record))
        })
        .filter(|(_, record)| !record.first_values.is_empty())
        .collect()
}

fn value_cache_source_boundary_at(
    dim: Option<usize>,
    token: Option<usize>,
    reference_cache: &ScalarTraceTensor,
    before_store: Option<&RustTraceRecord>,
    stored_f16: Option<&RustTraceRecord>,
    readback: Option<&RustTraceRecord>,
    expanded: &ScalarTraceTensor,
) -> Value {
    let mut missing = Vec::<String>::new();
    let reference_value = dim
        .zip(token)
        .and_then(|(dim, token)| scalar_tensor_dim_major_value(reference_cache, dim, token));
    let before_store_tensor = before_store.map(scalar_rust_tensor);
    let stored_f16_tensor = stored_f16.map(scalar_rust_tensor);
    let readback_tensor = readback.map(scalar_rust_tensor);
    let before_store_value = dim.zip(token).and_then(|(dim, token)| {
        before_store_tensor
            .as_ref()
            .and_then(|tensor| scalar_tensor_dim_major_value(tensor, dim, token))
    });
    let stored_f16_value = dim.zip(token).and_then(|(dim, token)| {
        stored_f16_tensor
            .as_ref()
            .and_then(|tensor| scalar_tensor_dim_major_value(tensor, dim, token))
    });
    let readback_value = dim.zip(token).and_then(|(dim, token)| {
        readback_tensor
            .as_ref()
            .and_then(|tensor| scalar_tensor_dim_major_value(tensor, dim, token))
    });
    let expanded_value =
        dim.zip(token).and_then(|(dim, token)| scalar_tensor_dim_major_value(expanded, dim, token));

    if dim.is_none() || token.is_none() {
        missing.push("first_mismatch_location_missing".to_string());
    }
    if before_store.is_none() {
        missing.push("attention_v_before_cache_store_kv_head_missing".to_string());
    }
    if stored_f16.is_none() {
        missing.push("attention_v_cache_stored_f16_kv_head_missing".to_string());
    }
    if readback.is_none() {
        missing.push("attention_v_cache_readback_kv_head_missing".to_string());
    }
    for (name, value) in [
        ("reference_value_cache", reference_value),
        ("before_cache_store", before_store_value),
        ("cache_stored_f16", stored_f16_value),
        ("cache_readback", readback_value),
        ("expanded_for_value_mix", expanded_value),
    ] {
        if value.is_none() {
            missing.push(format!("{name}_sample_missing"));
        }
    }
    missing.sort_unstable();
    missing.dedup();

    let reference_vs_before = abs_delta_opt(reference_value, before_store_value);
    let before_vs_stored_f16 = abs_delta_opt(before_store_value, stored_f16_value);
    let stored_f16_vs_readback = abs_delta_opt(stored_f16_value, readback_value);
    let readback_vs_expanded = abs_delta_opt(readback_value, expanded_value);
    let reference_vs_expanded = abs_delta_opt(reference_value, expanded_value);

    let first_material_boundary = [
        ("before_cache_store", reference_vs_before),
        ("cache_stored_f16", before_vs_stored_f16),
        ("cache_readback", stored_f16_vs_readback),
        ("expanded_for_value_mix", readback_vs_expanded),
        ("unattributed_reference_vs_expanded", reference_vs_expanded),
    ]
    .into_iter()
    .find_map(|(name, delta)| delta.is_some_and(|delta| delta > 1.0e-6).then_some(name));

    json!({
        "dim": dim,
        "source_token": token,
        "values": {
            "reference_value_cache": reference_value,
            "before_cache_store": before_store_value,
            "cache_stored_f16": stored_f16_value,
            "cache_readback": readback_value,
            "expanded_for_value_mix": expanded_value,
        },
        "deltas": {
            "reference_vs_before_cache_store": reference_vs_before,
            "before_cache_store_vs_cache_stored_f16": before_vs_stored_f16,
            "cache_stored_f16_vs_cache_readback": stored_f16_vs_readback,
            "cache_readback_vs_expanded_for_value_mix": readback_vs_expanded,
            "reference_vs_expanded_for_value_mix": reference_vs_expanded,
        },
        "first_material_boundary": first_material_boundary,
        "missing": missing,
    })
}

fn scalar_tensor_dim_major_value(
    tensor: &ScalarTraceTensor,
    dim: usize,
    token: usize,
) -> Option<f32> {
    let (dim_count, token_count) = scalar_tensor_dim_token_shape(tensor)?;
    if dim >= dim_count || token >= token_count {
        return None;
    }
    let sample_count = dim_count.checked_mul(token_count)?;
    if tensor.first_values.len() < sample_count {
        return None;
    }
    tensor.first_values.get(dim.checked_mul(token_count)?.checked_add(token)?).copied()
}

fn abs_delta_opt(left: Option<f32>, right: Option<f32>) -> Option<f64> {
    Some((left? as f64 - right? as f64).abs())
}

fn value_mix_history_candidate_value_cache_head(
    head: usize,
    kv_head: Option<usize>,
    lookup: ValueMixHistoryCacheLookup,
) -> Option<usize> {
    match lookup {
        ValueMixHistoryCacheLookup::KvHead => kv_head,
        ValueMixHistoryCacheLookup::AttentionHead => Some(head),
    }
}

fn attention_value_mix_history_input_attribution(
    reference_records: &[ReferenceTraceRecord],
    rust_records: &BTreeMap<String, RustTraceRecord>,
) -> Value {
    let reference_probability_heads = reference_records
        .iter()
        .filter_map(|record| {
            if !record.stage.ends_with("_history_ref_layout") {
                return None;
            }
            parse_stage_head(&record.stage, "kq_soft_max_ext_head")
                .and_then(|head| scalar_reference_tensor(record).map(|tensor| (head, tensor)))
        })
        .collect::<BTreeMap<_, _>>();
    let reference_value_cache_heads = reference_records
        .iter()
        .filter_map(|record| {
            parse_stage_head(&record.stage, "v_cache_rust_layout_head")
                .and_then(|head| scalar_reference_tensor(record).map(|tensor| (head, tensor)))
        })
        .collect::<BTreeMap<_, _>>();
    let reference_value_mix_heads = reference_records
        .iter()
        .filter_map(|record| {
            if !record.stage.ends_with("_history_ref_layout") {
                return None;
            }
            parse_stage_head(&record.stage, "kqv_head")
                .and_then(|head| scalar_reference_tensor(record).map(|tensor| (head, tensor)))
        })
        .collect::<BTreeMap<_, _>>();
    let rust_probability_heads = rust_records
        .iter()
        .filter_map(|(stage, record)| {
            parse_stage_head(stage, "attn_scores_softmax_head").and_then(|head| {
                record
                    .stage
                    .as_deref()
                    .unwrap_or("")
                    .ends_with("_history_ref_layout")
                    .then_some((head, scalar_rust_tensor(record)))
            })
        })
        .collect::<BTreeMap<_, _>>();
    let rust_value_cache_heads = rust_records
        .iter()
        .filter_map(|(stage, record)| {
            parse_stage_head(stage, "attention_v_cache_expanded_for_value_mix_head").and_then(
                |head| {
                    record
                        .stage
                        .as_deref()
                        .unwrap_or("")
                        .ends_with("_ref_layout")
                        .then_some((head, scalar_rust_tensor(record)))
                },
            )
        })
        .collect::<BTreeMap<_, _>>();

    let group_size = if reference_value_cache_heads.is_empty()
        || reference_value_mix_heads.is_empty()
        || !reference_value_mix_heads.len().is_multiple_of(reference_value_cache_heads.len())
    {
        None
    } else {
        Some(reference_value_mix_heads.len() / reference_value_cache_heads.len())
    };

    let candidates = [
        ValueMixHistoryInputCandidate {
            id: "reference_probability_history_reference_value_cache_history",
            probability_source: "reference_probability_history",
            value_cache_source: "reference_value_cache_history",
            value_cache_lookup: ValueMixHistoryCacheLookup::KvHead,
            probability_heads: &reference_probability_heads,
            value_cache_heads: &reference_value_cache_heads,
        },
        ValueMixHistoryInputCandidate {
            id: "reference_probability_history_rust_expanded_value_cache_history",
            probability_source: "reference_probability_history",
            value_cache_source: "rust_expanded_value_cache_history",
            value_cache_lookup: ValueMixHistoryCacheLookup::AttentionHead,
            probability_heads: &reference_probability_heads,
            value_cache_heads: &rust_value_cache_heads,
        },
        ValueMixHistoryInputCandidate {
            id: "rust_probability_history_reference_value_cache_history",
            probability_source: "rust_probability_history",
            value_cache_source: "reference_value_cache_history",
            value_cache_lookup: ValueMixHistoryCacheLookup::KvHead,
            probability_heads: &rust_probability_heads,
            value_cache_heads: &reference_value_cache_heads,
        },
        ValueMixHistoryInputCandidate {
            id: "rust_probability_history_rust_expanded_value_cache_history",
            probability_source: "rust_probability_history",
            value_cache_source: "rust_expanded_value_cache_history",
            value_cache_lookup: ValueMixHistoryCacheLookup::AttentionHead,
            probability_heads: &rust_probability_heads,
            value_cache_heads: &rust_value_cache_heads,
        },
    ];

    let mut rows = Vec::new();
    let mut compared_head_count = 0usize;
    let mut missing_input_count = 0usize;
    let mut best_candidate_counts = BTreeMap::<String, usize>::new();
    let mut max_best_abs_delta = 0.0f64;
    let mut max_best_rms_delta = 0.0f64;

    for (&head, target) in &reference_value_mix_heads {
        let kv_head = group_size.map(|group_size| head / group_size);
        let mut candidate_rows = Vec::new();
        let mut best_id = None::<&str>;
        let mut best_delta = Value::Null;
        let mut best_rank = (f64::INFINITY, f64::INFINITY, true);

        for candidate in candidates {
            let probability = candidate.probability_heads.get(&head);
            let value_cache_head = value_mix_history_candidate_value_cache_head(
                head,
                kv_head,
                candidate.value_cache_lookup,
            );
            let value_cache =
                value_cache_head.and_then(|head| candidate.value_cache_heads.get(&head));
            if let (Some(probability), Some(value_cache)) = (probability, value_cache)
                && let Some(delta) =
                    value_mix_history_candidate_delta(probability, value_cache, target)
            {
                let rank = value_mix_candidate_rank(&delta);
                if rank < best_rank {
                    best_rank = rank;
                    best_id = Some(candidate.id);
                    best_delta = delta.clone();
                }
                candidate_rows.push(json!({
                    "candidate": candidate.id,
                    "probability_source": candidate.probability_source,
                    "value_cache_source": candidate.value_cache_source,
                    "value_cache_head": value_cache_head,
                    "max_abs_delta": delta_metric(&delta, "/max_abs_delta"),
                    "rms_delta": delta_metric(&delta, "/rms_abs_delta"),
                    "delta": delta,
                }));
            }
        }

        if let Some(best_id) = best_id {
            compared_head_count += 1;
            *best_candidate_counts.entry(best_id.to_string()).or_insert(0) += 1;
            max_best_abs_delta =
                max_best_abs_delta.max(delta_metric(&best_delta, "/max_abs_delta"));
            max_best_rms_delta =
                max_best_rms_delta.max(delta_metric(&best_delta, "/rms_abs_delta"));
            rows.push(json!({
                "head": head,
                "kv_head": kv_head,
                "status": "compared",
                "best_candidate": best_id,
                "max_abs_delta": delta_metric(&best_delta, "/max_abs_delta"),
                "rms_delta": delta_metric(&best_delta, "/rms_abs_delta"),
                "candidate_count": candidate_rows.len(),
                "candidates": candidate_rows,
            }));
        } else {
            missing_input_count += 1;
            rows.push(json!({
                "head": head,
                "kv_head": kv_head,
                "status": "missing_input",
                "candidate_count": 0,
                "reference_probability_history_present": reference_probability_heads.contains_key(&head),
                "rust_probability_history_present": rust_probability_heads.contains_key(&head),
                "reference_value_cache_history_present": kv_head
                    .is_some_and(|head| reference_value_cache_heads.contains_key(&head)),
                "rust_expanded_value_cache_history_present": rust_value_cache_heads.contains_key(&head),
            }));
        }
    }

    json!({
        "diagnostic_only": true,
        "claim_allowed": false,
        "policy": "Full-history value-mix input attribution is diagnostic-only evidence for whether per-head history drift follows probability history, value-cache history, or both; it does not promote reference parity, A770 semantic quality, selected attention, resident KV, attention score residency, softmax residency, value-mix residency, full residency, performance, or completion",
        "layout": "dim_major_token_minor",
        "group_size": group_size,
        "reference_probability_history_head_count": reference_probability_heads.len(),
        "rust_probability_history_head_count": rust_probability_heads.len(),
        "reference_value_cache_history_head_count": reference_value_cache_heads.len(),
        "rust_expanded_value_cache_history_head_count": rust_value_cache_heads.len(),
        "reference_value_mix_history_head_count": reference_value_mix_heads.len(),
        "compared_head_count": compared_head_count,
        "missing_input_count": missing_input_count,
        "best_candidate_counts": best_candidate_counts,
        "max_best_abs_delta": max_best_abs_delta,
        "max_best_rms_delta": max_best_rms_delta,
        "all_compared": !reference_value_mix_heads.is_empty() && missing_input_count == 0,
        "rows": rows,
    })
}

fn attention_value_mix_reference_scalar_recompute(
    reference_records: &[ReferenceTraceRecord],
) -> Value {
    let probability_heads = reference_records
        .iter()
        .filter_map(|record| {
            parse_exact_stage_head(&record.stage, "kq_soft_max_ext_head").map(|head| (head, record))
        })
        .filter(|(_, record)| record.values_available && !record.first_values.is_empty())
        .collect::<BTreeMap<_, _>>();
    let value_cache_heads = reference_records
        .iter()
        .filter_map(|record| {
            parse_stage_head(&record.stage, "v_cache_rust_layout_head").map(|head| (head, record))
        })
        .filter(|(_, record)| record.values_available && !record.first_values.is_empty())
        .collect::<BTreeMap<_, _>>();
    let value_mix_heads = reference_records
        .iter()
        .filter_map(|record| {
            parse_exact_stage_head(&record.stage, "kqv_head").map(|head| (head, record))
        })
        .filter(|(_, record)| record.values_available && !record.first_values.is_empty())
        .collect::<BTreeMap<_, _>>();

    let group_size = if value_cache_heads.is_empty()
        || value_mix_heads.is_empty()
        || !value_mix_heads.len().is_multiple_of(value_cache_heads.len())
    {
        None
    } else {
        Some(value_mix_heads.len() / value_cache_heads.len())
    };

    let mut rows = Vec::new();
    let mut compared_count = 0usize;
    let mut missing_input_count = 0usize;
    let mut max_rms_delta = 0.0f64;
    let mut max_abs_delta = 0.0f64;

    for (&head, value_mix) in &value_mix_heads {
        let kv_head = group_size.map(|group_size| head / group_size);
        let probability = probability_heads.get(&head).copied();
        let value_cache = kv_head.and_then(|kv_head| value_cache_heads.get(&kv_head).copied());
        let mut status = "missing_input";
        let mut delta = Value::Null;
        let mut recomputed_first_values = Vec::<f32>::new();
        let mut token_count = None::<usize>;
        let mut value_dim = None::<usize>;

        if let (Some(probability), Some(value_cache)) = (probability, value_cache) {
            value_dim = usize::try_from(value_mix.nelements).ok();
            token_count =
                value_cache.shape.get(1).and_then(|dim| usize::try_from(*dim).ok()).or_else(|| {
                    value_dim.and_then(|dim| {
                        usize::try_from(value_cache.nelements).ok().map(|n| n / dim)
                    })
                });
            if let (Some(value_dim), Some(token_count)) = (value_dim, token_count) {
                let value_sample_count = value_dim.saturating_mul(token_count);
                if probability.first_values.len() >= token_count
                    && value_cache.first_values.len() >= value_sample_count
                    && value_mix.first_values.len() >= value_dim
                {
                    for dim in 0..value_dim {
                        let mut sum = 0.0f64;
                        for token in 0..token_count {
                            let probability = probability.first_values[token] as f64;
                            let value = value_cache.first_values[dim * token_count + token] as f64;
                            sum += probability * value;
                        }
                        recomputed_first_values.push(sum as f32);
                    }
                    delta = compare_prefix(
                        &recomputed_first_values,
                        &value_mix.first_values,
                        value_dim,
                    );
                    max_rms_delta = max_rms_delta.max(
                        delta.pointer("/rms_abs_delta").and_then(Value::as_f64).unwrap_or(0.0),
                    );
                    max_abs_delta = max_abs_delta.max(
                        delta.pointer("/max_abs_delta").and_then(Value::as_f64).unwrap_or(0.0),
                    );
                    compared_count += 1;
                    status = "compared";
                }
            }
        }

        if status == "missing_input" {
            missing_input_count += 1;
        }
        rows.push(json!({
            "head": head,
            "kv_head": kv_head,
            "status": status,
            "probability_stage_present": probability.is_some(),
            "value_cache_stage_present": value_cache.is_some(),
            "value_mix_stage_present": true,
            "token_count": token_count,
            "value_dim": value_dim,
            "delta": delta,
            "recomputed_first_values": recomputed_first_values,
        }));
    }

    json!({
        "diagnostic_only": true,
        "claim_allowed": false,
        "policy": "reference scalar value-mix recompute is diagnostic arithmetic evidence only; it does not promote reference parity, A770 semantic quality, value mix residency, selected attention, resident KV, or any support claim",
        "probability_head_count": probability_heads.len(),
        "value_cache_head_count": value_cache_heads.len(),
        "value_mix_head_count": value_mix_heads.len(),
        "group_size": group_size,
        "compared_count": compared_count,
        "missing_input_count": missing_input_count,
        "max_abs_delta": max_abs_delta,
        "max_rms_delta": max_rms_delta,
        "all_compared": !value_mix_heads.is_empty() && missing_input_count == 0,
        "rows": rows,
    })
}

