fn attention_key_cache_dim_major_f16_roundtrip_best_matches(
    reference_records: &[ReferenceTraceRecord],
    rust_records: &BTreeMap<String, RustTraceRecord>,
) -> Value {
    let reference_heads = reference_records
        .iter()
        .filter_map(|record| {
            let head = parse_stage_head(&record.stage, "k_kv_head")?;
            let first_values = key_cache_dim_major_first_values(record)?;
            Some((head, first_values))
        })
        .collect::<BTreeMap<_, _>>();
    let rust_heads = rust_records
        .iter()
        .filter_map(|(stage, record)| {
            parse_stage_head(stage, "attention_k_cache_f16_roundtrip_kv_head")
                .map(|head| (head, record))
        })
        .filter(|(_, record)| !record.first_values.is_empty())
        .collect::<BTreeMap<_, _>>();

    let mut rows = Vec::new();
    let mut identity_best_count = 0usize;
    let mut non_identity_best_count = 0usize;
    let mut missing_identity_count = 0usize;

    for (&reference_head, reference_values) in &reference_heads {
        let mut candidates = rust_heads
            .iter()
            .map(|(rust_head, rust)| {
                head_lane_delta(reference_head, *rust_head, reference_values, &rust.first_values)
            })
            .collect::<Vec<_>>();
        candidates.sort_by(head_lane_delta_order);

        let best = candidates.first().copied();
        let identity =
            candidates.iter().copied().find(|candidate| candidate.rust_head == reference_head);
        let identity_rank = identity.and_then(|identity| {
            candidates.iter().position(|candidate| {
                candidate.rust_head == identity.rust_head
                    && candidate.reference_head == identity.reference_head
            })
        });

        if let Some(best) = best {
            if best.rust_head == reference_head {
                identity_best_count += 1;
            } else {
                non_identity_best_count += 1;
            }
        }
        if identity.is_none() {
            missing_identity_count += 1;
        }

        rows.push(json!({
            "reference_head": reference_head,
            "best_rust_head": best.map(|best| best.rust_head),
            "identity_rust_head": reference_head,
            "identity_is_best": best.is_some_and(|best| best.rust_head == reference_head),
            "identity_rank": identity_rank.map(|rank| rank + 1),
            "best_delta": best.map(head_lane_delta_summary),
            "identity_delta": identity.map(head_lane_delta_summary),
            "candidate_count": candidates.len(),
        }));
    }

    json!({
        "diagnostic_only": true,
        "claim_allowed": false,
        "policy": "key-cache dim-major F16-roundtrip best matches are diagnostic layout evidence only; they reinterpret reference k_kv_head samples from token-major to dim-major and do not promote reference parity, A770 semantic quality, attention score residency, resident KV, selected attention, or any support claim",
        "reference_stage_prefix": "k_kv_head",
        "reference_reinterpretation": "token_major_to_dim_major",
        "rust_stage_prefix": "attention_k_cache_f16_roundtrip_kv_head",
        "reference_head_count": reference_heads.len(),
        "rust_head_count": rust_heads.len(),
        "identity_best_count": identity_best_count,
        "non_identity_best_count": non_identity_best_count,
        "missing_identity_count": missing_identity_count,
        "all_identity_best": !reference_heads.is_empty()
            && reference_heads.len() == identity_best_count
            && missing_identity_count == 0,
        "rows": rows,
    })
}

fn key_cache_dim_major_first_values(record: &ReferenceTraceRecord) -> Option<Vec<f32>> {
    if !record.values_available || record.first_values.is_empty() {
        return None;
    }
    let dim_count = usize::try_from(*record.shape.first()?).ok()?;
    let token_count = usize::try_from(*record.shape.get(1)?).ok()?;
    let sample_count = dim_count.checked_mul(token_count)?;
    if dim_count == 0 || token_count == 0 || record.first_values.len() < sample_count {
        return None;
    }
    let mut dim_major = Vec::with_capacity(sample_count);
    for dim in 0..dim_count {
        for token in 0..token_count {
            dim_major.push(record.first_values[token * dim_count + dim]);
        }
    }
    Some(dim_major)
}

fn attention_key_score_input_delta(
    reference_records: &[ReferenceTraceRecord],
    rust_records: &BTreeMap<String, RustTraceRecord>,
) -> Value {
    let reference_heads = reference_records
        .iter()
        .filter_map(|record| {
            parse_stage_head(&record.stage, "k_kv_head").map(|head| (head, record))
        })
        .filter(|(_, record)| record.values_available && !record.first_values.is_empty())
        .collect::<BTreeMap<_, _>>();
    let rust_heads = rust_records
        .iter()
        .filter_map(|(stage, record)| {
            parse_stage_head(stage, "attention_k_score_input_head").map(|head| (head, record))
        })
        .filter(|(_, record)| !record.first_values.is_empty())
        .collect::<BTreeMap<_, _>>();

    let group_size = if reference_heads.is_empty()
        || rust_heads.is_empty()
        || !rust_heads.len().is_multiple_of(reference_heads.len())
    {
        None
    } else {
        Some(rust_heads.len() / reference_heads.len())
    };

    let mut rows = Vec::new();
    let mut compared_head_count = 0usize;
    let mut missing_head_count = 0usize;
    let mut max_abs_delta = 0.0f64;
    let mut max_rms_delta = 0.0f64;

    for (&head, rust) in &rust_heads {
        let kv_head = group_size.map(|group_size| head / group_size);
        let reference = kv_head.and_then(|kv_head| reference_heads.get(&kv_head).copied());
        let mut blocked_reasons = Vec::<String>::new();
        let mut delta = Value::Null;
        let mut status = "missing_input";
        let mut dim_count = rust.shape.first().copied().unwrap_or(0);
        let mut token_count = rust.shape.get(1).copied().unwrap_or(0);
        let mut required_sample_count = dim_count.saturating_mul(token_count);
        let mut reference_sample_count = reference.map(|record| record.first_values.len());
        let rust_sample_count = rust.first_values.len();

        if let Some(reference) = reference {
            dim_count = usize::try_from(*reference.shape.first().unwrap_or(&0)).unwrap_or(0);
            token_count = usize::try_from(*reference.shape.get(1).unwrap_or(&0)).unwrap_or(0);
            required_sample_count = dim_count.saturating_mul(token_count);
            reference_sample_count = Some(reference.first_values.len());
            let reference_dim_major = key_cache_dim_major_first_values(reference);

            if dim_count == 0 || token_count == 0 {
                blocked_reasons.push("reference_k_kv_head_shape_unusable".to_string());
            }
            if reference_dim_major.is_none() {
                blocked_reasons.push("reference_k_kv_head_sample_incomplete".to_string());
            }
            if rust.first_values.len() < required_sample_count {
                blocked_reasons.push("rust_attention_k_score_input_sample_incomplete".to_string());
            }
            if let Some(reference_dim_major) = reference_dim_major
                && rust.first_values.len() >= required_sample_count
                && required_sample_count > 0
            {
                delta = dim_major_token_value_delta(
                    &reference_dim_major,
                    &rust.first_values,
                    dim_count,
                    token_count,
                );
                max_abs_delta = max_abs_delta.max(delta_metric(&delta, "/max_abs_delta"));
                max_rms_delta = max_rms_delta.max(delta_metric(&delta, "/rms_abs_delta"));
                compared_head_count += 1;
                status = "compared";
            }
        } else {
            blocked_reasons.push("reference_k_kv_head_missing".to_string());
        }

        if status == "missing_input" {
            missing_head_count += 1;
        }
        rows.push(json!({
            "head": head,
            "kv_head": kv_head,
            "status": status,
            "reference_stage_present": reference.is_some(),
            "rust_stage_present": true,
            "dim_count": dim_count,
            "token_count": token_count,
            "required_sample_count": required_sample_count,
            "reference_sample_count": reference_sample_count,
            "rust_sample_count": rust_sample_count,
            "blocked_reasons": blocked_reasons,
            "delta": delta,
        }));
    }

    json!({
        "diagnostic_only": true,
        "claim_allowed": false,
        "policy": "key score-input delta is diagnostic-only evidence for whether raw attention score drift follows Rust K score inputs; it reinterprets reference k_kv_head token-major samples as dim-major and does not promote reference parity, A770 semantic quality, attention score residency, selected attention, resident KV, or any support claim",
        "reference_stage_prefix": "k_kv_head",
        "reference_reinterpretation": "token_major_to_dim_major",
        "rust_stage_prefix": "attention_k_score_input_head",
        "reference_head_count": reference_heads.len(),
        "rust_head_count": rust_heads.len(),
        "group_size": group_size,
        "compared_head_count": compared_head_count,
        "missing_head_count": missing_head_count,
        "max_abs_delta": max_abs_delta,
        "max_rms_delta": max_rms_delta,
        "all_compared": !rust_heads.is_empty() && missing_head_count == 0,
        "rows": rows,
    })
}

fn attention_key_score_input_history_delta(
    reference_records: &[ReferenceTraceRecord],
    rust_records: &BTreeMap<String, RustTraceRecord>,
) -> Value {
    let reference_heads = reference_records
        .iter()
        .filter_map(|record| {
            parse_stage_head(&record.stage, "kcur_history_kv_head").map(|head| (head, record))
        })
        .filter(|(_, record)| record.values_available && !record.first_values.is_empty())
        .collect::<BTreeMap<_, _>>();
    let rust_stage_prefix = "attention_k_score_input_head";
    let rust_heads = rust_records
        .iter()
        .filter_map(|(stage, record)| {
            parse_stage_head(stage, rust_stage_prefix).map(|head| (head, record))
        })
        .filter(|(_, record)| !record.first_values.is_empty())
        .collect::<BTreeMap<_, _>>();

    let group_size = if reference_heads.is_empty()
        || rust_heads.is_empty()
        || !rust_heads.len().is_multiple_of(reference_heads.len())
    {
        None
    } else {
        Some(rust_heads.len() / reference_heads.len())
    };

    let mut rows = Vec::new();
    let mut compared_head_count = 0usize;
    let mut missing_head_count = 0usize;
    let mut total_bucket_mismatch_count = 0usize;
    let mut max_bucket_mismatch_count = 0usize;
    let mut max_abs_delta = 0.0f64;
    let mut max_rms_delta = 0.0f64;
    let mut blocked_reasons = Vec::<String>::new();

    if reference_heads.is_empty() {
        blocked_reasons.push("reference_kcur_history_records_missing".to_string());
    }
    if rust_heads.is_empty() {
        blocked_reasons.push("rust_attention_k_score_input_records_missing".to_string());
    }
    if !reference_heads.is_empty() && !rust_heads.is_empty() && group_size.is_none() {
        blocked_reasons.push("attention_head_to_kv_head_group_size_unavailable".to_string());
    }

    for (&head, rust) in &rust_heads {
        let kv_head = group_size.map(|group_size| head / group_size);
        let reference = kv_head.and_then(|kv_head| reference_heads.get(&kv_head).copied());
        let mut row_blockers = Vec::<String>::new();
        let mut status = "missing_input";
        let mut delta = Value::Null;
        let mut dim_count = reference
            .and_then(|record| record.shape.first().and_then(|dim| usize::try_from(*dim).ok()))
            .or_else(|| rust.shape.first().copied())
            .unwrap_or(0);
        let mut token_count = reference
            .and_then(|record| record.shape.get(1).and_then(|dim| usize::try_from(*dim).ok()))
            .or_else(|| rust.shape.get(1).copied())
            .unwrap_or(0);
        let mut required_sample_count = dim_count.saturating_mul(token_count);
        let reference_sample_count = reference.map(|record| record.first_values.len());
        let rust_sample_count = rust.first_values.len();

        if group_size.is_none() {
            row_blockers.push("attention_head_to_kv_head_group_size_unavailable".to_string());
        }
        if let Some(reference) = reference {
            dim_count = usize::try_from(*reference.shape.first().unwrap_or(&0)).unwrap_or(0);
            token_count = usize::try_from(*reference.shape.get(1).unwrap_or(&0)).unwrap_or(0);
            required_sample_count = dim_count.saturating_mul(token_count);
            if dim_count == 0 || token_count == 0 {
                row_blockers.push("reference_kcur_history_shape_unusable".to_string());
            }
            if reference.first_values.len() < required_sample_count {
                row_blockers.push("reference_kcur_history_sample_incomplete".to_string());
            }
            if rust.first_values.len() < required_sample_count {
                row_blockers.push("rust_attention_k_score_input_sample_incomplete".to_string());
            }
            if row_blockers.is_empty() && required_sample_count > 0 {
                delta = f16_bucket_delta_dim_major(
                    &reference.first_values,
                    &rust.first_values,
                    dim_count,
                    token_count,
                );
                let bucket_mismatch_count = delta
                    .pointer("/f16_bucket_mismatch_count")
                    .and_then(Value::as_u64)
                    .unwrap_or(0) as usize;
                total_bucket_mismatch_count += bucket_mismatch_count;
                max_bucket_mismatch_count = max_bucket_mismatch_count.max(bucket_mismatch_count);
                max_abs_delta = max_abs_delta.max(delta_metric(&delta, "/max_abs_delta"));
                max_rms_delta = max_rms_delta.max(delta_metric(&delta, "/rms_abs_delta"));
                compared_head_count += 1;
                status = "compared";
            }
        } else {
            row_blockers.push("reference_kcur_history_kv_head_missing".to_string());
        }

        if status == "missing_input" {
            missing_head_count += 1;
        }
        rows.push(json!({
            "head": head,
            "kv_head": kv_head,
            "status": status,
            "reference_stage_present": reference.is_some(),
            "rust_stage_present": true,
            "dim_count": dim_count,
            "token_count": token_count,
            "required_sample_count": required_sample_count,
            "reference_sample_count": reference_sample_count,
            "rust_sample_count": rust_sample_count,
            "blocked_reasons": row_blockers,
            "delta": delta,
        }));
    }

    json!({
        "diagnostic_only": true,
        "claim_allowed": false,
        "policy": "key score-input history delta is diagnostic-only evidence for whether raw attention score drift follows the reference Kcur history source expanded to Rust attention heads; it does not promote reference parity, A770 semantic quality, attention score residency, selected attention, resident KV, full residency, performance, or any support claim",
        "reference_stage_prefix": "kcur_history_kv_head",
        "reference_layout": "dim_major_token_minor",
        "rust_stage_prefix": rust_stage_prefix,
        "rust_layout": "dim_major_token_minor",
        "reference_head_count": reference_heads.len(),
        "rust_head_count": rust_heads.len(),
        "group_size": group_size,
        "compared_head_count": compared_head_count,
        "missing_head_count": missing_head_count,
        "total_f16_bucket_mismatch_count": total_bucket_mismatch_count,
        "max_head_f16_bucket_mismatch_count": max_bucket_mismatch_count,
        "max_abs_delta": max_abs_delta,
        "max_rms_delta": max_rms_delta,
        "all_compared": !rust_heads.is_empty() && missing_head_count == 0,
        "blocked_reasons": blocked_reasons,
        "rows": rows,
    })
}

fn attention_query_score_input_history_delta(
    reference_records: &[ReferenceTraceRecord],
    rust_records: &BTreeMap<String, RustTraceRecord>,
) -> Value {
    let reference_score_heads = reference_records
        .iter()
        .filter_map(|record| {
            parse_stage_head(&record.stage, "q_score_input_head").map(|head| (head, record))
        })
        .filter(|(_, record)| record.values_available && !record.first_values.is_empty())
        .collect::<BTreeMap<_, _>>();
    let reference_history_heads = reference_records
        .iter()
        .filter_map(|record| {
            parse_stage_head(&record.stage, "qcur_history_head").map(|head| (head, record))
        })
        .filter(|(_, record)| record.values_available && !record.first_values.is_empty())
        .collect::<BTreeMap<_, _>>();
    let rust_stage_prefix = "attention_q_score_input_head";
    let rust_heads = rust_records
        .iter()
        .filter_map(|(stage, record)| {
            parse_stage_head(stage, rust_stage_prefix).map(|head| (head, record))
        })
        .filter(|(_, record)| !record.first_values.is_empty())
        .collect::<BTreeMap<_, _>>();
    let mut head_ids = reference_score_heads
        .keys()
        .chain(reference_history_heads.keys())
        .chain(rust_heads.keys())
        .copied()
        .collect::<Vec<_>>();
    head_ids.sort_unstable();
    head_ids.dedup();

    let mut rows = Vec::new();
    let mut compared_head_count = 0usize;
    let mut missing_head_count = 0usize;
    let mut total_bucket_mismatch_count = 0usize;
    let mut max_bucket_mismatch_count = 0usize;
    let mut max_abs_delta = 0.0f64;
    let mut max_rms_delta = 0.0f64;
    let mut first_material_head = Value::Null;
    let mut blocked_reasons = Vec::<String>::new();

    if reference_score_heads.is_empty() && reference_history_heads.is_empty() {
        blocked_reasons.push("reference_query_score_input_history_records_missing".to_string());
    }
    if rust_heads.is_empty() {
        blocked_reasons.push("rust_attention_q_score_input_records_missing".to_string());
    }

    for &head in &head_ids {
        let (reference, reference_stage_prefix, reference_source_priority) =
            if let Some(reference) = reference_score_heads.get(&head).copied() {
                (Some(reference), "q_score_input_head", "score_input")
            } else if let Some(reference) = reference_history_heads.get(&head).copied() {
                (Some(reference), "qcur_history_head", "query_history")
            } else {
                (None, "none", "missing")
            };
        let rust = rust_heads.get(&head).copied();
        let mut row_blockers = Vec::<String>::new();
        let mut status = "missing_input";
        let mut delta = Value::Null;
        let mut material_mismatch = false;
        let mut dim_count = reference
            .and_then(|record| record.shape.first().and_then(|dim| usize::try_from(*dim).ok()))
            .or_else(|| rust.and_then(|record| record.shape.first().copied()))
            .unwrap_or(0);
        let mut token_count = reference
            .and_then(|record| record.shape.get(1).and_then(|dim| usize::try_from(*dim).ok()))
            .or_else(|| rust.and_then(|record| record.shape.get(1).copied()))
            .unwrap_or(0);
        let mut required_sample_count = dim_count.saturating_mul(token_count);
        let reference_sample_count = reference.map(|record| record.first_values.len());
        let rust_sample_count = rust.map(|record| record.first_values.len());

        match (reference, rust) {
            (Some(reference), Some(rust)) => {
                dim_count = usize::try_from(*reference.shape.first().unwrap_or(&0)).unwrap_or(0);
                token_count = usize::try_from(*reference.shape.get(1).unwrap_or(&0)).unwrap_or(0);
                required_sample_count = dim_count.saturating_mul(token_count);
                if dim_count == 0 || token_count == 0 {
                    row_blockers
                        .push("reference_query_score_input_history_shape_unusable".to_string());
                }
                if reference.first_values.len() < required_sample_count {
                    row_blockers
                        .push("reference_query_score_input_history_sample_incomplete".to_string());
                }
                if rust.first_values.len() < required_sample_count {
                    row_blockers.push("rust_attention_q_score_input_sample_incomplete".to_string());
                }
                if row_blockers.is_empty() && required_sample_count > 0 {
                    delta = f16_bucket_delta_dim_major(
                        &reference.first_values,
                        &rust.first_values,
                        dim_count,
                        token_count,
                    );
                    let bucket_mismatch_count = delta
                        .pointer("/f16_bucket_mismatch_count")
                        .and_then(Value::as_u64)
                        .unwrap_or(0) as usize;
                    total_bucket_mismatch_count += bucket_mismatch_count;
                    max_bucket_mismatch_count =
                        max_bucket_mismatch_count.max(bucket_mismatch_count);
                    max_abs_delta = max_abs_delta.max(delta_metric(&delta, "/max_abs_delta"));
                    max_rms_delta = max_rms_delta.max(delta_metric(&delta, "/rms_abs_delta"));
                    material_mismatch = bucket_mismatch_count > 0
                        || delta_metric(&delta, "/max_abs_delta") > 1.0e-6;
                    compared_head_count += 1;
                    status = "compared";
                }
            }
            (None, Some(_)) => {
                row_blockers.push("reference_query_score_input_head_missing".to_string());
            }
            (Some(_), None) => {
                row_blockers.push("rust_attention_q_score_input_head_missing".to_string());
            }
            (None, None) => {
                row_blockers.push("query_score_input_head_missing".to_string());
            }
        }

        if status == "missing_input" {
            missing_head_count += 1;
        }

        let row = json!({
            "head": head,
            "status": status,
            "reference_stage_prefix": reference_stage_prefix,
            "reference_source_priority": reference_source_priority,
            "rust_stage_prefix": rust_stage_prefix,
            "reference_stage_present": reference.is_some(),
            "rust_stage_present": rust.is_some(),
            "dim_count": dim_count,
            "token_count": token_count,
            "required_sample_count": required_sample_count,
            "reference_sample_count": reference_sample_count,
            "rust_sample_count": rust_sample_count,
            "blocked_reasons": row_blockers,
            "material_mismatch": material_mismatch,
            "delta": delta,
        });
        if material_mismatch && first_material_head.is_null() {
            first_material_head = row.clone();
        }
        rows.push(row);
    }

    json!({
        "diagnostic_only": true,
        "claim_allowed": false,
        "policy": "query score-input history delta is diagnostic-only evidence for whether selected score-position product drift follows reference/Rust Q score-input history differences; it does not promote runtime math changes, reference parity, A770 semantic quality, attention score residency, selected attention, resident KV, full residency, performance, or completion",
        "reference_score_stage_prefix": "q_score_input_head",
        "reference_history_stage_prefix": "qcur_history_head",
        "reference_layout": "dim_major_token_minor",
        "rust_stage_prefix": rust_stage_prefix,
        "rust_layout": "dim_major_token_minor",
        "reference_score_head_count": reference_score_heads.len(),
        "reference_history_head_count": reference_history_heads.len(),
        "rust_head_count": rust_heads.len(),
        "compared_head_count": compared_head_count,
        "missing_head_count": missing_head_count,
        "total_f16_bucket_mismatch_count": total_bucket_mismatch_count,
        "max_head_f16_bucket_mismatch_count": max_bucket_mismatch_count,
        "max_abs_delta": max_abs_delta,
        "max_rms_delta": max_rms_delta,
        "first_material_head": first_material_head,
        "all_compared": !head_ids.is_empty() && missing_head_count == 0,
        "blocked_reasons": blocked_reasons,
        "rows": rows,
    })
}

#[derive(Clone, Copy)]
struct DimMajorHistorySample<'a> {
    values: &'a [f32],
    dim_count: usize,
    token_count: usize,
}

fn reference_dim_major_history_sample(record: &ReferenceTraceRecord) -> DimMajorHistorySample<'_> {
    DimMajorHistorySample {
        values: &record.first_values,
        dim_count: record.shape.first().and_then(|dim| usize::try_from(*dim).ok()).unwrap_or(0),
        token_count: record.shape.get(1).and_then(|dim| usize::try_from(*dim).ok()).unwrap_or(0),
    }
}

fn rust_dim_major_history_sample(record: &RustTraceRecord) -> DimMajorHistorySample<'_> {
    DimMajorHistorySample {
        values: &record.first_values,
        dim_count: record.shape.first().copied().unwrap_or(0),
        token_count: record.shape.get(1).copied().unwrap_or(0),
    }
}

fn query_history_pair_delta(
    left: Option<DimMajorHistorySample<'_>>,
    right: Option<DimMajorHistorySample<'_>>,
    dim_count: usize,
    token_count: usize,
    left_missing_reason: &str,
    right_missing_reason: &str,
    left_incomplete_reason: &str,
    right_incomplete_reason: &str,
) -> Value {
    let mut blocked_reasons = Vec::<String>::new();
    let mut status = "missing_input";
    let mut delta = Value::Null;
    let mut material_mismatch = false;
    let required_sample_count = dim_count.saturating_mul(token_count);

    match (left, right) {
        (Some(left), Some(right)) => {
            if dim_count == 0 || token_count == 0 {
                blocked_reasons.push("query_history_shape_unusable".to_string());
            }
            if left.values.len() < required_sample_count {
                blocked_reasons.push(left_incomplete_reason.to_string());
            }
            if right.values.len() < required_sample_count {
                blocked_reasons.push(right_incomplete_reason.to_string());
            }
            if blocked_reasons.is_empty() {
                delta =
                    f16_bucket_delta_dim_major(left.values, right.values, dim_count, token_count);
                material_mismatch = f16_bucket_mismatch_count(&delta) > 0
                    || delta_metric(&delta, "/max_abs_delta") > 1.0e-6;
                status = "compared";
            }
        }
        (None, Some(_)) => {
            blocked_reasons.push(left_missing_reason.to_string());
        }
        (Some(_), None) => {
            blocked_reasons.push(right_missing_reason.to_string());
        }
        (None, None) => {
            blocked_reasons.push(left_missing_reason.to_string());
            blocked_reasons.push(right_missing_reason.to_string());
        }
    }

    json!({
        "status": status,
        "material_mismatch": material_mismatch,
        "dim_count": dim_count,
        "token_count": token_count,
        "required_sample_count": required_sample_count,
        "left_sample_count": left.map(|sample| sample.values.len()),
        "right_sample_count": right.map(|sample| sample.values.len()),
        "blocked_reasons": blocked_reasons,
        "delta": delta,
    })
}

fn query_boundary_material(delta: &Value) -> bool {
    delta.pointer("/material_mismatch").and_then(Value::as_bool).unwrap_or(false)
}

fn query_boundary_compared(delta: &Value) -> bool {
    delta.pointer("/status").and_then(Value::as_str) == Some("compared")
}

fn query_boundary_sample_incomplete(delta: &Value) -> bool {
    delta.pointer("/blocked_reasons").and_then(Value::as_array).is_some_and(|reasons| {
        reasons.iter().any(|reason| {
            reason.as_str().is_some_and(|reason| reason.ends_with("_sample_incomplete"))
        })
    })
}

fn attention_query_score_input_boundary(
    reference_records: &[ReferenceTraceRecord],
    rust_records: &BTreeMap<String, RustTraceRecord>,
) -> Value {
    let reference_score_heads = reference_records
        .iter()
        .filter_map(|record| {
            parse_stage_head(&record.stage, "q_score_input_head").map(|head| (head, record))
        })
        .filter(|(_, record)| record.values_available && !record.first_values.is_empty())
        .collect::<BTreeMap<_, _>>();
    let reference_history_heads = reference_records
        .iter()
        .filter_map(|record| {
            parse_stage_head(&record.stage, "qcur_history_head").map(|head| (head, record))
        })
        .filter(|(_, record)| record.values_available && !record.first_values.is_empty())
        .collect::<BTreeMap<_, _>>();
    let rust_rope_heads = rust_records
        .iter()
        .filter_map(|(stage, record)| {
            parse_stage_head(stage, "attention_q_rope_head").map(|head| (head, record))
        })
        .filter(|(_, record)| !record.first_values.is_empty())
        .collect::<BTreeMap<_, _>>();
    let rust_f16_heads = rust_records
        .iter()
        .filter_map(|(stage, record)| {
            parse_stage_head(stage, "attention_q_rope_f16_roundtrip_head")
                .map(|head| (head, record))
        })
        .filter(|(_, record)| !record.first_values.is_empty())
        .collect::<BTreeMap<_, _>>();
    let rust_score_heads = rust_records
        .iter()
        .filter_map(|(stage, record)| {
            parse_stage_head(stage, "attention_q_score_input_head").map(|head| (head, record))
        })
        .filter(|(_, record)| !record.first_values.is_empty())
        .collect::<BTreeMap<_, _>>();

    let mut head_ids = reference_score_heads
        .keys()
        .chain(reference_history_heads.keys())
        .chain(rust_rope_heads.keys())
        .chain(rust_f16_heads.keys())
        .chain(rust_score_heads.keys())
        .copied()
        .collect::<Vec<_>>();
    head_ids.sort_unstable();
    head_ids.dedup();

    let mut rows = Vec::new();
    let mut compared_head_count = 0usize;
    let mut fully_compared_head_count = 0usize;
    let mut missing_head_count = 0usize;
    let mut first_material_head = Value::Null;
    let mut boundary_counts = BTreeMap::<&'static str, usize>::new();
    let mut max_abs_delta = 0.0f64;
    let mut max_rms_delta = 0.0f64;
    let mut first_values_incomplete_delta_count = 0usize;
    let mut recommended_first_values_limit = 0usize;
    let mut blocked_reasons = Vec::<String>::new();

    if reference_score_heads.is_empty() && reference_history_heads.is_empty() {
        blocked_reasons.push("reference_query_score_input_history_records_missing".to_string());
    }
    if rust_rope_heads.is_empty() {
        blocked_reasons.push("rust_attention_q_rope_history_records_missing".to_string());
    }
    if rust_f16_heads.is_empty() {
        blocked_reasons
            .push("rust_attention_q_rope_f16_roundtrip_history_records_missing".to_string());
    }
    if rust_score_heads.is_empty() {
        blocked_reasons.push("rust_attention_q_score_input_records_missing".to_string());
    }

    for &head in &head_ids {
        let (reference, reference_stage_prefix, reference_source_priority) =
            if let Some(reference) = reference_score_heads.get(&head).copied() {
                (Some(reference), "q_score_input_head", "score_input")
            } else if let Some(reference) = reference_history_heads.get(&head).copied() {
                (Some(reference), "qcur_history_head", "query_history")
            } else {
                (None, "none", "missing")
            };
        let reference_sample = reference.map(reference_dim_major_history_sample);
        let rust_rope_sample =
            rust_rope_heads.get(&head).copied().map(rust_dim_major_history_sample);
        let rust_f16_sample = rust_f16_heads.get(&head).copied().map(rust_dim_major_history_sample);
        let rust_score_sample =
            rust_score_heads.get(&head).copied().map(rust_dim_major_history_sample);

        let dim_count = reference_sample
            .or(rust_rope_sample)
            .or(rust_f16_sample)
            .or(rust_score_sample)
            .map(|sample| sample.dim_count)
            .unwrap_or(0);
        let token_count = reference_sample
            .or(rust_rope_sample)
            .or(rust_f16_sample)
            .or(rust_score_sample)
            .map(|sample| sample.token_count)
            .unwrap_or(0);

        let reference_to_rope_delta = query_history_pair_delta(
            reference_sample,
            rust_rope_sample,
            dim_count,
            token_count,
            "reference_query_score_input_history_head_missing",
            "rust_attention_q_rope_head_missing",
            "reference_query_score_input_history_sample_incomplete",
            "rust_attention_q_rope_sample_incomplete",
        );
        let rope_to_f16_delta = query_history_pair_delta(
            rust_rope_sample,
            rust_f16_sample,
            dim_count,
            token_count,
            "rust_attention_q_rope_head_missing",
            "rust_attention_q_rope_f16_roundtrip_head_missing",
            "rust_attention_q_rope_sample_incomplete",
            "rust_attention_q_rope_f16_roundtrip_sample_incomplete",
        );
        let f16_to_score_delta = query_history_pair_delta(
            rust_f16_sample,
            rust_score_sample,
            dim_count,
            token_count,
            "rust_attention_q_rope_f16_roundtrip_head_missing",
            "rust_attention_q_score_input_head_missing",
            "rust_attention_q_rope_f16_roundtrip_sample_incomplete",
            "rust_attention_q_score_input_sample_incomplete",
        );
        let reference_to_score_delta = query_history_pair_delta(
            reference_sample,
            rust_score_sample,
            dim_count,
            token_count,
            "reference_query_score_input_history_head_missing",
            "rust_attention_q_score_input_head_missing",
            "reference_query_score_input_history_sample_incomplete",
            "rust_attention_q_score_input_sample_incomplete",
        );

        for delta in [
            &reference_to_rope_delta,
            &rope_to_f16_delta,
            &f16_to_score_delta,
            &reference_to_score_delta,
        ] {
            if query_boundary_compared(delta) {
                max_abs_delta = max_abs_delta.max(delta_metric(delta, "/delta/max_abs_delta"));
                max_rms_delta = max_rms_delta.max(delta_metric(delta, "/delta/rms_abs_delta"));
            } else if query_boundary_sample_incomplete(delta) {
                first_values_incomplete_delta_count += 1;
                recommended_first_values_limit = recommended_first_values_limit.max(
                    delta.pointer("/required_sample_count").and_then(Value::as_u64).unwrap_or(0)
                        as usize,
                );
            }
        }

        let first_material_boundary = if query_boundary_material(&reference_to_rope_delta) {
            "reference_to_rust_query_rope"
        } else if query_boundary_material(&rope_to_f16_delta) {
            "rust_query_f16_score_conversion"
        } else if query_boundary_material(&f16_to_score_delta) {
            "rust_query_score_input_serialization"
        } else if query_boundary_material(&reference_to_score_delta) {
            "unexplained_reference_to_score_input"
        } else if query_boundary_compared(&reference_to_score_delta) {
            "none"
        } else {
            "missing_input"
        };
        *boundary_counts.entry(first_material_boundary).or_insert(0) += 1;

        if query_boundary_compared(&reference_to_score_delta) {
            compared_head_count += 1;
        } else {
            missing_head_count += 1;
        }
        if query_boundary_compared(&reference_to_rope_delta)
            && query_boundary_compared(&rope_to_f16_delta)
            && query_boundary_compared(&f16_to_score_delta)
            && query_boundary_compared(&reference_to_score_delta)
        {
            fully_compared_head_count += 1;
        }

        let row = json!({
            "head": head,
            "reference_stage_prefix": reference_stage_prefix,
            "reference_source_priority": reference_source_priority,
            "rust_rope_stage_prefix": "attention_q_rope_head",
            "rust_f16_stage_prefix": "attention_q_rope_f16_roundtrip_head",
            "rust_score_stage_prefix": "attention_q_score_input_head",
            "reference_stage_present": reference_sample.is_some(),
            "rust_rope_stage_present": rust_rope_sample.is_some(),
            "rust_f16_stage_present": rust_f16_sample.is_some(),
            "rust_score_stage_present": rust_score_sample.is_some(),
            "dim_count": dim_count,
            "token_count": token_count,
            "first_material_boundary": first_material_boundary,
            "reference_to_rust_rope_delta": reference_to_rope_delta,
            "rust_rope_to_f16_delta": rope_to_f16_delta,
            "rust_f16_to_score_input_delta": f16_to_score_delta,
            "reference_to_score_input_delta": reference_to_score_delta,
        });
        if first_material_boundary != "none"
            && first_material_boundary != "missing_input"
            && first_material_head.is_null()
        {
            first_material_head = row.clone();
        }
        rows.push(row);
    }

    json!({
        "diagnostic_only": true,
        "claim_allowed": false,
        "policy": "query score-input boundary localization is diagnostic-only evidence for whether query score-input drift appears before Rust F16 score conversion, during conversion, or during score-input serialization; it does not change runtime math and does not promote reference parity, A770 semantic quality, attention score residency, selected attention, resident KV, full residency, performance, or completion",
        "reference_score_stage_prefix": "q_score_input_head",
        "reference_history_stage_prefix": "qcur_history_head",
        "reference_layout": "dim_major_token_minor",
        "rust_rope_stage_prefix": "attention_q_rope_head",
        "rust_f16_stage_prefix": "attention_q_rope_f16_roundtrip_head",
        "rust_score_stage_prefix": "attention_q_score_input_head",
        "rust_layout": "dim_major_token_minor",
        "reference_score_head_count": reference_score_heads.len(),
        "reference_history_head_count": reference_history_heads.len(),
        "rust_rope_head_count": rust_rope_heads.len(),
        "rust_f16_head_count": rust_f16_heads.len(),
        "rust_score_head_count": rust_score_heads.len(),
        "compared_head_count": compared_head_count,
        "fully_compared_head_count": fully_compared_head_count,
        "missing_head_count": missing_head_count,
        "first_values_incomplete_delta_count": first_values_incomplete_delta_count,
        "recommended_first_values_limit": if recommended_first_values_limit == 0 { Value::Null } else { json!(recommended_first_values_limit) },
        "first_material_head": first_material_head,
        "boundary_counts": boundary_counts,
        "max_abs_delta": max_abs_delta,
        "max_rms_delta": max_rms_delta,
        "all_compared": !head_ids.is_empty() && missing_head_count == 0,
        "blocked_reasons": blocked_reasons,
        "next_diagnostic": if first_values_incomplete_delta_count > 0 {
            "rerun reference and Rust trace capture with first_values_limit at least recommended_first_values_limit before changing query score-input policy"
        } else {
            "follow first_material_head and selected query score frontier before changing runtime math"
        },
        "rows": rows,
    })
}

fn query_f16_policy_candidate_value(
    id: &'static str,
    query_source: &'static str,
    query_values: &[f32],
    key_source: &'static str,
    key_values: &[f32],
    key_layout: ScoreKeyLayout,
    head: usize,
    head_dim: usize,
    key_slot: usize,
    query_token: usize,
) -> Value {
    let candidate = ScorePositionInputCandidate {
        id,
        base_candidate: id,
        score_input_variant: "query_state_fixed_reference_key",
        query_source,
        key_source,
        query_layout: ScoreQueryLayout::DimMajorHistory,
        key_layout,
        query_f16_roundtrip: false,
        key_f16_roundtrip: false,
        query_values,
        key_values,
    };
    match score_position_candidate_value(candidate, head, head_dim, key_slot, query_token, None) {
        Some(value) => json!({
            "status": "computed",
            "candidate": id,
            "query_source": query_source,
            "key_source": key_source,
            "score": value,
        }),
        None => json!({
            "status": "missing_input",
            "candidate": id,
            "query_source": query_source,
            "key_source": key_source,
            "score": Value::Null,
        }),
    }
}

fn score_value(candidate: &Value) -> Option<f64> {
    candidate.pointer("/score").and_then(Value::as_f64)
}

fn score_shift(left: &Value, right: &Value) -> Value {
    match (score_value(left), score_value(right)) {
        (Some(left), Some(right)) => json!(right - left),
        _ => Value::Null,
    }
}

fn score_shift_residual(predicted_shift: &Value, actual_shift: Option<f64>) -> Value {
    match (predicted_shift.as_f64(), actual_shift) {
        (Some(predicted), Some(actual)) => json!((actual - predicted).abs()),
        _ => Value::Null,
    }
}

fn score_position_qk_recompute_row_for_position<'a>(
    score_position_qk_recompute: &'a Value,
    label: &str,
    head: Option<usize>,
    key_slot: Option<usize>,
    query_token: Option<usize>,
) -> &'a Value {
    score_position_qk_recompute
        .pointer("/rows")
        .and_then(Value::as_array)
        .and_then(|rows| {
            rows.iter().find(|row| {
                row.pointer("/label").and_then(Value::as_str) == Some(label)
                    || (value_u64(row, "/head").and_then(|value| usize::try_from(value).ok())
                        == head
                        && value_u64(row, "/key_slot")
                            .and_then(|value| usize::try_from(value).ok())
                            == key_slot
                        && value_u64(row, "/query_token")
                            .and_then(|value| usize::try_from(value).ok())
                            == query_token)
            })
        })
        .unwrap_or(&Value::Null)
}

fn score_position_qk_recompute_top_dim(row: &Value) -> Option<u64> {
    row.pointer("/best_candidate_product_delta/top_abs_product_delta_contributors/0/dim")
        .and_then(Value::as_u64)
}

fn attention_query_score_input_f16_policy_effect(
    reference_records: &[ReferenceTraceRecord],
    rust_records: &BTreeMap<String, RustTraceRecord>,
    position_drilldown: &Value,
    score_position_qk_recompute: &Value,
) -> Value {
    let reference_score_query_heads = reference_records
        .iter()
        .filter_map(|record| {
            parse_stage_head(&record.stage, "q_score_input_head").map(|head| (head, record))
        })
        .filter(|(_, record)| record.values_available && !record.first_values.is_empty())
        .collect::<BTreeMap<_, _>>();
    let reference_query_history_heads = reference_records
        .iter()
        .filter_map(|record| {
            parse_stage_head(&record.stage, "qcur_history_head").map(|head| (head, record))
        })
        .filter(|(_, record)| record.values_available && !record.first_values.is_empty())
        .collect::<BTreeMap<_, _>>();
    let rust_rope_heads = rust_records
        .iter()
        .filter_map(|(stage, record)| {
            parse_stage_head(stage, "attention_q_rope_head").map(|head| (head, record))
        })
        .filter(|(_, record)| !record.first_values.is_empty())
        .collect::<BTreeMap<_, _>>();
    let rust_f16_heads = rust_records
        .iter()
        .filter_map(|(stage, record)| {
            parse_stage_head(stage, "attention_q_rope_f16_roundtrip_head")
                .map(|head| (head, record))
        })
        .filter(|(_, record)| !record.first_values.is_empty())
        .collect::<BTreeMap<_, _>>();
    let rust_score_heads = rust_records
        .iter()
        .filter_map(|(stage, record)| {
            parse_stage_head(stage, "attention_q_score_input_head").map(|head| (head, record))
        })
        .filter(|(_, record)| !record.first_values.is_empty())
        .collect::<BTreeMap<_, _>>();
    let reference_score_key_heads = reference_records
        .iter()
        .filter_map(|record| {
            parse_stage_head(&record.stage, "k_score_input_head").map(|head| (head, record))
        })
        .filter(|(_, record)| record.values_available && !record.first_values.is_empty())
        .collect::<BTreeMap<_, _>>();
    let reference_kcur_history_heads = reference_records
        .iter()
        .filter_map(|record| {
            parse_stage_head(&record.stage, "kcur_history_kv_head").map(|head| (head, record))
        })
        .filter(|(_, record)| record.values_available && !record.first_values.is_empty())
        .collect::<BTreeMap<_, _>>();
    let reference_legacy_key_heads = reference_records
        .iter()
        .filter_map(|record| {
            parse_stage_head(&record.stage, "k_kv_head").map(|head| (head, record))
        })
        .filter(|(_, record)| record.values_available && !record.first_values.is_empty())
        .collect::<BTreeMap<_, _>>();

    let (head_dim, head_count) =
        reference_trace_history_head_dim_count(&reference_score_query_heads)
            .or_else(|| reference_trace_history_head_dim_count(&reference_query_history_heads))
            .or_else(|| rust_trace_history_head_dim_count(&rust_rope_heads))
            .or_else(|| rust_trace_history_head_dim_count(&rust_f16_heads))
            .or_else(|| rust_trace_history_head_dim_count(&rust_score_heads))
            .unwrap_or((0, 0));
    let key_head_count = reference_score_key_heads
        .keys()
        .next_back()
        .map(|head| head + 1)
        .or_else(|| reference_kcur_history_heads.keys().next_back().map(|head| head + 1))
        .or_else(|| reference_legacy_key_heads.keys().next_back().map(|head| head + 1))
        .unwrap_or(0);
    let group_size = if head_count > 0 && key_head_count > 0 && head_count % key_head_count == 0 {
        Some(head_count / key_head_count)
    } else {
        None
    };

    let mut rows = Vec::new();
    let mut selected_count = 0usize;
    let mut compared_count = 0usize;
    let mut missing_input_count = 0usize;
    let mut f16_shift_closer_count = 0usize;
    let mut rope_shift_closer_count = 0usize;
    let mut score_input_matches_f16_count = 0usize;
    let mut blocked_reasons = Vec::<String>::new();

    if head_dim == 0 || head_count == 0 {
        blocked_reasons.push("query_score_input_head_shape_missing".to_string());
    }
    if group_size.is_none() {
        blocked_reasons.push("query_score_input_group_size_missing".to_string());
    }

    for label in ["first_material_position", "max_material_position"] {
        let Some(position) = position_drilldown.pointer(&format!("/{label}")) else {
            continue;
        };
        if position.is_null() {
            continue;
        }
        selected_count += 1;
        let head = value_u64(position, "/head").and_then(|value| usize::try_from(value).ok());
        let key_slot = value_u64(position, "/dim").and_then(|value| usize::try_from(value).ok());
        let query_token =
            value_u64(position, "/token").and_then(|value| usize::try_from(value).ok());
        let reference_score = position.pointer("/left").and_then(Value::as_f64);
        let rust_score = position.pointer("/right").and_then(Value::as_f64);
        let actual_score_shift = reference_score.zip(rust_score).map(|(left, right)| right - left);
        let qk_recompute_row = score_position_qk_recompute_row_for_position(
            score_position_qk_recompute,
            label,
            head,
            key_slot,
            query_token,
        );
        let selected_dim = score_position_qk_recompute_top_dim(qk_recompute_row);
        let selected_dim_source = if selected_dim.is_some() {
            "best_candidate_product_delta_top_contributor"
        } else if qk_recompute_row.is_null() {
            "missing_qk_recompute_row"
        } else {
            "missing_top_product_contributor"
        };
        let kv_head = head.zip(group_size).map(|(head, group_size)| head / group_size);
        let reference_query = head
            .and_then(|head| reference_score_query_heads.get(&head).copied())
            .or_else(|| head.and_then(|head| reference_query_history_heads.get(&head).copied()));
        let rust_rope = head.and_then(|head| rust_rope_heads.get(&head).copied());
        let rust_f16 = head.and_then(|head| rust_f16_heads.get(&head).copied());
        let rust_score_query = head.and_then(|head| rust_score_heads.get(&head).copied());
        let reference_key_score =
            kv_head.and_then(|kv_head| reference_score_key_heads.get(&kv_head).copied());
        let reference_key = reference_key_score.or_else(|| {
            kv_head.and_then(|kv_head| {
                reference_kcur_history_heads
                    .get(&kv_head)
                    .copied()
                    .or_else(|| reference_legacy_key_heads.get(&kv_head).copied())
            })
        });
        let reference_key_layout = if reference_key_score.is_some()
            || kv_head
                .and_then(|kv_head| reference_kcur_history_heads.get(&kv_head).copied())
                .is_some()
        {
            ScoreKeyLayout::DimMajor
        } else {
            ScoreKeyLayout::TokenMajor
        };
        let reference_key_source = if reference_key_score.is_some() {
            "reference_k_score_input_head"
        } else if matches!(reference_key_layout, ScoreKeyLayout::DimMajor) {
            "reference_kcur_history_kv_head"
        } else {
            "reference_k_kv_head"
        };

        let mut row_blockers = Vec::<String>::new();
        if head.is_none() {
            row_blockers.push("selected_score_head_missing".to_string());
        }
        if key_slot.is_none() {
            row_blockers.push("selected_score_key_slot_missing".to_string());
        }
        if query_token.is_none() {
            row_blockers.push("selected_score_query_token_missing".to_string());
        }
        if reference_query.is_none() {
            row_blockers.push("reference_query_score_input_head_missing".to_string());
        }
        if rust_rope.is_none() {
            row_blockers.push("rust_attention_q_rope_head_missing".to_string());
        }
        if rust_f16.is_none() {
            row_blockers.push("rust_attention_q_rope_f16_roundtrip_head_missing".to_string());
        }
        if rust_score_query.is_none() {
            row_blockers.push("rust_attention_q_score_input_head_missing".to_string());
        }
        if reference_key.is_none() {
            row_blockers.push("reference_score_key_head_missing".to_string());
        }
        if head_dim == 0 {
            row_blockers.push("query_score_input_head_dim_missing".to_string());
        }

        let mut candidates = Vec::<Value>::new();
        let mut f16_shift = Value::Null;
        let mut rope_shift = Value::Null;
        let mut score_input_shift = Value::Null;
        let mut f16_shift_residual = Value::Null;
        let mut rope_shift_residual = Value::Null;
        let mut score_input_shift_residual = Value::Null;
        let mut classification = "missing_input";

        if row_blockers.is_empty() {
            if let (
                Some(head),
                Some(key_slot),
                Some(query_token),
                Some(reference_query),
                Some(rust_rope),
                Some(rust_f16),
                Some(rust_score_query),
                Some(reference_key),
            ) = (
                head,
                key_slot,
                query_token,
                reference_query,
                rust_rope,
                rust_f16,
                rust_score_query,
                reference_key,
            ) {
                let reference_candidate = query_f16_policy_candidate_value(
                    "reference_query_fixed_reference_key",
                    "reference_q_score_input_or_qcur_history",
                    &reference_query.first_values,
                    reference_key_source,
                    &reference_key.first_values,
                    reference_key_layout,
                    head,
                    head_dim,
                    key_slot,
                    query_token,
                );
                let rust_rope_candidate = query_f16_policy_candidate_value(
                    "rust_rope_query_fixed_reference_key",
                    "rust_attention_q_rope_head",
                    &rust_rope.first_values,
                    reference_key_source,
                    &reference_key.first_values,
                    reference_key_layout,
                    head,
                    head_dim,
                    key_slot,
                    query_token,
                );
                let rust_f16_candidate = query_f16_policy_candidate_value(
                    "rust_f16_query_fixed_reference_key",
                    "rust_attention_q_rope_f16_roundtrip_head",
                    &rust_f16.first_values,
                    reference_key_source,
                    &reference_key.first_values,
                    reference_key_layout,
                    head,
                    head_dim,
                    key_slot,
                    query_token,
                );
                let rust_score_candidate = query_f16_policy_candidate_value(
                    "rust_score_query_fixed_reference_key",
                    "rust_attention_q_score_input_head",
                    &rust_score_query.first_values,
                    reference_key_source,
                    &reference_key.first_values,
                    reference_key_layout,
                    head,
                    head_dim,
                    key_slot,
                    query_token,
                );

                rope_shift = score_shift(&reference_candidate, &rust_rope_candidate);
                f16_shift = score_shift(&reference_candidate, &rust_f16_candidate);
                score_input_shift = score_shift(&reference_candidate, &rust_score_candidate);
                rope_shift_residual = score_shift_residual(&rope_shift, actual_score_shift);
                f16_shift_residual = score_shift_residual(&f16_shift, actual_score_shift);
                score_input_shift_residual =
                    score_shift_residual(&score_input_shift, actual_score_shift);

                let rope_residual = rope_shift_residual.as_f64().unwrap_or(f64::INFINITY);
                let f16_residual = f16_shift_residual.as_f64().unwrap_or(f64::INFINITY);
                let score_residual = score_input_shift_residual.as_f64().unwrap_or(f64::INFINITY);
                classification = if score_value(&rust_f16_candidate)
                    == score_value(&rust_score_candidate)
                    && f16_residual <= rope_residual
                {
                    score_input_matches_f16_count += 1;
                    "score_input_matches_f16_conversion"
                } else if f16_residual < rope_residual && f16_residual <= score_residual {
                    f16_shift_closer_count += 1;
                    "score_delta_better_predicted_by_query_f16_conversion"
                } else if rope_residual < f16_residual && rope_residual <= score_residual {
                    rope_shift_closer_count += 1;
                    "score_delta_better_predicted_by_pre_f16_query"
                } else {
                    "score_delta_not_explained_by_query_f16_policy"
                };
                candidates = vec![
                    reference_candidate,
                    rust_rope_candidate,
                    rust_f16_candidate,
                    rust_score_candidate,
                ];
                compared_count += 1;
            } else {
                row_blockers.push("selected_query_context_missing_after_blocker_check".to_string());
            }
        } else {
            missing_input_count += 1;
        }

        rows.push(json!({
            "label": label,
            "status": if row_blockers.is_empty() { "compared" } else { "missing_input" },
            "classification": classification,
            "head": head,
            "kv_head": kv_head,
            "key_slot": key_slot,
            "query_token": query_token,
            "selected_dim": selected_dim,
            "selected_dim_source": selected_dim_source,
            "selected_dim_context_present": selected_dim.is_some(),
            "head_dim": head_dim,
            "reference_score": reference_score,
            "rust_score": rust_score,
            "actual_score_shift": actual_score_shift,
            "reference_key_source": reference_key_source,
            "reference_key_layout": reference_key_layout.label(),
            "blocked_reasons": row_blockers,
            "candidates": candidates,
            "top_abs_product_delta_contributors": qk_recompute_row.pointer("/best_candidate_product_delta/top_abs_product_delta_contributors").cloned().unwrap_or(Value::Null),
            "selected_dim_abs_product_delta": qk_recompute_row.pointer("/best_candidate_product_delta/top_abs_product_delta_contributors/0/abs_product_delta").cloned().unwrap_or(Value::Null),
            "rope_shift_from_reference": rope_shift,
            "f16_shift_from_reference": f16_shift,
            "score_input_shift_from_reference": score_input_shift,
            "rope_shift_residual_abs": rope_shift_residual,
            "f16_shift_residual_abs": f16_shift_residual,
            "score_input_shift_residual_abs": score_input_shift_residual,
        }));
    }

    let classification = if selected_count == 0 {
        "no_selected_score_positions"
    } else if missing_input_count > 0 {
        "selected_score_positions_missing_inputs"
    } else if score_input_matches_f16_count == compared_count && compared_count > 0 {
        "selected_score_drift_follows_query_f16_score_input"
    } else if f16_shift_closer_count > rope_shift_closer_count {
        "selected_score_drift_partially_follows_query_f16_conversion"
    } else if rope_shift_closer_count > 0 {
        "selected_score_drift_not_improved_by_query_f16_conversion"
    } else {
        "selected_score_drift_query_f16_policy_unpinned"
    };
    let next_diagnostic = match classification {
        "selected_score_drift_follows_query_f16_score_input"
        | "selected_score_drift_partially_follows_query_f16_conversion" => {
            "probe whether Rust query F16 conversion policy should be aligned with the reference score operand before changing runtime math"
        }
        "selected_score_drift_not_improved_by_query_f16_conversion" => {
            "do not change query F16 conversion from this evidence; inspect key contribution, mixed Q/K score slots, or reference-to-Rust query RoPE rows"
        }
        "selected_score_positions_missing_inputs" => {
            "capture missing query/key score-input stages before interpreting F16 policy"
        }
        "no_selected_score_positions" => {
            "capture score-position drift before probing query F16 policy"
        }
        _ => "add a narrower selected-position Q/K source probe before changing runtime math",
    };

    json!({
        "diagnostic_only": true,
        "claim_allowed": false,
        "policy": "query score-input F16 policy effect is diagnostic-only evidence for whether selected raw score slots follow Rust query F16 conversion against a fixed reference key; it does not change runtime math and does not promote reference parity, A770 semantic quality, attention score residency, selected attention, resident KV, full residency, performance, or completion",
        "classification": classification,
        "selected_count": selected_count,
        "compared_count": compared_count,
        "missing_input_count": missing_input_count,
        "score_input_matches_f16_count": score_input_matches_f16_count,
        "f16_shift_closer_count": f16_shift_closer_count,
        "rope_shift_closer_count": rope_shift_closer_count,
        "reference_query_head_count": reference_score_query_heads.len().max(reference_query_history_heads.len()),
        "rust_rope_head_count": rust_rope_heads.len(),
        "rust_f16_head_count": rust_f16_heads.len(),
        "rust_score_head_count": rust_score_heads.len(),
        "reference_key_head_count": key_head_count,
        "head_dim": if head_dim == 0 { Value::Null } else { json!(head_dim) },
        "head_count": if head_count == 0 { Value::Null } else { json!(head_count) },
        "group_size": group_size,
        "blocked_reasons": blocked_reasons,
        "rows": rows,
        "next_diagnostic": next_diagnostic,
    })
}

fn attention_selected_score_mixed_qk_contribution(
    qk_recompute: &Value,
    query_boundary: &Value,
) -> Value {
    let rows = qk_recompute.pointer("/rows").and_then(Value::as_array);
    let mut output_rows = Vec::<Value>::new();
    let mut classification_counts = BTreeMap::<String, usize>::new();
    let mut dominant_input_counts = BTreeMap::<String, usize>::new();
    let mut query_boundary_counts = BTreeMap::<String, usize>::new();
    let mut selected_count = 0usize;
    let mut compared_count = 0usize;
    let mut product_delta_available_count = 0usize;
    let mut missing_input_count = 0usize;
    let mut unresolved_residual_count = 0usize;
    let mut query_dominant_count = 0usize;
    let mut key_dominant_count = 0usize;
    let mut mixed_qk_dominant_count = 0usize;
    let mut no_material_product_delta_count = 0usize;
    let mut max_abs_product_delta = 0.0f64;
    let mut first_unresolved_row = Value::Null;
    let mut first_product_row = Value::Null;

    if let Some(rows) = rows {
        for row in rows {
            selected_count += 1;
            let status = row.pointer("/status").and_then(Value::as_str).unwrap_or("unknown");
            if status != "recomputed" {
                missing_input_count += 1;
            } else {
                compared_count += 1;
            }

            let product_delta = row.pointer("/best_candidate_product_delta");
            let product_delta_available = product_delta.is_some_and(|delta| !delta.is_null());
            if product_delta_available {
                product_delta_available_count += 1;
            }

            let reference_residual = row
                .pointer("/best_reference_candidate/reference_abs_delta")
                .and_then(Value::as_f64)
                .is_some_and(|delta| delta > SCORE_POSITION_RECOMPUTE_RESIDUAL_WARN_ABS);
            let rust_residual = row
                .pointer("/best_rust_candidate/rust_abs_delta")
                .and_then(Value::as_f64)
                .is_some_and(|delta| delta > SCORE_POSITION_RECOMPUTE_RESIDUAL_WARN_ABS);
            let unresolved_residual = reference_residual && rust_residual;
            if unresolved_residual {
                unresolved_residual_count += 1;
            }

            let dominant_input = product_delta
                .and_then(|delta| delta.pointer("/dominant_input"))
                .and_then(Value::as_str)
                .unwrap_or("unavailable");
            if product_delta_available {
                *dominant_input_counts.entry(dominant_input.to_string()).or_insert(0) += 1;
            }
            let row_classification = if status != "recomputed" {
                "candidate_delta_unavailable"
            } else if !product_delta_available {
                "candidate_delta_unavailable"
            } else if unresolved_residual {
                "unresolved_residual"
            } else {
                match dominant_input {
                    "query" => {
                        query_dominant_count += 1;
                        "query_dominant"
                    }
                    "key" => {
                        key_dominant_count += 1;
                        "key_dominant"
                    }
                    "query_and_key" => {
                        mixed_qk_dominant_count += 1;
                        "mixed_qk_dominant"
                    }
                    "none" => {
                        no_material_product_delta_count += 1;
                        "no_material_product_delta"
                    }
                    _ => "candidate_delta_unavailable",
                }
            };
            *classification_counts.entry(row_classification.to_string()).or_insert(0) += 1;

            let head = row.pointer("/head").and_then(Value::as_u64);
            let query_boundary_row = head
                .and_then(|head| query_boundary_row_for_head(query_boundary, head))
                .cloned()
                .unwrap_or(Value::Null);
            let query_first_boundary = query_boundary_row
                .pointer("/first_material_boundary")
                .and_then(Value::as_str)
                .or_else(|| query_boundary_row.pointer("/classification").and_then(Value::as_str));
            if let Some(boundary) = query_first_boundary {
                *query_boundary_counts.entry(boundary.to_string()).or_insert(0) += 1;
            }

            max_abs_product_delta = max_abs_product_delta.max(
                product_delta
                    .and_then(|delta| delta.pointer("/max_abs_product_delta"))
                    .and_then(Value::as_f64)
                    .unwrap_or(0.0),
            );
            if first_product_row.is_null() && product_delta_available {
                first_product_row = json!({
                    "label": row.pointer("/label").cloned().unwrap_or(Value::Null),
                    "head": row.pointer("/head").cloned().unwrap_or(Value::Null),
                    "key_slot": row.pointer("/key_slot").cloned().unwrap_or(Value::Null),
                    "query_token": row.pointer("/query_token").cloned().unwrap_or(Value::Null),
                    "classification": row_classification,
                    "dominant_input": dominant_input,
                    "product_delta": product_delta.cloned().unwrap_or(Value::Null),
                });
            }
            if first_unresolved_row.is_null() && row_classification == "unresolved_residual" {
                first_unresolved_row = json!({
                    "label": row.pointer("/label").cloned().unwrap_or(Value::Null),
                    "head": row.pointer("/head").cloned().unwrap_or(Value::Null),
                    "key_slot": row.pointer("/key_slot").cloned().unwrap_or(Value::Null),
                    "query_token": row.pointer("/query_token").cloned().unwrap_or(Value::Null),
                    "reference_abs_delta": row
                        .pointer("/best_reference_candidate/reference_abs_delta")
                        .cloned()
                        .unwrap_or(Value::Null),
                    "rust_abs_delta": row
                        .pointer("/best_rust_candidate/rust_abs_delta")
                        .cloned()
                        .unwrap_or(Value::Null),
                });
            }

            output_rows.push(json!({
                "label": row.pointer("/label").cloned().unwrap_or(Value::Null),
                "status": status,
                "classification": row_classification,
                "head": row.pointer("/head").cloned().unwrap_or(Value::Null),
                "kv_head": row.pointer("/kv_head").cloned().unwrap_or(Value::Null),
                "key_slot": row.pointer("/key_slot").cloned().unwrap_or(Value::Null),
                "query_token": row.pointer("/query_token").cloned().unwrap_or(Value::Null),
                "actual_abs_delta": row.pointer("/actual_abs_delta").cloned().unwrap_or(Value::Null),
                "reference_best_candidate": row
                    .pointer("/best_reference_candidate")
                    .cloned()
                    .unwrap_or(Value::Null),
                "rust_best_candidate": row
                    .pointer("/best_rust_candidate")
                    .cloned()
                    .unwrap_or(Value::Null),
                "reference_residual_over_warn": reference_residual,
                "rust_residual_over_warn": rust_residual,
                "product_delta_available": product_delta_available,
                "dominant_input": if product_delta_available {
                    json!(dominant_input)
                } else {
                    Value::Null
                },
                "best_candidate_product_delta": product_delta.cloned().unwrap_or(Value::Null),
                "query_score_input_boundary": query_boundary_row,
            }));
        }
    }

    let query_rope_count =
        query_boundary_counts.get("reference_to_rust_query_rope").copied().unwrap_or(0);
    let classification = if selected_count == 0 {
        "no_selected_score_positions"
    } else if missing_input_count > 0 {
        "selected_score_positions_missing_inputs"
    } else if product_delta_available_count == 0 {
        "selected_score_product_delta_unavailable"
    } else if unresolved_residual_count == compared_count && compared_count > 0 {
        "selected_score_product_delta_blocked_by_residual"
    } else if mixed_qk_dominant_count > 0 {
        "selected_score_drift_has_mixed_qk_contribution"
    } else if key_dominant_count > 0 && query_dominant_count > 0 {
        "selected_score_drift_split_query_key_contribution"
    } else if key_dominant_count > 0 {
        "selected_score_drift_key_dominant"
    } else if query_rope_count > 0 && query_dominant_count > 0 {
        "selected_score_drift_query_dominant_with_query_rope_boundary"
    } else if query_dominant_count > 0 {
        "selected_score_drift_query_dominant"
    } else if no_material_product_delta_count == product_delta_available_count {
        "selected_score_product_delta_clean"
    } else {
        "selected_score_mixed_qk_contribution_unpinned"
    };
    let next_diagnostic = match classification {
        "selected_score_drift_has_mixed_qk_contribution"
        | "selected_score_drift_split_query_key_contribution" => {
            "inspect both query and key selected-position source rows before changing runtime math"
        }
        "selected_score_drift_query_dominant_with_query_rope_boundary"
        | "selected_score_drift_query_dominant" => {
            "localize the reference-to-Rust query RoPE rows for the dominant selected score slots"
        }
        "selected_score_drift_key_dominant" => {
            "localize the selected key score-input rows before changing score math"
        }
        "selected_score_product_delta_blocked_by_residual" => {
            "pin residual score-position recompute before interpreting mixed Q/K product contribution"
        }
        "selected_score_positions_missing_inputs" | "selected_score_product_delta_unavailable" => {
            "capture or recompute selected Q/K score-position product deltas before changing runtime math"
        }
        "selected_score_product_delta_clean" => {
            "selected product deltas are clean; inspect score accumulation or downstream probability rows"
        }
        "no_selected_score_positions" => {
            "capture selected score-position drift before interpreting mixed Q/K contribution"
        }
        _ => "add narrower selected Q/K source probes before changing runtime math",
    };

    json!({
        "diagnostic_only": true,
        "claim_allowed": false,
        "policy": "selected score mixed-QK contribution is diagnostic-only evidence for whether chosen raw score slots follow query, key, or mixed Q/K product deltas; it does not change runtime math and does not promote reference parity, A770 semantic quality, attention score residency, selected attention, resident KV, full residency, performance, or completion",
        "classification": classification,
        "residual_warn_abs": SCORE_POSITION_RECOMPUTE_RESIDUAL_WARN_ABS,
        "selected_count": selected_count,
        "compared_count": compared_count,
        "missing_input_count": missing_input_count,
        "product_delta_available_count": product_delta_available_count,
        "unresolved_residual_count": unresolved_residual_count,
        "query_dominant_count": query_dominant_count,
        "key_dominant_count": key_dominant_count,
        "mixed_qk_dominant_count": mixed_qk_dominant_count,
        "no_material_product_delta_count": no_material_product_delta_count,
        "max_abs_product_delta": max_abs_product_delta,
        "classification_counts": classification_counts,
        "dominant_input_counts": dominant_input_counts,
        "query_boundary_counts": query_boundary_counts,
        "first_product_row": first_product_row,
        "first_unresolved_row": first_unresolved_row,
        "rows": output_rows,
        "next_diagnostic": next_diagnostic,
    })
}

fn query_boundary_row_for_head(query_boundary: &Value, head: u64) -> Option<&Value> {
    query_boundary
        .pointer("/rows")
        .and_then(Value::as_array)?
        .iter()
        .find(|row| row.pointer("/head").and_then(Value::as_u64) == Some(head))
}

fn query_boundary_row_has_compared_delta(row: &Value) -> bool {
    [
        "/reference_to_rust_rope_delta/status",
        "/rust_rope_to_f16_delta/status",
        "/rust_f16_to_score_input_delta/status",
        "/reference_to_score_input_delta/status",
    ]
    .iter()
    .any(|path| row.pointer(path).and_then(Value::as_str) == Some("compared"))
}

fn query_boundary_row_has_usable_context(row: &Value) -> bool {
    if row.is_null() {
        return false;
    }
    if query_boundary_row_has_compared_delta(row) {
        return true;
    }
    row.pointer("/first_material_boundary")
        .and_then(Value::as_str)
        .is_some_and(|boundary| boundary != "missing_input")
}

fn attention_selected_key_score_input_source(
    selected_contribution: &Value,
    key_cache_boundary: &Value,
    key_kcur_boundary: &Value,
) -> Value {
    let selected_rows = selected_contribution.pointer("/rows").and_then(Value::as_array);
    let mut rows = Vec::<Value>::new();
    let mut selected_count = 0usize;
    let mut key_relevant_count = 0usize;
    let mut exact_before_store_count = 0usize;
    let mut exact_cache_readback_count = 0usize;
    let mut exact_cache_f16_roundtrip_count = 0usize;
    let mut exact_score_input_count = 0usize;
    let mut exact_kcur_before_store_count = 0usize;
    let mut exact_kcur_score_input_count = 0usize;
    let mut selected_token_before_store_count = 0usize;
    let mut selected_token_cache_readback_count = 0usize;
    let mut selected_token_cache_f16_roundtrip_count = 0usize;
    let mut selected_token_score_input_count = 0usize;
    let mut selected_token_kcur_before_store_count = 0usize;
    let mut selected_token_kcur_score_input_count = 0usize;
    let mut selected_dim_before_store_count = 0usize;
    let mut selected_dim_cache_readback_count = 0usize;
    let mut selected_dim_cache_f16_roundtrip_count = 0usize;
    let mut selected_dim_score_input_count = 0usize;
    let mut selected_dim_kcur_before_store_count = 0usize;
    let mut selected_dim_kcur_score_input_count = 0usize;
    let mut selected_dim_token_before_store_count = 0usize;
    let mut selected_dim_token_cache_readback_count = 0usize;
    let mut selected_dim_token_cache_f16_roundtrip_count = 0usize;
    let mut selected_dim_token_score_input_count = 0usize;
    let mut selected_dim_token_kcur_before_store_count = 0usize;
    let mut selected_dim_token_kcur_score_input_count = 0usize;
    let mut missing_boundary_count = 0usize;
    let mut max_abs_delta_at_boundary = 0.0f64;
    let mut first_exact_boundary_row = Value::Null;
    let mut first_context_boundary_row = Value::Null;

    if let Some(selected_rows) = selected_rows {
        for row in selected_rows {
            let row_classification =
                row.pointer("/classification").and_then(Value::as_str).unwrap_or("unknown");
            if !matches!(row_classification, "key_dominant" | "mixed_qk_dominant") {
                continue;
            }
            selected_count += 1;
            key_relevant_count += 1;
            let head = row.pointer("/head").and_then(Value::as_u64);
            let kv_head = row.pointer("/kv_head").and_then(Value::as_u64);
            let key_slot = row.pointer("/key_slot").and_then(Value::as_u64);
            let contributor = selected_key_contributor(row);
            let contributor_dim = contributor.pointer("/dim").and_then(Value::as_u64);

            let legacy_before_store = selected_key_boundary_summary(
                key_cache_boundary.pointer("/before_cache_store"),
                kv_head,
                contributor_dim,
                key_slot,
            );
            let legacy_cache_readback = selected_key_boundary_summary(
                key_cache_boundary.pointer("/cache_readback"),
                kv_head,
                contributor_dim,
                key_slot,
            );
            let legacy_cache_f16_roundtrip = selected_key_boundary_summary(
                key_cache_boundary.pointer("/cache_f16_roundtrip"),
                kv_head,
                contributor_dim,
                key_slot,
            );
            let legacy_score_input = selected_key_boundary_summary(
                key_cache_boundary.pointer("/score_input"),
                head,
                contributor_dim,
                key_slot,
            );
            let kcur_before_store = selected_key_boundary_summary(
                key_kcur_boundary.pointer("/before_cache_store"),
                kv_head,
                contributor_dim,
                key_slot,
            );
            let kcur_score_input = selected_key_boundary_summary(
                key_kcur_boundary.pointer("/score_input"),
                head,
                contributor_dim,
                key_slot,
            );

            let exact_before_store = boundary_selected_slot_exact(&legacy_before_store);
            let exact_cache_readback = boundary_selected_slot_exact(&legacy_cache_readback);
            let exact_cache_f16_roundtrip =
                boundary_selected_slot_exact(&legacy_cache_f16_roundtrip);
            let exact_score_input = boundary_selected_slot_exact(&legacy_score_input);
            let exact_kcur_before_store = boundary_selected_slot_exact(&kcur_before_store);
            let exact_kcur_score_input = boundary_selected_slot_exact(&kcur_score_input);
            let token_before_store = boundary_selected_token_bucket(&legacy_before_store);
            let token_cache_readback = boundary_selected_token_bucket(&legacy_cache_readback);
            let token_cache_f16_roundtrip =
                boundary_selected_token_bucket(&legacy_cache_f16_roundtrip);
            let token_score_input = boundary_selected_token_bucket(&legacy_score_input);
            let token_kcur_before_store = boundary_selected_token_bucket(&kcur_before_store);
            let token_kcur_score_input = boundary_selected_token_bucket(&kcur_score_input);
            let dim_before_store = boundary_selected_dim_bucket(&legacy_before_store);
            let dim_cache_readback = boundary_selected_dim_bucket(&legacy_cache_readback);
            let dim_cache_f16_roundtrip = boundary_selected_dim_bucket(&legacy_cache_f16_roundtrip);
            let dim_score_input = boundary_selected_dim_bucket(&legacy_score_input);
            let dim_kcur_before_store = boundary_selected_dim_bucket(&kcur_before_store);
            let dim_kcur_score_input = boundary_selected_dim_bucket(&kcur_score_input);

            if exact_before_store {
                exact_before_store_count += 1;
            }
            if exact_cache_readback {
                exact_cache_readback_count += 1;
            }
            if exact_cache_f16_roundtrip {
                exact_cache_f16_roundtrip_count += 1;
            }
            if exact_score_input {
                exact_score_input_count += 1;
            }
            if exact_kcur_before_store {
                exact_kcur_before_store_count += 1;
            }
            if exact_kcur_score_input {
                exact_kcur_score_input_count += 1;
            }
            if token_before_store {
                selected_token_before_store_count += 1;
            }
            if token_cache_readback {
                selected_token_cache_readback_count += 1;
            }
            if token_cache_f16_roundtrip {
                selected_token_cache_f16_roundtrip_count += 1;
            }
            if token_score_input {
                selected_token_score_input_count += 1;
            }
            if token_kcur_before_store {
                selected_token_kcur_before_store_count += 1;
            }
            if token_kcur_score_input {
                selected_token_kcur_score_input_count += 1;
            }
            if dim_before_store {
                selected_dim_before_store_count += 1;
            }
            if dim_cache_readback {
                selected_dim_cache_readback_count += 1;
            }
            if dim_cache_f16_roundtrip {
                selected_dim_cache_f16_roundtrip_count += 1;
            }
            if dim_score_input {
                selected_dim_score_input_count += 1;
            }
            if dim_kcur_before_store {
                selected_dim_kcur_before_store_count += 1;
            }
            if dim_kcur_score_input {
                selected_dim_kcur_score_input_count += 1;
            }
            if token_before_store && dim_before_store {
                selected_dim_token_before_store_count += 1;
            }
            if token_cache_readback && dim_cache_readback {
                selected_dim_token_cache_readback_count += 1;
            }
            if token_cache_f16_roundtrip && dim_cache_f16_roundtrip {
                selected_dim_token_cache_f16_roundtrip_count += 1;
            }
            if token_score_input && dim_score_input {
                selected_dim_token_score_input_count += 1;
            }
            if token_kcur_before_store && dim_kcur_before_store {
                selected_dim_token_kcur_before_store_count += 1;
            }
            if token_kcur_score_input && dim_kcur_score_input {
                selected_dim_token_kcur_score_input_count += 1;
            }

            let boundary_missing = [
                &legacy_before_store,
                &legacy_cache_readback,
                &legacy_cache_f16_roundtrip,
                &legacy_score_input,
                &kcur_before_store,
                &kcur_score_input,
            ]
            .iter()
            .all(|summary| summary.pointer("/status").and_then(Value::as_str) != Some("compared"));
            if boundary_missing {
                missing_boundary_count += 1;
            }
            for summary in [
                &legacy_before_store,
                &legacy_cache_readback,
                &legacy_cache_f16_roundtrip,
                &legacy_score_input,
                &kcur_before_store,
                &kcur_score_input,
            ] {
                max_abs_delta_at_boundary = max_abs_delta_at_boundary
                    .max(summary.pointer("/max_abs_delta").and_then(Value::as_f64).unwrap_or(0.0));
            }

            let boundary_classification = selected_key_boundary_classification(
                exact_before_store,
                exact_cache_readback,
                exact_cache_f16_roundtrip,
                exact_score_input,
                exact_kcur_before_store,
                exact_kcur_score_input,
                boundary_missing,
            );
            if first_exact_boundary_row.is_null()
                && !matches!(
                    boundary_classification,
                    "selected_key_boundary_unpinned" | "selected_key_boundary_missing"
                )
            {
                first_exact_boundary_row = json!({
                    "head": head,
                    "kv_head": kv_head,
                    "key_slot": key_slot,
                    "contributor_dim": contributor_dim,
                    "classification": boundary_classification,
                });
            }
            if first_context_boundary_row.is_null()
                && boundary_classification == "selected_key_boundary_unpinned"
                && [
                    &legacy_before_store,
                    &legacy_cache_readback,
                    &legacy_cache_f16_roundtrip,
                    &legacy_score_input,
                    &kcur_before_store,
                    &kcur_score_input,
                ]
                .iter()
                .any(|summary| {
                    boundary_selected_token_bucket(summary) || boundary_selected_dim_bucket(summary)
                })
            {
                first_context_boundary_row = json!({
                    "head": head,
                    "kv_head": kv_head,
                    "key_slot": key_slot,
                    "contributor_dim": contributor_dim,
                    "classification": "selected_key_boundary_context_unpinned",
                });
            }

            rows.push(json!({
                "status": if boundary_missing { "missing_boundary" } else { "compared" },
                "classification": boundary_classification,
                "selected_score_classification": row_classification,
                "head": head,
                "kv_head": kv_head,
                "key_slot": key_slot,
                "query_token": row.pointer("/query_token").cloned().unwrap_or(Value::Null),
                "contributor_dim": contributor_dim,
                "contributor": contributor,
                "legacy_cache_reference_source": "k_kv_head_token_major_reinterpreted",
                "kcur_reference_source": "kcur_history_kv_head_dim_major",
                "legacy_before_cache_store": legacy_before_store,
                "legacy_cache_readback": legacy_cache_readback,
                "legacy_cache_f16_roundtrip": legacy_cache_f16_roundtrip,
                "legacy_score_input": legacy_score_input,
                "kcur_before_cache_store": kcur_before_store,
                "kcur_score_input": kcur_score_input,
            }));
        }
    }

    let classification = if selected_count == 0 {
        "no_selected_key_dominant_score_rows"
    } else if missing_boundary_count == selected_count {
        "selected_key_score_input_boundary_missing"
    } else if exact_before_store_count > 0 || exact_kcur_before_store_count > 0 {
        "selected_key_drift_enters_before_cache_store"
    } else if exact_cache_readback_count > 0 {
        "selected_key_drift_enters_cache_readback"
    } else if exact_cache_f16_roundtrip_count > 0 {
        "selected_key_drift_follows_cache_f16_roundtrip"
    } else if exact_score_input_count > 0 || exact_kcur_score_input_count > 0 {
        "selected_key_drift_visible_at_score_input"
    } else {
        "selected_key_score_input_source_unpinned"
    };
    let selected_dim_token_context_count = selected_dim_token_before_store_count
        + selected_dim_token_cache_readback_count
        + selected_dim_token_cache_f16_roundtrip_count
        + selected_dim_token_score_input_count
        + selected_dim_token_kcur_before_store_count
        + selected_dim_token_kcur_score_input_count;
    let selected_token_context_count = selected_token_before_store_count
        + selected_token_cache_readback_count
        + selected_token_cache_f16_roundtrip_count
        + selected_token_score_input_count
        + selected_token_kcur_before_store_count
        + selected_token_kcur_score_input_count;
    let selected_dim_context_count = selected_dim_before_store_count
        + selected_dim_cache_readback_count
        + selected_dim_cache_f16_roundtrip_count
        + selected_dim_score_input_count
        + selected_dim_kcur_before_store_count
        + selected_dim_kcur_score_input_count;
    let boundary_context_classification = if selected_count == 0 {
        "no_selected_key_dominant_score_rows"
    } else if missing_boundary_count == selected_count {
        "selected_key_score_input_boundary_missing"
    } else if selected_dim_token_context_count > 0 {
        "selected_key_selected_dim_token_bucket_context_unpinned"
    } else if selected_token_context_count > 0 {
        "selected_key_selected_token_bucket_context_unpinned"
    } else if selected_dim_context_count > 0 {
        "selected_key_selected_dim_bucket_context_unpinned"
    } else {
        "selected_key_score_input_source_unpinned"
    };
    let next_diagnostic = match classification {
        "selected_key_drift_enters_before_cache_store" => {
            "localize selected key projection/RoPE input rows before changing score math"
        }
        "selected_key_drift_enters_cache_readback"
        | "selected_key_drift_follows_cache_f16_roundtrip" => {
            "localize selected key cache storage/readback rounding before changing score math"
        }
        "selected_key_drift_visible_at_score_input" => {
            "localize selected key score-input expansion rows before changing score math"
        }
        "selected_key_score_input_boundary_missing" => {
            "capture missing selected key cache/store/readback boundary rows"
        }
        "no_selected_key_dominant_score_rows" => {
            "classify selected score Q/K contribution before localizing key source"
        }
        _ if selected_dim_token_context_count > 0 || selected_token_context_count > 0 => {
            "emit selected key dim/token slot probes before changing score math"
        }
        _ => "add narrower selected key source probes before changing runtime math",
    };

    json!({
        "diagnostic_only": true,
        "claim_allowed": false,
        "policy": "selected key score-input source is diagnostic-only evidence for where a selected key-dominant score slot appears across key cache/store/readback boundaries; it does not change runtime math and does not promote reference parity, A770 semantic quality, attention score residency, selected attention, resident KV, full residency, performance, or completion",
        "classification": classification,
        "selected_count": selected_count,
        "key_relevant_count": key_relevant_count,
        "missing_boundary_count": missing_boundary_count,
        "exact_before_store_count": exact_before_store_count,
        "exact_cache_readback_count": exact_cache_readback_count,
        "exact_cache_f16_roundtrip_count": exact_cache_f16_roundtrip_count,
        "exact_score_input_count": exact_score_input_count,
        "exact_kcur_before_store_count": exact_kcur_before_store_count,
        "exact_kcur_score_input_count": exact_kcur_score_input_count,
        "selected_token_before_store_count": selected_token_before_store_count,
        "selected_token_cache_readback_count": selected_token_cache_readback_count,
        "selected_token_cache_f16_roundtrip_count": selected_token_cache_f16_roundtrip_count,
        "selected_token_score_input_count": selected_token_score_input_count,
        "selected_token_kcur_before_store_count": selected_token_kcur_before_store_count,
        "selected_token_kcur_score_input_count": selected_token_kcur_score_input_count,
        "selected_dim_before_store_count": selected_dim_before_store_count,
        "selected_dim_cache_readback_count": selected_dim_cache_readback_count,
        "selected_dim_cache_f16_roundtrip_count": selected_dim_cache_f16_roundtrip_count,
        "selected_dim_score_input_count": selected_dim_score_input_count,
        "selected_dim_kcur_before_store_count": selected_dim_kcur_before_store_count,
        "selected_dim_kcur_score_input_count": selected_dim_kcur_score_input_count,
        "selected_dim_token_before_store_count": selected_dim_token_before_store_count,
        "selected_dim_token_cache_readback_count": selected_dim_token_cache_readback_count,
        "selected_dim_token_cache_f16_roundtrip_count": selected_dim_token_cache_f16_roundtrip_count,
        "selected_dim_token_score_input_count": selected_dim_token_score_input_count,
        "selected_dim_token_kcur_before_store_count": selected_dim_token_kcur_before_store_count,
        "selected_dim_token_kcur_score_input_count": selected_dim_token_kcur_score_input_count,
        "selected_token_context_count": selected_token_context_count,
        "selected_dim_context_count": selected_dim_context_count,
        "selected_dim_token_context_count": selected_dim_token_context_count,
        "boundary_context_classification": boundary_context_classification,
        "max_abs_delta_at_boundary": max_abs_delta_at_boundary,
        "first_exact_boundary_row": first_exact_boundary_row,
        "first_context_boundary_row": first_context_boundary_row,
        "rows": rows,
        "next_diagnostic": next_diagnostic,
    })
}

fn selected_key_contributor(row: &Value) -> Value {
    row.pointer("/best_candidate_product_delta/top_abs_product_delta_contributors")
        .and_then(Value::as_array)
        .and_then(|contributors| {
            contributors
                .iter()
                .find(|contributor| {
                    contributor
                        .pointer("/key_delta")
                        .and_then(Value::as_f64)
                        .is_some_and(|delta| delta != 0.0)
                })
                .or_else(|| contributors.first())
        })
        .cloned()
        .unwrap_or(Value::Null)
}

fn selected_key_boundary_summary(
    section: Option<&Value>,
    row_head: Option<u64>,
    selected_dim: Option<u64>,
    selected_token: Option<u64>,
) -> Value {
    let row = row_head.and_then(|head| boundary_section_row_for_head(section, head));
    let Some(row) = row else {
        return json!({
            "status": "missing_boundary_row",
            "row_head": row_head,
            "selected_dim": selected_dim,
            "selected_token": selected_token,
        });
    };
    let status = row.pointer("/status").and_then(Value::as_str).unwrap_or("unknown");
    let delta = row.pointer("/delta").unwrap_or(&Value::Null);
    let first_bucket = delta
        .pointer("/first_f16_bucket_mismatch_layout")
        .or_else(|| delta.pointer("/first_f16_bucket_mismatch"))
        .cloned()
        .unwrap_or(Value::Null);
    let exact_selected_bucket = selected_dim.is_some()
        && selected_token.is_some()
        && first_bucket.pointer("/dim").and_then(Value::as_u64) == selected_dim
        && first_bucket.pointer("/token").and_then(Value::as_u64) == selected_token;
    let selected_token_bucket = selected_token.is_some_and(|selected_token| {
        delta.pointer("/token_mismatch_counts").and_then(Value::as_array).is_some_and(|tokens| {
            tokens.iter().any(|token| {
                token.pointer("/token").and_then(Value::as_u64) == Some(selected_token)
            })
        })
    });
    let selected_token_mismatch_row = selected_token
        .and_then(|selected_token| {
            delta
                .pointer("/token_mismatch_counts")
                .and_then(Value::as_array)?
                .iter()
                .find(|token| {
                    token.pointer("/token").and_then(Value::as_u64) == Some(selected_token)
                })
                .cloned()
        })
        .unwrap_or(Value::Null);
    let selected_token_f16_bucket_mismatch_count = selected_token_mismatch_row
        .pointer("/f16_bucket_mismatch_count")
        .and_then(Value::as_u64)
        .unwrap_or(0);
    let selected_dim_bucket = selected_dim.is_some_and(|selected_dim| {
        delta.pointer("/dim_mismatch_counts").and_then(Value::as_array).is_some_and(|dims| {
            dims.iter().any(|dim| dim.pointer("/dim").and_then(Value::as_u64) == Some(selected_dim))
        })
    });
    let selected_dim_mismatch_row = selected_dim
        .and_then(|selected_dim| {
            delta
                .pointer("/dim_mismatch_counts")
                .and_then(Value::as_array)?
                .iter()
                .find(|dim| dim.pointer("/dim").and_then(Value::as_u64) == Some(selected_dim))
                .cloned()
        })
        .unwrap_or(Value::Null);
    let selected_dim_f16_bucket_mismatch_count = selected_dim_mismatch_row
        .pointer("/f16_bucket_mismatch_count")
        .and_then(Value::as_u64)
        .unwrap_or(0);
    let selected_token_bucket_not_first = selected_token_bucket && !exact_selected_bucket;
    let selected_dim_bucket_not_first = selected_dim_bucket && !exact_selected_bucket;
    let selected_dim_and_token_bucket = selected_dim_bucket && selected_token_bucket;
    let bucket_mismatch_count =
        delta.pointer("/f16_bucket_mismatch_count").and_then(Value::as_u64).unwrap_or(0);
    let classification = if status != "compared" {
        "boundary_not_compared"
    } else if exact_selected_bucket {
        "selected_slot_is_first_f16_bucket_mismatch"
    } else if selected_token_bucket {
        "selected_token_has_f16_bucket_mismatch"
    } else if selected_dim_bucket {
        "selected_dim_has_f16_bucket_mismatch"
    } else if bucket_mismatch_count > 0 {
        "f16_bucket_mismatch_elsewhere"
    } else {
        "no_f16_bucket_mismatch"
    };

    json!({
        "status": status,
        "classification": classification,
        "row_head": row_head,
        "selected_dim": selected_dim,
        "selected_token": selected_token,
        "exact_selected_bucket": exact_selected_bucket,
        "selected_token_bucket": selected_token_bucket,
        "selected_dim_bucket": selected_dim_bucket,
        "selected_token_bucket_not_first": selected_token_bucket_not_first,
        "selected_dim_bucket_not_first": selected_dim_bucket_not_first,
        "selected_dim_and_token_bucket": selected_dim_and_token_bucket,
        "selected_token_f16_bucket_mismatch_count": selected_token_f16_bucket_mismatch_count,
        "selected_dim_f16_bucket_mismatch_count": selected_dim_f16_bucket_mismatch_count,
        "selected_token_mismatch_row": selected_token_mismatch_row,
        "selected_dim_mismatch_row": selected_dim_mismatch_row,
        "bucket_mismatch_count": bucket_mismatch_count,
        "first_f16_bucket_mismatch_layout": first_bucket,
        "max_abs_delta": delta.pointer("/max_abs_delta").cloned().unwrap_or(Value::Null),
        "rms_abs_delta": delta.pointer("/rms_abs_delta").cloned().unwrap_or(Value::Null),
    })
}

fn boundary_section_row_for_head(section: Option<&Value>, head: u64) -> Option<&Value> {
    section?.pointer("/rows").and_then(Value::as_array)?.iter().find(|row| {
        row.pointer("/head").or_else(|| row.pointer("/kv_head")).and_then(Value::as_u64)
            == Some(head)
    })
}

fn boundary_selected_slot_exact(summary: &Value) -> bool {
    summary.pointer("/exact_selected_bucket").and_then(Value::as_bool).unwrap_or(false)
}

fn boundary_selected_token_bucket(summary: &Value) -> bool {
    summary.pointer("/selected_token_bucket").and_then(Value::as_bool).unwrap_or(false)
}

fn boundary_selected_dim_bucket(summary: &Value) -> bool {
    summary.pointer("/selected_dim_bucket").and_then(Value::as_bool).unwrap_or(false)
}

fn selected_key_boundary_classification(
    exact_before_store: bool,
    exact_cache_readback: bool,
    exact_cache_f16_roundtrip: bool,
    exact_score_input: bool,
    exact_kcur_before_store: bool,
    exact_kcur_score_input: bool,
    boundary_missing: bool,
) -> &'static str {
    if boundary_missing {
        "selected_key_boundary_missing"
    } else if exact_before_store || exact_kcur_before_store {
        "selected_key_drift_enters_before_cache_store"
    } else if exact_cache_readback {
        "selected_key_drift_enters_cache_readback"
    } else if exact_cache_f16_roundtrip {
        "selected_key_drift_follows_cache_f16_roundtrip"
    } else if exact_score_input || exact_kcur_score_input {
        "selected_key_drift_visible_at_score_input"
    } else {
        "selected_key_boundary_unpinned"
    }
}

fn attention_selected_key_projection_rope_source(
    selected_key_source: &Value,
    rope_input_attribution: &Value,
    current_projection_rope_boundary: &Value,
) -> Value {
    let selected_rows = selected_key_source.pointer("/rows").and_then(Value::as_array);
    let current_probe_token =
        rope_input_attribution.pointer("/selected_token").and_then(Value::as_u64).or_else(|| {
            current_projection_rope_boundary.pointer("/selected_token").and_then(Value::as_u64)
        });
    let mut rows = Vec::<Value>::new();
    let mut selected_count = 0usize;
    let mut current_token_matched_count = 0usize;
    let mut historical_slot_uncovered_count = 0usize;
    let mut missing_attribution_count = 0usize;
    let mut before_rope_input_count = 0usize;
    let mut rust_rope_delta_count = 0usize;
    let mut reference_rope_delta_count = 0usize;
    let mut clean_current_rope_count = 0usize;

    if let Some(selected_rows) = selected_rows {
        for row in selected_rows {
            if row.pointer("/status").and_then(Value::as_str) != Some("compared") {
                continue;
            }
            selected_count += 1;
            let kv_head = row.pointer("/kv_head").and_then(Value::as_u64);
            let key_slot = row.pointer("/key_slot").and_then(Value::as_u64);
            let contributor_dim = row.pointer("/contributor_dim").and_then(Value::as_u64);
            let current_token_matches = key_slot.is_some()
                && current_probe_token.is_some()
                && key_slot == current_probe_token;
            let mut blocked_reasons = Vec::<String>::new();
            let mut attribution_row = Value::Null;
            let mut current_boundary_row = Value::Null;
            let mut selected_dim_summary = Value::Null;
            let row_classification: &'static str;

            if !current_token_matches {
                historical_slot_uncovered_count += 1;
                blocked_reasons.push("selected_key_slot_not_current_rope_probe".to_string());
                if key_slot.is_none() {
                    blocked_reasons.push("selected_key_slot_missing".to_string());
                }
                if current_probe_token.is_none() {
                    blocked_reasons.push("current_rope_probe_token_missing".to_string());
                }
                row_classification = "selected_key_projection_rope_source_missing_historical_slot";
            } else if let Some(kv_head) = kv_head {
                current_token_matched_count += 1;
                attribution_row = rope_attribution_row_for_kv_head(rope_input_attribution, kv_head)
                    .cloned()
                    .unwrap_or(Value::Null);
                current_boundary_row = current_key_projection_rope_row_for_kv_head(
                    current_projection_rope_boundary,
                    kv_head,
                )
                .cloned()
                .unwrap_or(Value::Null);
                if attribution_row.is_null() {
                    missing_attribution_count += 1;
                    blocked_reasons.push("selected_key_rope_attribution_row_missing".to_string());
                    row_classification = "selected_key_projection_rope_source_missing_attribution";
                } else {
                    let attribution = attribution_row
                        .pointer("/attribution")
                        .and_then(Value::as_str)
                        .unwrap_or("unknown");
                    selected_dim_summary =
                        selected_current_rope_dim_summary(&attribution_row, contributor_dim);
                    row_classification = match attribution {
                        "input_bucket_drift_before_rope" => {
                            before_rope_input_count += 1;
                            "selected_key_drift_before_rope_input"
                        }
                        "rust_runtime_rope_implementation_delta" => {
                            rust_rope_delta_count += 1;
                            "selected_key_drift_from_rust_rope"
                        }
                        "reference_rope_arithmetic_differs_from_runtime_variant" => {
                            reference_rope_delta_count += 1;
                            "selected_key_reference_rope_arithmetic_delta"
                        }
                        "no_post_rope_bucket_drift" => {
                            clean_current_rope_count += 1;
                            "selected_key_current_rope_source_clean"
                        }
                        _ => "selected_key_projection_rope_source_unpinned",
                    };
                }
            } else {
                missing_attribution_count += 1;
                blocked_reasons.push("selected_key_kv_head_missing".to_string());
                row_classification = "selected_key_projection_rope_source_missing_attribution";
            }

            rows.push(json!({
                "status": if blocked_reasons.is_empty() { "compared" } else { "blocked" },
                "classification": row_classification,
                "head": row.pointer("/head").cloned().unwrap_or(Value::Null),
                "kv_head": kv_head,
                "key_slot": key_slot,
                "query_token": row.pointer("/query_token").cloned().unwrap_or(Value::Null),
                "contributor_dim": contributor_dim,
                "current_probe_token": current_probe_token,
                "current_token_matches": current_token_matches,
                "blocked_reasons": blocked_reasons,
                "selected_key_source_classification": row.pointer("/classification").cloned().unwrap_or(Value::Null),
                "rope_input_attribution": attribution_row,
                "current_projection_rope_boundary": current_boundary_row,
                "selected_dim_summary": selected_dim_summary,
            }));
        }
    }

    let classification = if selected_count == 0 {
        "no_selected_key_source_rows"
    } else if historical_slot_uncovered_count == selected_count {
        "selected_key_projection_rope_source_missing_historical_slot"
    } else if before_rope_input_count > 0 {
        "selected_key_drift_before_rope_input"
    } else if rust_rope_delta_count > 0 {
        "selected_key_drift_from_rust_rope"
    } else if reference_rope_delta_count > 0 {
        "selected_key_reference_rope_arithmetic_delta"
    } else if missing_attribution_count > 0 {
        "selected_key_projection_rope_source_missing_attribution"
    } else if clean_current_rope_count == selected_count {
        "selected_key_current_rope_source_clean"
    } else {
        "selected_key_projection_rope_source_unpinned"
    };
    let next_diagnostic = match classification {
        "selected_key_projection_rope_source_missing_historical_slot" => {
            "capture historical pre-RoPE K projection/RoPE rows for the selected key slot"
        }
        "selected_key_drift_before_rope_input" => {
            "localize selected key projection output before changing score math"
        }
        "selected_key_drift_from_rust_rope" => {
            "pin selected key RoPE numeric policy before changing runtime math"
        }
        "selected_key_reference_rope_arithmetic_delta" => {
            "pin reference selected key RoPE arithmetic before changing runtime math"
        }
        "selected_key_projection_rope_source_missing_attribution" => {
            "capture missing selected key RoPE attribution rows"
        }
        "selected_key_current_rope_source_clean" => {
            "inspect selected key cache/score expansion despite clean current RoPE source"
        }
        "no_selected_key_source_rows" => {
            "localize selected key score-input source before projection/RoPE attribution"
        }
        _ => "add narrower selected key projection/RoPE probes before changing runtime math",
    };

    json!({
        "diagnostic_only": true,
        "claim_allowed": false,
        "policy": "selected key projection/RoPE source is diagnostic-only evidence for whether a selected key-dominant score slot can be attributed to current-token K projection/RoPE inputs; historical selected key slots must report missing source coverage rather than reusing current-token evidence, and this does not change runtime math or promote reference parity, A770 semantic quality, attention score residency, selected attention, resident KV, full residency, performance, or completion",
        "classification": classification,
        "selected_count": selected_count,
        "current_probe_token": current_probe_token,
        "current_token_matched_count": current_token_matched_count,
        "historical_slot_uncovered_count": historical_slot_uncovered_count,
        "missing_attribution_count": missing_attribution_count,
        "before_rope_input_count": before_rope_input_count,
        "rust_rope_delta_count": rust_rope_delta_count,
        "reference_rope_delta_count": reference_rope_delta_count,
        "clean_current_rope_count": clean_current_rope_count,
        "rows": rows,
        "next_diagnostic": next_diagnostic,
    })
}

fn rope_attribution_row_for_kv_head(section: &Value, kv_head: u64) -> Option<&Value> {
    section.pointer("/rows").and_then(Value::as_array)?.iter().find(|row| {
        row.pointer("/kv_head").or_else(|| row.pointer("/head")).and_then(Value::as_u64)
            == Some(kv_head)
    })
}

fn current_key_projection_rope_row_for_kv_head(section: &Value, kv_head: u64) -> Option<&Value> {
    section.pointer("/rows").and_then(Value::as_array)?.iter().find(|row| {
        row.pointer("/kv_head").or_else(|| row.pointer("/head")).and_then(Value::as_u64)
            == Some(kv_head)
    })
}

fn selected_current_rope_dim_summary(attribution_row: &Value, selected_dim: Option<u64>) -> Value {
    let selected_dim = selected_dim.unwrap_or(u64::MAX);
    let sections = [
        ("input", "/input_f16_bucket_delta"),
        ("actual_post_rope", "/actual_post_rope_f16_bucket_delta"),
        ("runtime_replay_input_shift", "/runtime_replay_input_shift_f16_bucket_delta"),
        ("rust_runtime_replay_to_actual", "/rust_runtime_replay_to_actual_f16_bucket_delta"),
        (
            "reference_runtime_replay_to_reference",
            "/reference_runtime_replay_to_reference_f16_bucket_delta",
        ),
    ];
    let mut rows = Vec::<Value>::new();
    let mut selected_dim_bucket_count = 0usize;

    for (stage, pointer) in sections {
        let delta = attribution_row.pointer(pointer).unwrap_or(&Value::Null);
        let first_bucket =
            delta.pointer("/first_f16_bucket_mismatch").cloned().unwrap_or(Value::Null);
        let exact_selected_dim =
            first_bucket.pointer("/index").and_then(Value::as_u64) == Some(selected_dim);
        if exact_selected_dim {
            selected_dim_bucket_count += 1;
        }
        rows.push(json!({
            "stage": stage,
            "status": if delta.is_null() { "missing_delta" } else { "compared" },
            "f16_bucket_mismatch_count": delta.pointer("/f16_bucket_mismatch_count").cloned().unwrap_or(Value::Null),
            "first_f16_bucket_mismatch": first_bucket,
            "exact_selected_dim": exact_selected_dim,
        }));
    }

    json!({
        "selected_dim": if selected_dim == u64::MAX { Value::Null } else { json!(selected_dim) },
        "selected_dim_bucket_count": selected_dim_bucket_count,
        "rows": rows,
    })
}

fn attention_selected_key_historical_projection_rope_source(
    selected_key_source: &Value,
    reference_records: &[ReferenceTraceRecord],
    rust_records: &BTreeMap<String, RustTraceRecord>,
) -> Value {
    let selected_rows = selected_key_source.pointer("/rows").and_then(Value::as_array);
    let reference_projection_heads = reference_records
        .iter()
        .filter_map(|record| {
            parse_stage_head(&record.stage, "k_projection_history_kv_head")
                .map(|head| (head, record))
        })
        .filter(|(_, record)| record.values_available && !record.first_values.is_empty())
        .collect::<BTreeMap<_, _>>();
    let reference_post_rope_heads = reference_records
        .iter()
        .filter_map(|record| {
            parse_stage_head(&record.stage, "kcur_history_kv_head").map(|head| (head, record))
        })
        .filter(|(_, record)| record.values_available && !record.first_values.is_empty())
        .collect::<BTreeMap<_, _>>();
    let rust_projection_heads = rust_records
        .iter()
        .filter_map(|(stage, record)| {
            parse_stage_head(stage, "attention_k_projection_kv_head").map(|head| (head, record))
        })
        .filter(|(_, record)| !record.first_values.is_empty())
        .collect::<BTreeMap<_, _>>();
    let rust_post_rope_heads = rust_records
        .iter()
        .filter_map(|(stage, record)| {
            parse_stage_head(stage, "attention_k_before_cache_store_kv_head")
                .map(|head| (head, record))
        })
        .filter(|(_, record)| !record.first_values.is_empty())
        .collect::<BTreeMap<_, _>>();
    let runtime_variant = runtime_rope_variant();

    let mut rows = Vec::<Value>::new();
    let mut selected_count = 0usize;
    let mut compared_count = 0usize;
    let mut missing_reference_projection_count = 0usize;
    let mut missing_input_count = 0usize;
    let mut before_rope_input_count = 0usize;
    let mut rust_rope_delta_count = 0usize;
    let mut reference_rope_delta_count = 0usize;
    let mut post_rope_epsilon_probe_count = 0usize;
    let mut post_rope_bucket_sensitivity_count = 0usize;
    let mut historical_source_clean_count = 0usize;
    let mut unpinned_count = 0usize;

    if let Some(selected_rows) = selected_rows {
        for selected in selected_rows {
            if selected.pointer("/status").and_then(Value::as_str) != Some("compared") {
                continue;
            }
            selected_count += 1;
            let kv_head = selected
                .pointer("/kv_head")
                .and_then(Value::as_u64)
                .and_then(|value| usize::try_from(value).ok());
            let key_slot = selected
                .pointer("/key_slot")
                .and_then(Value::as_u64)
                .and_then(|value| usize::try_from(value).ok());
            let contributor_dim = selected
                .pointer("/contributor_dim")
                .and_then(Value::as_u64)
                .and_then(|value| usize::try_from(value).ok());
            let reference_projection =
                kv_head.and_then(|head| reference_projection_heads.get(&head).copied());
            let reference_post_rope =
                kv_head.and_then(|head| reference_post_rope_heads.get(&head).copied());
            let rust_projection =
                kv_head.and_then(|head| rust_projection_heads.get(&head).copied());
            let rust_post_rope = kv_head.and_then(|head| rust_post_rope_heads.get(&head).copied());
            let mut blocked_reasons = Vec::<String>::new();

            if kv_head.is_none() {
                blocked_reasons.push("selected_key_kv_head_missing".to_string());
            }
            if key_slot.is_none() {
                blocked_reasons.push("selected_key_slot_missing".to_string());
            }
            if runtime_variant.is_none() {
                blocked_reasons.push("runtime_rope_variant_missing".to_string());
            }
            if reference_projection.is_none() {
                blocked_reasons.push("reference_historical_k_projection_missing".to_string());
            }
            if reference_post_rope.is_none() {
                blocked_reasons.push("reference_kcur_history_head_missing".to_string());
            }
            if rust_projection.is_none() {
                blocked_reasons
                    .push("rust_attention_k_projection_history_head_missing".to_string());
            }
            if rust_post_rope.is_none() {
                blocked_reasons
                    .push("rust_attention_k_before_cache_store_head_missing".to_string());
            }

            let reference_projection_token = reference_projection
                .zip(key_slot)
                .and_then(|(record, token)| reference_dim_major_token(record, token).ok());
            let reference_post_rope_token = reference_post_rope
                .zip(key_slot)
                .and_then(|(record, token)| reference_dim_major_token(record, token).ok());
            let rust_projection_token = rust_projection
                .zip(key_slot)
                .and_then(|(record, token)| rust_dim_major_token(record, token).ok());
            let rust_post_rope_token = rust_post_rope
                .zip(key_slot)
                .and_then(|(record, token)| rust_dim_major_token(record, token).ok());

            if reference_projection.is_some() && reference_projection_token.is_none() {
                blocked_reasons.push("reference_historical_k_projection_token_missing".to_string());
            }
            if reference_post_rope.is_some() && reference_post_rope_token.is_none() {
                blocked_reasons.push("reference_kcur_history_token_missing".to_string());
            }
            if rust_projection.is_some() && rust_projection_token.is_none() {
                blocked_reasons
                    .push("rust_attention_k_projection_history_token_missing".to_string());
            }
            if rust_post_rope.is_some() && rust_post_rope_token.is_none() {
                blocked_reasons
                    .push("rust_attention_k_before_cache_store_token_missing".to_string());
            }

            let mut reference_projection_vs_rust_projection_f16 = Value::Null;
            let mut reference_replay_to_post_f16 = Value::Null;
            let mut rust_replay_to_post_f16 = Value::Null;
            let mut reference_post_vs_rust_post_f16 = Value::Null;
            let mut post_rope_f16_bucket_sensitivity = Value::Null;
            let mut post_rope_epsilon_probe = Value::Null;
            let mut selected_dim_values = Value::Null;
            let mut classification = "selected_key_historical_projection_rope_source_missing_input";
            let mut status = "blocked";

            if let (
                Some(key_slot),
                Some(runtime_variant),
                Some(rust_projection_token),
                Some(rust_post_rope_token),
            ) = (
                key_slot,
                runtime_variant,
                rust_projection_token.as_ref(),
                rust_post_rope_token.as_ref(),
            ) {
                let head_dim = rust_projection_token.len();
                let rust_replay = apply_rope_split_head(
                    rust_projection_token,
                    key_slot,
                    head_dim,
                    runtime_variant.base,
                    runtime_variant.arithmetic,
                );
                if let Some(rust_replay) = rust_replay {
                    rust_replay_to_post_f16 = f16_bucket_delta(&rust_replay, rust_post_rope_token);
                    if let Some(reference_projection_token) = reference_projection_token.as_ref() {
                        reference_projection_vs_rust_projection_f16 =
                            f16_bucket_delta(reference_projection_token, rust_projection_token);
                        let reference_replay = apply_rope_split_head(
                            reference_projection_token,
                            key_slot,
                            reference_projection_token.len(),
                            runtime_variant.base,
                            runtime_variant.arithmetic,
                        );
                        if let (Some(reference_replay), Some(reference_post_rope_token)) =
                            (reference_replay, reference_post_rope_token.as_ref())
                        {
                            reference_replay_to_post_f16 =
                                f16_bucket_delta(&reference_replay, reference_post_rope_token);
                        }
                    }
                    if let Some(reference_post_rope_token) = reference_post_rope_token.as_ref() {
                        reference_post_vs_rust_post_f16 =
                            f16_bucket_delta(reference_post_rope_token, rust_post_rope_token);
                    }

                    let projection_bucket_count =
                        f16_bucket_mismatch_count(&reference_projection_vs_rust_projection_f16);
                    let rust_replay_bucket_count =
                        f16_bucket_mismatch_count(&rust_replay_to_post_f16);
                    let reference_replay_bucket_count =
                        f16_bucket_mismatch_count(&reference_replay_to_post_f16);
                    let post_rope_bucket_count =
                        f16_bucket_mismatch_count(&reference_post_vs_rust_post_f16);
                    if post_rope_bucket_count > 0 {
                        let first_bucket = reference_post_vs_rust_post_f16
                            .pointer("/first_f16_bucket_mismatch")
                            .cloned()
                            .unwrap_or(Value::Null);
                        let first_bucket_dim =
                            first_bucket.pointer("/index").and_then(Value::as_u64);
                        let selected_contributor_dim =
                            contributor_dim.and_then(|dim| u64::try_from(dim).ok());
                        post_rope_f16_bucket_sensitivity = json!({
                            "projection_f16_bucket_match": projection_bucket_count == 0,
                            "rust_replay_to_post_f16_bucket_match": rust_replay_bucket_count == 0,
                            "reference_replay_to_post_f16_bucket_match": reference_replay_bucket_count == 0,
                            "post_rope_f16_bucket_mismatch_count": post_rope_bucket_count,
                            "first_post_rope_f16_bucket_mismatch": first_bucket,
                            "first_post_rope_f16_bucket_mismatch_dim": first_bucket_dim,
                            "selected_contributor_dim": selected_contributor_dim,
                            "selected_contributor_dim_matches_first_bucket": first_bucket_dim == selected_contributor_dim,
                        });
                        let probe_dim = first_bucket_dim
                            .and_then(|dim| usize::try_from(dim).ok())
                            .or(contributor_dim);
                        if let (
                            Some(probe_dim),
                            Some(reference_projection_token),
                            Some(reference_post_rope_token),
                        ) = (
                            probe_dim,
                            reference_projection_token.as_ref(),
                            reference_post_rope_token.as_ref(),
                        ) {
                            post_rope_epsilon_probe = selected_historical_rope_epsilon_probe(
                                probe_dim,
                                key_slot,
                                runtime_variant,
                                reference_projection_token,
                                rust_projection_token,
                                reference_post_rope_token,
                                rust_post_rope_token,
                            );
                            if !post_rope_epsilon_probe.is_null() {
                                post_rope_epsilon_probe_count += 1;
                            }
                        }
                    }

                    classification =
                        if reference_projection_token.is_none() && post_rope_bucket_count > 0 {
                            missing_reference_projection_count += 1;
                            "selected_key_historical_reference_projection_missing"
                        } else if projection_bucket_count > 0 {
                            before_rope_input_count += 1;
                            "selected_key_historical_drift_before_rope_input"
                        } else if rust_replay_bucket_count > 0 {
                            rust_rope_delta_count += 1;
                            "selected_key_historical_rust_rope_delta"
                        } else if reference_replay_bucket_count > 0 {
                            reference_rope_delta_count += 1;
                            "selected_key_historical_reference_rope_delta"
                        } else if post_rope_bucket_count == 0 {
                            historical_source_clean_count += 1;
                            "selected_key_historical_projection_rope_source_clean"
                        } else if projection_bucket_count == 0
                            && rust_replay_bucket_count == 0
                            && reference_replay_bucket_count == 0
                        {
                            post_rope_bucket_sensitivity_count += 1;
                            "selected_key_historical_post_rope_f16_bucket_sensitivity"
                        } else {
                            unpinned_count += 1;
                            "selected_key_historical_projection_rope_source_unpinned"
                        };
                    compared_count += 1;
                    status =
                        if reference_projection_token.is_some() { "compared" } else { "blocked" };
                    selected_dim_values = selected_key_historical_dim_values(
                        contributor_dim,
                        reference_projection_token.as_deref(),
                        rust_projection_token,
                        reference_post_rope_token.as_deref(),
                        rust_post_rope_token,
                        Some(&rust_replay),
                    );
                } else {
                    blocked_reasons.push("rust_historical_rope_replay_failed".to_string());
                }
            }

            if status == "blocked" {
                missing_input_count += 1;
            }

            rows.push(json!({
                "status": status,
                "classification": classification,
                "head": selected.pointer("/head").cloned().unwrap_or(Value::Null),
                "kv_head": kv_head,
                "key_slot": key_slot,
                "query_token": selected.pointer("/query_token").cloned().unwrap_or(Value::Null),
                "contributor_dim": contributor_dim,
                "blocked_reasons": blocked_reasons,
                "reference_projection_present": reference_projection.is_some(),
                "reference_post_rope_present": reference_post_rope.is_some(),
                "rust_projection_present": rust_projection.is_some(),
                "rust_post_rope_present": rust_post_rope.is_some(),
                "reference_projection_vs_rust_projection_f16": reference_projection_vs_rust_projection_f16,
                "rust_runtime_replay_to_post_rope_f16": rust_replay_to_post_f16,
                "reference_runtime_replay_to_post_rope_f16": reference_replay_to_post_f16,
                "reference_post_rope_vs_rust_post_rope_f16": reference_post_vs_rust_post_f16,
                "post_rope_f16_bucket_sensitivity": post_rope_f16_bucket_sensitivity,
                "post_rope_epsilon_probe": post_rope_epsilon_probe,
                "selected_dim_values": selected_dim_values,
                "reference_projection_record": reference_stage_provenance_summary(reference_projection, None),
                "reference_post_rope_record": reference_stage_provenance_summary(reference_post_rope, None),
                "rust_projection_record": rust_trace_metadata_summary(rust_projection),
                "rust_post_rope_record": rust_trace_metadata_summary(rust_post_rope),
            }));
        }
    }

    let classification = if selected_count == 0 {
        "no_selected_key_source_rows"
    } else if missing_reference_projection_count > 0 {
        "selected_key_historical_reference_projection_missing"
    } else if before_rope_input_count > 0 {
        "selected_key_historical_drift_before_rope_input"
    } else if rust_rope_delta_count > 0 {
        "selected_key_historical_rust_rope_delta"
    } else if reference_rope_delta_count > 0 {
        "selected_key_historical_reference_rope_delta"
    } else if missing_input_count > 0 {
        "selected_key_historical_projection_rope_source_missing_input"
    } else if post_rope_epsilon_probe_count > 0 {
        "selected_key_historical_post_rope_epsilon_reported"
    } else if post_rope_bucket_sensitivity_count > 0 {
        "selected_key_historical_post_rope_f16_bucket_sensitivity"
    } else if historical_source_clean_count == selected_count {
        "selected_key_historical_projection_rope_source_clean"
    } else {
        "selected_key_historical_projection_rope_source_unpinned"
    };
    let next_diagnostic = match classification {
        "selected_key_historical_reference_projection_missing" => {
            "capture reference historical pre-RoPE K projection rows for the selected key slot"
        }
        "selected_key_historical_drift_before_rope_input" => {
            "localize selected historical K projection output before changing score math"
        }
        "selected_key_historical_rust_rope_delta" => {
            "pin selected historical K RoPE numeric policy before changing runtime math"
        }
        "selected_key_historical_reference_rope_delta" => {
            "pin reference historical K RoPE arithmetic before changing runtime math"
        }
        "selected_key_historical_post_rope_f16_bucket_sensitivity" => {
            "probe exact selected historical RoPE epsilon before changing runtime math"
        }
        "selected_key_historical_post_rope_epsilon_reported" => {
            "evaluate selected historical RoPE epsilon materiality against score-position contribution before changing runtime math"
        }
        "selected_key_historical_projection_rope_source_clean" => {
            "inspect selected score/key expansion despite clean historical projection/RoPE source"
        }
        "selected_key_historical_projection_rope_source_unpinned" => {
            "probe selected historical post-RoPE F16 bucket drift with both projection inputs present"
        }
        "no_selected_key_source_rows" => {
            "localize selected key score-input source before historical projection attribution"
        }
        _ => {
            "capture missing selected historical key projection/RoPE rows before changing runtime math"
        }
    };

    json!({
        "diagnostic_only": true,
        "claim_allowed": false,
        "policy": "selected historical key projection/RoPE source is diagnostic-only evidence for whether a selected key-dominant score slot can be attributed through historical pre-RoPE K projection and post-RoPE Kcur rows; missing reference historical pre-RoPE projection remains a blocker rather than a runtime conclusion, and this does not change runtime math or promote reference parity, A770 semantic quality, attention score residency, selected attention, resident KV, full residency, performance, or completion",
        "classification": classification,
        "selected_count": selected_count,
        "compared_count": compared_count,
        "missing_input_count": missing_input_count,
        "missing_reference_projection_count": missing_reference_projection_count,
        "before_rope_input_count": before_rope_input_count,
        "rust_rope_delta_count": rust_rope_delta_count,
        "reference_rope_delta_count": reference_rope_delta_count,
        "post_rope_epsilon_probe_count": post_rope_epsilon_probe_count,
        "post_rope_bucket_sensitivity_count": post_rope_bucket_sensitivity_count,
        "historical_source_clean_count": historical_source_clean_count,
        "unpinned_count": unpinned_count,
        "reference_projection_stage_prefix": "k_projection_history_kv_head",
        "reference_post_rope_stage_prefix": "kcur_history_kv_head",
        "rust_projection_stage_prefix": "attention_k_projection_kv_head",
        "rust_post_rope_stage_prefix": "attention_k_before_cache_store_kv_head",
        "reference_projection_head_count": reference_projection_heads.len(),
        "reference_post_rope_head_count": reference_post_rope_heads.len(),
        "rust_projection_head_count": rust_projection_heads.len(),
        "rust_post_rope_head_count": rust_post_rope_heads.len(),
        "runtime_variant_id": runtime_variant.map(|variant| variant.id),
        "rows": rows,
        "next_diagnostic": next_diagnostic,
    })
}

fn attention_selected_historical_rope_epsilon_materiality(
    selected_contribution: &Value,
    historical_rope_source: &Value,
) -> Value {
    let selected_rows = selected_contribution.pointer("/rows").and_then(Value::as_array);
    let historical_rows = historical_rope_source.pointer("/rows").and_then(Value::as_array);
    let mut rows = Vec::<Value>::new();
    let mut epsilon_row_count = 0usize;
    let mut compared_count = 0usize;
    let mut missing_product_context_count = 0usize;
    let mut key_delta_match_count = 0usize;
    let mut epsilon_not_product_material_count = 0usize;
    let mut product_uses_post_rope_f16_bucket_count = 0usize;
    let mut product_uses_score_input_capture_count = 0usize;
    let mut score_input_capture_uses_post_rope_f16_bucket_count = 0usize;
    let mut max_key_delta_abs_difference = 0.0f64;
    let mut max_product_abs_delta = 0.0f64;

    if let Some(historical_rows) = historical_rows {
        for historical_row in historical_rows {
            let epsilon_probe = historical_row.pointer("/post_rope_epsilon_probe");
            if !epsilon_probe.is_some_and(|probe| !probe.is_null()) {
                continue;
            }
            epsilon_row_count += 1;
            let head = historical_row.pointer("/head").and_then(Value::as_u64);
            let key_slot = historical_row.pointer("/key_slot").and_then(Value::as_u64);
            let query_token = historical_row.pointer("/query_token").and_then(Value::as_u64);
            let contributor_dim =
                historical_row.pointer("/contributor_dim").and_then(Value::as_u64);
            let product_row = selected_rows.and_then(|rows| {
                rows.iter().find(|row| {
                    row.pointer("/head").and_then(Value::as_u64) == head
                        && row.pointer("/key_slot").and_then(Value::as_u64) == key_slot
                        && row.pointer("/query_token").and_then(Value::as_u64) == query_token
                })
            });
            let product_contributor = product_row
                .and_then(|row| {
                    row.pointer("/best_candidate_product_delta/top_abs_product_delta_contributors")
                })
                .and_then(Value::as_array)
                .and_then(|contributors| {
                    contributors.iter().find(|contributor| {
                        contributor.pointer("/dim").and_then(Value::as_u64) == contributor_dim
                    })
                });

            let mut blocked_reasons = Vec::<String>::new();
            if product_row.is_none() {
                blocked_reasons.push("selected_score_product_row_missing".to_string());
            }
            if product_contributor.is_none() {
                blocked_reasons.push("selected_score_product_contributor_missing".to_string());
            }
            let mut materiality = Value::Null;
            let mut status = "missing_product_context";
            let mut classification = "selected_historical_rope_epsilon_product_context_missing";

            if let (Some(epsilon_probe), Some(product_contributor)) =
                (epsilon_probe, product_contributor)
            {
                let capture_delta =
                    epsilon_probe.pointer("/post_rope/capture_delta").and_then(Value::as_f64);
                let replay_delta = epsilon_probe
                    .pointer("/post_rope/runtime_replay_delta")
                    .and_then(Value::as_f64);
                let product_key_delta =
                    product_contributor.pointer("/key_delta").and_then(Value::as_f64);
                let product_reference_key =
                    product_contributor.pointer("/reference_key").and_then(Value::as_f64);
                let product_rust_key =
                    product_contributor.pointer("/rust_key").and_then(Value::as_f64);
                let post_rope_reference_f16 = epsilon_probe
                    .pointer("/post_rope_bucket/left_f16_value")
                    .and_then(Value::as_f64);
                let post_rope_rust_f16 = epsilon_probe
                    .pointer("/post_rope_bucket/right_f16_value")
                    .and_then(Value::as_f64);
                let reference_candidate = product_row
                    .and_then(|row| {
                        row.pointer("/best_candidate_product_delta/reference_candidate")
                    })
                    .and_then(Value::as_str);
                let rust_candidate = product_row
                    .and_then(|row| row.pointer("/best_candidate_product_delta/rust_candidate"))
                    .and_then(Value::as_str);
                let reference_key_source = product_row
                    .and_then(|row| {
                        row.pointer("/best_candidate_product_delta/reference_key_source")
                    })
                    .and_then(Value::as_str);
                let rust_key_source = product_row
                    .and_then(|row| row.pointer("/best_candidate_product_delta/rust_key_source"))
                    .and_then(Value::as_str);
                let reference_key_f16_roundtrip = product_row
                    .and_then(|row| {
                        row.pointer("/best_candidate_product_delta/reference_key_f16_roundtrip")
                    })
                    .and_then(Value::as_bool);
                let rust_key_f16_roundtrip = product_row
                    .and_then(|row| {
                        row.pointer("/best_candidate_product_delta/rust_key_f16_roundtrip")
                    })
                    .and_then(Value::as_bool);
                let signed_product_delta =
                    product_contributor.pointer("/signed_product_delta").and_then(Value::as_f64);
                let abs_product_delta = product_contributor
                    .pointer("/abs_product_delta")
                    .and_then(Value::as_f64)
                    .unwrap_or(0.0);
                let reference_query =
                    product_contributor.pointer("/reference_query").and_then(Value::as_f64);
                let rust_query = product_contributor.pointer("/rust_query").and_then(Value::as_f64);
                let query_delta =
                    product_contributor.pointer("/query_delta").and_then(Value::as_f64);

                if let (Some(capture_delta), Some(product_key_delta), Some(signed_product_delta)) =
                    (capture_delta, product_key_delta, signed_product_delta)
                {
                    let key_delta_from_epsilon = -capture_delta;
                    let key_delta_abs_difference =
                        (key_delta_from_epsilon - product_key_delta).abs();
                    let key_delta_matches_product = key_delta_abs_difference <= 1.0e-9;
                    let key_only_delta_reference_query =
                        reference_query.map(|query| query * key_delta_from_epsilon);
                    let key_only_delta_rust_query =
                        rust_query.map(|query| query * key_delta_from_epsilon);
                    let key_only_delta_reference_query_ratio = key_only_delta_reference_query
                        .and_then(|delta| {
                            if signed_product_delta == 0.0 {
                                None
                            } else {
                                Some(delta / signed_product_delta)
                            }
                        });
                    let key_only_delta_abs_ratio =
                        key_only_delta_reference_query_ratio.map(f64::abs).or_else(|| {
                            if abs_product_delta == 0.0 {
                                None
                            } else {
                                key_only_delta_reference_query
                                    .map(|delta| delta.abs() / abs_product_delta)
                            }
                        });
                    let epsilon_not_product_material = !key_delta_matches_product
                        && key_only_delta_abs_ratio.is_some_and(|ratio| ratio <= 0.01);
                    let reference_key_matches_post_rope_f16 = product_reference_key
                        .zip(post_rope_reference_f16)
                        .is_some_and(|(product, bucket)| (product - bucket).abs() <= 1.0e-9);
                    let rust_key_matches_post_rope_f16 = product_rust_key
                        .zip(post_rope_rust_f16)
                        .is_some_and(|(product, bucket)| (product - bucket).abs() <= 1.0e-9);
                    let product_uses_post_rope_f16_bucket_values =
                        reference_key_matches_post_rope_f16 && rust_key_matches_post_rope_f16;
                    let product_uses_score_input_capture = reference_key_source
                        .is_some_and(|source| source.contains("score_input"))
                        && rust_key_source.is_some_and(|source| source.contains("score_input"))
                        && reference_key_f16_roundtrip == Some(false)
                        && rust_key_f16_roundtrip == Some(false);
                    let score_input_capture_uses_post_rope_f16_bucket_values =
                        product_uses_score_input_capture
                            && product_uses_post_rope_f16_bucket_values;

                    compared_count += 1;
                    if key_delta_matches_product {
                        key_delta_match_count += 1;
                    }
                    if epsilon_not_product_material {
                        epsilon_not_product_material_count += 1;
                    }
                    if product_uses_post_rope_f16_bucket_values {
                        product_uses_post_rope_f16_bucket_count += 1;
                    }
                    if product_uses_score_input_capture {
                        product_uses_score_input_capture_count += 1;
                    }
                    if score_input_capture_uses_post_rope_f16_bucket_values {
                        score_input_capture_uses_post_rope_f16_bucket_count += 1;
                    }
                    max_key_delta_abs_difference =
                        max_key_delta_abs_difference.max(key_delta_abs_difference);
                    max_product_abs_delta = max_product_abs_delta.max(abs_product_delta);
                    status = "compared";
                    classification = if key_delta_matches_product {
                        "selected_historical_rope_epsilon_matches_key_product_delta"
                    } else if epsilon_not_product_material {
                        "selected_historical_rope_epsilon_not_product_material"
                    } else {
                        "selected_historical_rope_epsilon_product_delta_mismatch"
                    };
                    materiality = json!({
                        "capture_delta_sign_convention": "post_rope.capture_delta is rust_minus_reference; product key_delta is reference_minus_rust",
                        "key_delta_from_epsilon": key_delta_from_epsilon,
                        "product_key_delta": product_key_delta,
                        "key_delta_abs_difference": key_delta_abs_difference,
                        "key_delta_matches_product": key_delta_matches_product,
                        "replay_delta": replay_delta,
                        "reference_query": reference_query,
                        "rust_query": rust_query,
                        "query_delta": query_delta,
                        "signed_product_delta": signed_product_delta,
                        "abs_product_delta": abs_product_delta,
                        "key_only_delta_using_reference_query": key_only_delta_reference_query,
                        "key_only_delta_using_rust_query": key_only_delta_rust_query,
                        "key_only_reference_query_ratio_to_signed_product_delta": key_only_delta_reference_query_ratio,
                        "key_only_reference_query_abs_ratio_to_product_delta": key_only_delta_abs_ratio,
                        "epsilon_not_product_material": epsilon_not_product_material,
                        "product_bucket_source": {
                            "product_reference_key": product_reference_key,
                            "product_rust_key": product_rust_key,
                            "post_rope_reference_f16": post_rope_reference_f16,
                            "post_rope_rust_f16": post_rope_rust_f16,
                            "reference_key_matches_post_rope_f16": reference_key_matches_post_rope_f16,
                            "rust_key_matches_post_rope_f16": rust_key_matches_post_rope_f16,
                            "product_uses_post_rope_f16_bucket_values": product_uses_post_rope_f16_bucket_values,
                        },
                        "score_product_source_policy": {
                            "reference_candidate": reference_candidate,
                            "rust_candidate": rust_candidate,
                            "reference_key_source": reference_key_source,
                            "rust_key_source": rust_key_source,
                            "reference_key_f16_roundtrip": reference_key_f16_roundtrip,
                            "rust_key_f16_roundtrip": rust_key_f16_roundtrip,
                            "product_uses_score_input_capture": product_uses_score_input_capture,
                            "score_input_capture_uses_post_rope_f16_bucket_values": score_input_capture_uses_post_rope_f16_bucket_values,
                            "interpretation": if score_input_capture_uses_post_rope_f16_bucket_values {
                                "selected score product consumed captured score-input key values that already match post-RoPE F16 buckets"
                            } else if product_uses_score_input_capture {
                                "selected score product consumed captured score-input key values, but they do not match the post-RoPE F16 bucket probe"
                            } else {
                                "selected score product did not use captured score-input key values for both sides"
                            },
                        },
                    });
                } else {
                    blocked_reasons.push("selected_rope_or_product_delta_missing".to_string());
                    missing_product_context_count += 1;
                }
            } else {
                missing_product_context_count += 1;
            }

            rows.push(json!({
                "status": status,
                "classification": classification,
                "head": head,
                "kv_head": historical_row.pointer("/kv_head").cloned().unwrap_or(Value::Null),
                "key_slot": key_slot,
                "query_token": query_token,
                "contributor_dim": contributor_dim,
                "blocked_reasons": blocked_reasons,
                "product_row_present": product_row.is_some(),
                "product_contributor_present": product_contributor.is_some(),
                "epsilon_probe": epsilon_probe.cloned().unwrap_or(Value::Null),
                "product_contributor": product_contributor.cloned().unwrap_or(Value::Null),
                "materiality": materiality,
            }));
        }
    }

    let classification = if epsilon_row_count == 0 {
        "no_selected_historical_rope_epsilon_rows"
    } else if missing_product_context_count == epsilon_row_count {
        "selected_historical_rope_epsilon_product_context_missing"
    } else if key_delta_match_count == compared_count && compared_count > 0 {
        "selected_historical_rope_epsilon_materiality_pinned"
    } else if score_input_capture_uses_post_rope_f16_bucket_count == compared_count
        && compared_count > 0
    {
        "selected_score_product_uses_score_input_capture_post_rope_f16_buckets"
    } else if product_uses_post_rope_f16_bucket_count == compared_count && compared_count > 0 {
        "selected_historical_rope_product_uses_post_rope_f16_bucket_values"
    } else if epsilon_not_product_material_count == compared_count && compared_count > 0 {
        "selected_historical_rope_epsilon_not_product_material"
    } else {
        "selected_historical_rope_epsilon_materiality_unpinned"
    };
    let next_diagnostic = match classification {
        "selected_historical_rope_epsilon_materiality_pinned" => {
            "decide whether selected historical RoPE epsilon is acceptable capture precision or a runtime alignment target before changing runtime math"
        }
        "selected_historical_rope_epsilon_materiality_unpinned" => {
            "pin product-delta sign/source identity for the selected historical RoPE epsilon before changing runtime math"
        }
        "selected_historical_rope_epsilon_not_product_material" => {
            "inspect selected key F16 bucket value used by score product before changing RoPE runtime math"
        }
        "selected_score_product_uses_score_input_capture_post_rope_f16_buckets" => {
            "pin whether reference score input capture is the raw reference score operand before changing runtime math"
        }
        "selected_historical_rope_product_uses_post_rope_f16_bucket_values" => {
            "inspect whether selected score product should consume post-RoPE F16 bucket values before changing runtime math"
        }
        "selected_historical_rope_epsilon_product_context_missing" => {
            "capture selected score-position product contributors for the historical RoPE epsilon row"
        }
        "no_selected_historical_rope_epsilon_rows" => {
            "report selected historical RoPE epsilon before evaluating product materiality"
        }
        _ => "keep selected historical RoPE epsilon materiality diagnostic-only",
    };

    json!({
        "diagnostic_only": true,
        "claim_allowed": false,
        "policy": "selected historical RoPE epsilon materiality is diagnostic-only evidence tying one post-RoPE F16 bucket crossing back to the selected score-position product contributor; it does not change runtime math or promote reference parity, A770 semantic quality, attention score residency, selected attention, resident KV, full residency, performance, or completion",
        "classification": classification,
        "epsilon_row_count": epsilon_row_count,
        "compared_count": compared_count,
        "missing_product_context_count": missing_product_context_count,
        "key_delta_match_count": key_delta_match_count,
        "epsilon_not_product_material_count": epsilon_not_product_material_count,
        "product_uses_post_rope_f16_bucket_count": product_uses_post_rope_f16_bucket_count,
        "product_uses_score_input_capture_count": product_uses_score_input_capture_count,
        "score_input_capture_uses_post_rope_f16_bucket_count": score_input_capture_uses_post_rope_f16_bucket_count,
        "max_key_delta_abs_difference": max_key_delta_abs_difference,
        "max_product_abs_delta": max_product_abs_delta,
        "rows": rows,
        "next_diagnostic": next_diagnostic,
    })
}

fn attention_reference_score_input_operand_policy(
    qk_recompute: &Value,
    materiality: &Value,
) -> Value {
    let materiality_rows = materiality.pointer("/rows").and_then(Value::as_array);
    let qk_rows = qk_recompute.pointer("/rows").and_then(Value::as_array);
    let provenance_rows =
        qk_recompute.pointer("/reference_input_stage_provenance/rows").and_then(Value::as_array);

    let mut rows = Vec::<Value>::new();
    let mut candidate_row_count = 0usize;
    let mut matched_qk_row_count = 0usize;
    let mut reference_score_input_candidate_count = 0usize;
    let mut exact_graph_bound_count = 0usize;
    let mut exact_operand_count = 0usize;
    let mut tolerance_operand_count = 0usize;
    let mut residual_over_warn_count = 0usize;
    let mut score_input_capture_post_rope_bucket_count = 0usize;
    let mut max_reference_abs_delta = 0.0f64;

    if let Some(materiality_rows) = materiality_rows {
        for materiality_row in materiality_rows {
            let source_policy = materiality_row
                .pointer("/materiality/score_product_source_policy")
                .unwrap_or(&Value::Null);
            if source_policy
                .pointer("/score_input_capture_uses_post_rope_f16_bucket_values")
                .and_then(Value::as_bool)
                != Some(true)
            {
                continue;
            }
            candidate_row_count += 1;

            let head = materiality_row.pointer("/head").and_then(Value::as_u64);
            let key_slot = materiality_row.pointer("/key_slot").and_then(Value::as_u64);
            let query_token = materiality_row.pointer("/query_token").and_then(Value::as_u64);
            let qk_row = find_qk_recompute_row(qk_rows, head, key_slot, query_token);
            let provenance_row =
                find_qk_recompute_row(provenance_rows, head, key_slot, query_token);
            let mut blocked_reasons = Vec::<String>::new();

            if qk_row.is_none() {
                blocked_reasons.push("selected_qk_recompute_row_missing".to_string());
            }
            if provenance_row.is_none() {
                blocked_reasons.push("reference_score_input_provenance_row_missing".to_string());
            }

            let best_reference_candidate = qk_row
                .and_then(|row| row.pointer("/best_reference_candidate"))
                .unwrap_or(&Value::Null);
            let reference_abs_delta =
                best_reference_candidate.pointer("/reference_abs_delta").and_then(Value::as_f64);
            let reference_base_candidate =
                best_reference_candidate.pointer("/base_candidate").and_then(Value::as_str);
            let reference_query_source =
                best_reference_candidate.pointer("/query_source").and_then(Value::as_str);
            let reference_key_source =
                best_reference_candidate.pointer("/key_source").and_then(Value::as_str);
            let reference_query_f16_roundtrip =
                best_reference_candidate.pointer("/query_f16_roundtrip").and_then(Value::as_bool);
            let reference_key_f16_roundtrip =
                best_reference_candidate.pointer("/key_f16_roundtrip").and_then(Value::as_bool);
            let exact_graph_bound = provenance_row
                .and_then(|row| row.pointer("/exact_score_graph_source_bound"))
                .and_then(Value::as_bool)
                == Some(true);
            let residual_over_warn = provenance_row
                .and_then(|row| row.pointer("/reference_residual_over_warn"))
                .and_then(Value::as_bool)
                .unwrap_or_else(|| {
                    reference_abs_delta
                        .is_some_and(|delta| delta > SCORE_POSITION_RECOMPUTE_RESIDUAL_WARN_ABS)
                });
            let reference_score_input_candidate = reference_base_candidate
                == Some("reference_q_score_input_reference_k_score_input")
                && reference_query_source == Some("reference_q_score_input_head")
                && reference_key_source == Some("reference_k_score_input_head")
                && reference_query_f16_roundtrip == Some(true)
                && reference_key_f16_roundtrip == Some(false);
            let exact_operand = reference_abs_delta.is_some_and(|delta| delta <= 1.0e-12);
            let tolerance_operand = reference_abs_delta
                .is_some_and(|delta| delta <= SCORE_POSITION_RECOMPUTE_RESIDUAL_WARN_ABS);
            let score_input_capture_post_rope_bucket = source_policy
                .pointer("/score_input_capture_uses_post_rope_f16_bucket_values")
                .and_then(Value::as_bool)
                == Some(true);

            if qk_row.is_some() {
                matched_qk_row_count += 1;
            }
            if reference_score_input_candidate {
                reference_score_input_candidate_count += 1;
            }
            if exact_graph_bound {
                exact_graph_bound_count += 1;
            }
            if exact_operand {
                exact_operand_count += 1;
            }
            if tolerance_operand {
                tolerance_operand_count += 1;
            }
            if residual_over_warn {
                residual_over_warn_count += 1;
            }
            if score_input_capture_post_rope_bucket {
                score_input_capture_post_rope_bucket_count += 1;
            }
            if let Some(delta) = reference_abs_delta {
                max_reference_abs_delta = max_reference_abs_delta.max(delta);
            }
            if !reference_score_input_candidate {
                blocked_reasons
                    .push("reference_best_candidate_not_score_input_capture".to_string());
            }
            if !exact_graph_bound {
                blocked_reasons.push("reference_score_input_not_exact_graph_bound".to_string());
            }
            if reference_abs_delta.is_none() {
                blocked_reasons.push("reference_score_abs_delta_missing".to_string());
            }
            if residual_over_warn {
                blocked_reasons.push("reference_score_recompute_residual_over_warn".to_string());
            }

            let row_classification = if !blocked_reasons.is_empty() {
                "reference_score_input_operand_unpinned"
            } else if exact_operand {
                "reference_score_input_capture_exact_raw_operand"
            } else if tolerance_operand {
                "reference_score_input_capture_tolerance_pinned_operand"
            } else {
                "reference_score_input_operand_unpinned"
            };

            rows.push(json!({
                "classification": row_classification,
                "head": head,
                "kv_head": materiality_row.pointer("/kv_head").cloned().unwrap_or(Value::Null),
                "key_slot": key_slot,
                "query_token": query_token,
                "contributor_dim": materiality_row.pointer("/contributor_dim").cloned().unwrap_or(Value::Null),
                "blocked_reasons": blocked_reasons,
                "qk_recompute_row_present": qk_row.is_some(),
                "provenance_row_present": provenance_row.is_some(),
                "reference_score_input_candidate": reference_score_input_candidate,
                "exact_graph_bound": exact_graph_bound,
                "exact_operand": exact_operand,
                "tolerance_operand": tolerance_operand,
                "reference_abs_delta": reference_abs_delta,
                "reference_residual_warn_abs": SCORE_POSITION_RECOMPUTE_RESIDUAL_WARN_ABS,
                "reference_residual_over_warn": residual_over_warn,
                "score_input_capture_uses_post_rope_f16_bucket_values": score_input_capture_post_rope_bucket,
                "best_reference_candidate": best_reference_candidate.clone(),
                "reference_stage_provenance": provenance_row.cloned().unwrap_or(Value::Null),
                "score_product_source_policy": source_policy.clone(),
            }));
        }
    }

    let classification = if candidate_row_count == 0 {
        "no_selected_score_input_capture_rows"
    } else if matched_qk_row_count != candidate_row_count {
        "reference_score_input_operand_missing_qk_recompute"
    } else if reference_score_input_candidate_count != candidate_row_count
        || exact_graph_bound_count != candidate_row_count
    {
        "reference_score_input_operand_unpinned"
    } else if residual_over_warn_count > 0 {
        "reference_score_input_operand_residual_over_warn"
    } else if exact_operand_count == candidate_row_count {
        "reference_score_input_capture_exact_raw_operand"
    } else if tolerance_operand_count == candidate_row_count {
        "reference_score_input_capture_tolerance_pinned_operand"
    } else {
        "reference_score_input_operand_unpinned"
    };
    let next_diagnostic = match classification {
        "reference_score_input_capture_exact_raw_operand" => {
            "compare Rust score-input key/query captures against exact reference score operands before changing runtime math"
        }
        "reference_score_input_capture_tolerance_pinned_operand" => {
            "compare Rust score-input key/query captures against tolerance-pinned reference score operands before changing runtime math"
        }
        "reference_score_input_operand_residual_over_warn" => {
            "pin reference score accumulation or capture precision before interpreting Rust/reference operand drift"
        }
        "reference_score_input_operand_unpinned" => {
            "bind reference score input stages to raw score operands before changing runtime math"
        }
        "reference_score_input_operand_missing_qk_recompute" => {
            "capture selected Q/K recompute rows for score-input operand policy"
        }
        "no_selected_score_input_capture_rows" => {
            "capture selected score product source policy before evaluating reference score operands"
        }
        _ => "keep reference score input operand policy diagnostic-only",
    };

    json!({
        "diagnostic_only": true,
        "claim_allowed": false,
        "policy": "Reference score-input operand policy is diagnostic-only evidence for whether selected reference score products consume graph-bound score-input captures; tolerance-pinned rows are not bit-exact parity and do not promote runtime math changes, reference parity, A770 semantic quality, attention score residency, selected attention, resident KV, full residency, performance, or completion",
        "classification": classification,
        "reference_residual_warn_abs": SCORE_POSITION_RECOMPUTE_RESIDUAL_WARN_ABS,
        "candidate_row_count": candidate_row_count,
        "matched_qk_row_count": matched_qk_row_count,
        "reference_score_input_candidate_count": reference_score_input_candidate_count,
        "exact_graph_bound_count": exact_graph_bound_count,
        "exact_operand_count": exact_operand_count,
        "tolerance_operand_count": tolerance_operand_count,
        "residual_over_warn_count": residual_over_warn_count,
        "score_input_capture_post_rope_bucket_count": score_input_capture_post_rope_bucket_count,
        "max_reference_abs_delta": max_reference_abs_delta,
        "rows": rows,
        "next_diagnostic": next_diagnostic,
    })
}

fn attention_rust_score_input_operand_drift(operand_policy: &Value, materiality: &Value) -> Value {
    let operand_rows = operand_policy.pointer("/rows").and_then(Value::as_array);
    let materiality_rows = materiality.pointer("/rows").and_then(Value::as_array);
    let mut rows = Vec::<Value>::new();
    let mut compared_count = 0usize;
    let mut missing_materiality_count = 0usize;
    let mut clean_count = 0usize;
    let mut query_only_count = 0usize;
    let mut key_only_count = 0usize;
    let mut mixed_count = 0usize;
    let mut key_bucket_crossing_count = 0usize;
    let mut max_abs_query_delta = 0.0f64;
    let mut max_abs_key_delta = 0.0f64;
    let mut max_abs_product_delta = 0.0f64;

    if let Some(operand_rows) = operand_rows {
        for operand_row in operand_rows {
            let operand_classification =
                operand_row.pointer("/classification").and_then(Value::as_str);
            if !matches!(
                operand_classification,
                Some("reference_score_input_capture_exact_raw_operand")
                    | Some("reference_score_input_capture_tolerance_pinned_operand")
            ) {
                continue;
            }
            let head = operand_row.pointer("/head").and_then(Value::as_u64);
            let key_slot = operand_row.pointer("/key_slot").and_then(Value::as_u64);
            let query_token = operand_row.pointer("/query_token").and_then(Value::as_u64);
            let materiality_row =
                find_qk_recompute_row(materiality_rows, head, key_slot, query_token);
            if materiality_row.is_none() {
                missing_materiality_count += 1;
            }
            let product = materiality_row
                .and_then(|row| row.pointer("/product_contributor"))
                .unwrap_or(&Value::Null);
            let source_policy = materiality_row
                .and_then(|row| row.pointer("/materiality/score_product_source_policy"))
                .unwrap_or(&Value::Null);
            let query_delta = product.pointer("/query_delta").and_then(Value::as_f64);
            let key_delta = product.pointer("/key_delta").and_then(Value::as_f64);
            let abs_product_delta =
                product.pointer("/abs_product_delta").and_then(Value::as_f64).unwrap_or(0.0);
            let query_changed = query_delta.is_some_and(|delta| delta != 0.0);
            let key_changed = key_delta.is_some_and(|delta| delta != 0.0);
            let score_input_capture_post_rope_bucket = source_policy
                .pointer("/score_input_capture_uses_post_rope_f16_bucket_values")
                .and_then(Value::as_bool)
                == Some(true);
            let row_classification = match (query_changed, key_changed) {
                (false, false) => "selected_score_input_operand_drift_clean",
                (true, false) => "selected_score_input_operand_drift_query_only",
                (false, true) if score_input_capture_post_rope_bucket => {
                    "selected_score_input_operand_drift_key_bucket_crossing"
                }
                (false, true) => "selected_score_input_operand_drift_key_only",
                (true, true) => "selected_score_input_operand_drift_mixed_qk",
            };

            compared_count += 1;
            match row_classification {
                "selected_score_input_operand_drift_clean" => clean_count += 1,
                "selected_score_input_operand_drift_query_only" => query_only_count += 1,
                "selected_score_input_operand_drift_key_bucket_crossing" => {
                    key_only_count += 1;
                    key_bucket_crossing_count += 1;
                }
                "selected_score_input_operand_drift_key_only" => key_only_count += 1,
                "selected_score_input_operand_drift_mixed_qk" => mixed_count += 1,
                _ => {}
            }
            if let Some(delta) = query_delta {
                max_abs_query_delta = max_abs_query_delta.max(delta.abs());
            }
            if let Some(delta) = key_delta {
                max_abs_key_delta = max_abs_key_delta.max(delta.abs());
            }
            max_abs_product_delta = max_abs_product_delta.max(abs_product_delta);

            rows.push(json!({
                "classification": row_classification,
                "head": head,
                "kv_head": operand_row.pointer("/kv_head").cloned().unwrap_or(Value::Null),
                "key_slot": key_slot,
                "query_token": query_token,
                "contributor_dim": operand_row.pointer("/contributor_dim").cloned().unwrap_or(Value::Null),
                "operand_policy_classification": operand_classification,
                "materiality_row_present": materiality_row.is_some(),
                "query_delta": query_delta,
                "key_delta": key_delta,
                "abs_product_delta": abs_product_delta,
                "score_input_capture_uses_post_rope_f16_bucket_values": score_input_capture_post_rope_bucket,
                "product_contributor": product.clone(),
                "score_product_source_policy": source_policy.clone(),
            }));
        }
    }

    let classification = if compared_count == 0 {
        "no_tolerance_pinned_score_input_operand_rows"
    } else if missing_materiality_count == compared_count {
        "score_input_operand_drift_missing_materiality"
    } else if clean_count == compared_count {
        "score_input_operands_clean"
    } else if key_bucket_crossing_count == compared_count {
        "score_input_operand_drift_key_bucket_crossing"
    } else if key_only_count == compared_count {
        "score_input_operand_drift_key_only"
    } else if query_only_count == compared_count {
        "score_input_operand_drift_query_only"
    } else if mixed_count > 0 {
        "score_input_operand_drift_mixed_qk"
    } else {
        "score_input_operand_drift_unpinned"
    };
    let next_diagnostic = match classification {
        "score_input_operand_drift_key_bucket_crossing" => {
            "inspect selected key score-input capture source around the post-RoPE F16 bucket boundary before changing runtime math"
        }
        "score_input_operand_drift_key_only" => {
            "inspect selected key score-input capture source before changing runtime math"
        }
        "score_input_operand_drift_query_only" => {
            "inspect selected query score-input capture source before changing runtime math"
        }
        "score_input_operand_drift_mixed_qk" => {
            "inspect selected query and key score-input capture sources before changing runtime math"
        }
        "score_input_operands_clean" => {
            "move downstream to score accumulation or probability drift before changing runtime math"
        }
        "score_input_operand_drift_missing_materiality" => {
            "capture selected score product materiality rows before classifying operand drift"
        }
        "no_tolerance_pinned_score_input_operand_rows" => {
            "pin reference score input operand policy before classifying Rust/reference operand drift"
        }
        _ => "keep Rust score-input operand drift diagnostic-only",
    };

    json!({
        "diagnostic_only": true,
        "claim_allowed": false,
        "policy": "Rust/reference score-input operand drift is diagnostic-only evidence comparing selected score-product query/key operands after the reference operand is tolerance-pinned; it does not change runtime math or promote reference parity, A770 semantic quality, attention score residency, selected attention, resident KV, full residency, performance, or completion",
        "classification": classification,
        "compared_count": compared_count,
        "missing_materiality_count": missing_materiality_count,
        "clean_count": clean_count,
        "query_only_count": query_only_count,
        "key_only_count": key_only_count,
        "mixed_count": mixed_count,
        "key_bucket_crossing_count": key_bucket_crossing_count,
        "max_abs_query_delta": max_abs_query_delta,
        "max_abs_key_delta": max_abs_key_delta,
        "max_abs_product_delta": max_abs_product_delta,
        "rows": rows,
        "next_diagnostic": next_diagnostic,
    })
}

fn attention_selected_key_score_input_capture_source(
    operand_policy: &Value,
    operand_drift: &Value,
    materiality: &Value,
) -> Value {
    let operand_rows = operand_policy.pointer("/rows").and_then(Value::as_array);
    let drift_rows = operand_drift.pointer("/rows").and_then(Value::as_array);
    let materiality_rows = materiality.pointer("/rows").and_then(Value::as_array);
    let mut rows = Vec::<Value>::new();
    let mut compared_count = 0usize;
    let mut missing_context_count = 0usize;
    let mut raw_capture_count = 0usize;
    let mut post_rope_f16_view_count = 0usize;
    let mut f16_bucket_crossing_count = 0usize;
    let mut score_key_stage_f16_count = 0usize;

    if let Some(drift_rows) = drift_rows {
        for drift_row in drift_rows {
            if drift_row.pointer("/classification").and_then(Value::as_str)
                != Some("selected_score_input_operand_drift_key_bucket_crossing")
            {
                continue;
            }
            let head = drift_row.pointer("/head").and_then(Value::as_u64);
            let key_slot = drift_row.pointer("/key_slot").and_then(Value::as_u64);
            let query_token = drift_row.pointer("/query_token").and_then(Value::as_u64);
            let operand_row = find_qk_recompute_row(operand_rows, head, key_slot, query_token);
            let materiality_row =
                find_qk_recompute_row(materiality_rows, head, key_slot, query_token);
            let product_source = materiality_row
                .and_then(|row| row.pointer("/materiality/product_bucket_source"))
                .unwrap_or(&Value::Null);
            let source_policy = materiality_row
                .and_then(|row| row.pointer("/materiality/score_product_source_policy"))
                .unwrap_or(&Value::Null);
            let epsilon_probe = materiality_row
                .and_then(|row| row.pointer("/epsilon_probe"))
                .unwrap_or(&Value::Null);
            let key_stage = operand_row
                .and_then(|row| row.pointer("/reference_stage_provenance/key_stage"))
                .unwrap_or(&Value::Null);
            let product_reference_key =
                product_source.pointer("/product_reference_key").and_then(Value::as_f64);
            let product_rust_key =
                product_source.pointer("/product_rust_key").and_then(Value::as_f64);
            let reference_post_rope_raw =
                epsilon_probe.pointer("/post_rope/reference_capture").and_then(Value::as_f64);
            let rust_post_rope_raw =
                epsilon_probe.pointer("/post_rope/rust_capture").and_then(Value::as_f64);
            let reference_post_rope_f16 =
                epsilon_probe.pointer("/post_rope_bucket/left_f16_value").and_then(Value::as_f64);
            let rust_post_rope_f16 =
                epsilon_probe.pointer("/post_rope_bucket/right_f16_value").and_then(Value::as_f64);
            let bucket_crossing = epsilon_probe
                .pointer("/post_rope_bucket/f16_bucket_match")
                .and_then(Value::as_bool)
                == Some(false);
            let reference_matches_raw = product_reference_key
                .zip(reference_post_rope_raw)
                .is_some_and(|(product, raw)| (product - raw).abs() <= 1.0e-9);
            let rust_matches_raw = product_rust_key
                .zip(rust_post_rope_raw)
                .is_some_and(|(product, raw)| (product - raw).abs() <= 1.0e-9);
            let reference_matches_f16 = product_reference_key
                .zip(reference_post_rope_f16)
                .is_some_and(|(product, bucket)| (product - bucket).abs() <= 1.0e-9);
            let rust_matches_f16 = product_rust_key
                .zip(rust_post_rope_f16)
                .is_some_and(|(product, bucket)| (product - bucket).abs() <= 1.0e-9);
            let score_key_stage_is_f16 =
                key_stage.pointer("/dtype").and_then(Value::as_str) == Some("f16");
            let mut blocked_reasons = Vec::<String>::new();
            if operand_row.is_none() {
                blocked_reasons.push("reference_operand_policy_row_missing".to_string());
            }
            if materiality_row.is_none() {
                blocked_reasons.push("selected_materiality_row_missing".to_string());
            }
            if product_reference_key.is_none() || product_rust_key.is_none() {
                blocked_reasons.push("selected_product_key_values_missing".to_string());
            }
            if reference_post_rope_raw.is_none() || rust_post_rope_raw.is_none() {
                blocked_reasons.push("selected_post_rope_raw_capture_missing".to_string());
            }
            if reference_post_rope_f16.is_none() || rust_post_rope_f16.is_none() {
                blocked_reasons.push("selected_post_rope_f16_bucket_missing".to_string());
            }

            let row_classification = if !blocked_reasons.is_empty() {
                "selected_key_score_input_capture_source_missing"
            } else if reference_matches_raw && rust_matches_raw {
                "selected_key_score_input_capture_source_raw_post_rope"
            } else if reference_matches_f16 && rust_matches_f16 && score_key_stage_is_f16 {
                "selected_key_score_input_capture_source_post_rope_f16_view"
            } else if reference_matches_f16 && rust_matches_f16 {
                "selected_key_score_input_capture_source_post_rope_f16_value"
            } else {
                "selected_key_score_input_capture_source_unpinned"
            };

            compared_count += 1;
            match row_classification {
                "selected_key_score_input_capture_source_missing" => missing_context_count += 1,
                "selected_key_score_input_capture_source_raw_post_rope" => raw_capture_count += 1,
                "selected_key_score_input_capture_source_post_rope_f16_view"
                | "selected_key_score_input_capture_source_post_rope_f16_value" => {
                    post_rope_f16_view_count += 1;
                }
                _ => {}
            }
            if bucket_crossing {
                f16_bucket_crossing_count += 1;
            }
            if score_key_stage_is_f16 {
                score_key_stage_f16_count += 1;
            }

            rows.push(json!({
                "classification": row_classification,
                "head": head,
                "kv_head": drift_row.pointer("/kv_head").cloned().unwrap_or(Value::Null),
                "key_slot": key_slot,
                "query_token": query_token,
                "contributor_dim": drift_row.pointer("/contributor_dim").cloned().unwrap_or(Value::Null),
                "blocked_reasons": blocked_reasons,
                "operand_row_present": operand_row.is_some(),
                "materiality_row_present": materiality_row.is_some(),
                "score_key_stage_is_f16": score_key_stage_is_f16,
                "score_key_stage": key_stage.clone(),
                "f16_bucket_crossing": bucket_crossing,
                "product_reference_key": product_reference_key,
                "product_rust_key": product_rust_key,
                "reference_post_rope_raw": reference_post_rope_raw,
                "rust_post_rope_raw": rust_post_rope_raw,
                "reference_post_rope_f16": reference_post_rope_f16,
                "rust_post_rope_f16": rust_post_rope_f16,
                "reference_product_matches_raw_post_rope": reference_matches_raw,
                "rust_product_matches_raw_post_rope": rust_matches_raw,
                "reference_product_matches_post_rope_f16": reference_matches_f16,
                "rust_product_matches_post_rope_f16": rust_matches_f16,
                "product_bucket_source": product_source.clone(),
                "score_product_source_policy": source_policy.clone(),
            }));
        }
    }

    let classification = if compared_count == 0 {
        "no_selected_key_bucket_crossing_operand_rows"
    } else if missing_context_count == compared_count {
        "selected_key_score_input_capture_source_missing"
    } else if raw_capture_count == compared_count {
        "selected_key_score_input_capture_source_raw_post_rope"
    } else if post_rope_f16_view_count == compared_count
        && score_key_stage_f16_count == compared_count
    {
        "selected_key_score_input_capture_source_post_rope_f16_view"
    } else if post_rope_f16_view_count == compared_count {
        "selected_key_score_input_capture_source_post_rope_f16_value"
    } else {
        "selected_key_score_input_capture_source_unpinned"
    };
    let next_diagnostic = match classification {
        "selected_key_score_input_capture_source_post_rope_f16_view" => {
            "pin whether Rust and reference should both feed score products from post-RoPE F16 key views before changing runtime math"
        }
        "selected_key_score_input_capture_source_post_rope_f16_value" => {
            "pin score key capture dtype/provenance before changing runtime math"
        }
        "selected_key_score_input_capture_source_raw_post_rope" => {
            "move upstream from score-input capture to post-RoPE raw key generation before changing runtime math"
        }
        "selected_key_score_input_capture_source_missing" => {
            "capture selected key score-input and post-RoPE source values before changing runtime math"
        }
        "no_selected_key_bucket_crossing_operand_rows" => {
            "classify selected Rust/reference score-input operand drift before inspecting key capture source"
        }
        _ => "keep selected key score-input capture source diagnostic-only",
    };

    json!({
        "diagnostic_only": true,
        "claim_allowed": false,
        "policy": "Selected key score-input capture source is diagnostic-only evidence for whether the score product consumes raw post-RoPE key values or an F16 score-input view around the selected bucket crossing; it does not change runtime math or promote reference parity, A770 semantic quality, attention score residency, selected attention, resident KV, full residency, performance, or completion",
        "classification": classification,
        "compared_count": compared_count,
        "missing_context_count": missing_context_count,
        "raw_capture_count": raw_capture_count,
        "post_rope_f16_view_count": post_rope_f16_view_count,
        "f16_bucket_crossing_count": f16_bucket_crossing_count,
        "score_key_stage_f16_count": score_key_stage_f16_count,
        "rows": rows,
        "next_diagnostic": next_diagnostic,
    })
}

fn attention_selected_score_key_f16_policy(
    operand_policy: &Value,
    operand_drift: &Value,
    capture_source: &Value,
) -> Value {
    let operand_rows = operand_policy.pointer("/rows").and_then(Value::as_array);
    let drift_rows = operand_drift.pointer("/rows").and_then(Value::as_array);
    let source_rows = capture_source.pointer("/rows").and_then(Value::as_array);
    let mut rows = Vec::<Value>::new();
    let mut compared_count = 0usize;
    let mut missing_context_count = 0usize;
    let mut aligned_f16_view_count = 0usize;
    let mut bucket_sensitive_count = 0usize;
    let mut unpinned_count = 0usize;

    if let Some(source_rows) = source_rows {
        for source_row in source_rows {
            let source_classification =
                source_row.pointer("/classification").and_then(Value::as_str);
            if !matches!(
                source_classification,
                Some("selected_key_score_input_capture_source_post_rope_f16_view")
                    | Some("selected_key_score_input_capture_source_post_rope_f16_value")
            ) {
                continue;
            }
            let head = source_row.pointer("/head").and_then(Value::as_u64);
            let key_slot = source_row.pointer("/key_slot").and_then(Value::as_u64);
            let query_token = source_row.pointer("/query_token").and_then(Value::as_u64);
            let operand_row = find_qk_recompute_row(operand_rows, head, key_slot, query_token);
            let drift_row = find_qk_recompute_row(drift_rows, head, key_slot, query_token);
            let mut blocked_reasons = Vec::<String>::new();
            if operand_row.is_none() {
                blocked_reasons.push("reference_operand_policy_row_missing".to_string());
            }
            if drift_row.is_none() {
                blocked_reasons.push("rust_operand_drift_row_missing".to_string());
            }

            let reference_operand_classification =
                operand_row.and_then(|row| row.pointer("/classification").and_then(Value::as_str));
            let rust_operand_drift_classification =
                drift_row.and_then(|row| row.pointer("/classification").and_then(Value::as_str));
            let reference_score_candidate = operand_row
                .and_then(|row| row.pointer("/reference_score_input_candidate"))
                .and_then(Value::as_bool)
                == Some(true);
            let reference_exact_operand =
                operand_row.and_then(|row| row.pointer("/exact_operand")).and_then(Value::as_bool)
                    == Some(true);
            let reference_tolerance_operand = operand_row
                .and_then(|row| row.pointer("/tolerance_operand"))
                .and_then(Value::as_bool)
                == Some(true);
            let reference_abs_delta = operand_row
                .and_then(|row| row.pointer("/reference_abs_delta").and_then(Value::as_f64));
            let score_key_stage_is_f16 =
                source_row.pointer("/score_key_stage_is_f16").and_then(Value::as_bool)
                    == Some(true);
            let reference_matches_f16 = source_row
                .pointer("/reference_product_matches_post_rope_f16")
                .and_then(Value::as_bool)
                == Some(true);
            let rust_matches_f16 =
                source_row.pointer("/rust_product_matches_post_rope_f16").and_then(Value::as_bool)
                    == Some(true);
            let reference_matches_raw = source_row
                .pointer("/reference_product_matches_raw_post_rope")
                .and_then(Value::as_bool)
                == Some(true);
            let rust_matches_raw =
                source_row.pointer("/rust_product_matches_raw_post_rope").and_then(Value::as_bool)
                    == Some(true);
            let f16_bucket_crossing =
                source_row.pointer("/f16_bucket_crossing").and_then(Value::as_bool) == Some(true);
            let reference_feeds_f16_view =
                reference_score_candidate && score_key_stage_is_f16 && reference_matches_f16;
            let rust_feeds_f16_view = rust_matches_f16;
            let policy_aligned = reference_feeds_f16_view && rust_feeds_f16_view;
            let raw_policy_rejected = !reference_matches_raw && !rust_matches_raw;

            if !reference_score_candidate {
                blocked_reasons.push("reference_score_input_candidate_missing".to_string());
            }
            if !score_key_stage_is_f16 {
                blocked_reasons.push("reference_score_key_stage_not_f16".to_string());
            }
            if !reference_matches_f16 || !rust_matches_f16 {
                blocked_reasons
                    .push("score_key_product_not_post_rope_f16_on_both_sides".to_string());
            }

            let row_classification = if !blocked_reasons.is_empty() {
                "selected_score_key_f16_policy_unpinned"
            } else if policy_aligned && f16_bucket_crossing && raw_policy_rejected {
                "selected_score_key_f16_policy_aligned_bucket_sensitive"
            } else if policy_aligned {
                "selected_score_key_f16_policy_aligned"
            } else {
                "selected_score_key_f16_policy_unpinned"
            };

            compared_count += 1;
            match row_classification {
                "selected_score_key_f16_policy_unpinned" => unpinned_count += 1,
                "selected_score_key_f16_policy_aligned_bucket_sensitive" => {
                    aligned_f16_view_count += 1;
                    bucket_sensitive_count += 1;
                }
                "selected_score_key_f16_policy_aligned" => aligned_f16_view_count += 1,
                _ => {}
            }
            if !blocked_reasons.is_empty() {
                missing_context_count += 1;
            }

            rows.push(json!({
                "classification": row_classification,
                "head": head,
                "kv_head": source_row.pointer("/kv_head").cloned().unwrap_or(Value::Null),
                "key_slot": key_slot,
                "query_token": query_token,
                "contributor_dim": source_row.pointer("/contributor_dim").cloned().unwrap_or(Value::Null),
                "blocked_reasons": blocked_reasons,
                "capture_source_classification": source_classification,
                "reference_operand_classification": reference_operand_classification,
                "rust_operand_drift_classification": rust_operand_drift_classification,
                "reference_score_input_candidate": reference_score_candidate,
                "reference_exact_operand": reference_exact_operand,
                "reference_tolerance_operand": reference_tolerance_operand,
                "reference_abs_delta": reference_abs_delta,
                "score_key_stage_is_f16": score_key_stage_is_f16,
                "reference_feeds_post_rope_f16_view": reference_feeds_f16_view,
                "rust_feeds_post_rope_f16_view": rust_feeds_f16_view,
                "policy_aligned": policy_aligned,
                "f16_bucket_crossing": f16_bucket_crossing,
                "raw_policy_rejected": raw_policy_rejected,
                "reference_product_matches_raw_post_rope": reference_matches_raw,
                "rust_product_matches_raw_post_rope": rust_matches_raw,
                "reference_product_matches_post_rope_f16": reference_matches_f16,
                "rust_product_matches_post_rope_f16": rust_matches_f16,
                "runtime_change_candidate": if policy_aligned {
                    "none_from_score_key_f16_policy"
                } else {
                    "score_key_f16_policy_unpinned"
                },
            }));
        }
    }

    let classification = if compared_count == 0 {
        "no_selected_key_score_input_capture_source_rows"
    } else if unpinned_count == compared_count {
        "selected_score_key_f16_policy_unpinned"
    } else if aligned_f16_view_count == compared_count && bucket_sensitive_count > 0 {
        "selected_score_key_f16_policy_aligned_bucket_sensitive"
    } else if aligned_f16_view_count == compared_count {
        "selected_score_key_f16_policy_aligned"
    } else {
        "selected_score_key_f16_policy_mixed"
    };
    let next_diagnostic = match classification {
        "selected_score_key_f16_policy_aligned_bucket_sensitive" => {
            "localize the selected post-RoPE raw key epsilon that crosses the F16 bucket boundary; do not change score-input F16 policy"
        }
        "selected_score_key_f16_policy_aligned" => {
            "move downstream from score-key F16 policy because both sides feed post-RoPE F16 key views"
        }
        "selected_score_key_f16_policy_unpinned" => {
            "pin selected score-key F16 policy before changing runtime math"
        }
        "no_selected_key_score_input_capture_source_rows" => {
            "capture selected key score-input source rows before deciding F16 score-key policy"
        }
        _ => "keep selected score-key F16 policy diagnostic-only",
    };

    json!({
        "diagnostic_only": true,
        "claim_allowed": false,
        "policy": "Selected score-key F16 policy is diagnostic-only evidence for whether the selected reference and Rust score products are both fed by post-RoPE F16 key views; it does not change runtime math or promote reference parity, A770 semantic quality, attention score residency, selected attention, resident KV, full residency, performance, or completion",
        "classification": classification,
        "compared_count": compared_count,
        "missing_context_count": missing_context_count,
        "aligned_f16_view_count": aligned_f16_view_count,
        "bucket_sensitive_count": bucket_sensitive_count,
        "unpinned_count": unpinned_count,
        "rows": rows,
        "next_diagnostic": next_diagnostic,
    })
}

fn attention_selected_post_rope_raw_key_epsilon(
    score_key_policy: &Value,
    historical_rope_source: &Value,
) -> Value {
    let policy_rows = score_key_policy.pointer("/rows").and_then(Value::as_array);
    let historical_rows = historical_rope_source.pointer("/rows").and_then(Value::as_array);
    let mut rows = Vec::<Value>::new();
    let mut selected_count = 0usize;
    let mut compared_count = 0usize;
    let mut missing_probe_count = 0usize;
    let mut projection_bucket_crossing_count = 0usize;
    let mut capture_replay_mismatch_count = 0usize;
    let mut linearized_replay_mismatch_count = 0usize;
    let mut projection_subbucket_midpoint_crossing_count = 0usize;
    let mut unpinned_count = 0usize;
    let mut projection_buckets_stable_count = 0usize;
    let mut midpoint_straddled_count = 0usize;
    let mut replay_capture_match_count = 0usize;
    let mut linearized_replay_match_count = 0usize;
    let mut replay_bucket_crossing_count = 0usize;

    if let Some(policy_rows) = policy_rows {
        for policy_row in policy_rows {
            if policy_row.pointer("/classification").and_then(Value::as_str)
                != Some("selected_score_key_f16_policy_aligned_bucket_sensitive")
            {
                continue;
            }
            selected_count += 1;
            let head = policy_row.pointer("/head").and_then(Value::as_u64);
            let key_slot = policy_row.pointer("/key_slot").and_then(Value::as_u64);
            let query_token = policy_row.pointer("/query_token").and_then(Value::as_u64);
            let historical_row =
                find_qk_recompute_row(historical_rows, head, key_slot, query_token);
            let probe = historical_row
                .and_then(|row| row.pointer("/post_rope_epsilon_probe"))
                .unwrap_or(&Value::Null);
            let mut blocked_reasons = Vec::<String>::new();
            if historical_row.is_none() {
                blocked_reasons.push("historical_projection_rope_source_row_missing".to_string());
            }
            if probe.is_null() {
                blocked_reasons.push("post_rope_epsilon_probe_missing".to_string());
            }

            let projection_bucket_match =
                probe.pointer("/projection_bucket/f16_bucket_match").and_then(Value::as_bool);
            let paired_projection_bucket_match = probe
                .pointer("/paired_projection_bucket/f16_bucket_match")
                .and_then(Value::as_bool);
            let post_rope_bucket_match =
                probe.pointer("/post_rope_bucket/f16_bucket_match").and_then(Value::as_bool);
            let replay_bucket_match =
                probe.pointer("/replay_bucket/f16_bucket_match").and_then(Value::as_bool);
            let reference_replay_minus_capture =
                probe.pointer("/post_rope/reference_replay_minus_capture").and_then(Value::as_f64);
            let rust_replay_minus_capture =
                probe.pointer("/post_rope/rust_replay_minus_capture").and_then(Value::as_f64);
            let linearized_delta_minus_runtime_replay_delta = probe
                .pointer("/post_rope/linearized_delta_minus_runtime_replay_delta")
                .and_then(Value::as_f64);
            let left_minus_midpoint =
                probe.pointer("/post_rope_bucket/left_minus_midpoint").and_then(Value::as_f64);
            let right_minus_midpoint =
                probe.pointer("/post_rope_bucket/right_minus_midpoint").and_then(Value::as_f64);
            let capture_delta = probe.pointer("/post_rope/capture_delta").and_then(Value::as_f64);
            let runtime_replay_delta =
                probe.pointer("/post_rope/runtime_replay_delta").and_then(Value::as_f64);
            let linearized_delta =
                probe.pointer("/input_pair/linearized_delta_for_probe_dim").and_then(Value::as_f64);
            let post_rope_bucket_crossing = post_rope_bucket_match == Some(false);
            let projection_buckets_stable = projection_bucket_match == Some(true)
                && paired_projection_bucket_match == Some(true);
            let replay_bucket_crossing = replay_bucket_match == Some(false);
            let replay_matches_capture =
                reference_replay_minus_capture.zip(rust_replay_minus_capture).is_some_and(
                    |(reference, rust)| reference.abs() <= 1.0e-12 && rust.abs() <= 1.0e-12,
                );
            let linearized_matches_replay = linearized_delta_minus_runtime_replay_delta
                .is_some_and(|delta| delta.abs() <= 1.0e-6);
            let midpoint_straddled =
                left_minus_midpoint.zip(right_minus_midpoint).is_some_and(|(left, right)| {
                    (left > 0.0 && right < 0.0) || (left < 0.0 && right > 0.0)
                });

            if probe.is_null() {
                missing_probe_count += 1;
            } else {
                compared_count += 1;
            }
            if projection_bucket_match == Some(false)
                || paired_projection_bucket_match == Some(false)
            {
                projection_bucket_crossing_count += 1;
            }
            if projection_buckets_stable {
                projection_buckets_stable_count += 1;
            }
            if replay_bucket_crossing {
                replay_bucket_crossing_count += 1;
            }
            if replay_matches_capture {
                replay_capture_match_count += 1;
            }
            if linearized_matches_replay {
                linearized_replay_match_count += 1;
            }
            if midpoint_straddled {
                midpoint_straddled_count += 1;
            }

            let row_classification = if probe.is_null() {
                "selected_post_rope_raw_key_epsilon_missing"
            } else if !projection_buckets_stable {
                "selected_post_rope_raw_key_epsilon_projection_bucket_crossing"
            } else if !replay_matches_capture {
                capture_replay_mismatch_count += 1;
                "selected_post_rope_raw_key_epsilon_capture_replay_mismatch"
            } else if !linearized_matches_replay {
                linearized_replay_mismatch_count += 1;
                "selected_post_rope_raw_key_epsilon_rope_linearization_unpinned"
            } else if post_rope_bucket_crossing && replay_bucket_crossing && midpoint_straddled {
                projection_subbucket_midpoint_crossing_count += 1;
                "selected_post_rope_raw_key_epsilon_projection_subbucket_midpoint_crossing"
            } else {
                unpinned_count += 1;
                "selected_post_rope_raw_key_epsilon_unpinned"
            };

            rows.push(json!({
                "classification": row_classification,
                "head": head,
                "kv_head": policy_row.pointer("/kv_head").cloned().unwrap_or(Value::Null),
                "key_slot": key_slot,
                "query_token": query_token,
                "contributor_dim": policy_row.pointer("/contributor_dim").cloned().unwrap_or(Value::Null),
                "blocked_reasons": blocked_reasons,
                "historical_row_present": historical_row.is_some(),
                "post_rope_epsilon_probe_present": !probe.is_null(),
                "variant_id": probe.pointer("/variant_id").cloned().unwrap_or(Value::Null),
                "probe_dim": probe.pointer("/probe_dim").cloned().unwrap_or(Value::Null),
                "paired_dim": probe.pointer("/paired_dim").cloned().unwrap_or(Value::Null),
                "lane": probe.pointer("/lane").cloned().unwrap_or(Value::Null),
                "output_component": probe.pointer("/output_component").cloned().unwrap_or(Value::Null),
                "capture_delta": capture_delta,
                "runtime_replay_delta": runtime_replay_delta,
                "linearized_delta_for_probe_dim": linearized_delta,
                "linearized_delta_minus_runtime_replay_delta": linearized_delta_minus_runtime_replay_delta,
                "reference_replay_minus_capture": reference_replay_minus_capture,
                "rust_replay_minus_capture": rust_replay_minus_capture,
                "post_rope_bucket_crossing": post_rope_bucket_crossing,
                "projection_buckets_stable": projection_buckets_stable,
                "replay_bucket_crossing": replay_bucket_crossing,
                "replay_matches_capture": replay_matches_capture,
                "linearized_matches_replay": linearized_matches_replay,
                "midpoint_straddled": midpoint_straddled,
                "projection_bucket_match": projection_bucket_match,
                "paired_projection_bucket_match": paired_projection_bucket_match,
                "post_rope_bucket_match": post_rope_bucket_match,
                "replay_bucket_match": replay_bucket_match,
                "post_rope_bucket": probe.pointer("/post_rope_bucket").cloned().unwrap_or(Value::Null),
                "projection_bucket": probe.pointer("/projection_bucket").cloned().unwrap_or(Value::Null),
                "paired_projection_bucket": probe.pointer("/paired_projection_bucket").cloned().unwrap_or(Value::Null),
                "replay_bucket": probe.pointer("/replay_bucket").cloned().unwrap_or(Value::Null),
                "input_pair": probe.pointer("/input_pair").cloned().unwrap_or(Value::Null),
                "runtime_change_candidate": match row_classification {
                    "selected_post_rope_raw_key_epsilon_projection_subbucket_midpoint_crossing" => {
                        "none_from_score_input_or_rope_replay_capture"
                    }
                    "selected_post_rope_raw_key_epsilon_projection_bucket_crossing" => {
                        "localize_projection_input_bucket_crossing"
                    }
                    "selected_post_rope_raw_key_epsilon_capture_replay_mismatch" => {
                        "pin_post_rope_capture_replay_mismatch"
                    }
                    "selected_post_rope_raw_key_epsilon_rope_linearization_unpinned" => {
                        "pin_rope_linearization"
                    }
                    _ => "post_rope_raw_key_epsilon_unpinned",
                },
            }));
        }
    }

    let classification = if selected_count == 0 {
        "no_selected_score_key_f16_policy_bucket_sensitive_rows"
    } else if missing_probe_count == selected_count {
        "selected_post_rope_raw_key_epsilon_missing"
    } else if projection_bucket_crossing_count > 0 {
        "selected_post_rope_raw_key_epsilon_projection_bucket_crossing"
    } else if capture_replay_mismatch_count > 0 {
        "selected_post_rope_raw_key_epsilon_capture_replay_mismatch"
    } else if linearized_replay_mismatch_count > 0 {
        "selected_post_rope_raw_key_epsilon_rope_linearization_unpinned"
    } else if projection_subbucket_midpoint_crossing_count > 0 && unpinned_count == 0 {
        "selected_post_rope_raw_key_epsilon_projection_subbucket_midpoint_crossing"
    } else {
        "selected_post_rope_raw_key_epsilon_unpinned"
    };
    let next_diagnostic = match classification {
        "selected_post_rope_raw_key_epsilon_projection_subbucket_midpoint_crossing" => {
            "localize selected historical K projection subbucket epsilon source before changing RoPE or score-input runtime math"
        }
        "selected_post_rope_raw_key_epsilon_projection_bucket_crossing" => {
            "localize selected historical K projection bucket crossing before changing RoPE or score-input runtime math"
        }
        "selected_post_rope_raw_key_epsilon_capture_replay_mismatch" => {
            "pin selected post-RoPE capture versus replay mismatch before changing runtime math"
        }
        "selected_post_rope_raw_key_epsilon_rope_linearization_unpinned" => {
            "pin selected RoPE linearized delta versus replay delta before changing runtime math"
        }
        "selected_post_rope_raw_key_epsilon_missing" => {
            "capture selected post-RoPE raw key epsilon probe before changing runtime math"
        }
        "no_selected_score_key_f16_policy_bucket_sensitive_rows" => {
            "pin selected score-key F16 policy before post-RoPE raw key epsilon attribution"
        }
        _ => "keep selected post-RoPE raw key epsilon diagnostic-only",
    };

    json!({
        "diagnostic_only": true,
        "claim_allowed": false,
        "policy": "Selected post-RoPE raw key epsilon is diagnostic-only evidence for whether a selected score-key F16 bucket crossing is explained by sub-bucket projection input drift transformed through RoPE and straddling the post-RoPE F16 midpoint; it does not change runtime math or promote reference parity, A770 semantic quality, attention score residency, selected attention, resident KV, full residency, performance, or completion",
        "classification": classification,
        "selected_count": selected_count,
        "compared_count": compared_count,
        "missing_probe_count": missing_probe_count,
        "projection_bucket_crossing_count": projection_bucket_crossing_count,
        "capture_replay_mismatch_count": capture_replay_mismatch_count,
        "linearized_replay_mismatch_count": linearized_replay_mismatch_count,
        "projection_subbucket_midpoint_crossing_count": projection_subbucket_midpoint_crossing_count,
        "unpinned_count": unpinned_count,
        "projection_buckets_stable_count": projection_buckets_stable_count,
        "midpoint_straddled_count": midpoint_straddled_count,
        "replay_capture_match_count": replay_capture_match_count,
        "linearized_replay_match_count": linearized_replay_match_count,
        "replay_bucket_crossing_count": replay_bucket_crossing_count,
        "rows": rows,
        "next_diagnostic": next_diagnostic,
    })
}

fn attention_post_fix_score_input_frontier(
    operand_drift: &Value,
    selected_key_source: &Value,
    capture_source: &Value,
    score_key_policy: &Value,
    post_rope_raw_key_epsilon: &Value,
    historical_rope_source: &Value,
) -> Value {
    let drift_rows = operand_drift.pointer("/rows").and_then(Value::as_array);
    let selected_key_rows = selected_key_source.pointer("/rows").and_then(Value::as_array);
    let capture_rows = capture_source.pointer("/rows").and_then(Value::as_array);
    let policy_rows = score_key_policy.pointer("/rows").and_then(Value::as_array);
    let epsilon_rows = post_rope_raw_key_epsilon.pointer("/rows").and_then(Value::as_array);
    let historical_rows = historical_rope_source.pointer("/rows").and_then(Value::as_array);
    let mut rows = Vec::<Value>::new();
    let mut selected_count = 0usize;
    let mut missing_context_count = 0usize;
    let mut post_rope_f16_view_count = 0usize;
    let mut exact_boundary_count = 0usize;
    let mut selected_dim_token_context_count = 0usize;
    let mut historical_pre_rope_available_count = 0usize;
    let mut post_rope_epsilon_reported_count = 0usize;
    let mut capture_replay_mismatch_count = 0usize;
    let mut projection_subbucket_midpoint_count = 0usize;
    let mut history_expansion_context_count = 0usize;
    let mut max_abs_key_delta = 0.0f64;
    let mut max_abs_product_delta = 0.0f64;

    if let Some(drift_rows) = drift_rows {
        for drift_row in drift_rows {
            if drift_row.pointer("/classification").and_then(Value::as_str)
                != Some("selected_score_input_operand_drift_key_bucket_crossing")
            {
                continue;
            }
            selected_count += 1;
            let head = drift_row.pointer("/head").and_then(Value::as_u64);
            let key_slot = drift_row.pointer("/key_slot").and_then(Value::as_u64);
            let query_token = drift_row.pointer("/query_token").and_then(Value::as_u64);
            let selected_key_row =
                find_qk_recompute_row(selected_key_rows, head, key_slot, query_token);
            let capture_row = find_qk_recompute_row(capture_rows, head, key_slot, query_token);
            let policy_row = find_qk_recompute_row(policy_rows, head, key_slot, query_token);
            let epsilon_row = find_qk_recompute_row(epsilon_rows, head, key_slot, query_token);
            let historical_row =
                find_qk_recompute_row(historical_rows, head, key_slot, query_token);

            let key_delta = drift_row.pointer("/key_delta").and_then(Value::as_f64).unwrap_or(0.0);
            let abs_product_delta =
                drift_row.pointer("/abs_product_delta").and_then(Value::as_f64).unwrap_or(0.0);
            max_abs_key_delta = max_abs_key_delta.max(key_delta.abs());
            max_abs_product_delta = max_abs_product_delta.max(abs_product_delta);

            let selected_key_classification = selected_key_row
                .and_then(|row| row.pointer("/classification").and_then(Value::as_str));
            let capture_classification =
                capture_row.and_then(|row| row.pointer("/classification").and_then(Value::as_str));
            let policy_classification =
                policy_row.and_then(|row| row.pointer("/classification").and_then(Value::as_str));
            let epsilon_classification =
                epsilon_row.and_then(|row| row.pointer("/classification").and_then(Value::as_str));
            let historical_classification = historical_row
                .and_then(|row| row.pointer("/classification").and_then(Value::as_str));
            let post_rope_f16_view = matches!(
                capture_classification,
                Some("selected_key_score_input_capture_source_post_rope_f16_view")
                    | Some("selected_key_score_input_capture_source_post_rope_f16_value")
            );
            let exact_boundary = matches!(
                selected_key_classification,
                Some("selected_key_drift_enters_before_cache_store")
                    | Some("selected_key_drift_enters_cache_readback")
                    | Some("selected_key_drift_follows_cache_f16_roundtrip")
                    | Some("selected_key_drift_visible_at_score_input")
            );
            let selected_dim_token_context = selected_key_row
                .is_some_and(selected_key_source_row_has_selected_dim_token_context);
            let historical_pre_rope_available = historical_row
                .and_then(|row| row.pointer("/selected_dim_values/reference_projection"))
                .is_some_and(|value| !value.is_null());
            let post_rope_epsilon_reported = epsilon_row.is_some_and(|row| {
                row.pointer("/post_rope_epsilon_probe_present").and_then(Value::as_bool)
                    == Some(true)
            });
            let capture_replay_mismatch = epsilon_classification
                == Some("selected_post_rope_raw_key_epsilon_capture_replay_mismatch");
            let projection_subbucket_midpoint = epsilon_classification
                == Some(
                    "selected_post_rope_raw_key_epsilon_projection_subbucket_midpoint_crossing",
                );
            let history_expansion_context = selected_dim_token_context
                && post_rope_f16_view
                && historical_pre_rope_available
                && !exact_boundary;

            if post_rope_f16_view {
                post_rope_f16_view_count += 1;
            }
            if exact_boundary {
                exact_boundary_count += 1;
            }
            if selected_dim_token_context {
                selected_dim_token_context_count += 1;
            }
            if historical_pre_rope_available {
                historical_pre_rope_available_count += 1;
            }
            if post_rope_epsilon_reported {
                post_rope_epsilon_reported_count += 1;
            }
            if capture_replay_mismatch {
                capture_replay_mismatch_count += 1;
            }
            if projection_subbucket_midpoint {
                projection_subbucket_midpoint_count += 1;
            }
            if history_expansion_context {
                history_expansion_context_count += 1;
            }

            let mut blocked_reasons = Vec::<String>::new();
            if selected_key_row.is_none() {
                blocked_reasons.push("selected_key_source_row_missing".to_string());
            }
            if capture_row.is_none() {
                blocked_reasons.push("selected_key_capture_source_row_missing".to_string());
            }
            if policy_row.is_none() {
                blocked_reasons.push("selected_score_key_f16_policy_row_missing".to_string());
            }
            if historical_row.is_none() {
                blocked_reasons
                    .push("selected_historical_projection_rope_source_row_missing".to_string());
            }
            if epsilon_row.is_none() {
                blocked_reasons.push("selected_post_rope_raw_key_epsilon_row_missing".to_string());
            }
            if !historical_pre_rope_available {
                blocked_reasons.push("selected_pre_rope_k_value_missing".to_string());
            }

            let row_classification = if !blocked_reasons.is_empty() {
                missing_context_count += 1;
                "post_fix_score_input_frontier_missing_context"
            } else if exact_boundary {
                "post_fix_score_input_frontier_exact_boundary_attributed"
            } else if history_expansion_context {
                "post_fix_score_input_frontier_selected_dim_token_score_history_context"
            } else if projection_subbucket_midpoint {
                "post_fix_score_input_frontier_projection_subbucket_midpoint"
            } else if capture_replay_mismatch {
                "post_fix_score_input_frontier_post_rope_capture_replay_mismatch"
            } else if post_rope_f16_view {
                "post_fix_score_input_frontier_post_rope_f16_view_bucket_sensitive"
            } else {
                "post_fix_score_input_frontier_unpinned"
            };

            rows.push(json!({
                "classification": row_classification,
                "head": head,
                "kv_head": drift_row.pointer("/kv_head").cloned().unwrap_or(Value::Null),
                "key_slot": key_slot,
                "query_token": query_token,
                "contributor_dim": drift_row.pointer("/contributor_dim").cloned().unwrap_or(Value::Null),
                "blocked_reasons": blocked_reasons,
                "key_delta": drift_row.pointer("/key_delta").cloned().unwrap_or(Value::Null),
                "abs_product_delta": drift_row.pointer("/abs_product_delta").cloned().unwrap_or(Value::Null),
                "product_contributor": drift_row.pointer("/product_contributor").cloned().unwrap_or(Value::Null),
                "selected_key_source_classification": selected_key_classification,
                "capture_source_classification": capture_classification,
                "score_key_f16_policy_classification": policy_classification,
                "post_rope_raw_key_epsilon_classification": epsilon_classification,
                "historical_projection_rope_classification": historical_classification,
                "post_rope_f16_view": post_rope_f16_view,
                "exact_boundary": exact_boundary,
                "selected_dim_token_context": selected_dim_token_context,
                "historical_pre_rope_available": historical_pre_rope_available,
                "post_rope_epsilon_reported": post_rope_epsilon_reported,
                "history_expansion_context": history_expansion_context,
                "pre_rope_k": historical_row.and_then(|row| row.pointer("/selected_dim_values/reference_projection")).cloned().unwrap_or(Value::Null),
                "rust_pre_rope_k": historical_row.and_then(|row| row.pointer("/selected_dim_values/rust_projection")).cloned().unwrap_or(Value::Null),
                "post_rope_k": historical_row.and_then(|row| row.pointer("/selected_dim_values/reference_post_rope")).cloned().unwrap_or(Value::Null),
                "rust_post_rope_k": historical_row.and_then(|row| row.pointer("/selected_dim_values/rust_post_rope")).cloned().unwrap_or(Value::Null),
                "score_input_k": capture_row.and_then(|row| row.pointer("/product_reference_key")).cloned().unwrap_or(Value::Null),
                "rust_score_input_k": capture_row.and_then(|row| row.pointer("/product_rust_key")).cloned().unwrap_or(Value::Null),
                "reference_post_rope_raw": capture_row.and_then(|row| row.pointer("/reference_post_rope_raw")).cloned().unwrap_or(Value::Null),
                "rust_post_rope_raw": capture_row.and_then(|row| row.pointer("/rust_post_rope_raw")).cloned().unwrap_or(Value::Null),
                "reference_post_rope_f16": capture_row.and_then(|row| row.pointer("/reference_post_rope_f16")).cloned().unwrap_or(Value::Null),
                "rust_post_rope_f16": capture_row.and_then(|row| row.pointer("/rust_post_rope_f16")).cloned().unwrap_or(Value::Null),
                "selected_key_source_row": selected_key_row.cloned().unwrap_or(Value::Null),
                "capture_source_row": capture_row.cloned().unwrap_or(Value::Null),
                "score_key_f16_policy_row": policy_row.cloned().unwrap_or(Value::Null),
                "post_rope_raw_key_epsilon_row": epsilon_row.cloned().unwrap_or(Value::Null),
                "historical_projection_rope_row": historical_row.cloned().unwrap_or(Value::Null),
            }));
        }
    }

    let classification = if selected_count == 0 {
        "post_fix_score_input_frontier_no_key_bucket_crossings"
    } else if missing_context_count == selected_count {
        "post_fix_score_input_frontier_missing_context"
    } else if exact_boundary_count > 0 {
        "post_fix_score_input_frontier_exact_boundary_attributed"
    } else if history_expansion_context_count > 0 {
        "post_fix_score_input_frontier_selected_dim_token_score_history_context"
    } else if projection_subbucket_midpoint_count > 0 {
        "post_fix_score_input_frontier_projection_subbucket_midpoint"
    } else if capture_replay_mismatch_count > 0 {
        "post_fix_score_input_frontier_post_rope_capture_replay_mismatch"
    } else if post_rope_f16_view_count > 0 {
        "post_fix_score_input_frontier_post_rope_f16_view_bucket_sensitive"
    } else {
        "post_fix_score_input_frontier_unpinned"
    };
    let next_diagnostic = match classification {
        "post_fix_score_input_frontier_selected_dim_token_score_history_context" => {
            "emit selected key dim/token slot probes across pre-RoPE, post-RoPE, and score-input history before changing runtime math"
        }
        "post_fix_score_input_frontier_post_rope_capture_replay_mismatch" => {
            "pin post-RoPE capture versus replay after the ROPE expression fix before changing runtime math"
        }
        "post_fix_score_input_frontier_projection_subbucket_midpoint" => {
            "localize projection subbucket midpoint source before changing runtime math"
        }
        "post_fix_score_input_frontier_exact_boundary_attributed" => {
            "follow the exact selected key boundary classification before changing runtime math"
        }
        "post_fix_score_input_frontier_missing_context" => {
            "capture missing selected K pre-RoPE/post-RoPE/score-input context rows"
        }
        "post_fix_score_input_frontier_no_key_bucket_crossings" => {
            "move downstream from score-input operand drift"
        }
        _ => "keep the post-fix score-input frontier diagnostic-only",
    };

    json!({
        "diagnostic_only": true,
        "claim_allowed": false,
        "policy": "Post-fix score-input frontier is diagnostic-only evidence after the selected-K ROPE expression policy fix; it classifies remaining K bucket crossings by selected head/token/dim, pre-RoPE K, post-RoPE K, score-input K, and product contribution without changing runtime math or promoting reference parity, A770 semantic quality, attention score residency, selected attention, resident KV, full residency, performance, or completion",
        "classification": classification,
        "selected_count": selected_count,
        "missing_context_count": missing_context_count,
        "post_rope_f16_view_count": post_rope_f16_view_count,
        "exact_boundary_count": exact_boundary_count,
        "selected_dim_token_context_count": selected_dim_token_context_count,
        "historical_pre_rope_available_count": historical_pre_rope_available_count,
        "post_rope_epsilon_reported_count": post_rope_epsilon_reported_count,
        "capture_replay_mismatch_count": capture_replay_mismatch_count,
        "projection_subbucket_midpoint_count": projection_subbucket_midpoint_count,
        "history_expansion_context_count": history_expansion_context_count,
        "max_abs_key_delta": max_abs_key_delta,
        "max_abs_product_delta": max_abs_product_delta,
        "source_classifications": {
            "operand_drift": operand_drift.pointer("/classification").cloned().unwrap_or(Value::Null),
            "selected_key_source": selected_key_source.pointer("/classification").cloned().unwrap_or(Value::Null),
            "selected_key_boundary_context": selected_key_source.pointer("/boundary_context_classification").cloned().unwrap_or(Value::Null),
            "capture_source": capture_source.pointer("/classification").cloned().unwrap_or(Value::Null),
            "score_key_f16_policy": score_key_policy.pointer("/classification").cloned().unwrap_or(Value::Null),
            "post_rope_raw_key_epsilon": post_rope_raw_key_epsilon.pointer("/classification").cloned().unwrap_or(Value::Null),
            "historical_projection_rope": historical_rope_source.pointer("/classification").cloned().unwrap_or(Value::Null),
        },
        "rows": rows,
        "next_diagnostic": next_diagnostic,
    })
}

fn selected_key_source_row_has_selected_dim_token_context(row: &Value) -> bool {
    [
        "/legacy_before_cache_store",
        "/legacy_cache_readback",
        "/legacy_cache_f16_roundtrip",
        "/legacy_score_input",
        "/kcur_before_cache_store",
        "/kcur_score_input",
    ]
    .iter()
    .any(|pointer| {
        row.pointer(pointer)
            .and_then(|summary| summary.pointer("/selected_dim_and_token_bucket"))
            .and_then(Value::as_bool)
            == Some(true)
    })
}

fn attention_selected_key_dim_token_slot_probe(post_fix_frontier: &Value) -> Value {
    let frontier_rows = post_fix_frontier.pointer("/rows").and_then(Value::as_array);
    let mut rows = Vec::<Value>::new();
    let mut selected_count = 0usize;
    let mut missing_context_count = 0usize;
    let mut pre_rope_bucket_crossing_count = 0usize;
    let mut post_rope_bucket_crossing_count = 0usize;
    let mut score_input_bucket_crossing_count = 0usize;
    let mut score_input_matches_post_rope_f16_count = 0usize;
    let mut clean_count = 0usize;
    let mut max_abs_stage_delta = 0.0f64;

    if let Some(frontier_rows) = frontier_rows {
        for frontier_row in frontier_rows {
            let selected_dim_token_context =
                frontier_row.pointer("/selected_dim_token_context").and_then(Value::as_bool)
                    == Some(true);
            let frontier_classification =
                frontier_row.pointer("/classification").and_then(Value::as_str);
            if !selected_dim_token_context
                && frontier_classification
                    != Some(
                        "post_fix_score_input_frontier_selected_dim_token_score_history_context",
                    )
            {
                continue;
            }
            selected_count += 1;
            let pre_rope = selected_key_slot_stage_probe(
                "pre_rope_projection",
                value_f64(frontier_row, "/pre_rope_k"),
                value_f64(frontier_row, "/rust_pre_rope_k"),
            );
            let post_rope = selected_key_slot_stage_probe(
                "post_rope_history",
                value_f64(frontier_row, "/post_rope_k"),
                value_f64(frontier_row, "/rust_post_rope_k"),
            );
            let score_input = selected_key_slot_stage_probe(
                "score_input_history",
                value_f64(frontier_row, "/score_input_k"),
                value_f64(frontier_row, "/rust_score_input_k"),
            );

            let stage_probes = [&pre_rope, &post_rope, &score_input];
            let missing_context = stage_probes.iter().any(|probe| {
                probe.pointer("/values_present").and_then(Value::as_bool) != Some(true)
            });
            let pre_rope_bucket_crossing = selected_key_slot_probe_bucket_crossing(&pre_rope);
            let post_rope_bucket_crossing = selected_key_slot_probe_bucket_crossing(&post_rope);
            let score_input_bucket_crossing = selected_key_slot_probe_bucket_crossing(&score_input);
            let reference_score_matches_post_f16 = selected_key_score_matches_post_rope_f16(
                value_f64(frontier_row, "/score_input_k"),
                &post_rope,
                "/bucket/left_f16_value",
            );
            let rust_score_matches_post_f16 = selected_key_score_matches_post_rope_f16(
                value_f64(frontier_row, "/rust_score_input_k"),
                &post_rope,
                "/bucket/right_f16_value",
            );
            let score_input_matches_post_rope_f16 =
                reference_score_matches_post_f16 && rust_score_matches_post_f16;

            for probe in stage_probes {
                if let Some(delta) = value_f64(probe, "/abs_delta") {
                    max_abs_stage_delta = max_abs_stage_delta.max(delta);
                }
            }

            let mut blocked_reasons = Vec::<String>::new();
            if value_f64(frontier_row, "/pre_rope_k").is_none()
                || value_f64(frontier_row, "/rust_pre_rope_k").is_none()
            {
                blocked_reasons.push("selected_pre_rope_values_missing".to_string());
            }
            if value_f64(frontier_row, "/post_rope_k").is_none()
                || value_f64(frontier_row, "/rust_post_rope_k").is_none()
            {
                blocked_reasons.push("selected_post_rope_values_missing".to_string());
            }
            if value_f64(frontier_row, "/score_input_k").is_none()
                || value_f64(frontier_row, "/rust_score_input_k").is_none()
            {
                blocked_reasons.push("selected_score_input_values_missing".to_string());
            }

            let row_classification = if missing_context {
                missing_context_count += 1;
                "selected_key_dim_token_slot_probe_missing_context"
            } else if pre_rope_bucket_crossing {
                pre_rope_bucket_crossing_count += 1;
                "selected_key_dim_token_slot_probe_pre_rope_bucket_crossing"
            } else if post_rope_bucket_crossing {
                post_rope_bucket_crossing_count += 1;
                "selected_key_dim_token_slot_probe_post_rope_bucket_crossing"
            } else if score_input_bucket_crossing {
                score_input_bucket_crossing_count += 1;
                "selected_key_dim_token_slot_probe_score_input_bucket_crossing"
            } else {
                clean_count += 1;
                "selected_key_dim_token_slot_probe_clean"
            };
            if score_input_matches_post_rope_f16 {
                score_input_matches_post_rope_f16_count += 1;
            }
            rows.push(json!({
                "classification": row_classification,
                "head": frontier_row.pointer("/head").cloned().unwrap_or(Value::Null),
                "kv_head": frontier_row.pointer("/kv_head").cloned().unwrap_or(Value::Null),
                "key_slot": frontier_row.pointer("/key_slot").cloned().unwrap_or(Value::Null),
                "query_token": frontier_row.pointer("/query_token").cloned().unwrap_or(Value::Null),
                "contributor_dim": frontier_row.pointer("/contributor_dim").cloned().unwrap_or(Value::Null),
                "blocked_reasons": blocked_reasons,
                "frontier_classification": frontier_row.pointer("/classification").cloned().unwrap_or(Value::Null),
                "pre_rope": pre_rope,
                "post_rope": post_rope,
                "score_input": score_input,
                "reference_score_input_matches_post_rope_f16": reference_score_matches_post_f16,
                "rust_score_input_matches_post_rope_f16": rust_score_matches_post_f16,
                "score_input_matches_post_rope_f16": score_input_matches_post_rope_f16,
                "source": {
                    "selected_key_source_classification": frontier_row.pointer("/selected_key_source_classification").cloned().unwrap_or(Value::Null),
                    "capture_source_classification": frontier_row.pointer("/capture_source_classification").cloned().unwrap_or(Value::Null),
                    "score_key_f16_policy_classification": frontier_row.pointer("/score_key_f16_policy_classification").cloned().unwrap_or(Value::Null),
                    "post_rope_raw_key_epsilon_classification": frontier_row.pointer("/post_rope_raw_key_epsilon_classification").cloned().unwrap_or(Value::Null),
                    "historical_projection_rope_classification": frontier_row.pointer("/historical_projection_rope_classification").cloned().unwrap_or(Value::Null),
                },
            }));
        }
    }

    let classification = if selected_count == 0 {
        "selected_key_dim_token_slot_probe_no_selected_rows"
    } else if missing_context_count == selected_count {
        "selected_key_dim_token_slot_probe_missing_context"
    } else if pre_rope_bucket_crossing_count > 0 {
        "selected_key_dim_token_slot_probe_pre_rope_bucket_crossing"
    } else if post_rope_bucket_crossing_count > 0 {
        "selected_key_dim_token_slot_probe_post_rope_bucket_crossing"
    } else if score_input_bucket_crossing_count > 0 {
        "selected_key_dim_token_slot_probe_score_input_bucket_crossing"
    } else if clean_count == selected_count {
        "selected_key_dim_token_slot_probe_clean"
    } else {
        "selected_key_dim_token_slot_probe_unpinned"
    };
    let next_diagnostic = match classification {
        "selected_key_dim_token_slot_probe_post_rope_bucket_crossing" => {
            "localize selected post-RoPE history bucket crossing before changing score-input or runtime math"
        }
        "selected_key_dim_token_slot_probe_pre_rope_bucket_crossing" => {
            "localize selected pre-RoPE K projection bucket crossing before changing RoPE or score math"
        }
        "selected_key_dim_token_slot_probe_score_input_bucket_crossing" => {
            "localize selected post-RoPE to score-input history expansion before changing runtime math"
        }
        "selected_key_dim_token_slot_probe_missing_context" => {
            "capture missing selected key dim/token pre-RoPE, post-RoPE, or score-input values"
        }
        "selected_key_dim_token_slot_probe_clean" => {
            "move downstream from selected key dim/token slot values to score accumulation or probability drift"
        }
        "selected_key_dim_token_slot_probe_no_selected_rows" => {
            "refresh post-fix score-input frontier before probing selected key slots"
        }
        _ => "keep selected key dim/token slot probe diagnostic-only",
    };

    json!({
        "diagnostic_only": true,
        "claim_allowed": false,
        "policy": "Selected key dim/token slot probe is diagnostic-only evidence for one remaining post-fix score-input frontier row; it compares pre-RoPE K, post-RoPE K, and score-input K at the selected head/key/query/dim without changing runtime math or promoting reference parity, A770 semantic quality, attention score residency, selected attention, resident KV, full residency, performance, or completion",
        "classification": classification,
        "selected_count": selected_count,
        "compared_count": selected_count.saturating_sub(missing_context_count),
        "missing_context_count": missing_context_count,
        "pre_rope_bucket_crossing_count": pre_rope_bucket_crossing_count,
        "post_rope_bucket_crossing_count": post_rope_bucket_crossing_count,
        "score_input_bucket_crossing_count": score_input_bucket_crossing_count,
        "score_input_matches_post_rope_f16_count": score_input_matches_post_rope_f16_count,
        "clean_count": clean_count,
        "max_abs_stage_delta": max_abs_stage_delta,
        "source_frontier_classification": post_fix_frontier.pointer("/classification").cloned().unwrap_or(Value::Null),
        "rows": rows,
        "next_diagnostic": next_diagnostic,
    })
}

fn selected_key_slot_stage_probe(stage: &str, reference: Option<f64>, rust: Option<f64>) -> Value {
    let bucket = reference
        .zip(rust)
        .map(|(reference, rust)| f16_bucket_pair_probe(reference as f32, rust as f32))
        .unwrap_or(Value::Null);
    let f16_bucket_crossing =
        bucket.pointer("/f16_bucket_match").and_then(Value::as_bool) == Some(false);
    json!({
        "stage": stage,
        "values_present": reference.is_some() && rust.is_some(),
        "reference": reference,
        "rust": rust,
        "delta": reference.zip(rust).map(|(reference, rust)| rust - reference),
        "abs_delta": reference.zip(rust).map(|(reference, rust)| (rust - reference).abs()),
        "bucket": bucket,
        "f16_bucket_crossing": f16_bucket_crossing,
    })
}

fn selected_key_slot_probe_bucket_crossing(probe: &Value) -> bool {
    probe.pointer("/f16_bucket_crossing").and_then(Value::as_bool) == Some(true)
}

fn selected_key_score_matches_post_rope_f16(
    score_value: Option<f64>,
    post_rope_probe: &Value,
    bucket_pointer: &str,
) -> bool {
    score_value
        .zip(post_rope_probe.pointer(bucket_pointer).and_then(Value::as_f64))
        .is_some_and(|(score, bucket)| (score - bucket).abs() <= 1.0e-9)
}

fn attention_selected_post_rope_history_bucket_source(
    slot_probe: &Value,
    post_rope_raw_key_epsilon: &Value,
    historical_rope_source: &Value,
) -> Value {
    let slot_rows = slot_probe.pointer("/rows").and_then(Value::as_array);
    let epsilon_rows = post_rope_raw_key_epsilon.pointer("/rows").and_then(Value::as_array);
    let historical_rows = historical_rope_source.pointer("/rows").and_then(Value::as_array);
    let mut rows = Vec::<Value>::new();
    let mut selected_count = 0usize;
    let mut missing_context_count = 0usize;
    let mut pre_rope_bucket_crossing_count = 0usize;
    let mut capture_replay_mismatch_count = 0usize;
    let mut projection_subbucket_midpoint_count = 0usize;
    let mut projection_bucket_crossing_count = 0usize;
    let mut f16_midpoint_sensitive_count = 0usize;
    let mut clean_count = 0usize;
    let mut unpinned_count = 0usize;

    if let Some(slot_rows) = slot_rows {
        for slot_row in slot_rows {
            if slot_row.pointer("/classification").and_then(Value::as_str)
                != Some("selected_key_dim_token_slot_probe_post_rope_bucket_crossing")
            {
                continue;
            }
            selected_count += 1;
            let head = slot_row.pointer("/head").and_then(Value::as_u64);
            let key_slot = slot_row.pointer("/key_slot").and_then(Value::as_u64);
            let query_token = slot_row.pointer("/query_token").and_then(Value::as_u64);
            let epsilon_row = find_qk_recompute_row(epsilon_rows, head, key_slot, query_token);
            let historical_row =
                find_qk_recompute_row(historical_rows, head, key_slot, query_token);

            let slot_pre_rope_bucket_crossing = selected_key_slot_probe_bucket_crossing(
                slot_row.pointer("/pre_rope").unwrap_or(&Value::Null),
            );
            let slot_post_rope_bucket_crossing = selected_key_slot_probe_bucket_crossing(
                slot_row.pointer("/post_rope").unwrap_or(&Value::Null),
            );
            let score_input_matches_post_rope_f16 =
                slot_row.pointer("/score_input_matches_post_rope_f16").and_then(Value::as_bool)
                    == Some(true);
            let epsilon_classification =
                epsilon_row.and_then(|row| row.pointer("/classification").and_then(Value::as_str));
            let historical_classification = historical_row
                .and_then(|row| row.pointer("/classification").and_then(Value::as_str));
            let replay_matches_capture = epsilon_row
                .and_then(|row| row.pointer("/replay_matches_capture").and_then(Value::as_bool));
            let midpoint_straddled = epsilon_row
                .and_then(|row| row.pointer("/midpoint_straddled").and_then(Value::as_bool));
            let projection_bucket_match = epsilon_row
                .and_then(|row| row.pointer("/projection_bucket_match").and_then(Value::as_bool));
            let paired_projection_bucket_match = epsilon_row.and_then(|row| {
                row.pointer("/paired_projection_bucket_match").and_then(Value::as_bool)
            });
            let post_rope_bucket_match = epsilon_row
                .and_then(|row| row.pointer("/post_rope_bucket_match").and_then(Value::as_bool));

            let mut blocked_reasons = Vec::<String>::new();
            if epsilon_row.is_none() {
                blocked_reasons.push("selected_post_rope_raw_key_epsilon_row_missing".to_string());
            }
            if historical_row.is_none() {
                blocked_reasons
                    .push("selected_historical_projection_rope_source_row_missing".to_string());
            }
            if !slot_post_rope_bucket_crossing {
                blocked_reasons.push("selected_slot_post_rope_bucket_crossing_missing".to_string());
            }

            let projection_bucket_crossing = matches!(
                epsilon_classification,
                Some("selected_post_rope_raw_key_epsilon_projection_bucket_crossing")
            ) || matches!(
                historical_classification,
                Some("selected_key_historical_drift_before_rope_input")
            ) || projection_bucket_match == Some(false)
                || paired_projection_bucket_match == Some(false);
            let capture_replay_mismatch = matches!(
                epsilon_classification,
                Some("selected_post_rope_raw_key_epsilon_capture_replay_mismatch")
            ) || replay_matches_capture == Some(false);
            let projection_subbucket_midpoint = matches!(
                epsilon_classification,
                Some("selected_post_rope_raw_key_epsilon_projection_subbucket_midpoint_crossing")
            ) || midpoint_straddled == Some(true);
            let f16_midpoint_sensitive = matches!(
                historical_classification,
                Some(
                    "selected_key_historical_post_rope_f16_bucket_sensitivity"
                        | "selected_key_historical_post_rope_epsilon_reported"
                )
            ) && score_input_matches_post_rope_f16
                && post_rope_bucket_match == Some(false);

            let row_classification = if !blocked_reasons.is_empty() {
                missing_context_count += 1;
                "selected_post_rope_history_bucket_source_missing_context"
            } else if slot_pre_rope_bucket_crossing {
                pre_rope_bucket_crossing_count += 1;
                "selected_post_rope_history_bucket_source_pre_rope_bucket_crossing"
            } else if projection_bucket_crossing {
                projection_bucket_crossing_count += 1;
                "selected_post_rope_history_bucket_source_projection_bucket_crossing"
            } else if capture_replay_mismatch {
                capture_replay_mismatch_count += 1;
                "selected_post_rope_history_bucket_source_capture_replay_mismatch"
            } else if projection_subbucket_midpoint {
                projection_subbucket_midpoint_count += 1;
                "selected_post_rope_history_bucket_source_projection_subbucket_midpoint"
            } else if f16_midpoint_sensitive {
                f16_midpoint_sensitive_count += 1;
                "selected_post_rope_history_bucket_source_f16_midpoint_sensitive"
            } else if !slot_post_rope_bucket_crossing {
                clean_count += 1;
                "selected_post_rope_history_bucket_source_clean"
            } else {
                unpinned_count += 1;
                "selected_post_rope_history_bucket_source_unpinned"
            };

            rows.push(json!({
                "classification": row_classification,
                "head": head,
                "kv_head": slot_row.pointer("/kv_head").cloned().unwrap_or(Value::Null),
                "key_slot": key_slot,
                "query_token": query_token,
                "contributor_dim": slot_row.pointer("/contributor_dim").cloned().unwrap_or(Value::Null),
                "blocked_reasons": blocked_reasons,
                "slot_probe_classification": slot_row.pointer("/classification").cloned().unwrap_or(Value::Null),
                "post_rope_raw_key_epsilon_classification": epsilon_classification,
                "historical_projection_rope_classification": historical_classification,
                "slot_pre_rope_bucket_crossing": slot_pre_rope_bucket_crossing,
                "slot_post_rope_bucket_crossing": slot_post_rope_bucket_crossing,
                "score_input_matches_post_rope_f16": score_input_matches_post_rope_f16,
                "projection_bucket_crossing": projection_bucket_crossing,
                "capture_replay_mismatch": capture_replay_mismatch,
                "projection_subbucket_midpoint": projection_subbucket_midpoint,
                "f16_midpoint_sensitive": f16_midpoint_sensitive,
                "replay_matches_capture": replay_matches_capture,
                "midpoint_straddled": midpoint_straddled,
                "projection_bucket_match": projection_bucket_match,
                "paired_projection_bucket_match": paired_projection_bucket_match,
                "post_rope_bucket_match": post_rope_bucket_match,
                "slot_probe_row": slot_row.clone(),
                "post_rope_raw_key_epsilon_row": epsilon_row.cloned().unwrap_or(Value::Null),
                "historical_projection_rope_row": historical_row.cloned().unwrap_or(Value::Null),
            }));
        }
    }

    let classification = if selected_count == 0 {
        "selected_post_rope_history_bucket_source_no_selected_rows"
    } else if missing_context_count == selected_count {
        "selected_post_rope_history_bucket_source_missing_context"
    } else if pre_rope_bucket_crossing_count > 0 {
        "selected_post_rope_history_bucket_source_pre_rope_bucket_crossing"
    } else if projection_bucket_crossing_count > 0 {
        "selected_post_rope_history_bucket_source_projection_bucket_crossing"
    } else if capture_replay_mismatch_count > 0 {
        "selected_post_rope_history_bucket_source_capture_replay_mismatch"
    } else if projection_subbucket_midpoint_count > 0 {
        "selected_post_rope_history_bucket_source_projection_subbucket_midpoint"
    } else if f16_midpoint_sensitive_count > 0 {
        "selected_post_rope_history_bucket_source_f16_midpoint_sensitive"
    } else if clean_count == selected_count {
        "selected_post_rope_history_bucket_source_clean"
    } else {
        "selected_post_rope_history_bucket_source_unpinned"
    };
    let next_diagnostic = match classification {
        "selected_post_rope_history_bucket_source_capture_replay_mismatch" => {
            "pin selected post-RoPE trace capture versus runtime replay before changing ROPE or score-input math"
        }
        "selected_post_rope_history_bucket_source_projection_subbucket_midpoint" => {
            "localize selected pre-RoPE projection sub-bucket source before changing ROPE math"
        }
        "selected_post_rope_history_bucket_source_projection_bucket_crossing"
        | "selected_post_rope_history_bucket_source_pre_rope_bucket_crossing" => {
            "localize selected K projection input/output bucket crossing before changing ROPE math"
        }
        "selected_post_rope_history_bucket_source_f16_midpoint_sensitive" => {
            "decide whether selected post-RoPE F16 midpoint sensitivity is acceptable capture precision or requires runtime alignment"
        }
        "selected_post_rope_history_bucket_source_missing_context" => {
            "capture missing selected post-RoPE epsilon and historical projection source rows"
        }
        "selected_post_rope_history_bucket_source_clean" => {
            "move downstream from selected post-RoPE history bucket source"
        }
        "selected_post_rope_history_bucket_source_no_selected_rows" => {
            "refresh selected key dim/token slot probe before post-RoPE history source attribution"
        }
        _ => "keep selected post-RoPE history bucket source diagnostic-only",
    };

    json!({
        "diagnostic_only": true,
        "claim_allowed": false,
        "policy": "Selected post-RoPE history bucket source is diagnostic-only evidence for the remaining selected key dim/token bucket crossing; it connects the slot probe to existing post-RoPE epsilon and historical projection/RoPE rows without changing runtime math or promoting reference parity, A770 semantic quality, attention score residency, selected attention, resident KV, full residency, performance, or completion",
        "classification": classification,
        "selected_count": selected_count,
        "missing_context_count": missing_context_count,
        "pre_rope_bucket_crossing_count": pre_rope_bucket_crossing_count,
        "capture_replay_mismatch_count": capture_replay_mismatch_count,
        "projection_subbucket_midpoint_count": projection_subbucket_midpoint_count,
        "projection_bucket_crossing_count": projection_bucket_crossing_count,
        "f16_midpoint_sensitive_count": f16_midpoint_sensitive_count,
        "clean_count": clean_count,
        "unpinned_count": unpinned_count,
        "rows": rows,
        "next_diagnostic": next_diagnostic,
    })
}

fn attention_selected_post_rope_capture_replay_source(history_source: &Value) -> Value {
    let source_rows = history_source.pointer("/rows").and_then(Value::as_array);
    let mut rows = Vec::<Value>::new();
    let mut selected_count = 0usize;
    let mut missing_context_count = 0usize;
    let mut reference_only_count = 0usize;
    let mut rust_only_count = 0usize;
    let mut both_sides_count = 0usize;
    let mut runtime_replay_delta_count = 0usize;
    let mut clean_count = 0usize;
    let mut max_abs_reference_replay_minus_capture = 0.0f64;
    let mut max_abs_rust_replay_minus_capture = 0.0f64;

    if let Some(source_rows) = source_rows {
        for source_row in source_rows {
            if source_row.pointer("/classification").and_then(Value::as_str)
                != Some("selected_post_rope_history_bucket_source_capture_replay_mismatch")
            {
                continue;
            }
            selected_count += 1;
            let epsilon_row =
                source_row.pointer("/post_rope_raw_key_epsilon_row").unwrap_or(&Value::Null);
            let mut blocked_reasons = Vec::<String>::new();
            if epsilon_row.is_null() {
                blocked_reasons.push("selected_post_rope_raw_key_epsilon_row_missing".to_string());
            }

            let reference_replay_minus_capture =
                value_f64(epsilon_row, "/reference_replay_minus_capture");
            let rust_replay_minus_capture = value_f64(epsilon_row, "/rust_replay_minus_capture");
            let runtime_replay_delta = value_f64(epsilon_row, "/runtime_replay_delta");
            let capture_delta = value_f64(epsilon_row, "/capture_delta");
            let linearized_delta_minus_runtime_replay_delta =
                value_f64(epsilon_row, "/linearized_delta_minus_runtime_replay_delta");
            let post_rope_bucket_match = value_bool(epsilon_row, "/post_rope_bucket_match");
            let replay_bucket_match = value_bool(epsilon_row, "/replay_bucket_match");
            let reference_mismatch =
                reference_replay_minus_capture.is_some_and(|delta| delta.abs() > 1.0e-12);
            let rust_mismatch =
                rust_replay_minus_capture.is_some_and(|delta| delta.abs() > 1.0e-12);
            let runtime_replay_has_delta =
                runtime_replay_delta.is_some_and(|delta| delta.abs() > 1.0e-12);
            if reference_replay_minus_capture.is_none() {
                blocked_reasons.push("reference_replay_minus_capture_missing".to_string());
            }
            if rust_replay_minus_capture.is_none() {
                blocked_reasons.push("rust_replay_minus_capture_missing".to_string());
            }
            if runtime_replay_delta.is_none() {
                blocked_reasons.push("runtime_replay_delta_missing".to_string());
            }
            if let Some(delta) = reference_replay_minus_capture {
                max_abs_reference_replay_minus_capture =
                    max_abs_reference_replay_minus_capture.max(delta.abs());
            }
            if let Some(delta) = rust_replay_minus_capture {
                max_abs_rust_replay_minus_capture =
                    max_abs_rust_replay_minus_capture.max(delta.abs());
            }

            let row_classification = if !blocked_reasons.is_empty() {
                missing_context_count += 1;
                "selected_post_rope_capture_replay_source_missing_context"
            } else if reference_mismatch && rust_mismatch {
                both_sides_count += 1;
                "selected_post_rope_capture_replay_source_both_sides_mismatch"
            } else if reference_mismatch {
                reference_only_count += 1;
                "selected_post_rope_capture_replay_source_reference_capture_mismatch"
            } else if rust_mismatch {
                rust_only_count += 1;
                "selected_post_rope_capture_replay_source_rust_capture_mismatch"
            } else if runtime_replay_has_delta {
                runtime_replay_delta_count += 1;
                "selected_post_rope_capture_replay_source_runtime_replay_delta"
            } else {
                clean_count += 1;
                "selected_post_rope_capture_replay_source_clean"
            };

            rows.push(json!({
                "classification": row_classification,
                "head": source_row.pointer("/head").cloned().unwrap_or(Value::Null),
                "kv_head": source_row.pointer("/kv_head").cloned().unwrap_or(Value::Null),
                "key_slot": source_row.pointer("/key_slot").cloned().unwrap_or(Value::Null),
                "query_token": source_row.pointer("/query_token").cloned().unwrap_or(Value::Null),
                "contributor_dim": source_row.pointer("/contributor_dim").cloned().unwrap_or(Value::Null),
                "blocked_reasons": blocked_reasons,
                "reference_replay_minus_capture": reference_replay_minus_capture,
                "rust_replay_minus_capture": rust_replay_minus_capture,
                "runtime_replay_delta": runtime_replay_delta,
                "capture_delta": capture_delta,
                "linearized_delta_minus_runtime_replay_delta": linearized_delta_minus_runtime_replay_delta,
                "reference_capture_mismatch": reference_mismatch,
                "rust_capture_mismatch": rust_mismatch,
                "runtime_replay_has_delta": runtime_replay_has_delta,
                "post_rope_bucket_match": post_rope_bucket_match,
                "replay_bucket_match": replay_bucket_match,
                "post_rope_bucket": epsilon_row.pointer("/post_rope_bucket").cloned().unwrap_or(Value::Null),
                "replay_bucket": epsilon_row.pointer("/replay_bucket").cloned().unwrap_or(Value::Null),
                "history_source_row": source_row.clone(),
            }));
        }
    }

    let classification = if selected_count == 0 {
        "selected_post_rope_capture_replay_source_no_selected_rows"
    } else if missing_context_count == selected_count {
        "selected_post_rope_capture_replay_source_missing_context"
    } else if both_sides_count > 0 {
        "selected_post_rope_capture_replay_source_both_sides_mismatch"
    } else if reference_only_count > 0 {
        "selected_post_rope_capture_replay_source_reference_capture_mismatch"
    } else if rust_only_count > 0 {
        "selected_post_rope_capture_replay_source_rust_capture_mismatch"
    } else if runtime_replay_delta_count > 0 {
        "selected_post_rope_capture_replay_source_runtime_replay_delta"
    } else if clean_count == selected_count {
        "selected_post_rope_capture_replay_source_clean"
    } else {
        "selected_post_rope_capture_replay_source_unpinned"
    };
    let next_diagnostic = match classification {
        "selected_post_rope_capture_replay_source_reference_capture_mismatch" => {
            "pin reference post-RoPE trace capture or serialization precision before changing Rust runtime math"
        }
        "selected_post_rope_capture_replay_source_rust_capture_mismatch" => {
            "pin Rust post-RoPE trace capture versus runtime replay before changing runtime math"
        }
        "selected_post_rope_capture_replay_source_both_sides_mismatch" => {
            "pin shared post-RoPE replay arithmetic or trace capture policy before changing runtime math"
        }
        "selected_post_rope_capture_replay_source_runtime_replay_delta" => {
            "pin selected post-RoPE runtime replay delta before changing score-input math"
        }
        "selected_post_rope_capture_replay_source_missing_context" => {
            "capture selected replay-minus-capture values before interpreting post-RoPE history source"
        }
        "selected_post_rope_capture_replay_source_clean" => {
            "move downstream from selected post-RoPE capture/replay source"
        }
        "selected_post_rope_capture_replay_source_no_selected_rows" => {
            "classify selected post-RoPE history bucket source before capture/replay attribution"
        }
        _ => "keep selected post-RoPE capture/replay source diagnostic-only",
    };

    json!({
        "diagnostic_only": true,
        "claim_allowed": false,
        "policy": "Selected post-RoPE capture/replay source is diagnostic-only evidence for whether the selected post-RoPE bucket crossing is introduced by reference capture, Rust capture, shared replay arithmetic, or missing trace context; it does not change runtime math or promote reference parity, A770 semantic quality, attention score residency, selected attention, resident KV, full residency, performance, or completion",
        "classification": classification,
        "selected_count": selected_count,
        "missing_context_count": missing_context_count,
        "reference_only_count": reference_only_count,
        "rust_only_count": rust_only_count,
        "both_sides_count": both_sides_count,
        "runtime_replay_delta_count": runtime_replay_delta_count,
        "clean_count": clean_count,
        "max_abs_reference_replay_minus_capture": max_abs_reference_replay_minus_capture,
        "max_abs_rust_replay_minus_capture": max_abs_rust_replay_minus_capture,
        "rows": rows,
        "next_diagnostic": next_diagnostic,
    })
}

fn attention_selected_rust_post_rope_capture_source(capture_replay_source: &Value) -> Value {
    let source_rows = capture_replay_source.pointer("/rows").and_then(Value::as_array);
    let mut rows = Vec::<Value>::new();
    let mut selected_count = 0usize;
    let mut missing_context_count = 0usize;
    let mut trace_bucket_crossing_count = 0usize;
    let mut trace_subbucket_drift_count = 0usize;
    let mut runtime_replay_unclean_count = 0usize;
    let mut clean_count = 0usize;
    let mut max_abs_rust_replay_minus_capture = 0.0f64;

    if let Some(source_rows) = source_rows {
        for source_row in source_rows {
            if source_row.pointer("/classification").and_then(Value::as_str)
                != Some("selected_post_rope_capture_replay_source_rust_capture_mismatch")
            {
                continue;
            }
            selected_count += 1;
            let mut blocked_reasons = Vec::<String>::new();
            let reference_mismatch = value_bool(source_row, "/reference_capture_mismatch");
            let rust_mismatch = value_bool(source_row, "/rust_capture_mismatch");
            let runtime_replay_has_delta = value_bool(source_row, "/runtime_replay_has_delta");
            let post_rope_bucket_match = value_bool(source_row, "/post_rope_bucket_match");
            let replay_bucket_match = value_bool(source_row, "/replay_bucket_match");
            let rust_replay_minus_capture = value_f64(source_row, "/rust_replay_minus_capture");
            if reference_mismatch.is_none() {
                blocked_reasons.push("reference_capture_mismatch_missing".to_string());
            }
            if rust_mismatch.is_none() {
                blocked_reasons.push("rust_capture_mismatch_missing".to_string());
            }
            if runtime_replay_has_delta.is_none() {
                blocked_reasons.push("runtime_replay_has_delta_missing".to_string());
            }
            if post_rope_bucket_match.is_none() {
                blocked_reasons.push("post_rope_bucket_match_missing".to_string());
            }
            if replay_bucket_match.is_none() {
                blocked_reasons.push("replay_bucket_match_missing".to_string());
            }
            if rust_replay_minus_capture.is_none() {
                blocked_reasons.push("rust_replay_minus_capture_missing".to_string());
            }
            if let Some(delta) = rust_replay_minus_capture {
                max_abs_rust_replay_minus_capture =
                    max_abs_rust_replay_minus_capture.max(delta.abs());
            }

            let row_classification = if !blocked_reasons.is_empty() {
                missing_context_count += 1;
                "selected_rust_post_rope_capture_source_missing_context"
            } else if runtime_replay_has_delta == Some(true) || replay_bucket_match == Some(false) {
                runtime_replay_unclean_count += 1;
                "selected_rust_post_rope_capture_source_runtime_replay_unclean"
            } else if reference_mismatch == Some(false)
                && rust_mismatch == Some(true)
                && replay_bucket_match == Some(true)
                && post_rope_bucket_match == Some(false)
            {
                trace_bucket_crossing_count += 1;
                "selected_rust_post_rope_capture_source_trace_bucket_crossing"
            } else if reference_mismatch == Some(false) && rust_mismatch == Some(true) {
                trace_subbucket_drift_count += 1;
                "selected_rust_post_rope_capture_source_trace_subbucket_drift"
            } else {
                clean_count += 1;
                "selected_rust_post_rope_capture_source_clean"
            };

            rows.push(json!({
                "classification": row_classification,
                "head": source_row.pointer("/head").cloned().unwrap_or(Value::Null),
                "kv_head": source_row.pointer("/kv_head").cloned().unwrap_or(Value::Null),
                "key_slot": source_row.pointer("/key_slot").cloned().unwrap_or(Value::Null),
                "query_token": source_row.pointer("/query_token").cloned().unwrap_or(Value::Null),
                "contributor_dim": source_row.pointer("/contributor_dim").cloned().unwrap_or(Value::Null),
                "blocked_reasons": blocked_reasons,
                "reference_capture_mismatch": reference_mismatch,
                "rust_capture_mismatch": rust_mismatch,
                "runtime_replay_has_delta": runtime_replay_has_delta,
                "rust_replay_minus_capture": rust_replay_minus_capture,
                "post_rope_bucket_match": post_rope_bucket_match,
                "replay_bucket_match": replay_bucket_match,
                "post_rope_left_f16_bits": source_row.pointer("/post_rope_bucket/left_f16_bits").cloned().unwrap_or(Value::Null),
                "post_rope_right_f16_bits": source_row.pointer("/post_rope_bucket/right_f16_bits").cloned().unwrap_or(Value::Null),
                "replay_left_f16_bits": source_row.pointer("/replay_bucket/left_f16_bits").cloned().unwrap_or(Value::Null),
                "replay_right_f16_bits": source_row.pointer("/replay_bucket/right_f16_bits").cloned().unwrap_or(Value::Null),
                "post_rope_bucket": source_row.pointer("/post_rope_bucket").cloned().unwrap_or(Value::Null),
                "replay_bucket": source_row.pointer("/replay_bucket").cloned().unwrap_or(Value::Null),
                "capture_replay_source_row": source_row.clone(),
            }));
        }
    }

    let classification = if selected_count == 0 {
        "selected_rust_post_rope_capture_source_no_rust_capture_rows"
    } else if missing_context_count == selected_count {
        "selected_rust_post_rope_capture_source_missing_context"
    } else if runtime_replay_unclean_count > 0 {
        "selected_rust_post_rope_capture_source_runtime_replay_unclean"
    } else if trace_bucket_crossing_count > 0 {
        "selected_rust_post_rope_capture_source_trace_bucket_crossing"
    } else if trace_subbucket_drift_count > 0 {
        "selected_rust_post_rope_capture_source_trace_subbucket_drift"
    } else if clean_count == selected_count {
        "selected_rust_post_rope_capture_source_clean"
    } else {
        "selected_rust_post_rope_capture_source_unpinned"
    };
    let next_diagnostic = match classification {
        "selected_rust_post_rope_capture_source_trace_bucket_crossing" => {
            "pin Rust post-RoPE trace capture write precision for the selected history record before changing runtime math"
        }
        "selected_rust_post_rope_capture_source_trace_subbucket_drift" => {
            "decide whether Rust post-RoPE trace subbucket capture drift is material before changing runtime math"
        }
        "selected_rust_post_rope_capture_source_runtime_replay_unclean" => {
            "pin selected post-RoPE runtime replay before interpreting Rust trace capture"
        }
        "selected_rust_post_rope_capture_source_missing_context" => {
            "capture selected Rust post-RoPE bucket and replay context before source attribution"
        }
        "selected_rust_post_rope_capture_source_clean" => {
            "move downstream from selected Rust post-RoPE capture source"
        }
        "selected_rust_post_rope_capture_source_no_rust_capture_rows" => {
            "classify selected post-RoPE capture/replay source before Rust capture attribution"
        }
        _ => "keep selected Rust post-RoPE capture source diagnostic-only",
    };

    json!({
        "diagnostic_only": true,
        "claim_allowed": false,
        "policy": "Selected Rust post-RoPE capture source is diagnostic-only evidence for whether the selected score-key bucket crossing is introduced by Rust trace capture rather than runtime replay; it does not change runtime math or promote reference parity, A770 semantic quality, attention score residency, selected attention, resident KV, full residency, performance, or completion",
        "classification": classification,
        "selected_count": selected_count,
        "missing_context_count": missing_context_count,
        "trace_bucket_crossing_count": trace_bucket_crossing_count,
        "trace_subbucket_drift_count": trace_subbucket_drift_count,
        "runtime_replay_unclean_count": runtime_replay_unclean_count,
        "clean_count": clean_count,
        "max_abs_rust_replay_minus_capture": max_abs_rust_replay_minus_capture,
        "rows": rows,
        "next_diagnostic": next_diagnostic,
    })
}

fn attention_selected_post_rope_runtime_replay_source(rust_capture_source: &Value) -> Value {
    let source_rows = rust_capture_source.pointer("/rows").and_then(Value::as_array);
    let mut rows = Vec::<Value>::new();
    let mut selected_count = 0usize;
    let mut missing_context_count = 0usize;
    let mut projection_pair_delta_count = 0usize;
    let mut arithmetic_unpinned_count = 0usize;
    let mut capture_only_count = 0usize;
    let mut clean_count = 0usize;
    let mut max_abs_runtime_replay_delta = 0.0f64;
    let mut max_abs_linearized_minus_replay = 0.0f64;

    if let Some(source_rows) = source_rows {
        for source_row in source_rows {
            if source_row.pointer("/classification").and_then(Value::as_str)
                != Some("selected_rust_post_rope_capture_source_runtime_replay_unclean")
            {
                continue;
            }
            selected_count += 1;
            let capture_replay_row =
                source_row.pointer("/capture_replay_source_row").unwrap_or(&Value::Null);
            let direct_epsilon_row = capture_replay_row
                .pointer("/post_rope_raw_key_epsilon_row")
                .unwrap_or(&Value::Null);
            let nested_epsilon_row = capture_replay_row
                .pointer("/history_source_row/post_rope_raw_key_epsilon_row")
                .unwrap_or(&Value::Null);
            let epsilon_row =
                if direct_epsilon_row.is_null() { nested_epsilon_row } else { direct_epsilon_row };
            let mut blocked_reasons = Vec::<String>::new();
            if capture_replay_row.is_null() {
                blocked_reasons.push("capture_replay_source_row_missing".to_string());
            }
            if epsilon_row.is_null() {
                blocked_reasons.push("post_rope_raw_key_epsilon_row_missing".to_string());
            }

            let runtime_replay_delta = value_f64(epsilon_row, "/runtime_replay_delta");
            let linearized_delta_minus_runtime_replay_delta =
                value_f64(epsilon_row, "/linearized_delta_minus_runtime_replay_delta");
            let linearized_delta_for_probe_dim =
                value_f64(epsilon_row, "/linearized_delta_for_probe_dim");
            let projection_bucket_match = value_bool(epsilon_row, "/projection_bucket_match");
            let paired_projection_bucket_match =
                value_bool(epsilon_row, "/paired_projection_bucket_match");
            let replay_bucket_match = value_bool(epsilon_row, "/replay_bucket_match");
            let post_rope_bucket_match = value_bool(epsilon_row, "/post_rope_bucket_match");
            let midpoint_straddled = value_bool(epsilon_row, "/midpoint_straddled");
            if runtime_replay_delta.is_none() {
                blocked_reasons.push("runtime_replay_delta_missing".to_string());
            }
            if linearized_delta_minus_runtime_replay_delta.is_none() {
                blocked_reasons
                    .push("linearized_delta_minus_runtime_replay_delta_missing".to_string());
            }
            if linearized_delta_for_probe_dim.is_none() {
                blocked_reasons.push("linearized_delta_for_probe_dim_missing".to_string());
            }
            if projection_bucket_match.is_none() {
                blocked_reasons.push("projection_bucket_match_missing".to_string());
            }
            if paired_projection_bucket_match.is_none() {
                blocked_reasons.push("paired_projection_bucket_match_missing".to_string());
            }
            if replay_bucket_match.is_none() {
                blocked_reasons.push("replay_bucket_match_missing".to_string());
            }
            if post_rope_bucket_match.is_none() {
                blocked_reasons.push("post_rope_bucket_match_missing".to_string());
            }
            if midpoint_straddled.is_none() {
                blocked_reasons.push("midpoint_straddled_missing".to_string());
            }
            if let Some(delta) = runtime_replay_delta {
                max_abs_runtime_replay_delta = max_abs_runtime_replay_delta.max(delta.abs());
            }
            if let Some(delta) = linearized_delta_minus_runtime_replay_delta {
                max_abs_linearized_minus_replay = max_abs_linearized_minus_replay.max(delta.abs());
            }

            let linearized_matches_replay = linearized_delta_minus_runtime_replay_delta
                .is_some_and(|delta| delta.abs() <= 1.0e-6);
            let projection_buckets_stable = projection_bucket_match == Some(true)
                && paired_projection_bucket_match == Some(true);
            let replay_bucket_crossing = replay_bucket_match == Some(false);
            let post_rope_bucket_crossing = post_rope_bucket_match == Some(false);
            let replay_has_delta = runtime_replay_delta.is_some_and(|delta| delta.abs() > 1.0e-12);

            let row_classification = if !blocked_reasons.is_empty() {
                missing_context_count += 1;
                "selected_post_rope_runtime_replay_source_missing_context"
            } else if replay_has_delta
                && projection_buckets_stable
                && linearized_matches_replay
                && replay_bucket_crossing
                && midpoint_straddled == Some(true)
            {
                projection_pair_delta_count += 1;
                "selected_post_rope_runtime_replay_source_projection_pair_delta_bucket_crossing"
            } else if replay_has_delta && !linearized_matches_replay {
                arithmetic_unpinned_count += 1;
                "selected_post_rope_runtime_replay_source_arithmetic_unpinned"
            } else if !replay_has_delta && post_rope_bucket_crossing {
                capture_only_count += 1;
                "selected_post_rope_runtime_replay_source_capture_only"
            } else {
                clean_count += 1;
                "selected_post_rope_runtime_replay_source_clean"
            };

            rows.push(json!({
                "classification": row_classification,
                "head": source_row.pointer("/head").cloned().unwrap_or(Value::Null),
                "kv_head": source_row.pointer("/kv_head").cloned().unwrap_or(Value::Null),
                "key_slot": source_row.pointer("/key_slot").cloned().unwrap_or(Value::Null),
                "query_token": source_row.pointer("/query_token").cloned().unwrap_or(Value::Null),
                "contributor_dim": source_row.pointer("/contributor_dim").cloned().unwrap_or(Value::Null),
                "blocked_reasons": blocked_reasons,
                "runtime_replay_delta": runtime_replay_delta,
                "linearized_delta_for_probe_dim": linearized_delta_for_probe_dim,
                "linearized_delta_minus_runtime_replay_delta": linearized_delta_minus_runtime_replay_delta,
                "linearized_matches_replay": linearized_matches_replay,
                "projection_buckets_stable": projection_buckets_stable,
                "projection_bucket_match": projection_bucket_match,
                "paired_projection_bucket_match": paired_projection_bucket_match,
                "post_rope_bucket_match": post_rope_bucket_match,
                "replay_bucket_match": replay_bucket_match,
                "replay_bucket_crossing": replay_bucket_crossing,
                "post_rope_bucket_crossing": post_rope_bucket_crossing,
                "midpoint_straddled": midpoint_straddled,
                "input_pair": epsilon_row.pointer("/input_pair").cloned().unwrap_or(Value::Null),
                "post_rope_bucket": epsilon_row.pointer("/post_rope_bucket").cloned().unwrap_or(Value::Null),
                "replay_bucket": epsilon_row.pointer("/replay_bucket").cloned().unwrap_or(Value::Null),
                "rust_capture_source_row": source_row.clone(),
            }));
        }
    }

    let classification = if selected_count == 0 {
        "selected_post_rope_runtime_replay_source_no_runtime_rows"
    } else if missing_context_count == selected_count {
        "selected_post_rope_runtime_replay_source_missing_context"
    } else if projection_pair_delta_count > 0 {
        "selected_post_rope_runtime_replay_source_projection_pair_delta_bucket_crossing"
    } else if arithmetic_unpinned_count > 0 {
        "selected_post_rope_runtime_replay_source_arithmetic_unpinned"
    } else if capture_only_count > 0 {
        "selected_post_rope_runtime_replay_source_capture_only"
    } else if clean_count == selected_count {
        "selected_post_rope_runtime_replay_source_clean"
    } else {
        "selected_post_rope_runtime_replay_source_unpinned"
    };
    let next_diagnostic = match classification {
        "selected_post_rope_runtime_replay_source_projection_pair_delta_bucket_crossing" => {
            "move upstream to the selected pre-RoPE projection pair delta before changing post-RoPE runtime math"
        }
        "selected_post_rope_runtime_replay_source_arithmetic_unpinned" => {
            "pin selected post-RoPE replay arithmetic before changing runtime math"
        }
        "selected_post_rope_runtime_replay_source_capture_only" => {
            "return to Rust trace capture precision because runtime replay is clean"
        }
        "selected_post_rope_runtime_replay_source_missing_context" => {
            "capture selected runtime replay and linearized delta context before source attribution"
        }
        "selected_post_rope_runtime_replay_source_clean" => {
            "move downstream from selected post-RoPE runtime replay source"
        }
        "selected_post_rope_runtime_replay_source_no_runtime_rows" => {
            "classify selected Rust post-RoPE capture source before runtime replay attribution"
        }
        _ => "keep selected post-RoPE runtime replay source diagnostic-only",
    };

    json!({
        "diagnostic_only": true,
        "claim_allowed": false,
        "policy": "Selected post-RoPE runtime replay source is diagnostic-only evidence for whether the selected replay delta is explained by pre-RoPE projection pair epsilon and ROPE linearization; it does not change runtime math or promote reference parity, A770 semantic quality, attention score residency, selected attention, resident KV, full residency, performance, or completion",
        "classification": classification,
        "selected_count": selected_count,
        "missing_context_count": missing_context_count,
        "projection_pair_delta_count": projection_pair_delta_count,
        "arithmetic_unpinned_count": arithmetic_unpinned_count,
        "capture_only_count": capture_only_count,
        "clean_count": clean_count,
        "max_abs_runtime_replay_delta": max_abs_runtime_replay_delta,
        "max_abs_linearized_minus_replay": max_abs_linearized_minus_replay,
        "rows": rows,
        "next_diagnostic": next_diagnostic,
    })
}

fn attention_selected_pre_rope_projection_pair_source(runtime_replay_source: &Value) -> Value {
    let source_rows = runtime_replay_source.pointer("/rows").and_then(Value::as_array);
    let mut rows = Vec::<Value>::new();
    let mut selected_count = 0usize;
    let mut missing_input_pair_count = 0usize;
    let mut projection_bucket_crossing_count = 0usize;
    let mut raw_projection_pair_count = 0usize;
    let mut dominant_x0_count = 0usize;
    let mut dominant_x1_count = 0usize;
    let mut unpinned_count = 0usize;
    let mut max_abs_linearized_contribution = 0.0f64;
    let mut max_abs_projection_delta = 0.0f64;

    if let Some(source_rows) = source_rows {
        for source_row in source_rows {
            if source_row.pointer("/classification").and_then(Value::as_str)
                != Some(
                    "selected_post_rope_runtime_replay_source_projection_pair_delta_bucket_crossing",
                )
            {
                continue;
            }
            selected_count += 1;

            let input_pair = source_row.pointer("/input_pair").unwrap_or(&Value::Null);
            let delta_x0 = value_f64(input_pair, "/delta_x0");
            let delta_x1 = value_f64(input_pair, "/delta_x1");
            let x0_coefficient = value_f64(input_pair, "/x0_coefficient_for_probe_dim");
            let x1_coefficient = value_f64(input_pair, "/x1_coefficient_for_probe_dim");
            let x0_dim = input_pair.pointer("/x0_dim").and_then(Value::as_u64);
            let x1_dim = input_pair.pointer("/x1_dim").and_then(Value::as_u64);
            let projection_buckets_stable = value_bool(source_row, "/projection_buckets_stable");
            let projection_bucket_match = value_bool(source_row, "/projection_bucket_match");
            let paired_projection_bucket_match =
                value_bool(source_row, "/paired_projection_bucket_match");
            let linearized_matches_replay = value_bool(source_row, "/linearized_matches_replay");
            let replay_bucket_crossing = value_bool(source_row, "/replay_bucket_crossing");
            let midpoint_straddled = value_bool(source_row, "/midpoint_straddled");
            let runtime_replay_delta = value_f64(source_row, "/runtime_replay_delta");
            let linearized_delta = value_f64(source_row, "/linearized_delta_for_probe_dim");
            let linearized_delta_minus_runtime_replay_delta =
                value_f64(source_row, "/linearized_delta_minus_runtime_replay_delta");

            let mut blocked_reasons = Vec::<String>::new();
            if input_pair.is_null() {
                blocked_reasons.push("projection_input_pair_missing".to_string());
            }
            if delta_x0.is_none() || delta_x1.is_none() {
                blocked_reasons.push("projection_input_pair_delta_missing".to_string());
            }
            if x0_coefficient.is_none() || x1_coefficient.is_none() {
                blocked_reasons.push("rope_projection_pair_coefficient_missing".to_string());
            }
            if x0_dim.is_none() || x1_dim.is_none() {
                blocked_reasons.push("projection_input_pair_dim_missing".to_string());
            }
            if projection_buckets_stable.is_none() {
                blocked_reasons.push("projection_buckets_stable_missing".to_string());
            }
            if linearized_matches_replay.is_none() {
                blocked_reasons.push("linearized_matches_replay_missing".to_string());
            }
            if replay_bucket_crossing.is_none() {
                blocked_reasons.push("replay_bucket_crossing_missing".to_string());
            }
            if midpoint_straddled.is_none() {
                blocked_reasons.push("midpoint_straddled_missing".to_string());
            }

            let x0_linearized_contribution =
                delta_x0.zip(x0_coefficient).map(|(delta, coefficient)| delta * coefficient);
            let x1_linearized_contribution =
                delta_x1.zip(x1_coefficient).map(|(delta, coefficient)| delta * coefficient);
            let linearized_sum =
                x0_linearized_contribution.zip(x1_linearized_contribution).map(|(x0, x1)| x0 + x1);
            let linearized_sum_matches_report = linearized_sum
                .zip(linearized_delta)
                .is_some_and(|(sum, delta)| (sum - delta).abs() <= 1.0e-12);
            let dominant_projection_input =
                match (x0_linearized_contribution, x1_linearized_contribution) {
                    (Some(x0), Some(x1)) if x0.abs() >= x1.abs() => Some(("x0", x0_dim, x0)),
                    (Some(_), Some(x1)) => Some(("x1", x1_dim, x1)),
                    _ => None,
                };
            let dominant_input_label = dominant_projection_input.map(|(label, _, _)| label);
            let dominant_input_dim = dominant_projection_input.and_then(|(_, dim, _)| dim);
            let dominant_linearized_contribution =
                dominant_projection_input.map(|(_, _, contribution)| contribution);
            if let Some(contribution) = dominant_linearized_contribution {
                max_abs_linearized_contribution =
                    max_abs_linearized_contribution.max(contribution.abs());
            }
            if let Some(delta) = delta_x0 {
                max_abs_projection_delta = max_abs_projection_delta.max(delta.abs());
            }
            if let Some(delta) = delta_x1 {
                max_abs_projection_delta = max_abs_projection_delta.max(delta.abs());
            }

            let row_classification = if !blocked_reasons.is_empty() {
                missing_input_pair_count += 1;
                "selected_pre_rope_projection_pair_source_missing_input_pair"
            } else if projection_buckets_stable == Some(false)
                || projection_bucket_match == Some(false)
                || paired_projection_bucket_match == Some(false)
            {
                projection_bucket_crossing_count += 1;
                "selected_pre_rope_projection_pair_source_projection_bucket_crossing"
            } else if projection_buckets_stable == Some(true)
                && linearized_matches_replay == Some(true)
                && replay_bucket_crossing == Some(true)
                && midpoint_straddled == Some(true)
                && linearized_sum_matches_report
            {
                raw_projection_pair_count += 1;
                if dominant_input_label == Some("x0") {
                    dominant_x0_count += 1;
                } else if dominant_input_label == Some("x1") {
                    dominant_x1_count += 1;
                }
                "selected_pre_rope_projection_pair_source_raw_projection_pair_delta"
            } else {
                unpinned_count += 1;
                "selected_pre_rope_projection_pair_source_unpinned"
            };

            rows.push(json!({
                "classification": row_classification,
                "head": source_row.pointer("/head").cloned().unwrap_or(Value::Null),
                "kv_head": source_row.pointer("/kv_head").cloned().unwrap_or(Value::Null),
                "key_slot": source_row.pointer("/key_slot").cloned().unwrap_or(Value::Null),
                "query_token": source_row.pointer("/query_token").cloned().unwrap_or(Value::Null),
                "contributor_dim": source_row.pointer("/contributor_dim").cloned().unwrap_or(Value::Null),
                "blocked_reasons": blocked_reasons,
                "probe_dim": source_row.pointer("/contributor_dim").cloned().unwrap_or(Value::Null),
                "x0_dim": x0_dim,
                "x1_dim": x1_dim,
                "delta_x0": delta_x0,
                "delta_x1": delta_x1,
                "x0_coefficient_for_probe_dim": x0_coefficient,
                "x1_coefficient_for_probe_dim": x1_coefficient,
                "x0_linearized_contribution": x0_linearized_contribution,
                "x1_linearized_contribution": x1_linearized_contribution,
                "dominant_projection_input": dominant_input_label,
                "dominant_projection_input_dim": dominant_input_dim,
                "dominant_linearized_contribution": dominant_linearized_contribution,
                "linearized_sum_from_projection_pair": linearized_sum,
                "linearized_sum_matches_report": linearized_sum_matches_report,
                "linearized_delta_for_probe_dim": linearized_delta,
                "linearized_delta_minus_runtime_replay_delta": linearized_delta_minus_runtime_replay_delta,
                "runtime_replay_delta": runtime_replay_delta,
                "projection_buckets_stable": projection_buckets_stable,
                "projection_bucket_match": projection_bucket_match,
                "paired_projection_bucket_match": paired_projection_bucket_match,
                "linearized_matches_replay": linearized_matches_replay,
                "replay_bucket_crossing": replay_bucket_crossing,
                "midpoint_straddled": midpoint_straddled,
                "projection_bucket": source_row.pointer("/projection_bucket").cloned().unwrap_or(Value::Null),
                "paired_projection_bucket": source_row.pointer("/paired_projection_bucket").cloned().unwrap_or(Value::Null),
                "post_rope_runtime_replay_source_row": source_row.clone(),
            }));
        }
    }

    let classification = if selected_count == 0 {
        "selected_pre_rope_projection_pair_source_no_runtime_projection_pair_rows"
    } else if missing_input_pair_count == selected_count {
        "selected_pre_rope_projection_pair_source_missing_input_pair"
    } else if projection_bucket_crossing_count > 0 {
        "selected_pre_rope_projection_pair_source_projection_bucket_crossing"
    } else if raw_projection_pair_count > 0 && unpinned_count == 0 {
        "selected_pre_rope_projection_pair_source_raw_projection_pair_delta"
    } else {
        "selected_pre_rope_projection_pair_source_unpinned"
    };
    let next_diagnostic = match classification {
        "selected_pre_rope_projection_pair_source_raw_projection_pair_delta" => {
            "localize selected pre-RoPE projection input history at the dominant dim before changing QK256, ROPE, or score-input runtime math"
        }
        "selected_pre_rope_projection_pair_source_projection_bucket_crossing" => {
            "localize selected pre-RoPE projection F16 bucket crossing before changing ROPE runtime math"
        }
        "selected_pre_rope_projection_pair_source_missing_input_pair" => {
            "capture selected pre-RoPE projection input-pair context before changing runtime math"
        }
        "selected_pre_rope_projection_pair_source_no_runtime_projection_pair_rows" => {
            "classify selected post-RoPE runtime replay source before pre-RoPE projection-pair attribution"
        }
        _ => "keep selected pre-RoPE projection-pair source diagnostic-only",
    };

    json!({
        "diagnostic_only": true,
        "claim_allowed": false,
        "policy": "Selected pre-RoPE projection-pair source is diagnostic-only evidence for whether stable pre-RoPE projection pair epsilons explain the selected post-RoPE replay bucket crossing; it does not change QK256, ROPE, score-input, or runtime math and does not promote reference parity, A770 semantic quality, attention score residency, selected attention, resident KV, full residency, performance, or completion",
        "classification": classification,
        "selected_count": selected_count,
        "missing_input_pair_count": missing_input_pair_count,
        "projection_bucket_crossing_count": projection_bucket_crossing_count,
        "raw_projection_pair_count": raw_projection_pair_count,
        "dominant_x0_count": dominant_x0_count,
        "dominant_x1_count": dominant_x1_count,
        "unpinned_count": unpinned_count,
        "max_abs_linearized_contribution": max_abs_linearized_contribution,
        "max_abs_projection_delta": max_abs_projection_delta,
        "rows": rows,
        "next_diagnostic": next_diagnostic,
    })
}

fn attention_selected_pre_rope_projection_history_source(
    projection_pair_source: &Value,
    reference_records: &[ReferenceTraceRecord],
    rust_records: &BTreeMap<String, RustTraceRecord>,
    model_path: Option<&Path>,
) -> Value {
    let source_rows = projection_pair_source.pointer("/rows").and_then(Value::as_array);
    let reference_input = reference_records.iter().find(|record| {
        record.stage == "attn_norm_history_ref_layout"
            && record.values_available
            && !record.first_values.is_empty()
    });
    let rust_input = rust_records
        .get("attention_v_input_history_ref_layout")
        .filter(|record| !record.first_values.is_empty());
    let reference_projection_heads = reference_records
        .iter()
        .filter_map(|record| {
            parse_stage_head(&record.stage, "k_projection_history_kv_head")
                .map(|head| (head, record))
        })
        .filter(|(_, record)| record.values_available && !record.first_values.is_empty())
        .collect::<BTreeMap<_, _>>();
    let rust_projection_heads = rust_records
        .iter()
        .filter_map(|(stage, record)| {
            parse_stage_head(stage, "attention_k_projection_kv_head").map(|head| (head, record))
        })
        .filter(|(_, record)| !record.first_values.is_empty())
        .collect::<BTreeMap<_, _>>();

    let mut rows = Vec::<Value>::new();
    let mut selected_count = 0usize;
    let mut compared_count = 0usize;
    let mut missing_context_count = 0usize;
    let mut reference_replay_mismatch_count = 0usize;
    let mut rust_replay_mismatch_count = 0usize;
    let mut replay_delta_unpinned_count = 0usize;
    let mut history_delta_explained_count = 0usize;
    let mut max_abs_projection_pair_delta = 0.0f64;
    let mut max_abs_target_delta = 0.0f64;
    let mut max_abs_replay_delta = 0.0f64;
    let mut model_report = json!({
        "path": model_path.map(|path| json!(path_to_string(path))).unwrap_or(Value::Null),
        "exists": model_path.is_some_and(|path| path.is_file()),
    });
    let mut weight_report = json!({
        "name": DEFAULT_KEY_PROJECTION_WEIGHT,
    });
    let mut weight_load_error = Value::Null;

    let projection = match model_path {
        Some(path) if path.is_file() => {
            match reference_input.map(dim_major_dim_count).transpose().and_then(|input_dim| {
                load_qk256_same_input_projection(
                    path,
                    DEFAULT_KEY_PROJECTION_WEIGHT,
                    input_dim.unwrap_or(0),
                    None,
                )
            }) {
                Ok(projection) => {
                    model_report = projection.model_report.clone();
                    weight_report = projection.weight_report.clone();
                    Some(projection)
                }
                Err(err) => {
                    weight_load_error = json!(err.to_string());
                    None
                }
            }
        }
        _ => None,
    };

    let (reference_replay, reference_replay_error) = match (reference_input, projection.as_ref()) {
        (Some(input), Some(projection)) => match dim_major_dim_count(input).and_then(|input_dim| {
            let token_count = dim_major_token_count(input)?;
            replay_qk256_dim_major_history(&input.first_values, input_dim, token_count, projection)
        }) {
            Ok(values) => (Some(values), Value::Null),
            Err(err) => (None, json!(err.to_string())),
        },
        _ => (None, Value::Null),
    };
    let (rust_replay, rust_replay_error) = match (rust_input, reference_input, projection.as_ref())
    {
        (Some(input), Some(reference_input), Some(projection)) => {
            match dim_major_dim_count(reference_input).and_then(|input_dim| {
                let token_count = dim_major_token_count(reference_input)?;
                replay_qk256_dim_major_history(
                    &input.first_values,
                    input_dim,
                    token_count,
                    projection,
                )
            }) {
                Ok(values) => (Some(values), Value::Null),
                Err(err) => (None, json!(err.to_string())),
            }
        }
        _ => (None, Value::Null),
    };

    if let Some(source_rows) = source_rows {
        for source_row in source_rows {
            if source_row.pointer("/classification").and_then(Value::as_str)
                != Some("selected_pre_rope_projection_pair_source_raw_projection_pair_delta")
            {
                continue;
            }
            selected_count += 1;

            let kv_head = source_row
                .pointer("/kv_head")
                .and_then(Value::as_u64)
                .and_then(|value| usize::try_from(value).ok());
            let key_slot = source_row
                .pointer("/key_slot")
                .and_then(Value::as_u64)
                .and_then(|value| usize::try_from(value).ok());
            let dominant_dim = source_row
                .pointer("/dominant_projection_input_dim")
                .and_then(Value::as_u64)
                .and_then(|value| usize::try_from(value).ok());
            let dominant_projection_pair_delta =
                match source_row.pointer("/dominant_projection_input").and_then(Value::as_str) {
                    Some("x0") => value_f64(source_row, "/delta_x0"),
                    Some("x1") => value_f64(source_row, "/delta_x1"),
                    _ => None,
                };
            let reference_target =
                kv_head.and_then(|head| reference_projection_heads.get(&head).copied());
            let rust_target = kv_head.and_then(|head| rust_projection_heads.get(&head).copied());
            let mut blocked_reasons = Vec::<String>::new();

            if model_path.is_none() {
                blocked_reasons
                    .push("model_path_missing_for_pre_rope_projection_replay".to_string());
            } else if model_path.is_some_and(|path| !path.is_file()) {
                blocked_reasons
                    .push("model_gguf_missing_for_pre_rope_projection_replay".to_string());
            }
            if weight_load_error != Value::Null {
                blocked_reasons.push("k_projection_weight_load_failed".to_string());
            }
            if reference_input.is_none() {
                blocked_reasons.push("reference_attn_norm_history_missing".to_string());
            }
            if rust_input.is_none() {
                blocked_reasons.push("rust_attention_v_input_history_missing".to_string());
            }
            if reference_replay.is_none() {
                blocked_reasons.push("reference_k_projection_replay_missing".to_string());
            }
            if rust_replay.is_none() {
                blocked_reasons.push("rust_k_projection_replay_missing".to_string());
            }
            if kv_head.is_none() {
                blocked_reasons.push("selected_kv_head_missing".to_string());
            }
            if key_slot.is_none() {
                blocked_reasons.push("selected_key_slot_missing".to_string());
            }
            if dominant_dim.is_none() {
                blocked_reasons.push("selected_dominant_projection_dim_missing".to_string());
            }
            if dominant_projection_pair_delta.is_none() {
                blocked_reasons.push("selected_dominant_projection_pair_delta_missing".to_string());
            }
            if reference_target.is_none() {
                blocked_reasons.push("reference_k_projection_target_head_missing".to_string());
            }
            if rust_target.is_none() {
                blocked_reasons.push("rust_k_projection_target_head_missing".to_string());
            }

            let target_head_dim = reference_target
                .and_then(|record| dim_major_dim_count(record).ok())
                .or_else(|| rust_target.and_then(|record| record.shape.first().copied()));
            let token_count = reference_input
                .and_then(|record| dim_major_token_count(record).ok())
                .or_else(|| reference_target.and_then(|record| dim_major_token_count(record).ok()))
                .or_else(|| rust_target.and_then(|record| record.shape.get(1).copied()));
            let overall_projection_dim = kv_head
                .zip(target_head_dim)
                .zip(dominant_dim)
                .map(|((head, head_dim), dim)| head.saturating_mul(head_dim).saturating_add(dim));
            if target_head_dim.is_none() {
                blocked_reasons.push("k_projection_target_head_dim_missing".to_string());
            }
            if token_count.is_none() {
                blocked_reasons.push("k_projection_token_count_missing".to_string());
            }
            if overall_projection_dim.is_none() {
                blocked_reasons.push("overall_projection_dim_missing".to_string());
            }

            let reference_replay_value = reference_replay
                .as_ref()
                .zip(overall_projection_dim)
                .zip(token_count)
                .and_then(|((values, dim), token_count)| {
                    dim_major_value(values, projection.as_ref()?.rows, token_count, dim, key_slot?)
                });
            let rust_replay_value = rust_replay
                .as_ref()
                .zip(overall_projection_dim)
                .zip(token_count)
                .and_then(|((values, dim), token_count)| {
                    dim_major_value(values, projection.as_ref()?.rows, token_count, dim, key_slot?)
                });
            let reference_target_value = reference_target.zip(dominant_dim).zip(key_slot).and_then(
                |((record, dim), token)| {
                    let head_dim = dim_major_dim_count(record).ok()?;
                    let tokens = dim_major_token_count(record).ok()?;
                    dim_major_value(&record.first_values, head_dim, tokens, dim, token)
                },
            );
            let rust_target_value =
                rust_target.zip(dominant_dim).zip(key_slot).and_then(|((record, dim), token)| {
                    let head_dim = record.shape.first().copied()?;
                    let tokens = record.shape.get(1).copied()?;
                    dim_major_value(&record.first_values, head_dim, tokens, dim, token)
                });

            let reference_replay_vs_reference_target =
                scalar_f16_bucket_delta(reference_replay_value, reference_target_value);
            let rust_replay_vs_rust_target =
                scalar_f16_bucket_delta(rust_replay_value, rust_target_value);
            let reference_replay_vs_rust_replay =
                scalar_f16_bucket_delta(reference_replay_value, rust_replay_value);
            let reference_target_vs_rust_target =
                scalar_f16_bucket_delta(reference_target_value, rust_target_value);

            let reference_replay_matches_target =
                scalar_delta_abs(reference_replay_value, reference_target_value)
                    .is_some_and(|delta| delta <= 1.0e-5);
            let rust_replay_matches_target = scalar_delta_abs(rust_replay_value, rust_target_value)
                .is_some_and(|delta| delta <= 1.0e-5);
            let target_delta = reference_target_value
                .zip(rust_target_value)
                .map(|(reference, rust)| rust as f64 - reference as f64);
            let replay_delta = reference_replay_value
                .zip(rust_replay_value)
                .map(|(reference, rust)| rust as f64 - reference as f64);
            let replay_delta_minus_target_delta =
                replay_delta.zip(target_delta).map(|(replay, target)| replay - target);
            let replay_delta_matches_target_delta =
                replay_delta_minus_target_delta.is_some_and(|delta| delta.abs() <= 1.0e-5);
            let target_delta_matches_projection_pair_delta = target_delta
                .zip(dominant_projection_pair_delta)
                .is_some_and(|(target, pair)| (target - pair).abs() <= 1.0e-12);

            if reference_replay_value.is_none() {
                blocked_reasons.push("reference_replay_selected_value_missing".to_string());
            }
            if rust_replay_value.is_none() {
                blocked_reasons.push("rust_replay_selected_value_missing".to_string());
            }
            if reference_target_value.is_none() {
                blocked_reasons.push("reference_target_selected_value_missing".to_string());
            }
            if rust_target_value.is_none() {
                blocked_reasons.push("rust_target_selected_value_missing".to_string());
            }

            if let Some(delta) = dominant_projection_pair_delta {
                max_abs_projection_pair_delta = max_abs_projection_pair_delta.max(delta.abs());
            }
            if let Some(delta) = target_delta {
                max_abs_target_delta = max_abs_target_delta.max(delta.abs());
            }
            if let Some(delta) = replay_delta {
                max_abs_replay_delta = max_abs_replay_delta.max(delta.abs());
            }

            let row_classification = if !blocked_reasons.is_empty() {
                missing_context_count += 1;
                "selected_pre_rope_projection_history_source_missing_context"
            } else if !reference_replay_matches_target {
                reference_replay_mismatch_count += 1;
                "selected_pre_rope_projection_history_reference_replay_mismatch"
            } else if !rust_replay_matches_target {
                rust_replay_mismatch_count += 1;
                "selected_pre_rope_projection_history_rust_replay_mismatch"
            } else if !replay_delta_matches_target_delta
                || !target_delta_matches_projection_pair_delta
            {
                replay_delta_unpinned_count += 1;
                "selected_pre_rope_projection_history_replay_delta_unpinned"
            } else {
                history_delta_explained_count += 1;
                "selected_pre_rope_projection_history_replay_explains_pair_delta"
            };
            if blocked_reasons.is_empty() {
                compared_count += 1;
            }

            rows.push(json!({
                "classification": row_classification,
                "head": source_row.pointer("/head").cloned().unwrap_or(Value::Null),
                "kv_head": kv_head,
                "key_slot": key_slot,
                "query_token": source_row.pointer("/query_token").cloned().unwrap_or(Value::Null),
                "contributor_dim": source_row.pointer("/contributor_dim").cloned().unwrap_or(Value::Null),
                "dominant_projection_input": source_row.pointer("/dominant_projection_input").cloned().unwrap_or(Value::Null),
                "dominant_projection_input_dim": dominant_dim,
                "dominant_linearized_contribution": source_row.pointer("/dominant_linearized_contribution").cloned().unwrap_or(Value::Null),
                "dominant_projection_pair_delta": dominant_projection_pair_delta,
                "target_head_dim": target_head_dim,
                "overall_projection_dim": overall_projection_dim,
                "blocked_reasons": blocked_reasons,
                "reference_input_stage": "attn_norm_history_ref_layout",
                "rust_input_stage": "attention_v_input_history_ref_layout",
                "reference_replay_error": reference_replay_error,
                "rust_replay_error": rust_replay_error,
                "weight": DEFAULT_KEY_PROJECTION_WEIGHT,
                "reference_replay_value": reference_replay_value,
                "reference_target_value": reference_target_value,
                "rust_replay_value": rust_replay_value,
                "rust_target_value": rust_target_value,
                "target_delta_rust_minus_reference": target_delta,
                "replay_delta_rust_minus_reference": replay_delta,
                "replay_delta_minus_target_delta": replay_delta_minus_target_delta,
                "target_delta_matches_projection_pair_delta": target_delta_matches_projection_pair_delta,
                "reference_replay_matches_target": reference_replay_matches_target,
                "rust_replay_matches_target": rust_replay_matches_target,
                "replay_delta_matches_target_delta": replay_delta_matches_target_delta,
                "reference_replay_vs_reference_target": reference_replay_vs_reference_target,
                "rust_replay_vs_rust_target": rust_replay_vs_rust_target,
                "reference_replay_vs_rust_replay": reference_replay_vs_rust_replay,
                "reference_target_vs_rust_target": reference_target_vs_rust_target,
                "pre_rope_projection_pair_source_row": source_row.clone(),
                "runtime_change_candidate": match row_classification {
                    "selected_pre_rope_projection_history_replay_explains_pair_delta" => {
                        "none_from_k_projection_weight_layout_or_pre_rope_history_trace"
                    }
                    "selected_pre_rope_projection_history_reference_replay_mismatch" => {
                        "pin_reference_k_projection_semantics_or_weight_layout"
                    }
                    "selected_pre_rope_projection_history_rust_replay_mismatch" => {
                        "pin_rust_k_projection_runtime_dispatch_or_trace_capture"
                    }
                    "selected_pre_rope_projection_history_replay_delta_unpinned" => {
                        "pin_selected_pre_rope_projection_delta_before_runtime_change"
                    }
                    _ => "selected_pre_rope_projection_history_context_missing",
                },
            }));
        }
    }

    let classification = if selected_count == 0 {
        "no_selected_pre_rope_projection_pair_raw_delta_rows"
    } else if missing_context_count == selected_count {
        "selected_pre_rope_projection_history_source_missing_context"
    } else if reference_replay_mismatch_count > 0 {
        "selected_pre_rope_projection_history_reference_replay_mismatch"
    } else if rust_replay_mismatch_count > 0 {
        "selected_pre_rope_projection_history_rust_replay_mismatch"
    } else if replay_delta_unpinned_count > 0 {
        "selected_pre_rope_projection_history_replay_delta_unpinned"
    } else if history_delta_explained_count > 0 {
        "selected_pre_rope_projection_history_replay_explains_pair_delta"
    } else {
        "selected_pre_rope_projection_history_source_unpinned"
    };
    let next_diagnostic = match classification {
        "selected_pre_rope_projection_history_replay_explains_pair_delta" => {
            "localize attention-norm history epsilon feeding selected K projection before changing QK256 or RoPE runtime math"
        }
        "selected_pre_rope_projection_history_reference_replay_mismatch" => {
            "pin reference K projection semantics or GGUF weight interpretation before changing Rust runtime math"
        }
        "selected_pre_rope_projection_history_rust_replay_mismatch" => {
            "pin Rust K projection dispatch or trace capture before changing runtime math"
        }
        "selected_pre_rope_projection_history_replay_delta_unpinned" => {
            "explain selected pre-RoPE projection delta before changing runtime math"
        }
        "selected_pre_rope_projection_history_source_missing_context" => {
            "capture model, attention-norm histories, and selected K projection traces before replay attribution"
        }
        "no_selected_pre_rope_projection_pair_raw_delta_rows" => {
            "classify selected pre-RoPE projection-pair source before history attribution"
        }
        _ => "keep selected pre-RoPE projection history source diagnostic-only",
    };

    json!({
        "diagnostic_only": true,
        "claim_allowed": false,
        "policy": "Selected pre-RoPE projection history source is diagnostic-only evidence for whether the dominant pre-RoPE K projection pair delta is reproduced by replaying reference and Rust attention-norm histories through the loaded blk.0.attn_k.weight; it does not change QK256, ROPE, score-input, or runtime math and does not promote reference parity, A770 semantic quality, attention score residency, selected attention, resident KV, full residency, performance, or completion",
        "classification": classification,
        "selected_count": selected_count,
        "compared_count": compared_count,
        "missing_context_count": missing_context_count,
        "reference_replay_mismatch_count": reference_replay_mismatch_count,
        "rust_replay_mismatch_count": rust_replay_mismatch_count,
        "replay_delta_unpinned_count": replay_delta_unpinned_count,
        "history_delta_explained_count": history_delta_explained_count,
        "max_abs_projection_pair_delta": max_abs_projection_pair_delta,
        "max_abs_target_delta": max_abs_target_delta,
        "max_abs_replay_delta": max_abs_replay_delta,
        "model": model_report,
        "weight": weight_report,
        "weight_load_error": weight_load_error,
        "rows": rows,
        "next_diagnostic": next_diagnostic,
    })
}

fn attention_selected_historical_k_projection_subbucket_epsilon_source(
    post_rope_raw_key_epsilon: &Value,
) -> Value {
    let source_rows = post_rope_raw_key_epsilon.pointer("/rows").and_then(Value::as_array);
    let mut rows = Vec::<Value>::new();
    let mut selected_count = 0usize;
    let mut compared_count = 0usize;
    let mut missing_input_pair_count = 0usize;
    let mut projection_bucket_crossing_count = 0usize;
    let mut raw_projection_pair_count = 0usize;
    let mut dominant_x0_count = 0usize;
    let mut dominant_x1_count = 0usize;
    let mut unpinned_count = 0usize;
    let mut max_abs_linearized_contribution = 0.0f64;

    if let Some(source_rows) = source_rows {
        for source_row in source_rows {
            if source_row.pointer("/classification").and_then(Value::as_str)
                != Some("selected_post_rope_raw_key_epsilon_projection_subbucket_midpoint_crossing")
            {
                continue;
            }
            selected_count += 1;

            let input_pair = source_row.pointer("/input_pair").unwrap_or(&Value::Null);
            let delta_x0 = input_pair.pointer("/delta_x0").and_then(Value::as_f64);
            let delta_x1 = input_pair.pointer("/delta_x1").and_then(Value::as_f64);
            let x0_coefficient =
                input_pair.pointer("/x0_coefficient_for_probe_dim").and_then(Value::as_f64);
            let x1_coefficient =
                input_pair.pointer("/x1_coefficient_for_probe_dim").and_then(Value::as_f64);
            let x0_dim = input_pair.pointer("/x0_dim").and_then(Value::as_u64);
            let x1_dim = input_pair.pointer("/x1_dim").and_then(Value::as_u64);
            let linearized_delta =
                source_row.pointer("/linearized_delta_for_probe_dim").and_then(Value::as_f64);
            let capture_delta = source_row.pointer("/capture_delta").and_then(Value::as_f64);
            let runtime_replay_delta =
                source_row.pointer("/runtime_replay_delta").and_then(Value::as_f64);
            let projection_bucket_match =
                source_row.pointer("/projection_bucket/f16_bucket_match").and_then(Value::as_bool);
            let paired_projection_bucket_match = source_row
                .pointer("/paired_projection_bucket/f16_bucket_match")
                .and_then(Value::as_bool);
            let post_rope_bucket_crossing =
                source_row.pointer("/post_rope_bucket_crossing").and_then(Value::as_bool)
                    == Some(true);
            let replay_matches_capture =
                source_row.pointer("/replay_matches_capture").and_then(Value::as_bool)
                    == Some(true);
            let linearized_matches_replay =
                source_row.pointer("/linearized_matches_replay").and_then(Value::as_bool)
                    == Some(true);
            let projection_buckets_stable = projection_bucket_match == Some(true)
                && paired_projection_bucket_match == Some(true);

            let mut blocked_reasons = Vec::<String>::new();
            if input_pair.is_null() {
                blocked_reasons.push("projection_input_pair_missing".to_string());
            }
            if delta_x0.is_none() || delta_x1.is_none() {
                blocked_reasons.push("projection_input_pair_delta_missing".to_string());
            }
            if x0_coefficient.is_none() || x1_coefficient.is_none() {
                blocked_reasons.push("rope_projection_pair_coefficient_missing".to_string());
            }
            if x0_dim.is_none() || x1_dim.is_none() {
                blocked_reasons.push("projection_input_pair_dim_missing".to_string());
            }

            let x0_linearized_contribution =
                delta_x0.zip(x0_coefficient).map(|(delta, coefficient)| delta * coefficient);
            let x1_linearized_contribution =
                delta_x1.zip(x1_coefficient).map(|(delta, coefficient)| delta * coefficient);
            let linearized_sum =
                x0_linearized_contribution.zip(x1_linearized_contribution).map(|(x0, x1)| x0 + x1);
            let linearized_sum_matches_probe = linearized_sum
                .zip(linearized_delta)
                .is_some_and(|(sum, delta)| (sum - delta).abs() <= 1.0e-12);
            let dominant_projection_input =
                match (x0_linearized_contribution, x1_linearized_contribution) {
                    (Some(x0), Some(x1)) if x0.abs() >= x1.abs() => Some(("x0", x0_dim, x0)),
                    (Some(_), Some(x1)) => Some(("x1", x1_dim, x1)),
                    _ => None,
                };
            let dominant_input_label = dominant_projection_input.map(|(label, _, _)| label);
            let dominant_input_dim = dominant_projection_input.and_then(|(_, dim, _)| dim);
            let dominant_linearized_contribution =
                dominant_projection_input.map(|(_, _, contribution)| contribution);
            if let Some(contribution) = dominant_linearized_contribution {
                max_abs_linearized_contribution =
                    max_abs_linearized_contribution.max(contribution.abs());
            }

            let row_classification = if !blocked_reasons.is_empty() {
                missing_input_pair_count += 1;
                "selected_historical_k_projection_subbucket_epsilon_source_missing_input_pair"
            } else if !projection_buckets_stable {
                projection_bucket_crossing_count += 1;
                "selected_historical_k_projection_subbucket_epsilon_source_projection_bucket_crossing"
            } else if post_rope_bucket_crossing
                && replay_matches_capture
                && linearized_matches_replay
                && linearized_sum_matches_probe
            {
                raw_projection_pair_count += 1;
                if dominant_input_label == Some("x0") {
                    dominant_x0_count += 1;
                } else if dominant_input_label == Some("x1") {
                    dominant_x1_count += 1;
                }
                "selected_historical_k_projection_subbucket_epsilon_source_raw_projection_pair"
            } else {
                unpinned_count += 1;
                "selected_historical_k_projection_subbucket_epsilon_source_unpinned"
            };
            if !blocked_reasons.is_empty()
                || row_classification
                    != "selected_historical_k_projection_subbucket_epsilon_source_missing_input_pair"
            {
                compared_count += 1;
            }

            rows.push(json!({
                "classification": row_classification,
                "head": source_row.pointer("/head").cloned().unwrap_or(Value::Null),
                "kv_head": source_row.pointer("/kv_head").cloned().unwrap_or(Value::Null),
                "key_slot": source_row.pointer("/key_slot").cloned().unwrap_or(Value::Null),
                "query_token": source_row.pointer("/query_token").cloned().unwrap_or(Value::Null),
                "contributor_dim": source_row.pointer("/contributor_dim").cloned().unwrap_or(Value::Null),
                "probe_dim": source_row.pointer("/probe_dim").cloned().unwrap_or(Value::Null),
                "paired_dim": source_row.pointer("/paired_dim").cloned().unwrap_or(Value::Null),
                "output_component": source_row.pointer("/output_component").cloned().unwrap_or(Value::Null),
                "blocked_reasons": blocked_reasons,
                "projection_buckets_stable": projection_buckets_stable,
                "projection_bucket_match": projection_bucket_match,
                "paired_projection_bucket_match": paired_projection_bucket_match,
                "post_rope_bucket_crossing": post_rope_bucket_crossing,
                "replay_matches_capture": replay_matches_capture,
                "linearized_matches_replay": linearized_matches_replay,
                "linearized_sum_matches_probe": linearized_sum_matches_probe,
                "capture_delta": capture_delta,
                "runtime_replay_delta": runtime_replay_delta,
                "linearized_delta_for_probe_dim": linearized_delta,
                "linearized_sum_from_projection_pair": linearized_sum,
                "x0_dim": x0_dim,
                "x1_dim": x1_dim,
                "delta_x0": delta_x0,
                "delta_x1": delta_x1,
                "x0_coefficient_for_probe_dim": x0_coefficient,
                "x1_coefficient_for_probe_dim": x1_coefficient,
                "x0_linearized_contribution": x0_linearized_contribution,
                "x1_linearized_contribution": x1_linearized_contribution,
                "dominant_projection_input": dominant_input_label,
                "dominant_projection_input_dim": dominant_input_dim,
                "dominant_linearized_contribution": dominant_linearized_contribution,
                "projection_bucket": source_row.pointer("/projection_bucket").cloned().unwrap_or(Value::Null),
                "paired_projection_bucket": source_row.pointer("/paired_projection_bucket").cloned().unwrap_or(Value::Null),
                "runtime_change_candidate": match row_classification {
                    "selected_historical_k_projection_subbucket_epsilon_source_raw_projection_pair" => {
                        "none_from_rope_replay_capture_or_score_input_policy"
                    }
                    "selected_historical_k_projection_subbucket_epsilon_source_projection_bucket_crossing" => {
                        "localize_projection_bucket_crossing_before_rope"
                    }
                    _ => "historical_k_projection_subbucket_epsilon_source_unpinned",
                },
            }));
        }
    }

    let classification = if selected_count == 0 {
        "no_selected_post_rope_raw_key_epsilon_rows"
    } else if missing_input_pair_count == selected_count {
        "selected_historical_k_projection_subbucket_epsilon_source_missing_input_pair"
    } else if projection_bucket_crossing_count > 0 {
        "selected_historical_k_projection_subbucket_epsilon_source_projection_bucket_crossing"
    } else if raw_projection_pair_count > 0 && unpinned_count == 0 {
        "selected_historical_k_projection_subbucket_epsilon_source_raw_projection_pair"
    } else {
        "selected_historical_k_projection_subbucket_epsilon_source_unpinned"
    };
    let next_diagnostic = match classification {
        "selected_historical_k_projection_subbucket_epsilon_source_raw_projection_pair" => {
            "localize selected historical K projection raw epsilon at the dominant input dim before changing QK256, RoPE, or score-input runtime math"
        }
        "selected_historical_k_projection_subbucket_epsilon_source_projection_bucket_crossing" => {
            "localize selected historical K projection F16 bucket crossing before changing RoPE or score-input runtime math"
        }
        "selected_historical_k_projection_subbucket_epsilon_source_missing_input_pair" => {
            "capture selected historical K projection input-pair epsilon before changing runtime math"
        }
        "no_selected_post_rope_raw_key_epsilon_rows" => {
            "pin selected post-RoPE raw key epsilon before localizing projection sub-bucket source"
        }
        _ => "keep selected historical K projection sub-bucket epsilon source diagnostic-only",
    };

    json!({
        "diagnostic_only": true,
        "claim_allowed": false,
        "policy": "Selected historical K projection sub-bucket epsilon source is diagnostic-only evidence for whether the raw pre-RoPE projection input pair explains a post-RoPE F16 midpoint crossing; it does not change QK256, RoPE, score-input, or runtime math and does not promote reference parity, A770 semantic quality, attention score residency, selected attention, resident KV, full residency, performance, or completion",
        "classification": classification,
        "selected_count": selected_count,
        "compared_count": compared_count,
        "missing_input_pair_count": missing_input_pair_count,
        "projection_bucket_crossing_count": projection_bucket_crossing_count,
        "raw_projection_pair_count": raw_projection_pair_count,
        "dominant_x0_count": dominant_x0_count,
        "dominant_x1_count": dominant_x1_count,
        "unpinned_count": unpinned_count,
        "max_abs_linearized_contribution": max_abs_linearized_contribution,
        "rows": rows,
        "next_diagnostic": next_diagnostic,
    })
}

fn attention_selected_historical_k_projection_replay_source(
    projection_epsilon_source: &Value,
    reference_records: &[ReferenceTraceRecord],
    rust_records: &BTreeMap<String, RustTraceRecord>,
    model_path: Option<&Path>,
) -> Value {
    let source_rows = projection_epsilon_source.pointer("/rows").and_then(Value::as_array);
    let reference_input = reference_records.iter().find(|record| {
        record.stage == "attn_norm_history_ref_layout"
            && record.values_available
            && !record.first_values.is_empty()
    });
    let rust_input = rust_records
        .get("attention_v_input_history_ref_layout")
        .filter(|record| !record.first_values.is_empty());
    let reference_projection_heads = reference_records
        .iter()
        .filter_map(|record| {
            parse_stage_head(&record.stage, "k_projection_history_kv_head")
                .map(|head| (head, record))
        })
        .filter(|(_, record)| record.values_available && !record.first_values.is_empty())
        .collect::<BTreeMap<_, _>>();
    let rust_projection_heads = rust_records
        .iter()
        .filter_map(|(stage, record)| {
            parse_stage_head(stage, "attention_k_projection_kv_head").map(|head| (head, record))
        })
        .filter(|(_, record)| !record.first_values.is_empty())
        .collect::<BTreeMap<_, _>>();

    let mut rows = Vec::<Value>::new();
    let mut selected_count = 0usize;
    let mut compared_count = 0usize;
    let mut missing_context_count = 0usize;
    let mut reference_replay_mismatch_count = 0usize;
    let mut rust_replay_mismatch_count = 0usize;
    let mut replay_delta_unpinned_count = 0usize;
    let mut replay_explained_count = 0usize;
    let mut max_abs_target_delta = 0.0f64;
    let mut max_abs_replay_delta = 0.0f64;
    let mut model_report = json!({
        "path": model_path.map(|path| json!(path_to_string(path))).unwrap_or(Value::Null),
        "exists": model_path.is_some_and(|path| path.is_file()),
    });
    let mut weight_report = json!({
        "name": DEFAULT_KEY_PROJECTION_WEIGHT,
    });
    let mut weight_load_error = Value::Null;

    let projection = match model_path {
        Some(path) if path.is_file() => {
            match reference_input.map(dim_major_dim_count).transpose().and_then(|input_dim| {
                load_qk256_same_input_projection(
                    path,
                    DEFAULT_KEY_PROJECTION_WEIGHT,
                    input_dim.unwrap_or(0),
                    None,
                )
            }) {
                Ok(projection) => {
                    model_report = projection.model_report.clone();
                    weight_report = projection.weight_report.clone();
                    Some(projection)
                }
                Err(err) => {
                    weight_load_error = json!(err.to_string());
                    None
                }
            }
        }
        _ => None,
    };

    let (reference_replay, reference_replay_error) = match (reference_input, projection.as_ref()) {
        (Some(input), Some(projection)) => match dim_major_dim_count(input).and_then(|input_dim| {
            let token_count = dim_major_token_count(input)?;
            replay_qk256_dim_major_history(&input.first_values, input_dim, token_count, projection)
        }) {
            Ok(values) => (Some(values), Value::Null),
            Err(err) => (None, json!(err.to_string())),
        },
        _ => (None, Value::Null),
    };
    let (rust_replay, rust_replay_error) = match (rust_input, reference_input, projection.as_ref())
    {
        (Some(input), Some(reference_input), Some(projection)) => {
            match dim_major_dim_count(reference_input).and_then(|input_dim| {
                let token_count = dim_major_token_count(reference_input)?;
                replay_qk256_dim_major_history(
                    &input.first_values,
                    input_dim,
                    token_count,
                    projection,
                )
            }) {
                Ok(values) => (Some(values), Value::Null),
                Err(err) => (None, json!(err.to_string())),
            }
        }
        _ => (None, Value::Null),
    };

    if let Some(source_rows) = source_rows {
        for source_row in source_rows {
            if source_row.pointer("/classification").and_then(Value::as_str)
                != Some(
                    "selected_historical_k_projection_subbucket_epsilon_source_raw_projection_pair",
                )
            {
                continue;
            }
            selected_count += 1;

            let kv_head = source_row
                .pointer("/kv_head")
                .and_then(Value::as_u64)
                .and_then(|value| usize::try_from(value).ok());
            let key_slot = source_row
                .pointer("/key_slot")
                .and_then(Value::as_u64)
                .and_then(|value| usize::try_from(value).ok());
            let dominant_dim = source_row
                .pointer("/dominant_projection_input_dim")
                .and_then(Value::as_u64)
                .and_then(|value| usize::try_from(value).ok());
            let reference_target =
                kv_head.and_then(|head| reference_projection_heads.get(&head).copied());
            let rust_target = kv_head.and_then(|head| rust_projection_heads.get(&head).copied());
            let mut blocked_reasons = Vec::<String>::new();

            if model_path.is_none() {
                blocked_reasons.push("model_path_missing_for_k_projection_replay".to_string());
            } else if model_path.is_some_and(|path| !path.is_file()) {
                blocked_reasons.push("model_gguf_missing_for_k_projection_replay".to_string());
            }
            if weight_load_error != Value::Null {
                blocked_reasons.push("k_projection_weight_load_failed".to_string());
            }
            if reference_input.is_none() {
                blocked_reasons.push("reference_attn_norm_history_missing".to_string());
            }
            if rust_input.is_none() {
                blocked_reasons.push("rust_attention_v_input_history_missing".to_string());
            }
            if reference_replay.is_none() {
                blocked_reasons.push("reference_k_projection_replay_missing".to_string());
            }
            if rust_replay.is_none() {
                blocked_reasons.push("rust_k_projection_replay_missing".to_string());
            }
            if kv_head.is_none() {
                blocked_reasons.push("selected_kv_head_missing".to_string());
            }
            if key_slot.is_none() {
                blocked_reasons.push("selected_key_slot_missing".to_string());
            }
            if dominant_dim.is_none() {
                blocked_reasons.push("selected_dominant_projection_dim_missing".to_string());
            }
            if reference_target.is_none() {
                blocked_reasons.push("reference_k_projection_target_head_missing".to_string());
            }
            if rust_target.is_none() {
                blocked_reasons.push("rust_k_projection_target_head_missing".to_string());
            }

            let target_head_dim = reference_target
                .and_then(|record| dim_major_dim_count(record).ok())
                .or_else(|| rust_target.and_then(|record| record.shape.first().copied()));
            let token_count = reference_input
                .and_then(|record| dim_major_token_count(record).ok())
                .or_else(|| reference_target.and_then(|record| dim_major_token_count(record).ok()))
                .or_else(|| rust_target.and_then(|record| record.shape.get(1).copied()));
            let overall_projection_dim = kv_head
                .zip(target_head_dim)
                .zip(dominant_dim)
                .map(|((head, head_dim), dim)| head.saturating_mul(head_dim).saturating_add(dim));
            if target_head_dim.is_none() {
                blocked_reasons.push("k_projection_target_head_dim_missing".to_string());
            }
            if token_count.is_none() {
                blocked_reasons.push("k_projection_token_count_missing".to_string());
            }
            if overall_projection_dim.is_none() {
                blocked_reasons.push("overall_projection_dim_missing".to_string());
            }

            let reference_replay_value = reference_replay
                .as_ref()
                .zip(overall_projection_dim)
                .zip(token_count)
                .and_then(|((values, dim), token_count)| {
                    dim_major_value(values, projection.as_ref()?.rows, token_count, dim, key_slot?)
                });
            let rust_replay_value = rust_replay
                .as_ref()
                .zip(overall_projection_dim)
                .zip(token_count)
                .and_then(|((values, dim), token_count)| {
                    dim_major_value(values, projection.as_ref()?.rows, token_count, dim, key_slot?)
                });
            let reference_target_value = reference_target.zip(dominant_dim).zip(key_slot).and_then(
                |((record, dim), token)| {
                    let head_dim = dim_major_dim_count(record).ok()?;
                    let tokens = dim_major_token_count(record).ok()?;
                    dim_major_value(&record.first_values, head_dim, tokens, dim, token)
                },
            );
            let rust_target_value =
                rust_target.zip(dominant_dim).zip(key_slot).and_then(|((record, dim), token)| {
                    let head_dim = record.shape.first().copied()?;
                    let tokens = record.shape.get(1).copied()?;
                    dim_major_value(&record.first_values, head_dim, tokens, dim, token)
                });

            let reference_replay_vs_reference_target =
                scalar_f16_bucket_delta(reference_replay_value, reference_target_value);
            let rust_replay_vs_rust_target =
                scalar_f16_bucket_delta(rust_replay_value, rust_target_value);
            let reference_replay_vs_rust_replay =
                scalar_f16_bucket_delta(reference_replay_value, rust_replay_value);
            let reference_target_vs_rust_target =
                scalar_f16_bucket_delta(reference_target_value, rust_target_value);

            let reference_replay_matches_target =
                scalar_delta_abs(reference_replay_value, reference_target_value)
                    .is_some_and(|delta| delta <= 1.0e-5);
            let rust_replay_matches_target = scalar_delta_abs(rust_replay_value, rust_target_value)
                .is_some_and(|delta| delta <= 1.0e-5);
            let target_delta = reference_target_value
                .zip(rust_target_value)
                .map(|(reference, rust)| rust as f64 - reference as f64);
            let replay_delta = reference_replay_value
                .zip(rust_replay_value)
                .map(|(reference, rust)| rust as f64 - reference as f64);
            let replay_delta_minus_target_delta =
                replay_delta.zip(target_delta).map(|(replay, target)| replay - target);
            let replay_delta_matches_target_delta =
                replay_delta_minus_target_delta.is_some_and(|delta| delta.abs() <= 1.0e-5);
            let target_bucket_stable = reference_target_vs_rust_target
                .pointer("/f16_bucket_match")
                .and_then(Value::as_bool)
                == Some(true);
            let replay_bucket_stable = reference_replay_vs_rust_replay
                .pointer("/f16_bucket_match")
                .and_then(Value::as_bool)
                == Some(true);

            if reference_replay_value.is_none() {
                blocked_reasons.push("reference_replay_selected_value_missing".to_string());
            }
            if rust_replay_value.is_none() {
                blocked_reasons.push("rust_replay_selected_value_missing".to_string());
            }
            if reference_target_value.is_none() {
                blocked_reasons.push("reference_target_selected_value_missing".to_string());
            }
            if rust_target_value.is_none() {
                blocked_reasons.push("rust_target_selected_value_missing".to_string());
            }

            if let Some(delta) = target_delta {
                max_abs_target_delta = max_abs_target_delta.max(delta.abs());
            }
            if let Some(delta) = replay_delta {
                max_abs_replay_delta = max_abs_replay_delta.max(delta.abs());
            }

            let row_classification = if !blocked_reasons.is_empty() {
                missing_context_count += 1;
                "selected_historical_k_projection_replay_source_missing_context"
            } else if !reference_replay_matches_target {
                reference_replay_mismatch_count += 1;
                "selected_historical_k_projection_reference_replay_mismatch"
            } else if !rust_replay_matches_target {
                rust_replay_mismatch_count += 1;
                "selected_historical_k_projection_rust_replay_mismatch"
            } else if !replay_delta_matches_target_delta {
                replay_delta_unpinned_count += 1;
                "selected_historical_k_projection_replay_delta_unpinned"
            } else {
                replay_explained_count += 1;
                "selected_historical_k_projection_replay_explains_raw_epsilon"
            };
            if blocked_reasons.is_empty() {
                compared_count += 1;
            }

            rows.push(json!({
                "classification": row_classification,
                "head": source_row.pointer("/head").cloned().unwrap_or(Value::Null),
                "kv_head": kv_head,
                "key_slot": key_slot,
                "query_token": source_row.pointer("/query_token").cloned().unwrap_or(Value::Null),
                "contributor_dim": source_row.pointer("/contributor_dim").cloned().unwrap_or(Value::Null),
                "dominant_projection_input": source_row.pointer("/dominant_projection_input").cloned().unwrap_or(Value::Null),
                "dominant_projection_input_dim": dominant_dim,
                "dominant_linearized_contribution": source_row.pointer("/dominant_linearized_contribution").cloned().unwrap_or(Value::Null),
                "target_head_dim": target_head_dim,
                "overall_projection_dim": overall_projection_dim,
                "blocked_reasons": blocked_reasons,
                "reference_input_stage": "attn_norm_history_ref_layout",
                "rust_input_stage": "attention_v_input_history_ref_layout",
                "reference_replay_error": reference_replay_error,
                "rust_replay_error": rust_replay_error,
                "weight": DEFAULT_KEY_PROJECTION_WEIGHT,
                "reference_replay_value": reference_replay_value,
                "reference_target_value": reference_target_value,
                "rust_replay_value": rust_replay_value,
                "rust_target_value": rust_target_value,
                "target_delta_rust_minus_reference": target_delta,
                "replay_delta_rust_minus_reference": replay_delta,
                "replay_delta_minus_target_delta": replay_delta_minus_target_delta,
                "reference_replay_matches_target": reference_replay_matches_target,
                "rust_replay_matches_target": rust_replay_matches_target,
                "replay_delta_matches_target_delta": replay_delta_matches_target_delta,
                "target_bucket_stable": target_bucket_stable,
                "replay_bucket_stable": replay_bucket_stable,
                "reference_replay_vs_reference_target": reference_replay_vs_reference_target,
                "rust_replay_vs_rust_target": rust_replay_vs_rust_target,
                "reference_replay_vs_rust_replay": reference_replay_vs_rust_replay,
                "reference_target_vs_rust_target": reference_target_vs_rust_target,
                "runtime_change_candidate": match row_classification {
                    "selected_historical_k_projection_replay_explains_raw_epsilon" => {
                        "none_from_k_projection_weight_layout_or_runtime_trace"
                    }
                    "selected_historical_k_projection_reference_replay_mismatch" => {
                        "pin_reference_k_projection_semantics_or_weight_layout"
                    }
                    "selected_historical_k_projection_rust_replay_mismatch" => {
                        "pin_rust_k_projection_runtime_dispatch_or_trace_capture"
                    }
                    "selected_historical_k_projection_replay_delta_unpinned" => {
                        "pin_k_projection_replay_delta_before_runtime_change"
                    }
                    _ => "selected_historical_k_projection_replay_context_missing",
                },
            }));
        }
    }

    let classification = if selected_count == 0 {
        "no_selected_historical_k_projection_raw_epsilon_rows"
    } else if missing_context_count == selected_count {
        "selected_historical_k_projection_replay_source_missing_context"
    } else if reference_replay_mismatch_count > 0 {
        "selected_historical_k_projection_reference_replay_mismatch"
    } else if rust_replay_mismatch_count > 0 {
        "selected_historical_k_projection_rust_replay_mismatch"
    } else if replay_delta_unpinned_count > 0 {
        "selected_historical_k_projection_replay_delta_unpinned"
    } else if replay_explained_count > 0 {
        "selected_historical_k_projection_replay_explains_raw_epsilon"
    } else {
        "selected_historical_k_projection_replay_source_unpinned"
    };
    let next_diagnostic = match classification {
        "selected_historical_k_projection_replay_explains_raw_epsilon" => {
            "localize attention-norm input history epsilon feeding selected K projection before changing QK256 or RoPE runtime math"
        }
        "selected_historical_k_projection_reference_replay_mismatch" => {
            "pin reference K projection semantics or GGUF weight interpretation before changing Rust runtime math"
        }
        "selected_historical_k_projection_rust_replay_mismatch" => {
            "pin Rust K projection dispatch or trace capture before changing runtime math"
        }
        "selected_historical_k_projection_replay_delta_unpinned" => {
            "explain selected K projection replay delta before changing runtime math"
        }
        "selected_historical_k_projection_replay_source_missing_context" => {
            "capture model, attention-norm histories, and selected K projection traces before replay attribution"
        }
        "no_selected_historical_k_projection_raw_epsilon_rows" => {
            "pin selected historical K projection raw epsilon before replay attribution"
        }
        _ => "keep selected historical K projection replay source diagnostic-only",
    };

    json!({
        "diagnostic_only": true,
        "claim_allowed": false,
        "policy": "Selected historical K projection replay source is diagnostic-only evidence for whether the dominant raw K projection epsilon is reproduced by replaying reference and Rust attention-norm histories through the loaded blk.0.attn_k.weight; it does not change QK256, RoPE, score-input, or runtime math and does not promote reference parity, A770 semantic quality, attention score residency, selected attention, resident KV, full residency, performance, or completion",
        "classification": classification,
        "selected_count": selected_count,
        "compared_count": compared_count,
        "missing_context_count": missing_context_count,
        "reference_replay_mismatch_count": reference_replay_mismatch_count,
        "rust_replay_mismatch_count": rust_replay_mismatch_count,
        "replay_delta_unpinned_count": replay_delta_unpinned_count,
        "replay_explained_count": replay_explained_count,
        "max_abs_target_delta": max_abs_target_delta,
        "max_abs_replay_delta": max_abs_replay_delta,
        "model": model_report,
        "weight": weight_report,
        "weight_load_error": weight_load_error,
        "rows": rows,
        "next_diagnostic": next_diagnostic,
    })
}

fn pre_rope_attention_norm_source_classification(classification: &str) -> &'static str {
    match classification {
        "no_selected_k_projection_replay_explained_rows" => {
            "no_selected_pre_rope_projection_history_replay_explained_rows"
        }
        "selected_historical_k_attention_norm_source_missing_context" => {
            "selected_pre_rope_attention_norm_history_source_missing_context"
        }
        "selected_historical_k_attention_norm_source_input_history_epsilon" => {
            "selected_pre_rope_attention_norm_history_source_input_history_epsilon"
        }
        "selected_historical_k_attention_norm_source_output_replay_explains_epsilon" => {
            "selected_pre_rope_attention_norm_history_source_output_replay_explains_epsilon"
        }
        "selected_historical_k_attention_norm_source_output_epsilon_unpinned" => {
            "selected_pre_rope_attention_norm_history_source_output_epsilon_unpinned"
        }
        "selected_historical_k_attention_norm_source_clean" => {
            "selected_pre_rope_attention_norm_history_source_clean"
        }
        _ => "selected_pre_rope_attention_norm_history_source_unpinned",
    }
}

fn pre_rope_attention_norm_source_next_diagnostic(classification: &str) -> &'static str {
    match classification {
        "selected_pre_rope_attention_norm_history_source_input_history_epsilon" => {
            "localize selected pre-RoPE attention-norm input-history epsilon before changing RMSNorm, K projection, QK256, or ROPE runtime math"
        }
        "selected_pre_rope_attention_norm_history_source_output_replay_explains_epsilon" => {
            "pin whether attention RMSNorm accumulation or trace serialization explains the selected pre-RoPE K projection source epsilon"
        }
        "selected_pre_rope_attention_norm_history_source_output_epsilon_unpinned" => {
            "capture enough attention RMSNorm replay context to explain selected pre-RoPE output epsilon before changing runtime math"
        }
        "selected_pre_rope_attention_norm_history_source_missing_context" => {
            "capture model and full attention-norm input/output histories before selected pre-RoPE K attention-norm attribution"
        }
        "no_selected_pre_rope_projection_history_replay_explained_rows" => {
            "pin selected pre-RoPE projection history source before attention-norm attribution"
        }
        "selected_pre_rope_attention_norm_history_source_clean" => {
            "selected pre-RoPE attention-norm source is clean; inspect upstream selection or downstream score residual before runtime math changes"
        }
        _ => "keep selected pre-RoPE attention-norm history source diagnostic-only",
    }
}

fn pre_rope_attention_norm_runtime_candidate(candidate: Option<&str>) -> &'static str {
    match candidate {
        Some("localize_attention_norm_input_history_before_changing_rmsnorm_or_k_projection") => {
            "localize_pre_rope_attention_norm_input_history_before_changing_rmsnorm_or_k_projection"
        }
        Some("pin_attention_rmsnorm_accumulation_or_serialization_policy") => {
            "pin_pre_rope_attention_rmsnorm_accumulation_or_serialization_policy"
        }
        Some("pin_attention_norm_replay_delta_before_runtime_change") => {
            "pin_pre_rope_attention_norm_replay_delta_before_runtime_change"
        }
        Some("none_from_selected_attention_norm_input_or_output") => {
            "none_from_selected_pre_rope_attention_norm_input_or_output"
        }
        _ => "selected_pre_rope_attention_norm_source_context_missing",
    }
}

fn attention_selected_pre_rope_attention_norm_history_source(
    projection_history_source: &Value,
    reference_records: &[ReferenceTraceRecord],
    rust_records: &BTreeMap<String, RustTraceRecord>,
    model_path: Option<&Path>,
) -> Value {
    let selected_source_rows = projection_history_source
        .pointer("/rows")
        .and_then(Value::as_array)
        .map(|rows| {
            rows.iter()
                .filter(|row| {
                    row.pointer("/classification").and_then(Value::as_str)
                        == Some("selected_pre_rope_projection_history_replay_explains_pair_delta")
                })
                .cloned()
                .collect::<Vec<_>>()
        })
        .unwrap_or_default();
    let translated_rows = selected_source_rows
        .iter()
        .map(|row| {
            let mut translated = row.clone();
            if let Some(object) = translated.as_object_mut() {
                object.insert(
                    "classification".to_string(),
                    json!("selected_historical_k_projection_replay_explains_raw_epsilon"),
                );
            }
            translated
        })
        .collect::<Vec<_>>();
    let translated_source = json!({
        "rows": translated_rows,
    });
    let mut report = attention_selected_historical_k_attention_norm_source(
        &translated_source,
        reference_records,
        rust_records,
        model_path,
    );

    let classification = report
        .pointer("/classification")
        .and_then(Value::as_str)
        .map(pre_rope_attention_norm_source_classification)
        .unwrap_or("selected_pre_rope_attention_norm_history_source_unpinned");
    if let Some(object) = report.as_object_mut() {
        object.insert(
            "policy".to_string(),
            json!("Selected pre-RoPE attention-norm history source is diagnostic-only evidence for whether the K projection replay-explained pre-RoPE pair delta is already present at attention RMSNorm input or output for the selected token/dim; it does not change RMSNorm, QK256, ROPE, score-input, or runtime math and does not promote reference parity, A770 semantic quality, attention score residency, selected attention, resident KV, full residency, performance, or completion"),
        );
        object.insert("classification".to_string(), json!(classification));
        object.insert(
            "source_report".to_string(),
            json!("attention_selected_pre_rope_projection_history_source"),
        );
        object.insert(
            "next_diagnostic".to_string(),
            json!(pre_rope_attention_norm_source_next_diagnostic(classification)),
        );
        if let Some(rows) = object.get_mut("rows").and_then(Value::as_array_mut) {
            for (index, row) in rows.iter_mut().enumerate() {
                let source_row = selected_source_rows.get(index);
                if let Some(row_object) = row.as_object_mut() {
                    let row_classification = row_object
                        .get("classification")
                        .and_then(Value::as_str)
                        .map(pre_rope_attention_norm_source_classification)
                        .unwrap_or("selected_pre_rope_attention_norm_history_source_unpinned");
                    row_object.insert("classification".to_string(), json!(row_classification));
                    row_object.insert(
                        "runtime_change_candidate".to_string(),
                        json!(pre_rope_attention_norm_runtime_candidate(
                            row_object.get("runtime_change_candidate").and_then(Value::as_str)
                        )),
                    );
                    row_object.insert(
                        "source_report".to_string(),
                        json!("attention_selected_pre_rope_projection_history_source"),
                    );
                    if let Some(source_row) = source_row {
                        row_object.insert(
                            "dominant_projection_pair_delta".to_string(),
                            source_row
                                .pointer("/dominant_projection_pair_delta")
                                .cloned()
                                .unwrap_or(Value::Null),
                        );
                        row_object.insert(
                            "target_delta_rust_minus_reference".to_string(),
                            source_row
                                .pointer("/target_delta_rust_minus_reference")
                                .cloned()
                                .unwrap_or(Value::Null),
                        );
                        row_object.insert(
                            "replay_delta_rust_minus_reference".to_string(),
                            source_row
                                .pointer("/replay_delta_rust_minus_reference")
                                .cloned()
                                .unwrap_or(Value::Null),
                        );
                        row_object.insert(
                            "replay_delta_minus_target_delta".to_string(),
                            source_row
                                .pointer("/replay_delta_minus_target_delta")
                                .cloned()
                                .unwrap_or(Value::Null),
                        );
                        row_object.insert(
                            "overall_projection_dim".to_string(),
                            source_row
                                .pointer("/overall_projection_dim")
                                .cloned()
                                .unwrap_or(Value::Null),
                        );
                        row_object.insert(
                            "target_head_dim".to_string(),
                            source_row.pointer("/target_head_dim").cloned().unwrap_or(Value::Null),
                        );
                        row_object.insert(
                            "pre_rope_projection_history_source_row".to_string(),
                            source_row.clone(),
                        );
                    }
                }
            }
        }
    }

    report
}

fn attention_selected_historical_k_attention_norm_source(
    projection_replay_source: &Value,
    reference_records: &[ReferenceTraceRecord],
    rust_records: &BTreeMap<String, RustTraceRecord>,
    model_path: Option<&Path>,
) -> Value {
    let source_rows = projection_replay_source.pointer("/rows").and_then(Value::as_array);
    let reference_layer = Some(0_i64);
    let rust_layer = Some(0_isize);
    let reference_input = reference_records.iter().find(|record| {
        record.layer == reference_layer
            && record.stage == "attn_norm_input_history_ref_layout"
            && record.values_available
            && !record.first_values.is_empty()
    });
    let reference_output = reference_records.iter().find(|record| {
        record.layer == reference_layer
            && record.stage == "attn_norm_history_ref_layout"
            && record.values_available
            && !record.first_values.is_empty()
    });
    let rust_input = rust_records
        .get("attention_norm_input_history_ref_layout")
        .filter(|record| record.layer == rust_layer)
        .filter(|record| !record.first_values.is_empty());
    let rust_output = rust_records
        .get("attention_v_input_history_ref_layout")
        .filter(|record| record.layer == rust_layer)
        .filter(|record| !record.first_values.is_empty());

    let hidden = reference_input
        .and_then(|record| dim_major_dim_count(record).ok())
        .or_else(|| reference_output.and_then(|record| dim_major_dim_count(record).ok()));
    let weight_name = "blk.0.attn_norm.weight";
    let mut weight_load_error = Value::Null;
    let loaded_weight = match (model_path, hidden) {
        (Some(path), Some(hidden)) if path.is_file() => {
            match load_rmsnorm_weight(path, weight_name, hidden) {
                Ok(weight) => Some(weight),
                Err(err) => {
                    weight_load_error = json!(err.to_string());
                    None
                }
            }
        }
        _ => None,
    };
    let variants = loaded_weight
        .as_ref()
        .map(|weight| rmsnorm_replay_variants(weight.eps, &weight.eps_source))
        .unwrap_or_default();

    let mut rows = Vec::<Value>::new();
    let mut selected_count = 0usize;
    let mut compared_count = 0usize;
    let mut missing_context_count = 0usize;
    let mut input_history_epsilon_count = 0usize;
    let mut output_replay_explained_count = 0usize;
    let mut output_replay_unpinned_count = 0usize;
    let mut output_clean_count = 0usize;
    let mut max_input_abs_delta = 0.0f64;
    let mut max_output_abs_delta = 0.0f64;

    if let Some(source_rows) = source_rows {
        for source_row in source_rows {
            if source_row.pointer("/classification").and_then(Value::as_str)
                != Some("selected_historical_k_projection_replay_explains_raw_epsilon")
            {
                continue;
            }
            selected_count += 1;

            let key_slot = source_row
                .pointer("/key_slot")
                .and_then(Value::as_u64)
                .and_then(|value| usize::try_from(value).ok());
            let selected_dim = source_row
                .pointer("/dominant_projection_input_dim")
                .and_then(Value::as_u64)
                .and_then(|value| usize::try_from(value).ok());
            let mut blocked_reasons = Vec::<String>::new();

            if model_path.is_none() {
                blocked_reasons
                    .push("model_path_missing_for_selected_attention_norm_replay".to_string());
            } else if model_path.is_some_and(|path| !path.is_file()) {
                blocked_reasons
                    .push("model_gguf_missing_for_selected_attention_norm_replay".to_string());
            }
            if weight_load_error != Value::Null {
                blocked_reasons.push("attention_norm_weight_load_failed".to_string());
            }
            if reference_input.is_none() {
                blocked_reasons.push("reference_attention_norm_input_history_missing".to_string());
            }
            if rust_input.is_none() {
                blocked_reasons.push("rust_attention_norm_input_history_missing".to_string());
            }
            if reference_output.is_none() {
                blocked_reasons.push("reference_attention_norm_output_history_missing".to_string());
            }
            if rust_output.is_none() {
                blocked_reasons.push("rust_attention_norm_output_history_missing".to_string());
            }
            if key_slot.is_none() {
                blocked_reasons.push("selected_key_slot_missing".to_string());
            }
            if selected_dim.is_none() {
                blocked_reasons.push("selected_k_output_dim_missing".to_string());
            }
            if loaded_weight.is_none() {
                blocked_reasons
                    .push("attention_norm_weight_unavailable_for_selected_replay".to_string());
            }

            let reference_input_value = reference_input.zip(selected_dim).zip(key_slot).and_then(
                |((record, dim), token)| {
                    let dim_count = dim_major_dim_count(record).ok()?;
                    let token_count = dim_major_token_count(record).ok()?;
                    dim_major_value(&record.first_values, dim_count, token_count, dim, token)
                },
            );
            let rust_input_value =
                rust_input.zip(selected_dim).zip(key_slot).and_then(|((record, dim), token)| {
                    let dim_count = record.shape.first().copied()?;
                    let token_count = record.shape.get(1).copied()?;
                    dim_major_value(&record.first_values, dim_count, token_count, dim, token)
                });
            let reference_output_value = reference_output.zip(selected_dim).zip(key_slot).and_then(
                |((record, dim), token)| {
                    let dim_count = dim_major_dim_count(record).ok()?;
                    let token_count = dim_major_token_count(record).ok()?;
                    dim_major_value(&record.first_values, dim_count, token_count, dim, token)
                },
            );
            let rust_output_value =
                rust_output.zip(selected_dim).zip(key_slot).and_then(|((record, dim), token)| {
                    let dim_count = record.shape.first().copied()?;
                    let token_count = record.shape.get(1).copied()?;
                    dim_major_value(&record.first_values, dim_count, token_count, dim, token)
                });

            if reference_input_value.is_none() {
                blocked_reasons
                    .push("reference_selected_attention_norm_input_value_missing".to_string());
            }
            if rust_input_value.is_none() {
                blocked_reasons
                    .push("rust_selected_attention_norm_input_value_missing".to_string());
            }
            if reference_output_value.is_none() {
                blocked_reasons
                    .push("reference_selected_attention_norm_output_value_missing".to_string());
            }
            if rust_output_value.is_none() {
                blocked_reasons
                    .push("rust_selected_attention_norm_output_value_missing".to_string());
            }

            let same_index_input_delta =
                scalar_f16_bucket_delta(reference_input_value, rust_input_value);
            let same_index_output_delta =
                scalar_f16_bucket_delta(reference_output_value, rust_output_value);

            let reference_input_token = reference_input
                .zip(key_slot)
                .and_then(|(record, token)| reference_dim_major_token(record, token).ok());
            let rust_input_token = rust_input
                .zip(key_slot)
                .and_then(|(record, token)| rust_dim_major_token(record, token).ok());
            let reference_output_token = reference_output
                .zip(key_slot)
                .and_then(|(record, token)| reference_dim_major_token(record, token).ok());
            let rust_output_token = rust_output
                .zip(key_slot)
                .and_then(|(record, token)| rust_dim_major_token(record, token).ok());
            let input_delta = reference_input_token
                .as_ref()
                .zip(rust_input_token.as_ref())
                .map(|(reference, rust)| compare_vectors(reference, rust))
                .unwrap_or(Value::Null);
            let output_delta = reference_output_token
                .as_ref()
                .zip(rust_output_token.as_ref())
                .map(|(reference, rust)| compare_vectors(reference, rust))
                .unwrap_or(Value::Null);
            let output_f16_delta = reference_output_token
                .as_ref()
                .zip(rust_output_token.as_ref())
                .map(|(reference, rust)| f16_bucket_delta(reference, rust))
                .unwrap_or(Value::Null);
            max_input_abs_delta =
                max_input_abs_delta.max(delta_metric(&input_delta, "/max_abs_delta"));
            max_output_abs_delta =
                max_output_abs_delta.max(delta_metric(&output_delta, "/max_abs_delta"));

            let reference_input_replay = match (
                loaded_weight.as_ref(),
                reference_input_token.as_deref(),
                reference_output_token.as_deref(),
            ) {
                (Some(weight), Some(input), Some(target)) => rmsnorm_replay_section(
                    "reference_selected_attention_norm_input_history_token",
                    input,
                    &weight.values,
                    &variants,
                    Some(target),
                    rust_output_token.as_deref(),
                )
                .unwrap_or_else(|err| {
                    json!({
                        "status": "rmsnorm_replay_error",
                        "error": err.to_string(),
                    })
                }),
                _ => Value::Null,
            };
            let rust_input_replay = match (
                loaded_weight.as_ref(),
                rust_input_token.as_deref(),
                rust_output_token.as_deref(),
            ) {
                (Some(weight), Some(input), Some(target)) => rmsnorm_replay_section(
                    "rust_selected_attention_norm_input_history_token",
                    input,
                    &weight.values,
                    &variants,
                    reference_output_token.as_deref(),
                    Some(target),
                )
                .unwrap_or_else(|err| {
                    json!({
                        "status": "rmsnorm_replay_error",
                        "error": err.to_string(),
                    })
                }),
                _ => Value::Null,
            };
            let accumulation_rule_probe = match (
                loaded_weight.as_ref(),
                reference_input_token.as_deref(),
                rust_input_token.as_deref(),
                reference_output_token.as_deref(),
                rust_output_token.as_deref(),
            ) {
                (
                    Some(weight),
                    Some(reference_input_token),
                    Some(rust_input_token),
                    Some(reference_output_token),
                    Some(rust_output_token),
                ) => attention_norm_accumulation_rule_probe(
                    weight,
                    reference_input_token,
                    rust_input_token,
                    reference_output_token,
                    rust_output_token,
                )
                .unwrap_or_else(|err| {
                    json!({
                        "status": "accumulation_rule_probe_error",
                        "error": err.to_string(),
                    })
                }),
                _ => Value::Null,
            };
            let reference_replay_delta = reference_input_replay
                .pointer("/best_vs_reference_target/max_abs_delta")
                .and_then(Value::as_f64);
            let rust_replay_delta = rust_input_replay
                .pointer("/best_vs_rust_target/max_abs_delta")
                .and_then(Value::as_f64);
            let replay_explains_targets = reference_replay_delta
                .is_some_and(|delta| delta <= 1.0e-6)
                && rust_replay_delta.is_some_and(|delta| delta <= 1.0e-6);
            let input_delta_present = delta_has_any_numeric_delta(&input_delta);
            let output_delta_present = delta_has_any_numeric_delta(&output_delta);

            let row_classification = if !blocked_reasons.is_empty() {
                missing_context_count += 1;
                "selected_historical_k_attention_norm_source_missing_context"
            } else if input_delta_present {
                input_history_epsilon_count += 1;
                "selected_historical_k_attention_norm_source_input_history_epsilon"
            } else if output_delta_present && replay_explains_targets {
                output_replay_explained_count += 1;
                "selected_historical_k_attention_norm_source_output_replay_explains_epsilon"
            } else if output_delta_present {
                output_replay_unpinned_count += 1;
                "selected_historical_k_attention_norm_source_output_epsilon_unpinned"
            } else {
                output_clean_count += 1;
                "selected_historical_k_attention_norm_source_clean"
            };
            if blocked_reasons.is_empty() {
                compared_count += 1;
            }

            rows.push(json!({
                "classification": row_classification,
                "head": source_row.pointer("/head").cloned().unwrap_or(Value::Null),
                "kv_head": source_row.pointer("/kv_head").cloned().unwrap_or(Value::Null),
                "key_slot": key_slot,
                "query_token": source_row.pointer("/query_token").cloned().unwrap_or(Value::Null),
                "dominant_projection_input": source_row.pointer("/dominant_projection_input").cloned().unwrap_or(Value::Null),
                "selected_k_output_dim": selected_dim,
                "blocked_reasons": blocked_reasons,
                "reference_input_stage": "attn_norm_input_history_ref_layout",
                "rust_input_stage": "attention_norm_input_history_ref_layout",
                "reference_output_stage": "attn_norm_history_ref_layout",
                "rust_output_stage": "attention_v_input_history_ref_layout",
                "same_index_attention_norm_input_reference_value": reference_input_value,
                "same_index_attention_norm_input_rust_value": rust_input_value,
                "same_index_attention_norm_output_reference_value": reference_output_value,
                "same_index_attention_norm_output_rust_value": rust_output_value,
                "same_index_input_delta": same_index_input_delta,
                "same_index_output_delta": same_index_output_delta,
                "input_delta": input_delta,
                "output_delta": output_delta,
                "output_f16_delta": output_f16_delta,
                "reference_input_replay": reference_input_replay,
                "rust_input_replay": rust_input_replay,
                "reference_replay_best_delta": reference_replay_delta,
                "rust_replay_best_delta": rust_replay_delta,
                "replay_explains_targets": replay_explains_targets,
                "accumulation_rule_probe": accumulation_rule_probe,
                "runtime_change_candidate": match row_classification {
                    "selected_historical_k_attention_norm_source_input_history_epsilon" => {
                        "localize_attention_norm_input_history_before_changing_rmsnorm_or_k_projection"
                    }
                    "selected_historical_k_attention_norm_source_output_replay_explains_epsilon" => {
                        "pin_attention_rmsnorm_accumulation_or_serialization_policy"
                    }
                    "selected_historical_k_attention_norm_source_output_epsilon_unpinned" => {
                        "pin_attention_norm_replay_delta_before_runtime_change"
                    }
                    "selected_historical_k_attention_norm_source_clean" => {
                        "none_from_selected_attention_norm_input_or_output"
                    }
                    _ => "selected_attention_norm_source_context_missing",
                },
            }));
        }
    }

    let classification = if selected_count == 0 {
        "no_selected_k_projection_replay_explained_rows"
    } else if missing_context_count == selected_count {
        "selected_historical_k_attention_norm_source_missing_context"
    } else if input_history_epsilon_count > 0 {
        "selected_historical_k_attention_norm_source_input_history_epsilon"
    } else if output_replay_explained_count > 0 && output_replay_unpinned_count == 0 {
        "selected_historical_k_attention_norm_source_output_replay_explains_epsilon"
    } else if output_replay_unpinned_count > 0 {
        "selected_historical_k_attention_norm_source_output_epsilon_unpinned"
    } else if output_clean_count > 0 {
        "selected_historical_k_attention_norm_source_clean"
    } else {
        "selected_historical_k_attention_norm_source_unpinned"
    };
    let next_diagnostic = match classification {
        "selected_historical_k_attention_norm_source_input_history_epsilon" => {
            "localize selected attention-norm input-history epsilon before changing RMSNorm, K projection, QK256, or RoPE runtime math"
        }
        "selected_historical_k_attention_norm_source_output_replay_explains_epsilon" => {
            "pin whether attention RMSNorm accumulation or trace serialization explains the selected K projection source epsilon"
        }
        "selected_historical_k_attention_norm_source_output_epsilon_unpinned" => {
            "capture enough attention RMSNorm replay context to explain selected output epsilon before changing runtime math"
        }
        "selected_historical_k_attention_norm_source_missing_context" => {
            "capture model and full attention-norm input/output histories before selected K attention-norm attribution"
        }
        "no_selected_k_projection_replay_explained_rows" => {
            "pin selected K projection replay source before attention-norm attribution"
        }
        "selected_historical_k_attention_norm_source_clean" => {
            "selected attention-norm source is clean; inspect upstream selection or downstream score residual before runtime math changes"
        }
        _ => "keep selected historical K attention-norm source diagnostic-only",
    };

    json!({
        "diagnostic_only": true,
        "claim_allowed": false,
        "policy": "Selected historical K attention-norm source is diagnostic-only evidence for whether the K projection replay epsilon is already present at attention RMSNorm input or output for the selected token/dim; it does not change RMSNorm, QK256, RoPE, score-input, or runtime math and does not promote reference parity, A770 semantic quality, attention score residency, selected attention, resident KV, full residency, performance, or completion",
        "classification": classification,
        "selected_count": selected_count,
        "compared_count": compared_count,
        "missing_context_count": missing_context_count,
        "input_history_epsilon_count": input_history_epsilon_count,
        "output_replay_explained_count": output_replay_explained_count,
        "output_replay_unpinned_count": output_replay_unpinned_count,
        "output_clean_count": output_clean_count,
        "max_input_abs_delta": max_input_abs_delta,
        "max_output_abs_delta": max_output_abs_delta,
        "model": model_path.map(|path| json!({
            "path": path_to_string(path),
            "exists": path.is_file(),
        })).unwrap_or(Value::Null),
        "weight_name": weight_name,
        "weight": loaded_weight.map(|weight| weight.weight_report).unwrap_or(Value::Null),
        "weight_load_error": weight_load_error,
        "rows": rows,
        "next_diagnostic": next_diagnostic,
    })
}

fn attention_selected_historical_k_attention_norm_f64_effect(
    selected_source: &Value,
    reference_records: &[ReferenceTraceRecord],
    baseline_rust_records: &BTreeMap<String, RustTraceRecord>,
    f64_rust_records: &BTreeMap<String, RustTraceRecord>,
) -> Value {
    let source_rows = selected_source.pointer("/rows").and_then(Value::as_array);
    let reference_output = reference_records.iter().find(|record| {
        record.layer == Some(0)
            && record.stage == "attn_norm_history_ref_layout"
            && record.values_available
            && !record.first_values.is_empty()
    });
    let baseline_output = baseline_rust_records
        .get("attention_v_input_history_ref_layout")
        .filter(|record| record.layer == Some(0))
        .filter(|record| !record.first_values.is_empty());
    let f64_output = f64_rust_records
        .get("attention_v_input_history_ref_layout")
        .filter(|record| record.layer == Some(0))
        .filter(|record| !record.first_values.is_empty());

    let mut rows = Vec::<Value>::new();
    let mut selected_count = 0usize;
    let mut compared_count = 0usize;
    let mut missing_context_count = 0usize;
    let mut f64_improves_count = 0usize;
    let mut f64_clears_bucket_count = 0usize;
    let mut f64_residual_count = 0usize;
    let mut f64_not_better_count = 0usize;
    let mut max_baseline_abs_delta = 0.0f64;
    let mut max_f64_abs_delta = 0.0f64;

    if let Some(source_rows) = source_rows {
        for source_row in source_rows {
            if source_row.pointer("/classification").and_then(Value::as_str)
                != Some(
                    "selected_historical_k_attention_norm_source_output_replay_explains_epsilon",
                )
            {
                continue;
            }
            selected_count += 1;

            let key_slot = source_row
                .pointer("/key_slot")
                .and_then(Value::as_u64)
                .and_then(|value| usize::try_from(value).ok());
            let mut blocked_reasons = Vec::<String>::new();
            if reference_output.is_none() {
                blocked_reasons.push("reference_attention_norm_output_history_missing".to_string());
            }
            if baseline_output.is_none() {
                blocked_reasons.push("baseline_attention_norm_output_history_missing".to_string());
            }
            if f64_output.is_none() {
                blocked_reasons.push("f64_attention_norm_output_history_missing".to_string());
            }
            if key_slot.is_none() {
                blocked_reasons.push("selected_key_slot_missing".to_string());
            }

            let reference_token = reference_output
                .zip(key_slot)
                .and_then(|(record, token)| reference_dim_major_token(record, token).ok());
            let baseline_token = baseline_output
                .zip(key_slot)
                .and_then(|(record, token)| rust_dim_major_token(record, token).ok());
            let f64_token = f64_output
                .zip(key_slot)
                .and_then(|(record, token)| rust_dim_major_token(record, token).ok());
            if reference_token.is_none() {
                blocked_reasons
                    .push("reference_selected_attention_norm_output_token_missing".to_string());
            }
            if baseline_token.is_none() {
                blocked_reasons
                    .push("baseline_selected_attention_norm_output_token_missing".to_string());
            }
            if f64_token.is_none() {
                blocked_reasons
                    .push("f64_selected_attention_norm_output_token_missing".to_string());
            }

            let baseline_delta = reference_token
                .as_ref()
                .zip(baseline_token.as_ref())
                .map(|(reference, baseline)| compare_vectors(reference, baseline))
                .unwrap_or(Value::Null);
            let f64_delta = reference_token
                .as_ref()
                .zip(f64_token.as_ref())
                .map(|(reference, f64)| compare_vectors(reference, f64))
                .unwrap_or(Value::Null);
            let baseline_f16_delta = reference_token
                .as_ref()
                .zip(baseline_token.as_ref())
                .map(|(reference, baseline)| f16_bucket_delta(reference, baseline))
                .unwrap_or(Value::Null);
            let f64_f16_delta = reference_token
                .as_ref()
                .zip(f64_token.as_ref())
                .map(|(reference, f64)| f16_bucket_delta(reference, f64))
                .unwrap_or(Value::Null);
            let baseline_max = delta_metric(&baseline_delta, "/max_abs_delta");
            let f64_max = delta_metric(&f64_delta, "/max_abs_delta");
            max_baseline_abs_delta = max_baseline_abs_delta.max(baseline_max);
            max_f64_abs_delta = max_f64_abs_delta.max(f64_max);
            let baseline_bucket_mismatches = f16_bucket_mismatch_count(&baseline_f16_delta);
            let f64_bucket_mismatches = f16_bucket_mismatch_count(&f64_f16_delta);
            let f64_improves = blocked_reasons.is_empty() && f64_max < baseline_max;
            let f64_clears_bucket = blocked_reasons.is_empty()
                && baseline_bucket_mismatches > 0
                && f64_bucket_mismatches == 0;

            let row_classification = if !blocked_reasons.is_empty() {
                missing_context_count += 1;
                "selected_historical_k_attention_norm_f64_effect_missing_context"
            } else if f64_clears_bucket && f64_max > 0.0 {
                f64_improves_count += usize::from(f64_improves);
                f64_clears_bucket_count += 1;
                f64_residual_count += 1;
                "selected_historical_k_attention_norm_f64_effect_clears_bucket_with_residual"
            } else if f64_clears_bucket {
                f64_improves_count += usize::from(f64_improves);
                f64_clears_bucket_count += 1;
                "selected_historical_k_attention_norm_f64_effect_clears_bucket_exact"
            } else if f64_improves {
                f64_improves_count += 1;
                f64_residual_count += 1;
                "selected_historical_k_attention_norm_f64_effect_improves_but_bucket_remains"
            } else {
                f64_not_better_count += 1;
                "selected_historical_k_attention_norm_f64_effect_not_better"
            };
            if blocked_reasons.is_empty() {
                compared_count += 1;
            }

            rows.push(json!({
                "classification": row_classification,
                "head": source_row.pointer("/head").cloned().unwrap_or(Value::Null),
                "kv_head": source_row.pointer("/kv_head").cloned().unwrap_or(Value::Null),
                "key_slot": key_slot,
                "query_token": source_row.pointer("/query_token").cloned().unwrap_or(Value::Null),
                "selected_k_output_dim": source_row.pointer("/selected_k_output_dim").cloned().unwrap_or(Value::Null),
                "blocked_reasons": blocked_reasons,
                "reference_output_stage": "attn_norm_history_ref_layout",
                "baseline_output_stage": "attention_v_input_history_ref_layout",
                "f64_output_stage": "attention_v_input_history_ref_layout",
                "baseline_delta": baseline_delta,
                "f64_delta": f64_delta,
                "baseline_f16_delta": baseline_f16_delta,
                "f64_f16_delta": f64_f16_delta,
                "baseline_max_abs_delta": baseline_max,
                "f64_max_abs_delta": f64_max,
                "baseline_f16_bucket_mismatch_count": baseline_bucket_mismatches,
                "f64_f16_bucket_mismatch_count": f64_bucket_mismatches,
                "f64_improves": f64_improves,
                "f64_clears_bucket": f64_clears_bucket,
                "runtime_change_candidate": match row_classification {
                    "selected_historical_k_attention_norm_f64_effect_clears_bucket_with_residual" => {
                        "attention_rmsnorm_f64_accumulation_clears_selected_bucket_but_residual_trace_delta_remains"
                    }
                    "selected_historical_k_attention_norm_f64_effect_clears_bucket_exact" => {
                        "attention_rmsnorm_f64_accumulation_matches_selected_reference_output"
                    }
                    "selected_historical_k_attention_norm_f64_effect_improves_but_bucket_remains" => {
                        "attention_rmsnorm_f64_accumulation_improves_selected_output_but_not_enough"
                    }
                    "selected_historical_k_attention_norm_f64_effect_not_better" => {
                        "attention_rmsnorm_f64_accumulation_does_not_explain_selected_output"
                    }
                    _ => "selected_attention_norm_f64_effect_context_missing",
                },
            }));
        }
    }

    let classification = if selected_count == 0 {
        "no_selected_attention_norm_source_output_replay_rows"
    } else if missing_context_count == selected_count {
        "selected_historical_k_attention_norm_f64_effect_missing_context"
    } else if f64_clears_bucket_count > 0 && f64_residual_count > 0 {
        "selected_historical_k_attention_norm_f64_effect_clears_bucket_with_residual"
    } else if f64_clears_bucket_count > 0 {
        "selected_historical_k_attention_norm_f64_effect_clears_bucket_exact"
    } else if f64_improves_count > 0 {
        "selected_historical_k_attention_norm_f64_effect_improves_but_bucket_remains"
    } else if f64_not_better_count > 0 {
        "selected_historical_k_attention_norm_f64_effect_not_better"
    } else {
        "selected_historical_k_attention_norm_f64_effect_unpinned"
    };
    let next_diagnostic = match classification {
        "selected_historical_k_attention_norm_f64_effect_clears_bucket_with_residual" => {
            "localize the remaining f64 downstream residual before promoting any production RMSNorm runtime change"
        }
        "selected_historical_k_attention_norm_f64_effect_clears_bucket_exact" => {
            "rerun downstream score and value-mix diagnostics under f64 RMSNorm before changing production math"
        }
        "selected_historical_k_attention_norm_f64_effect_improves_but_bucket_remains" => {
            "pin the remaining selected attention-norm output bucket mismatch before runtime changes"
        }
        "selected_historical_k_attention_norm_f64_effect_not_better" => {
            "do not change RMSNorm accumulation; inspect trace serialization or another selected source"
        }
        "selected_historical_k_attention_norm_f64_effect_missing_context" => {
            "capture matching baseline and f64 attention-norm output histories before selected f64 attribution"
        }
        "no_selected_attention_norm_source_output_replay_rows" => {
            "pin selected K attention-norm source before f64 effect attribution"
        }
        _ => "keep selected K f64 attention-norm effect diagnostic-only",
    };

    json!({
        "diagnostic_only": true,
        "claim_allowed": false,
        "policy": "Selected historical K attention-norm f64 effect is diagnostic-only evidence for whether BITNET_DIAG_RMSNORM_F64_ACCUM clears the selected attention-norm output bucket drift; it does not change production RMSNorm, QK256, RoPE, score-input, or runtime math and does not promote reference parity, A770 semantic quality, attention score residency, selected attention, resident KV, full residency, performance, or completion",
        "classification": classification,
        "selected_count": selected_count,
        "compared_count": compared_count,
        "missing_context_count": missing_context_count,
        "f64_improves_count": f64_improves_count,
        "f64_clears_bucket_count": f64_clears_bucket_count,
        "f64_residual_count": f64_residual_count,
        "f64_not_better_count": f64_not_better_count,
        "max_baseline_abs_delta": max_baseline_abs_delta,
        "max_f64_abs_delta": max_f64_abs_delta,
        "rows": rows,
        "next_diagnostic": next_diagnostic,
    })
}

fn pre_rope_attention_norm_f64_effect_classification(classification: &str) -> &'static str {
    match classification {
        "no_selected_attention_norm_source_output_replay_rows" => {
            "no_selected_pre_rope_attention_norm_output_replay_rows"
        }
        "selected_historical_k_attention_norm_f64_effect_missing_context" => {
            "selected_pre_rope_attention_norm_f64_effect_missing_context"
        }
        "selected_historical_k_attention_norm_f64_effect_clears_bucket_with_residual" => {
            "selected_pre_rope_attention_norm_f64_effect_clears_bucket_with_residual"
        }
        "selected_historical_k_attention_norm_f64_effect_clears_bucket_exact" => {
            "selected_pre_rope_attention_norm_f64_effect_clears_bucket_exact"
        }
        "selected_historical_k_attention_norm_f64_effect_improves_but_bucket_remains" => {
            "selected_pre_rope_attention_norm_f64_effect_improves_but_bucket_remains"
        }
        "selected_historical_k_attention_norm_f64_effect_not_better" => {
            "selected_pre_rope_attention_norm_f64_effect_not_better"
        }
        _ => "selected_pre_rope_attention_norm_f64_effect_unpinned",
    }
}

