fn attention_f64_score_history_residual(
    selected_pre_rope_f64_residual: &Value,
    f64_downstream: &Value,
) -> Value {
    let downstream_frontier = f64_downstream.pointer("/residual_frontier").unwrap_or(&Value::Null);
    let probability_effect =
        f64_downstream.pointer("/f64/probability_history_effect").unwrap_or(&Value::Null);
    let score_history_frontier =
        probability_effect.pointer("/score_history_residual_frontier").unwrap_or(&Value::Null);
    let value_mix_attribution =
        f64_downstream.pointer("/f64/value_mix_history_attribution").unwrap_or(&Value::Null);
    let source_summary = value_mix_attribution.pointer("/source_summary").unwrap_or(&Value::Null);
    let probability_source_summary = value_mix_attribution
        .pointer("/probability_history_source_summary")
        .unwrap_or(&Value::Null);

    let selected_residual_classification =
        selected_pre_rope_f64_residual.pointer("/classification").and_then(Value::as_str);
    let downstream_frontier_classification =
        downstream_frontier.pointer("/classification").and_then(Value::as_str);
    let score_history_frontier_classification =
        score_history_frontier.pointer("/classification").and_then(Value::as_str);
    let value_mix_source_classification =
        source_summary.pointer("/classification").and_then(Value::as_str);
    let probability_source_classification =
        probability_source_summary.pointer("/classification").and_then(Value::as_str);

    let selected_count = value_u64(selected_pre_rope_f64_residual, "/selected_count").unwrap_or(0);
    let selected_residual_count =
        value_u64(selected_pre_rope_f64_residual, "/residual_count").unwrap_or(0);
    let score_raw_history_material_count =
        value_u64(probability_effect, "/score_raw_history_material_count").unwrap_or(0);
    let score_raw_live_material_count =
        value_u64(probability_effect, "/score_raw_live_material_count").unwrap_or(0);
    let score_raw_history_missing_count =
        value_u64(probability_effect, "/score_raw_history_missing_count").unwrap_or(0);
    let probability_history_material_count =
        value_u64(probability_effect, "/probability_history_material_count").unwrap_or(0);
    let probability_history_missing_count =
        value_u64(probability_effect, "/probability_history_missing_count").unwrap_or(0);
    let score_frontier_missing_inputs =
        value_u64(score_history_frontier, "/missing_inputs").unwrap_or(0);
    let score_frontier_raw_material =
        value_u64(score_history_frontier, "/raw_material_mismatch_count").unwrap_or(0);
    let score_frontier_raw_live_material =
        value_u64(score_history_frontier, "/raw_live_material_mismatch_count").unwrap_or(0);

    let probability_source_drift =
        value_bool(source_summary, "/probability_source_drift_present").unwrap_or(false);
    let value_cache_source_drift =
        value_bool(source_summary, "/value_cache_source_drift_present").unwrap_or(false);
    let value_cache_source_clean =
        value_bool(source_summary, "/value_cache_source_clean").unwrap_or(false);
    let rust_self_recompute_drift =
        value_bool(source_summary, "/rust_self_recompute_drift_present").unwrap_or(false);
    let rust_self_recompute_explained =
        value_bool(source_summary, "/rust_self_recompute_explained_by_numeric_variants")
            .unwrap_or(false);

    let selected_points_to_score_history = selected_residual_classification
        == Some("selected_pre_rope_attention_norm_f64_residual_score_history_drives_value_mix");
    let downstream_points_to_score_history = matches!(
        downstream_frontier_classification,
        Some("f64_downstream_residual_frontier_score_history_drives_value_mix")
            | Some("f64_downstream_residual_frontier_score_history")
    );
    let score_history_context_present = !score_history_frontier.is_null()
        || score_raw_history_material_count > 0
        || score_raw_live_material_count > 0
        || probability_history_material_count > 0;

    let classification = if selected_count == 0
        || selected_residual_classification
            == Some("selected_pre_rope_attention_norm_f64_residual_missing_context")
        || downstream_frontier_classification
            == Some("f64_downstream_residual_frontier_capture_not_cleared")
        || (!selected_points_to_score_history
            && !downstream_points_to_score_history
            && !score_history_context_present)
        || score_history_frontier_classification
            == Some("f64_score_history_frontier_missing_inputs")
        || score_frontier_missing_inputs > 0
        || score_raw_history_missing_count > 0
        || probability_history_missing_count > 0
    {
        "f64_score_history_residual_missing_context"
    } else if value_cache_source_drift {
        "f64_score_history_residual_value_cache_source"
    } else if matches!(
        score_history_frontier_classification,
        Some("f64_score_history_frontier_qk_score_input_history_bucket_drift")
            | Some("f64_score_history_frontier_qk_score_input_history_numeric_drift")
            | Some("f64_score_history_frontier_current_key_score_input_drift")
    ) {
        "f64_score_history_residual_score_input"
    } else if matches!(
        score_history_frontier_classification,
        Some("f64_score_history_frontier_qk_f16_probe_residual")
            | Some("f64_score_history_frontier_raw_score_residual_unpinned")
    ) || score_frontier_raw_material > 0
        || score_frontier_raw_live_material > 0
        || score_raw_history_material_count > 0
        || score_raw_live_material_count > 0
    {
        "f64_score_history_residual_score_accumulation"
    } else if probability_history_material_count > 0 || probability_source_drift {
        "f64_score_history_residual_softmax_probability"
    } else if rust_self_recompute_drift && rust_self_recompute_explained {
        "f64_score_history_residual_value_mix_numeric"
    } else if score_history_frontier_classification == Some("f64_score_history_frontier_clean")
        && downstream_frontier_classification == Some("f64_downstream_residual_frontier_clear")
    {
        "f64_score_history_residual_clean"
    } else {
        "f64_score_history_residual_unpinned"
    };

    json!({
        "diagnostic_only": true,
        "claim_allowed": false,
        "policy": "F64 score-history residual report bridges the selected pre-RoPE f64 residual to raw score history, probability history, and value-mix input attribution; it is diagnostic-only and does not make f64 RMSNorm a production default or promote reference parity, A770 semantic quality, attention score residency, softmax residency, value-mix residency, selected attention, resident KV, full residency, performance, or completion",
        "classification": classification,
        "selected_residual_classification": selected_residual_classification,
        "selected_count": selected_count,
        "selected_residual_count": selected_residual_count,
        "downstream_frontier_classification": downstream_frontier_classification,
        "score_history_frontier_classification": score_history_frontier_classification,
        "value_mix_source_classification": value_mix_source_classification,
        "probability_source_classification": probability_source_classification,
        "score_raw_history_material_count": score_raw_history_material_count,
        "score_raw_live_material_count": score_raw_live_material_count,
        "score_raw_history_missing_count": score_raw_history_missing_count,
        "probability_history_material_count": probability_history_material_count,
        "probability_history_missing_count": probability_history_missing_count,
        "score_frontier_missing_inputs": score_frontier_missing_inputs,
        "score_frontier_raw_material_count": score_frontier_raw_material,
        "score_frontier_raw_live_material_count": score_frontier_raw_live_material,
        "probability_source_drift_present": probability_source_drift,
        "value_cache_source_drift_present": value_cache_source_drift,
        "value_cache_source_clean": value_cache_source_clean,
        "rust_self_recompute_drift_present": rust_self_recompute_drift,
        "rust_self_recompute_explained_by_numeric_variants": rust_self_recompute_explained,
        "first_selected_pre_rope_residual_row": compact_selected_pre_rope_f64_residual_context_row(selected_pre_rope_f64_residual.pointer("/rows/0").unwrap_or(&Value::Null)),
        "first_material_score_head": compact_head_delta_row(score_history_frontier.pointer("/first_material_score_head").unwrap_or(&Value::Null)),
        "first_live_material_score_head": compact_head_delta_row(score_history_frontier.pointer("/first_live_material_score_head").unwrap_or(&Value::Null)),
        "first_material_key_history_head": compact_head_delta_row(score_history_frontier.pointer("/first_material_key_history_head").unwrap_or(&Value::Null)),
        "first_material_query_history_head": compact_head_delta_row(score_history_frontier.pointer("/first_material_query_history_head").unwrap_or(&Value::Null)),
        "first_probability_history_head": compact_head_delta_row(probability_effect.pointer("/probability_history_delta/first_material_head").unwrap_or(&Value::Null)),
        "first_material_target_row": compact_f64_score_history_context_row(source_summary.pointer("/first_material_target_row").unwrap_or(&Value::Null)),
        "first_material_probability_source_row": compact_f64_score_history_context_row(source_summary.pointer("/first_material_probability_source_row").unwrap_or(&Value::Null)),
        "first_material_score_source_row": compact_f64_score_history_context_row(probability_source_summary.pointer("/first_material_score_source_row").unwrap_or(&Value::Null)),
        "first_material_rust_self_recompute_row": compact_f64_score_history_context_row(source_summary.pointer("/first_material_rust_self_recompute_row").unwrap_or(&Value::Null)),
        "current_blocked_reasons": f64_downstream.pointer("/current_blocked_reasons").cloned().unwrap_or(Value::Null),
        "next_diagnostic": f64_score_history_residual_next_diagnostic(classification),
    })
}

fn f64_qk_score_input_bucket_residual_next_diagnostic(classification: &str) -> &'static str {
    match classification {
        "f64_qk_score_input_bucket_residual_selected_query_history" => {
            "localize the selected query score-input history bucket before changing score accumulation, softmax, value-mix, or RMSNorm production math"
        }
        "f64_qk_score_input_bucket_residual_selected_key_history" => {
            "localize the selected key score-input history bucket before changing score accumulation, softmax, value-mix, or RMSNorm production math"
        }
        "f64_qk_score_input_bucket_residual_selected_qk_history" => {
            "split selected Q and K score-input history buckets before changing score accumulation, softmax, value-mix, or RMSNorm production math"
        }
        "f64_qk_score_input_bucket_residual_query_history" => {
            "localize f64 query score-input history bucket drift before changing score accumulation or softmax"
        }
        "f64_qk_score_input_bucket_residual_key_history" => {
            "localize f64 key score-input history bucket drift before changing score accumulation or softmax"
        }
        "f64_qk_score_input_bucket_residual_qk_history" => {
            "separate f64 query and key score-input history bucket drift before changing score accumulation or softmax"
        }
        "f64_qk_score_input_bucket_residual_current_key" => {
            "localize current key score-input drift before changing score accumulation or softmax"
        }
        "f64_qk_score_input_bucket_residual_numeric_no_bucket" => {
            "pin f64 Q/K score-input numeric drift without bucket crossings before changing score accumulation"
        }
        "f64_qk_score_input_bucket_residual_clean" => {
            "Q/K score-input bucket residual is clean; rerun raw score and probability residual attribution"
        }
        "f64_qk_score_input_bucket_residual_missing_context" => {
            "capture selected score-position Q/K history buckets and score frontier context before changing runtime math"
        }
        _ => {
            "keep f64 Q/K score-input bucket residual diagnostic-only until one operand side is pinned"
        }
    }
}

fn attention_f64_qk_score_input_bucket_residual(
    f64_score_history_residual: &Value,
    f64_downstream: &Value,
) -> Value {
    let probability_effect =
        f64_downstream.pointer("/f64/probability_history_effect").unwrap_or(&Value::Null);
    let score_history_frontier =
        probability_effect.pointer("/score_history_residual_frontier").unwrap_or(&Value::Null);
    let score_qk_bucket_frontier =
        probability_effect.pointer("/score_qk_bucket_frontier").unwrap_or(&Value::Null);

    let residual_classification =
        f64_score_history_residual.pointer("/classification").and_then(Value::as_str);
    let score_history_frontier_classification =
        score_history_frontier.pointer("/classification").and_then(Value::as_str);
    let qk_bucket_frontier_classification =
        score_qk_bucket_frontier.pointer("/classification").and_then(Value::as_str);

    let selected_key_bucket_hit_count =
        value_u64(score_qk_bucket_frontier, "/selected_key_bucket_hit_count").unwrap_or(0);
    let selected_query_bucket_hit_count =
        value_u64(score_qk_bucket_frontier, "/selected_query_bucket_hit_count").unwrap_or(0);
    let selected_position_count =
        value_u64(score_qk_bucket_frontier, "/selected_position_count").unwrap_or(0);
    let selected_missing_input_count =
        value_u64(score_qk_bucket_frontier, "/missing_input_count").unwrap_or(0);
    let key_history_total =
        value_u64(score_qk_bucket_frontier, "/key_history_total_f16_bucket_mismatch_count")
            .or_else(|| value_u64(score_history_frontier, "/key_history_f16_bucket_mismatch_count"))
            .unwrap_or(0);
    let query_history_total =
        value_u64(score_qk_bucket_frontier, "/query_history_total_f16_bucket_mismatch_count")
            .or_else(|| {
                value_u64(score_history_frontier, "/query_history_f16_bucket_mismatch_count")
            })
            .unwrap_or(0);
    let key_history_max_abs =
        value_f64(score_history_frontier, "/key_history_max_abs_delta").unwrap_or(0.0);
    let query_history_max_abs =
        value_f64(score_history_frontier, "/query_history_max_abs_delta").unwrap_or(0.0);
    let key_current_max_abs =
        value_f64(score_history_frontier, "/key_current_max_abs_delta").unwrap_or(0.0);
    let score_frontier_missing_inputs =
        value_u64(score_history_frontier, "/missing_inputs").unwrap_or(0);
    let residual_missing_context =
        residual_classification == Some("f64_score_history_residual_missing_context");
    let first_selected_query_bucket_row = score_qk_bucket_frontier
        .pointer("/selected_rows")
        .and_then(Value::as_array)
        .and_then(|rows| {
            rows.iter().find(|row| {
                value_u64(row, "/query_history_f16_bucket_count_at_query_token").unwrap_or(0) > 0
            })
        })
        .unwrap_or(&Value::Null);
    let first_selected_key_bucket_row = score_qk_bucket_frontier
        .pointer("/selected_rows")
        .and_then(Value::as_array)
        .and_then(|rows| {
            rows.iter().find(|row| {
                value_u64(row, "/key_history_f16_bucket_count_at_key_slot").unwrap_or(0) > 0
            })
        })
        .unwrap_or(&Value::Null);

    let classification = if residual_missing_context
        || residual_classification != Some("f64_score_history_residual_score_input")
        || selected_missing_input_count > 0
        || score_frontier_missing_inputs > 0
        || score_history_frontier_classification
            == Some("f64_score_history_frontier_missing_inputs")
    {
        "f64_qk_score_input_bucket_residual_missing_context"
    } else if selected_query_bucket_hit_count > 0 && selected_key_bucket_hit_count > 0 {
        "f64_qk_score_input_bucket_residual_selected_qk_history"
    } else if selected_query_bucket_hit_count > 0 {
        "f64_qk_score_input_bucket_residual_selected_query_history"
    } else if selected_key_bucket_hit_count > 0 {
        "f64_qk_score_input_bucket_residual_selected_key_history"
    } else if query_history_total > 0 && key_history_total > 0 {
        "f64_qk_score_input_bucket_residual_qk_history"
    } else if query_history_total > 0 {
        "f64_qk_score_input_bucket_residual_query_history"
    } else if key_history_total > 0 {
        "f64_qk_score_input_bucket_residual_key_history"
    } else if score_history_frontier_classification
        == Some("f64_score_history_frontier_current_key_score_input_drift")
        || key_current_max_abs > 1.0e-6
    {
        "f64_qk_score_input_bucket_residual_current_key"
    } else if score_history_frontier_classification
        == Some("f64_score_history_frontier_qk_score_input_history_numeric_drift")
        || key_history_max_abs > 1.0e-6
        || query_history_max_abs > 1.0e-6
    {
        "f64_qk_score_input_bucket_residual_numeric_no_bucket"
    } else if score_history_frontier_classification == Some("f64_score_history_frontier_clean") {
        "f64_qk_score_input_bucket_residual_clean"
    } else {
        "f64_qk_score_input_bucket_residual_unpinned"
    };

    json!({
        "diagnostic_only": true,
        "claim_allowed": false,
        "policy": "F64 Q/K score-input bucket residual is diagnostic-only evidence for separating the f64 raw score-history residual into selected query history, selected key history, broader Q/K history, current key, numeric-no-bucket, or missing-context cases; it does not change runtime math and does not promote reference parity, A770 semantic quality, attention score residency, selected attention, resident KV, softmax residency, value-mix residency, full residency, performance, or completion",
        "classification": classification,
        "f64_score_history_residual_classification": residual_classification,
        "score_history_frontier_classification": score_history_frontier_classification,
        "qk_bucket_frontier_classification": qk_bucket_frontier_classification,
        "selected_position_count": selected_position_count,
        "selected_missing_input_count": selected_missing_input_count,
        "selected_key_bucket_hit_count": selected_key_bucket_hit_count,
        "selected_query_bucket_hit_count": selected_query_bucket_hit_count,
        "key_history_total_f16_bucket_mismatch_count": key_history_total,
        "query_history_total_f16_bucket_mismatch_count": query_history_total,
        "key_history_max_abs_delta": key_history_max_abs,
        "query_history_max_abs_delta": query_history_max_abs,
        "key_current_max_abs_delta": key_current_max_abs,
        "score_frontier_missing_inputs": score_frontier_missing_inputs,
        "score_position_classification": score_qk_bucket_frontier.pointer("/score_position_classification").cloned().unwrap_or(Value::Null),
        "score_position_first_material": compact_f64_score_history_context_row(score_qk_bucket_frontier.pointer("/score_position_first_material").unwrap_or(&Value::Null)),
        "score_position_max_material": compact_f64_score_history_context_row(score_qk_bucket_frontier.pointer("/score_position_max_material").unwrap_or(&Value::Null)),
        "candidate_delta_summary": compact_candidate_delta_summary(score_qk_bucket_frontier.pointer("/candidate_delta_summary").unwrap_or(&Value::Null)),
        "first_selected_qk_bucket_row": compact_selected_qk_bucket_row(score_qk_bucket_frontier.pointer("/selected_rows/0").unwrap_or(&Value::Null)),
        "first_selected_query_bucket_row": compact_selected_qk_bucket_row(first_selected_query_bucket_row),
        "first_selected_key_bucket_row": compact_selected_qk_bucket_row(first_selected_key_bucket_row),
        "first_material_key_history_head": compact_head_delta_row(score_history_frontier.pointer("/first_material_key_history_head").unwrap_or(&Value::Null)),
        "first_material_query_history_head": compact_head_delta_row(score_history_frontier.pointer("/first_material_query_history_head").unwrap_or(&Value::Null)),
        "first_material_score_head": compact_head_delta_row(score_history_frontier.pointer("/first_material_score_head").unwrap_or(&Value::Null)),
        "next_diagnostic": f64_qk_score_input_bucket_residual_next_diagnostic(classification),
    })
}

fn selected_query_score_input_bucket_source_next_diagnostic(classification: &str) -> &'static str {
    match classification {
        "selected_query_score_input_bucket_source_reference_to_rope" => {
            "localize selected query pre-score RoPE input/projection history before changing score accumulation, softmax, value-mix, or RMSNorm production math"
        }
        "selected_query_score_input_bucket_source_f16_conversion" => {
            "pin selected query RoPE-to-F16 score-input conversion before changing score accumulation or softmax"
        }
        "selected_query_score_input_bucket_source_score_input_serialization" => {
            "pin selected query score-input serialization after F16 conversion before changing score accumulation or softmax"
        }
        "selected_query_score_input_bucket_source_reference_to_score_unexplained" => {
            "split selected query reference-to-score drift across RoPE, F16 conversion, and serialization before changing runtime math"
        }
        "selected_query_score_input_bucket_source_dim_token_context_unpinned" => {
            "emit selected query dim/token source probes before changing score accumulation or softmax"
        }
        "selected_query_score_input_bucket_source_head_boundary_unpinned" => {
            "localize selected query head boundary rows before changing score accumulation or softmax"
        }
        "selected_query_score_input_bucket_source_clean" => {
            "selected query score-input bucket source is clean; rerun f64 score residual attribution"
        }
        "selected_query_score_input_bucket_source_missing_context" => {
            "capture selected query score-input boundary rows before changing runtime math"
        }
        _ => {
            "keep selected query score-input bucket source diagnostic-only until the boundary is pinned"
        }
    }
}

fn selected_query_boundary_summary(
    boundary_delta: &Value,
    selected_dim: Option<u64>,
    selected_token: Option<u64>,
) -> Value {
    if boundary_delta.is_null() {
        return json!({
            "status": "missing_boundary",
            "selected_dim": selected_dim,
            "selected_token": selected_token,
        });
    }

    let status = boundary_delta.pointer("/status").and_then(Value::as_str).unwrap_or("unknown");
    let material_mismatch =
        boundary_delta.pointer("/material_mismatch").and_then(Value::as_bool).unwrap_or(false);
    let delta = boundary_delta.pointer("/delta").unwrap_or(&Value::Null);
    let first_bucket = delta
        .pointer("/first_f16_bucket_mismatch_layout")
        .or_else(|| delta.pointer("/first_f16_bucket_mismatch"))
        .cloned()
        .unwrap_or(Value::Null);
    let exact_selected_bucket = selected_dim.is_some()
        && selected_token.is_some()
        && first_bucket.pointer("/dim").and_then(Value::as_u64) == selected_dim
        && first_bucket.pointer("/token").and_then(Value::as_u64) == selected_token;
    let selected_token_mismatch_row = selected_token
        .and_then(|selected_token| {
            delta
                .pointer("/token_mismatch_counts")
                .and_then(Value::as_array)?
                .iter()
                .find(|token| {
                    token.pointer("/token").and_then(Value::as_u64) == Some(selected_token)
                })
                .cloned()
        })
        .unwrap_or(Value::Null);
    let selected_dim_mismatch_row = selected_dim
        .and_then(|selected_dim| {
            delta
                .pointer("/dim_mismatch_counts")
                .and_then(Value::as_array)?
                .iter()
                .find(|dim| dim.pointer("/dim").and_then(Value::as_u64) == Some(selected_dim))
                .cloned()
        })
        .unwrap_or(Value::Null);
    let selected_token_bucket = !selected_token_mismatch_row.is_null();
    let selected_dim_bucket = !selected_dim_mismatch_row.is_null();
    let selected_dim_and_token_bucket = selected_token_bucket && selected_dim_bucket;

    json!({
        "status": status,
        "material_mismatch": material_mismatch,
        "selected_dim": selected_dim,
        "selected_token": selected_token,
        "exact_selected_bucket": exact_selected_bucket,
        "selected_token_bucket": selected_token_bucket,
        "selected_dim_bucket": selected_dim_bucket,
        "selected_dim_and_token_bucket": selected_dim_and_token_bucket,
        "selected_token_mismatch_row": selected_token_mismatch_row,
        "selected_dim_mismatch_row": selected_dim_mismatch_row,
        "first_f16_bucket_mismatch_layout": first_bucket,
        "max_abs_delta": delta.pointer("/max_abs_delta").cloned().unwrap_or(Value::Null),
        "rms_abs_delta": delta.pointer("/rms_abs_delta").cloned().unwrap_or(Value::Null),
    })
}

fn selected_query_score_source_row_has_context(row: &Value) -> bool {
    value_u64(row, "/head").is_some()
        && value_u64(row, "/query_token").is_some()
        && (value_u64(row, "/product_delta/top_contributors/0/dim").is_some()
            || value_u64(row, "/product_delta/top_abs_product_delta_contributors/0/dim").is_some()
            || value_u64(row, "/top_abs_product_delta_contributors/0/dim").is_some())
}

fn selected_query_score_source_row_has_head_boundary_context(row: &Value) -> bool {
    value_u64(row, "/head").is_some()
        && value_u64(row, "/query_token").is_some()
        && row.pointer("/query_score_input_boundary").is_some_and(|boundary| {
            !boundary.is_null()
                && boundary.pointer("/first_material_boundary").and_then(Value::as_str).is_some()
        })
}

fn selected_query_mixed_score_report_context_row(report: &Value) -> Option<&Value> {
    let first_row = report.pointer("/first_product_row").unwrap_or(&Value::Null);
    if selected_query_score_source_row_has_context(first_row)
        || selected_query_score_source_row_has_head_boundary_context(first_row)
    {
        return Some(first_row);
    }
    report.pointer("/rows").and_then(Value::as_array).and_then(|rows| {
        rows.iter().find(|row| {
            selected_query_score_source_row_has_context(row)
                || selected_query_score_source_row_has_head_boundary_context(row)
        })
    })
}

fn attention_selected_f64_query_score_input_bucket_source(
    f64_qk_score_input_bucket_residual: &Value,
    f64_downstream: &Value,
    base_comparison: &Value,
) -> Value {
    let probability_effect =
        f64_downstream.pointer("/f64/probability_history_effect").unwrap_or(&Value::Null);
    let f64_query_boundary = probability_effect.pointer("/query_boundary").unwrap_or(&Value::Null);
    let base_query_boundary =
        base_comparison.pointer("/attention_query_score_input_boundary").unwrap_or(&Value::Null);
    let f64_mixed_qk = probability_effect
        .pointer("/attention_selected_score_mixed_qk_contribution")
        .unwrap_or(&Value::Null);
    let base_mixed_qk = base_comparison
        .pointer("/attention_selected_score_mixed_qk_contribution")
        .unwrap_or(&Value::Null);
    let f64_mixed_row = selected_query_mixed_score_report_context_row(f64_mixed_qk);
    let base_mixed_row = selected_query_mixed_score_report_context_row(base_mixed_qk);
    let (mixed_qk, mixed_score_position_row) = if let Some(row) = f64_mixed_row {
        (f64_mixed_qk, row)
    } else if let Some(row) = base_mixed_row {
        (base_mixed_qk, row)
    } else if !f64_mixed_qk.is_null() {
        (f64_mixed_qk, f64_mixed_qk.pointer("/first_product_row").unwrap_or(&Value::Null))
    } else {
        (base_mixed_qk, base_mixed_qk.pointer("/first_product_row").unwrap_or(&Value::Null))
    };
    let mixed_qk_classification = mixed_qk.pointer("/classification").and_then(Value::as_str);
    let residual_classification =
        f64_qk_score_input_bucket_residual.pointer("/classification").and_then(Value::as_str);
    let selected_query_bucket_row = f64_qk_score_input_bucket_residual
        .pointer("/first_selected_query_bucket_row")
        .filter(|row| selected_query_score_source_row_has_context(row));
    let selected_qk_bucket_row = f64_qk_score_input_bucket_residual
        .pointer("/first_selected_qk_bucket_row")
        .filter(|row| selected_query_score_source_row_has_context(row));
    let mixed_context_available =
        matches!(
            mixed_qk_classification,
            Some("selected_score_drift_query_dominant")
                | Some("selected_score_drift_query_dominant_with_query_rope_boundary")
                | Some("selected_score_drift_has_mixed_qk_contribution")
                | Some("selected_score_drift_split_query_key_contribution")
                | Some("selected_score_product_delta_clean")
        ) && (selected_query_score_source_row_has_context(mixed_score_position_row)
            || selected_query_score_source_row_has_head_boundary_context(mixed_score_position_row));
    let selected_row = selected_query_bucket_row
        .or(selected_qk_bucket_row)
        .or_else(|| mixed_context_available.then_some(mixed_score_position_row))
        .unwrap_or(&Value::Null);
    let selected_row_source = if selected_query_bucket_row.is_some() {
        "f64_qk_residual_query_bucket_row"
    } else if selected_qk_bucket_row.is_some() {
        "f64_qk_residual_qk_bucket_row"
    } else if mixed_context_available {
        "mixed_score_position_row"
    } else {
        "missing_selected_row"
    };
    let head = selected_row.pointer("/head").and_then(Value::as_u64);
    let selected_token = selected_row.pointer("/query_token").and_then(Value::as_u64);
    let selected_dim = selected_row
        .pointer("/product_delta/top_contributors/0/dim")
        .or_else(|| selected_row.pointer("/product_delta/top_abs_product_delta_contributors/0/dim"))
        .or_else(|| selected_row.pointer("/top_abs_product_delta_contributors/0/dim"))
        .and_then(Value::as_u64);
    let f64_query_boundary_row =
        head.and_then(|head| query_boundary_row_for_head(f64_query_boundary, head));
    let selected_nested_query_boundary_row = selected_row.pointer("/query_score_input_boundary");
    let base_query_boundary_row =
        head.and_then(|head| query_boundary_row_for_head(base_query_boundary, head));
    let (query_boundary_source, query_boundary_row) = [
        ("f64_probability_effect_query_boundary", f64_query_boundary_row),
        ("selected_score_position_query_boundary", selected_nested_query_boundary_row),
        ("base_attention_query_score_input_boundary", base_query_boundary_row),
    ]
    .iter()
    .copied()
    .find(|(_, row)| row.is_some_and(query_boundary_row_has_compared_delta))
    .or_else(|| {
        [
            ("f64_probability_effect_query_boundary", f64_query_boundary_row),
            ("selected_score_position_query_boundary", selected_nested_query_boundary_row),
            ("base_attention_query_score_input_boundary", base_query_boundary_row),
        ]
        .iter()
        .copied()
        .find(|(_, row)| row.is_some_and(query_boundary_row_has_usable_context))
    })
    .unwrap_or(("missing_query_boundary", None));
    let query_boundary_row = query_boundary_row.unwrap_or(&Value::Null);

    let reference_to_rope = selected_query_boundary_summary(
        query_boundary_row.pointer("/reference_to_rust_rope_delta").unwrap_or(&Value::Null),
        selected_dim,
        selected_token,
    );
    let rope_to_f16 = selected_query_boundary_summary(
        query_boundary_row.pointer("/rust_rope_to_f16_delta").unwrap_or(&Value::Null),
        selected_dim,
        selected_token,
    );
    let f16_to_score = selected_query_boundary_summary(
        query_boundary_row.pointer("/rust_f16_to_score_input_delta").unwrap_or(&Value::Null),
        selected_dim,
        selected_token,
    );
    let reference_to_score = selected_query_boundary_summary(
        query_boundary_row.pointer("/reference_to_score_input_delta").unwrap_or(&Value::Null),
        selected_dim,
        selected_token,
    );

    let boundary_missing =
        query_boundary_row.is_null() || head.is_none() || selected_token.is_none();
    let exact_reference_to_rope =
        value_bool(&reference_to_rope, "/exact_selected_bucket").unwrap_or(false);
    let exact_rope_to_f16 = value_bool(&rope_to_f16, "/exact_selected_bucket").unwrap_or(false);
    let exact_f16_to_score = value_bool(&f16_to_score, "/exact_selected_bucket").unwrap_or(false);
    let exact_reference_to_score =
        value_bool(&reference_to_score, "/exact_selected_bucket").unwrap_or(false);
    let selected_dim_token_context =
        [&reference_to_rope, &rope_to_f16, &f16_to_score, &reference_to_score].iter().any(
            |summary| {
                value_bool(summary, "/selected_dim_and_token_bucket").unwrap_or(false)
                    || (value_bool(summary, "/selected_dim_bucket").unwrap_or(false)
                        && value_bool(summary, "/selected_token_bucket").unwrap_or(false))
            },
        );
    let head_boundary_material = query_boundary_row
        .pointer("/first_material_boundary")
        .and_then(Value::as_str)
        .is_some_and(|boundary| boundary != "none" && boundary != "missing_input");

    let source_context_available = residual_classification
        == Some("f64_qk_score_input_bucket_residual_selected_query_history")
        || mixed_context_available;
    let classification = if !source_context_available || boundary_missing {
        "selected_query_score_input_bucket_source_missing_context"
    } else if exact_reference_to_rope {
        "selected_query_score_input_bucket_source_reference_to_rope"
    } else if exact_rope_to_f16 {
        "selected_query_score_input_bucket_source_f16_conversion"
    } else if exact_f16_to_score {
        "selected_query_score_input_bucket_source_score_input_serialization"
    } else if exact_reference_to_score {
        "selected_query_score_input_bucket_source_reference_to_score_unexplained"
    } else if selected_dim_token_context {
        "selected_query_score_input_bucket_source_dim_token_context_unpinned"
    } else if head_boundary_material {
        "selected_query_score_input_bucket_source_head_boundary_unpinned"
    } else if query_boundary_row.pointer("/first_material_boundary").and_then(Value::as_str)
        == Some("none")
    {
        "selected_query_score_input_bucket_source_clean"
    } else {
        "selected_query_score_input_bucket_source_unpinned"
    };

    json!({
        "diagnostic_only": true,
        "claim_allowed": false,
        "policy": "Selected f64 query score-input bucket source is diagnostic-only evidence for localizing the selected query-side bucket to reference-to-Rust RoPE, Rust F16 conversion, score-input serialization, or unresolved query boundary context; it does not change runtime math and does not promote reference parity, A770 semantic quality, attention score residency, selected attention, resident KV, softmax residency, value-mix residency, full residency, performance, or completion",
        "classification": classification,
        "f64_qk_score_input_bucket_residual_classification": residual_classification,
        "head": head,
        "selected_dim": selected_dim,
        "selected_token": selected_token,
        "query_boundary_present": !query_boundary_row.is_null(),
        "query_boundary_source": query_boundary_source,
        "query_boundary_first_material_boundary": query_boundary_row.pointer("/first_material_boundary").cloned().unwrap_or(Value::Null),
        "selected_qk_bucket_row": selected_row.clone(),
        "selected_row_source": selected_row_source,
        "mixed_score_position_classification": mixed_qk_classification,
        "mixed_score_position_row": compact_selected_score_product_row(mixed_score_position_row),
        "reference_to_rust_rope": reference_to_rope,
        "rust_rope_to_f16": rope_to_f16,
        "rust_f16_to_score_input": f16_to_score,
        "reference_to_score_input": reference_to_score,
        "next_diagnostic": selected_query_score_input_bucket_source_next_diagnostic(classification),
    })
}

fn selected_query_score_input_candidate_policy_next_diagnostic(
    classification: &str,
) -> &'static str {
    match classification {
        "selected_query_score_input_candidate_policy_reference_q_f16_rust_q_f32" => {
            "capture the selected query boundary rows for the reference q-F16 vs Rust q-F32 candidate policy before changing score-input policy"
        }
        "selected_query_score_input_candidate_policy_reference_q_f32_rust_q_f16" => {
            "capture the selected query boundary rows for the reference q-F32 vs Rust q-F16 candidate policy before changing score-input policy"
        }
        "selected_query_score_input_candidate_policy_query_policy_unpinned" => {
            "pin whether the selected query candidate-policy delta is projection, RoPE, F16 conversion, or score-input serialization"
        }
        "selected_query_score_input_candidate_policy_key_policy" => {
            "follow key-side candidate-policy attribution before changing query-side score-input policy"
        }
        "selected_query_score_input_candidate_policy_mixed_qk_policy" => {
            "separate selected query and key candidate-policy deltas before changing score accumulation"
        }
        "selected_query_score_input_candidate_policy_same_policy_residual" => {
            "replay selected raw QK score accumulation because candidate score-input policies match"
        }
        "selected_query_score_input_candidate_policy_clean" => {
            "selected query candidate-policy frontier is clean; rerun downstream score residual attribution"
        }
        "selected_query_score_input_candidate_policy_missing_context" => {
            "capture selected query score-position product-delta candidate context before changing runtime math"
        }
        _ => "keep selected query score-input candidate policy diagnostic-only",
    }
}

fn selected_query_candidate_product_context_present(product_delta: &Value) -> bool {
    if product_delta.is_null() {
        return false;
    }
    let top_contributor_present = product_delta
        .pointer("/top_abs_product_delta_contributors/0")
        .or_else(|| product_delta.pointer("/top_contributors/0"))
        .is_some_and(|row| !row.is_null());
    top_contributor_present
        && product_delta.pointer("/dominant_input").and_then(Value::as_str).is_some()
        && product_delta.pointer("/reference_query_source").and_then(Value::as_str).is_some()
        && product_delta.pointer("/rust_query_source").and_then(Value::as_str).is_some()
        && product_delta.pointer("/reference_key_source").and_then(Value::as_str).is_some()
        && product_delta.pointer("/rust_key_source").and_then(Value::as_str).is_some()
}

fn attention_selected_query_score_input_candidate_policy_frontier(
    selected_query_source: &Value,
) -> Value {
    let primary_selected_row =
        selected_query_source.pointer("/selected_qk_bucket_row").unwrap_or(&Value::Null);
    let mixed_score_row =
        selected_query_source.pointer("/mixed_score_position_row").unwrap_or(&Value::Null);
    let primary_product_delta =
        primary_selected_row.pointer("/product_delta").unwrap_or(&Value::Null);
    let mixed_product_delta = mixed_score_row.pointer("/product_delta").unwrap_or(&Value::Null);
    let mixed_context_present =
        selected_query_candidate_product_context_present(mixed_product_delta);
    let primary_context_present =
        selected_query_candidate_product_context_present(primary_product_delta);
    let (selected_row, selected_row_context_source) =
        if !primary_context_present && mixed_context_present {
            (mixed_score_row, "mixed_score_position_row_candidate_context")
        } else {
            (primary_selected_row, "selected_qk_bucket_row")
        };
    let product_delta = selected_row.pointer("/product_delta").unwrap_or(&Value::Null);
    let top_contributor = product_delta
        .pointer("/top_abs_product_delta_contributors/0")
        .or_else(|| product_delta.pointer("/top_contributors/0"))
        .unwrap_or(&Value::Null);
    let source_classification =
        selected_query_source.pointer("/classification").and_then(Value::as_str);
    let dominant_input = product_delta.pointer("/dominant_input").and_then(Value::as_str);
    let reference_query_source =
        product_delta.pointer("/reference_query_source").and_then(Value::as_str);
    let rust_query_source = product_delta.pointer("/rust_query_source").and_then(Value::as_str);
    let reference_key_source =
        product_delta.pointer("/reference_key_source").and_then(Value::as_str);
    let rust_key_source = product_delta.pointer("/rust_key_source").and_then(Value::as_str);
    let reference_query_f16 =
        value_bool(product_delta, "/reference_query_f16_roundtrip").unwrap_or(false);
    let rust_query_f16 = value_bool(product_delta, "/rust_query_f16_roundtrip").unwrap_or(false);
    let reference_key_f16 =
        value_bool(product_delta, "/reference_key_f16_roundtrip").unwrap_or(false);
    let rust_key_f16 = value_bool(product_delta, "/rust_key_f16_roundtrip").unwrap_or(false);
    let query_changed_dim_count = value_u64(product_delta, "/query_changed_dim_count").unwrap_or(0);
    let key_changed_dim_count = value_u64(product_delta, "/key_changed_dim_count").unwrap_or(0);
    let material_product_delta_count =
        value_u64(product_delta, "/material_product_delta_count").unwrap_or(0);
    let max_abs_product_delta = value_f64(product_delta, "/max_abs_product_delta").unwrap_or(0.0);
    let same_query_source =
        reference_query_source.is_some() && reference_query_source == rust_query_source;
    let same_key_source = reference_key_source.is_some() && reference_key_source == rust_key_source;
    let same_query_policy = same_query_source && reference_query_f16 == rust_query_f16;
    let same_key_policy = same_key_source && reference_key_f16 == rust_key_f16;
    let product_context_present = selected_query_candidate_product_context_present(product_delta);

    let classification = if !product_context_present {
        "selected_query_score_input_candidate_policy_missing_context"
    } else if material_product_delta_count == 0
        || max_abs_product_delta == 0.0
        || dominant_input == Some("none")
    {
        "selected_query_score_input_candidate_policy_clean"
    } else if dominant_input == Some("query")
        && same_query_source
        && same_key_source
        && same_key_policy
        && key_changed_dim_count == 0
        && query_changed_dim_count > 0
        && reference_query_f16
        && !rust_query_f16
    {
        "selected_query_score_input_candidate_policy_reference_q_f16_rust_q_f32"
    } else if dominant_input == Some("query")
        && same_query_source
        && same_key_source
        && same_key_policy
        && key_changed_dim_count == 0
        && query_changed_dim_count > 0
        && !reference_query_f16
        && rust_query_f16
    {
        "selected_query_score_input_candidate_policy_reference_q_f32_rust_q_f16"
    } else if dominant_input == Some("query") && !same_query_policy {
        "selected_query_score_input_candidate_policy_query_policy_unpinned"
    } else if dominant_input == Some("key")
        || (key_changed_dim_count > 0 && query_changed_dim_count == 0)
    {
        "selected_query_score_input_candidate_policy_key_policy"
    } else if dominant_input == Some("query_and_key")
        || (query_changed_dim_count > 0 && key_changed_dim_count > 0)
    {
        "selected_query_score_input_candidate_policy_mixed_qk_policy"
    } else if same_query_policy && same_key_policy {
        "selected_query_score_input_candidate_policy_same_policy_residual"
    } else {
        "selected_query_score_input_candidate_policy_query_policy_unpinned"
    };

    let blocked_reasons =
        if classification == "selected_query_score_input_candidate_policy_missing_context" {
            json!(["selected_query_score_input_candidate_policy_missing_context"])
        } else {
            json!([])
        };

    json!({
        "diagnostic_only": true,
        "claim_allowed": false,
        "policy": "Selected query score-input candidate-policy frontier is diagnostic-only evidence for summarizing whether the selected query-side score residual is explained by candidate score-input policy differences such as q-F16 versus q-F32 operands; it does not change RMSNorm, QK256, RoPE, F16 score-input conversion, score accumulation, softmax, value-mix, or runtime math and does not promote reference parity, A770 semantic quality, attention score residency, selected attention, resident KV, full residency, performance, or completion",
        "classification": classification,
        "source_report": "attention_selected_f64_query_score_input_bucket_source",
        "source_classification": source_classification,
        "head": value_u64(selected_query_source, "/head"),
        "selected_dim": value_u64(selected_query_source, "/selected_dim"),
        "selected_token": value_u64(selected_query_source, "/selected_token"),
        "key_slot": value_u64(selected_row, "/key_slot"),
        "selected_row_source": selected_query_source.pointer("/selected_row_source").cloned().unwrap_or(Value::Null),
        "selected_row_context_source": selected_row_context_source,
        "dominant_input": dominant_input,
        "reference_score_input_variant": product_delta.pointer("/reference_score_input_variant").cloned().unwrap_or(Value::Null),
        "rust_score_input_variant": product_delta.pointer("/rust_score_input_variant").cloned().unwrap_or(Value::Null),
        "reference_query_source": reference_query_source,
        "rust_query_source": rust_query_source,
        "reference_key_source": reference_key_source,
        "rust_key_source": rust_key_source,
        "reference_query_f16_roundtrip": reference_query_f16,
        "rust_query_f16_roundtrip": rust_query_f16,
        "reference_key_f16_roundtrip": reference_key_f16,
        "rust_key_f16_roundtrip": rust_key_f16,
        "same_query_source": same_query_source,
        "same_key_source": same_key_source,
        "same_query_policy": same_query_policy,
        "same_key_policy": same_key_policy,
        "query_changed_dim_count": query_changed_dim_count,
        "key_changed_dim_count": key_changed_dim_count,
        "material_product_delta_count": material_product_delta_count,
        "max_abs_product_delta": product_delta.pointer("/max_abs_product_delta").cloned().unwrap_or(Value::Null),
        "product_abs_delta_sum": product_delta.pointer("/product_abs_delta_sum").cloned().unwrap_or(Value::Null),
        "product_signed_delta_sum": product_delta.pointer("/product_signed_delta_sum").cloned().unwrap_or(Value::Null),
        "top_contributor": top_contributor.clone(),
        "product_context_present": product_context_present,
        "blocked_reasons": blocked_reasons,
        "next_diagnostic": selected_query_score_input_candidate_policy_next_diagnostic(classification),
    })
}

fn selected_query_candidate_policy_boundary_next_diagnostic(classification: &str) -> &'static str {
    match classification {
        "selected_query_score_input_candidate_policy_boundary_reference_q_f16_rust_q_f32" => {
            "capture or bind the selected reference q-F16 and Rust q-F32 query operands to the exact raw score input before changing score-input policy"
        }
        "selected_query_score_input_candidate_policy_boundary_reference_q_f32_rust_q_f16" => {
            "capture or bind the selected reference q-F32 and Rust q-F16 query operands to the exact raw score input before changing score-input policy"
        }
        "selected_query_score_input_candidate_policy_boundary_query_policy_unpinned" => {
            "pin selected query candidate-policy operands against query boundary rows before changing score-input policy"
        }
        "selected_query_score_input_candidate_policy_boundary_rows_missing" => {
            "capture selected query boundary rows for the active candidate score-input policy before changing runtime math"
        }
        "selected_query_score_input_candidate_policy_boundary_clean" => {
            "selected query candidate-policy boundary is clean; rerun downstream score residual attribution"
        }
        "selected_query_score_input_candidate_policy_boundary_not_active" => {
            "follow the active candidate-policy classification before capturing selected query policy boundary rows"
        }
        "selected_query_score_input_candidate_policy_boundary_missing_context" => {
            "capture selected query candidate product contributors and query boundary rows before changing runtime math"
        }
        _ => "keep selected query candidate-policy boundary diagnostic-only",
    }
}

fn selected_query_candidate_policy_boundary_summary(source: &Value, key: &str) -> Value {
    let boundary = source.pointer(key).unwrap_or(&Value::Null);
    if boundary.is_null() {
        return json!({
            "status": "missing_boundary",
            "exact_selected_bucket": false,
            "selected_dim_and_token_bucket": false,
        });
    }

    json!({
        "status": boundary.pointer("/status").cloned().unwrap_or(Value::Null),
        "material_mismatch": value_bool(boundary, "/material_mismatch").unwrap_or(false),
        "exact_selected_bucket": value_bool(boundary, "/exact_selected_bucket").unwrap_or(false),
        "selected_dim_bucket": value_bool(boundary, "/selected_dim_bucket").unwrap_or(false),
        "selected_token_bucket": value_bool(boundary, "/selected_token_bucket").unwrap_or(false),
        "selected_dim_and_token_bucket": value_bool(boundary, "/selected_dim_and_token_bucket").unwrap_or(false),
        "max_abs_delta": boundary.pointer("/max_abs_delta").cloned().unwrap_or(Value::Null),
        "first_f16_bucket_mismatch_layout": boundary.pointer("/first_f16_bucket_mismatch_layout").cloned().unwrap_or(Value::Null),
        "selected_dim_mismatch_row": boundary.pointer("/selected_dim_mismatch_row").cloned().unwrap_or(Value::Null),
        "selected_token_mismatch_row": boundary.pointer("/selected_token_mismatch_row").cloned().unwrap_or(Value::Null),
    })
}

fn selected_query_candidate_boundary_row_present(boundary: &Value) -> bool {
    boundary
        .pointer("/status")
        .and_then(Value::as_str)
        .is_some_and(|status| status != "missing_boundary" && status != "missing_input")
}

fn attention_selected_query_score_input_candidate_policy_boundary(
    candidate_policy: &Value,
    selected_query_source: &Value,
) -> Value {
    let policy_classification = candidate_policy.pointer("/classification").and_then(Value::as_str);
    let top_contributor = candidate_policy.pointer("/top_contributor").unwrap_or(&Value::Null);
    let top_contributor_present = top_contributor.pointer("/dim").and_then(Value::as_u64).is_some();
    let query_boundary_present =
        value_bool(selected_query_source, "/query_boundary_present").unwrap_or(false);
    let reference_to_rope = selected_query_candidate_policy_boundary_summary(
        selected_query_source,
        "/reference_to_rust_rope",
    );
    let rope_to_f16 = selected_query_candidate_policy_boundary_summary(
        selected_query_source,
        "/rust_rope_to_f16",
    );
    let f16_to_score = selected_query_candidate_policy_boundary_summary(
        selected_query_source,
        "/rust_f16_to_score_input",
    );
    let reference_to_score = selected_query_candidate_policy_boundary_summary(
        selected_query_source,
        "/reference_to_score_input",
    );
    let boundary_rows_present =
        [&reference_to_rope, &rope_to_f16, &f16_to_score, &reference_to_score]
            .iter()
            .any(|boundary| selected_query_candidate_boundary_row_present(boundary));
    let reference_query_f16 =
        value_bool(candidate_policy, "/reference_query_f16_roundtrip").unwrap_or(false);
    let rust_query_f16 = value_bool(candidate_policy, "/rust_query_f16_roundtrip").unwrap_or(false);
    let same_key_policy = value_bool(candidate_policy, "/same_key_policy").unwrap_or(false);
    let query_changed_dim_count =
        value_u64(candidate_policy, "/query_changed_dim_count").unwrap_or(0);
    let key_changed_dim_count = value_u64(candidate_policy, "/key_changed_dim_count").unwrap_or(0);

    let classification = match policy_classification {
        Some("selected_query_score_input_candidate_policy_reference_q_f16_rust_q_f32")
            if top_contributor_present && boundary_rows_present =>
        {
            "selected_query_score_input_candidate_policy_boundary_reference_q_f16_rust_q_f32"
        }
        Some("selected_query_score_input_candidate_policy_reference_q_f32_rust_q_f16")
            if top_contributor_present && boundary_rows_present =>
        {
            "selected_query_score_input_candidate_policy_boundary_reference_q_f32_rust_q_f16"
        }
        Some("selected_query_score_input_candidate_policy_query_policy_unpinned")
            if top_contributor_present && boundary_rows_present =>
        {
            "selected_query_score_input_candidate_policy_boundary_query_policy_unpinned"
        }
        Some("selected_query_score_input_candidate_policy_clean") => {
            "selected_query_score_input_candidate_policy_boundary_clean"
        }
        Some("selected_query_score_input_candidate_policy_reference_q_f16_rust_q_f32")
        | Some("selected_query_score_input_candidate_policy_reference_q_f32_rust_q_f16")
        | Some("selected_query_score_input_candidate_policy_query_policy_unpinned")
            if top_contributor_present && !boundary_rows_present =>
        {
            "selected_query_score_input_candidate_policy_boundary_rows_missing"
        }
        Some("selected_query_score_input_candidate_policy_reference_q_f16_rust_q_f32")
        | Some("selected_query_score_input_candidate_policy_reference_q_f32_rust_q_f16")
        | Some("selected_query_score_input_candidate_policy_query_policy_unpinned")
            if !top_contributor_present =>
        {
            "selected_query_score_input_candidate_policy_boundary_missing_context"
        }
        Some(_) => "selected_query_score_input_candidate_policy_boundary_not_active",
        None => "selected_query_score_input_candidate_policy_boundary_missing_context",
    };

    let blocked_reasons = if classification
        == "selected_query_score_input_candidate_policy_boundary_missing_context"
        || classification == "selected_query_score_input_candidate_policy_boundary_rows_missing"
    {
        let mut reasons = Vec::<&str>::new();
        if !top_contributor_present {
            reasons.push("selected_query_candidate_top_contributor_missing");
        }
        if !boundary_rows_present {
            reasons.push("selected_query_candidate_boundary_rows_missing");
        }
        json!(reasons)
    } else {
        json!([])
    };

    json!({
        "diagnostic_only": true,
        "claim_allowed": false,
        "policy": "Selected query score-input candidate-policy boundary rows are diagnostic-only evidence for the active q-F16/q-F32 candidate split; they compactly carry the selected product contributor and query boundary summaries, but do not change RMSNorm, QK256, RoPE, F16 score-input conversion, score accumulation, softmax, value-mix, or runtime math and do not promote reference parity, A770 semantic quality, attention score residency, selected attention, resident KV, full residency, performance, or completion",
        "classification": classification,
        "source_report": "attention_selected_query_score_input_candidate_policy_frontier",
        "source_classification": policy_classification,
        "head": candidate_policy.pointer("/head").cloned().unwrap_or(Value::Null),
        "selected_dim": candidate_policy.pointer("/selected_dim").cloned().unwrap_or(Value::Null),
        "selected_token": candidate_policy.pointer("/selected_token").cloned().unwrap_or(Value::Null),
        "key_slot": candidate_policy.pointer("/key_slot").cloned().unwrap_or(Value::Null),
        "contributor_dim": top_contributor.pointer("/dim").cloned().unwrap_or(Value::Null),
        "selected_row_context_source": candidate_policy.pointer("/selected_row_context_source").cloned().unwrap_or(Value::Null),
        "dominant_input": candidate_policy.pointer("/dominant_input").cloned().unwrap_or(Value::Null),
        "reference_score_input_variant": candidate_policy.pointer("/reference_score_input_variant").cloned().unwrap_or(Value::Null),
        "rust_score_input_variant": candidate_policy.pointer("/rust_score_input_variant").cloned().unwrap_or(Value::Null),
        "reference_query_source": candidate_policy.pointer("/reference_query_source").cloned().unwrap_or(Value::Null),
        "rust_query_source": candidate_policy.pointer("/rust_query_source").cloned().unwrap_or(Value::Null),
        "reference_key_source": candidate_policy.pointer("/reference_key_source").cloned().unwrap_or(Value::Null),
        "rust_key_source": candidate_policy.pointer("/rust_key_source").cloned().unwrap_or(Value::Null),
        "reference_query_f16_roundtrip": reference_query_f16,
        "rust_query_f16_roundtrip": rust_query_f16,
        "same_key_policy": same_key_policy,
        "query_changed_dim_count": query_changed_dim_count,
        "key_changed_dim_count": key_changed_dim_count,
        "top_contributor": top_contributor.clone(),
        "query_boundary_present": query_boundary_present,
        "boundary_rows_present": boundary_rows_present,
        "reference_to_rust_rope": reference_to_rope,
        "rust_rope_to_f16": rope_to_f16,
        "rust_f16_to_score_input": f16_to_score,
        "reference_to_score_input": reference_to_score,
        "blocked_reasons": blocked_reasons,
        "next_diagnostic": selected_query_candidate_policy_boundary_next_diagnostic(classification),
    })
}

fn selected_query_head_boundary_next_diagnostic(classification: &str) -> &'static str {
    match classification {
        "selected_query_head_boundary_reference_to_rope" => {
            "localize selected query reference-to-Rust RoPE head rows before changing RoPE or score accumulation"
        }
        "selected_query_head_boundary_f16_conversion" => {
            "pin selected query RoPE-to-F16 head conversion before changing F16 score-input or score accumulation"
        }
        "selected_query_head_boundary_score_input_serialization" => {
            "pin selected query score-input serialization after F16 conversion before changing score accumulation"
        }
        "selected_query_head_boundary_reference_to_score_unexplained" => {
            "split selected query reference-to-score head drift across RoPE, F16 conversion, and score serialization"
        }
        "selected_query_head_boundary_selected_dim_token_context" => {
            "promote the selected query dim/token context to exact boundary attribution before runtime changes"
        }
        "selected_query_head_boundary_clean" => {
            "selected query head boundary is clean; rerun selected Q/K downstream score residual attribution"
        }
        "selected_query_head_boundary_not_active" => {
            "follow the active selected query source classification before probing head boundary rows"
        }
        "selected_query_head_boundary_missing_context" => {
            "capture selected query source and head boundary deltas before changing runtime math"
        }
        _ => "keep selected query head boundary diagnostic-only",
    }
}

