fn attention_selected_query_downstream_score_residual_frontier(
    selected_query_frontier: &Value,
    f64_score_history_residual: &Value,
    f64_qk_score_input_bucket_residual: &Value,
    f64_downstream: &Value,
    base_comparison: &Value,
) -> Value {
    let probability_effect =
        f64_downstream.pointer("/f64/probability_history_effect").unwrap_or(&Value::Null);
    let mixed_qk = probability_effect
        .pointer("/attention_selected_score_mixed_qk_contribution")
        .or_else(|| f64_downstream.pointer("/attention_selected_score_mixed_qk_contribution"))
        .or_else(|| base_comparison.pointer("/attention_selected_score_mixed_qk_contribution"))
        .unwrap_or(&Value::Null);
    let score_qk_bucket_frontier = probability_effect
        .pointer("/score_qk_bucket_frontier")
        .or_else(|| f64_downstream.pointer("/score_qk_bucket_frontier"))
        .or_else(|| base_comparison.pointer("/score_qk_bucket_frontier"))
        .unwrap_or(&Value::Null);
    let selected_key_source = probability_effect
        .pointer("/selected_key_score_input_source")
        .or_else(|| f64_downstream.pointer("/selected_key_score_input_source"))
        .or_else(|| base_comparison.pointer("/attention_selected_key_score_input_source"))
        .or_else(|| base_comparison.pointer("/selected_key_score_input_source"))
        .unwrap_or(&Value::Null);
    let selected_key_bucket_source = probability_effect
        .pointer("/selected_key_bucket_source_frontier")
        .or_else(|| f64_downstream.pointer("/selected_key_bucket_source_frontier"))
        .or_else(|| base_comparison.pointer("/selected_key_bucket_source_frontier"))
        .unwrap_or(&Value::Null);
    let score_history_frontier =
        probability_effect.pointer("/score_history_residual_frontier").unwrap_or(&Value::Null);
    let value_mix_attribution =
        f64_downstream.pointer("/f64/value_mix_history_attribution").unwrap_or(&Value::Null);
    let value_mix_source = value_mix_attribution.pointer("/source_summary").unwrap_or(&Value::Null);

    let query_classification = selected_report_classification(selected_query_frontier);
    let f64_score_residual_classification =
        selected_report_classification(f64_score_history_residual);
    let f64_qk_residual_classification =
        selected_report_classification(f64_qk_score_input_bucket_residual);
    let mixed_classification = selected_report_classification(mixed_qk);
    let score_history_frontier_classification =
        selected_report_classification(score_history_frontier);
    let qk_bucket_classification = selected_report_classification(score_qk_bucket_frontier);
    let selected_key_source_classification = selected_report_classification(selected_key_source);
    let selected_key_bucket_classification =
        selected_report_classification(selected_key_bucket_source);
    let query_chain_clean = query_classification
        == Some("selected_query_score_frontier_downstream_score_residual_after_clean_norm_replay");
    let score_raw_history_material_count =
        value_u64(f64_score_history_residual, "/score_raw_history_material_count")
            .or_else(|| value_u64(probability_effect, "/score_raw_history_material_count"))
            .unwrap_or(0);
    let score_raw_live_material_count =
        value_u64(f64_score_history_residual, "/score_raw_live_material_count")
            .or_else(|| value_u64(probability_effect, "/score_raw_live_material_count"))
            .unwrap_or(0);
    let probability_history_material_count =
        value_u64(f64_score_history_residual, "/probability_history_material_count")
            .or_else(|| value_u64(probability_effect, "/probability_history_material_count"))
            .unwrap_or(0);
    let probability_history_missing_count =
        value_u64(f64_score_history_residual, "/probability_history_missing_count")
            .or_else(|| value_u64(probability_effect, "/probability_history_missing_count"))
            .unwrap_or(0);
    let value_mix_source_classification =
        selected_report_classification(value_mix_source).or_else(|| {
            f64_score_history_residual
                .pointer("/value_mix_source_classification")
                .and_then(Value::as_str)
        });
    let probability_source_drift =
        value_bool(f64_score_history_residual, "/probability_source_drift_present")
            .or_else(|| value_bool(value_mix_source, "/probability_source_drift_present"))
            .unwrap_or(false);
    let value_cache_source_drift =
        value_bool(f64_score_history_residual, "/value_cache_source_drift_present")
            .or_else(|| value_bool(value_mix_source, "/value_cache_source_drift_present"))
            .unwrap_or(false);
    let rust_self_recompute_drift =
        value_bool(f64_score_history_residual, "/rust_self_recompute_drift_present")
            .or_else(|| value_bool(value_mix_source, "/rust_self_recompute_drift_present"))
            .unwrap_or(false);
    let rust_self_recompute_explained = value_bool(
        f64_score_history_residual,
        "/rust_self_recompute_explained_by_numeric_variants",
    )
    .or_else(|| value_bool(value_mix_source, "/rust_self_recompute_explained_by_numeric_variants"))
    .unwrap_or(false);
    let missing_context =
        query_classification.is_none() || f64_score_residual_classification.is_none();

    let classification = if missing_context {
        "selected_query_downstream_score_residual_missing_context"
    } else if !query_chain_clean {
        "selected_query_downstream_score_residual_selected_q_history"
    } else if f64_score_residual_classification == Some("f64_score_history_residual_score_input") {
        match mixed_classification {
            Some("selected_score_drift_has_mixed_qk_contribution")
            | Some("selected_score_drift_split_query_key_contribution") => {
                "selected_query_downstream_score_residual_selected_qk_history"
            }
            Some("selected_score_drift_query_dominant_with_query_rope_boundary")
            | Some("selected_score_drift_query_dominant") => {
                "selected_query_downstream_score_residual_selected_q_history"
            }
            Some("selected_score_drift_key_dominant") => {
                "selected_query_downstream_score_residual_selected_k_history"
            }
            Some("selected_score_product_delta_blocked_by_residual") => {
                "selected_query_downstream_score_residual_raw_score_accumulation"
            }
            Some("selected_score_product_delta_clean") => {
                "selected_query_downstream_score_residual_raw_score_accumulation"
            }
            Some("selected_score_positions_missing_inputs")
            | Some("selected_score_product_delta_unavailable")
            | Some("no_selected_score_positions") => {
                "selected_query_downstream_score_residual_missing_context"
            }
            _ => match f64_qk_residual_classification {
                Some("f64_qk_score_input_bucket_residual_selected_qk_history")
                | Some("f64_qk_score_input_bucket_residual_qk_history") => {
                    "selected_query_downstream_score_residual_selected_qk_history"
                }
                Some("f64_qk_score_input_bucket_residual_selected_query_history")
                | Some("f64_qk_score_input_bucket_residual_query_history") => {
                    "selected_query_downstream_score_residual_selected_q_history"
                }
                Some("f64_qk_score_input_bucket_residual_selected_key_history")
                | Some("f64_qk_score_input_bucket_residual_key_history")
                | Some("f64_qk_score_input_bucket_residual_current_key") => {
                    "selected_query_downstream_score_residual_selected_k_history"
                }
                Some("f64_qk_score_input_bucket_residual_numeric_no_bucket") => {
                    "selected_query_downstream_score_residual_raw_score_accumulation"
                }
                Some("f64_qk_score_input_bucket_residual_clean") => {
                    "selected_query_downstream_score_residual_clean"
                }
                _ => "selected_query_downstream_score_residual_missing_context",
            },
        }
    } else if value_cache_source_drift
        || f64_score_residual_classification
            == Some("f64_score_history_residual_value_cache_source")
        || f64_score_residual_classification == Some("f64_score_history_residual_value_mix_numeric")
        || (rust_self_recompute_drift && rust_self_recompute_explained)
    {
        "selected_query_downstream_score_residual_value_mix"
    } else if f64_score_residual_classification
        == Some("f64_score_history_residual_softmax_probability")
        || probability_history_material_count > 0
        || probability_source_drift
    {
        "selected_query_downstream_score_residual_softmax_probability"
    } else if f64_score_residual_classification
        == Some("f64_score_history_residual_score_accumulation")
    {
        if score_raw_history_material_count > 0
            && probability_history_material_count == 0
            && score_raw_live_material_count == 0
        {
            "selected_query_downstream_score_residual_score_history_serialization"
        } else {
            "selected_query_downstream_score_residual_raw_score_accumulation"
        }
    } else if f64_score_residual_classification == Some("f64_score_history_residual_clean") {
        "selected_query_downstream_score_residual_clean"
    } else {
        "selected_query_downstream_score_residual_missing_context"
    };

    json!({
        "diagnostic_only": true,
        "claim_allowed": false,
        "policy": "Selected query downstream score residual frontier is diagnostic-only evidence for classifying the remaining selected-query score residual after the selected-query source chain is locally clean; it does not change RMSNorm, QK256, RoPE, F16 score-input conversion, score accumulation, softmax, value-mix, or runtime math and does not promote reference parity, A770 semantic quality, attention score residency, selected attention, resident KV, full residency, performance, or completion",
        "classification": classification,
        "selected_query_frontier_classification": query_classification,
        "f64_score_history_residual_classification": f64_score_residual_classification,
        "f64_qk_score_input_bucket_residual_classification": f64_qk_residual_classification,
        "score_history_frontier_classification": score_history_frontier_classification,
        "selected_score_mixed_qk_classification": mixed_classification,
        "score_qk_bucket_frontier_classification": qk_bucket_classification,
        "selected_key_score_input_source_classification": selected_key_source_classification,
        "selected_key_bucket_source_frontier_classification": selected_key_bucket_classification,
        "value_mix_source_classification": value_mix_source_classification,
        "selected_query_head": value_u64(selected_query_frontier, "/head"),
        "selected_query_dim": value_u64(selected_query_frontier, "/selected_dim"),
        "selected_query_token": value_u64(selected_query_frontier, "/selected_token"),
        "selected_query_key_slot": value_u64(selected_query_frontier, "/key_slot"),
        "score_raw_history_material_count": score_raw_history_material_count,
        "score_raw_live_material_count": score_raw_live_material_count,
        "probability_history_material_count": probability_history_material_count,
        "probability_history_missing_count": probability_history_missing_count,
        "probability_source_drift_present": probability_source_drift,
        "value_cache_source_drift_present": value_cache_source_drift,
        "rust_self_recompute_drift_present": rust_self_recompute_drift,
        "rust_self_recompute_explained_by_numeric_variants": rust_self_recompute_explained,
        "selected_count": value_u64(mixed_qk, "/selected_count"),
        "compared_count": value_u64(mixed_qk, "/compared_count"),
        "query_dominant_count": value_u64(mixed_qk, "/query_dominant_count"),
        "key_dominant_count": value_u64(mixed_qk, "/key_dominant_count"),
        "mixed_qk_dominant_count": value_u64(mixed_qk, "/mixed_qk_dominant_count"),
        "unresolved_residual_count": value_u64(mixed_qk, "/unresolved_residual_count"),
        "max_abs_product_delta": mixed_qk.pointer("/max_abs_product_delta").cloned().unwrap_or(Value::Null),
        "first_product_row": mixed_qk.pointer("/first_product_row").cloned().unwrap_or(Value::Null),
        "mixed_qk_next_diagnostic": mixed_qk.pointer("/next_diagnostic").cloned().unwrap_or(Value::Null),
        "selected_key_next_diagnostic": selected_key_source.pointer("/next_diagnostic").cloned().unwrap_or(Value::Null),
        "blocked_reasons": if missing_context {
            json!(["selected_query_downstream_score_residual_missing_context"])
        } else {
            json!([])
        },
        "next_diagnostic": selected_query_downstream_score_residual_next_diagnostic(classification),
    })
}

fn selected_qk_downstream_score_residual_next_diagnostic(classification: &str) -> &'static str {
    match classification {
        "selected_qk_downstream_score_residual_key_pre_rope" => {
            "localize selected historical K pre-RoPE projection rows before changing score accumulation or softmax"
        }
        "selected_qk_downstream_score_residual_key_post_rope_history" => {
            "localize selected historical K post-RoPE history bucket source before changing score accumulation or softmax"
        }
        "selected_qk_downstream_score_residual_key_score_input_expansion" => {
            "localize selected K post-RoPE to score-input expansion before changing score accumulation or softmax"
        }
        "selected_qk_downstream_score_residual_key_exact_boundary" => {
            "follow selected key exact boundary attribution before changing score accumulation or softmax"
        }
        "selected_qk_downstream_score_residual_mixed_qk_product" => {
            "replay selected mixed Q/K score-position residual before changing score accumulation or softmax"
        }
        "selected_qk_downstream_score_residual_selected_query_history" => {
            "continue selected query-history attribution before changing score accumulation or softmax"
        }
        "selected_qk_downstream_score_residual_raw_score_accumulation" => {
            "replay selected raw QK score accumulation before changing score accumulation policy"
        }
        "selected_qk_downstream_score_residual_score_history_serialization" => {
            "pin score-history serialization/capture before changing score accumulation or softmax"
        }
        "selected_qk_downstream_score_residual_softmax_probability" => {
            "localize selected softmax probability formation before value-mix changes"
        }
        "selected_qk_downstream_score_residual_value_mix" => {
            "localize selected value-mix inputs before changing value-mix runtime math"
        }
        "selected_qk_downstream_score_residual_clean" => {
            "selected Q/K downstream score residual is clean; rerun downstream probability, value-mix, and logits parity"
        }
        "selected_qk_downstream_score_residual_missing_context" => {
            "capture selected query downstream, selected key source, post-fix score-input, and slot-probe context before changing runtime math"
        }
        _ => "keep selected Q/K downstream score residual diagnostic-only",
    }
}

fn attention_selected_qk_downstream_score_residual_frontier(
    selected_query_downstream: &Value,
    base_comparison: &Value,
) -> Value {
    let post_fix_frontier =
        base_comparison.pointer("/attention_post_fix_score_input_frontier").unwrap_or(&Value::Null);
    let slot_probe = base_comparison
        .pointer("/attention_selected_key_dim_token_slot_probe")
        .unwrap_or(&Value::Null);
    let post_rope_source = base_comparison
        .pointer("/attention_selected_post_rope_history_bucket_source")
        .unwrap_or(&Value::Null);
    let mixed_qk = base_comparison
        .pointer("/attention_selected_score_mixed_qk_contribution")
        .unwrap_or(&Value::Null);
    let selected_key_source = base_comparison
        .pointer("/attention_selected_key_score_input_source")
        .unwrap_or(&Value::Null);
    let operand_drift = base_comparison
        .pointer("/attention_rust_score_input_operand_drift")
        .unwrap_or(&Value::Null);

    let downstream_classification = selected_report_classification(selected_query_downstream);
    let post_fix_classification = selected_report_classification(post_fix_frontier);
    let slot_probe_classification = selected_report_classification(slot_probe);
    let post_rope_source_classification = selected_report_classification(post_rope_source);
    let mixed_classification = selected_report_classification(mixed_qk);
    let selected_key_source_classification = selected_report_classification(selected_key_source);
    let operand_drift_classification = selected_report_classification(operand_drift);

    let exact_key_boundary = matches!(
        selected_key_source_classification,
        Some("selected_key_drift_enters_before_cache_store")
            | Some("selected_key_drift_enters_cache_readback")
            | Some("selected_key_drift_follows_cache_f16_roundtrip")
            | Some("selected_key_drift_visible_at_score_input")
    ) || post_fix_classification
        == Some("post_fix_score_input_frontier_exact_boundary_attributed");
    let mixed_qk_product = matches!(
        mixed_classification,
        Some("selected_score_drift_has_mixed_qk_contribution")
            | Some("selected_score_drift_split_query_key_contribution")
    );
    let key_context_present = post_fix_classification.is_some()
        || slot_probe_classification.is_some()
        || selected_key_source_classification.is_some();
    let classification = match downstream_classification {
        None => "selected_qk_downstream_score_residual_missing_context",
        Some("selected_query_downstream_score_residual_selected_q_history") => {
            "selected_qk_downstream_score_residual_selected_query_history"
        }
        Some("selected_query_downstream_score_residual_selected_k_history")
        | Some("selected_query_downstream_score_residual_selected_qk_history") => {
            if slot_probe_classification
                == Some("selected_key_dim_token_slot_probe_pre_rope_bucket_crossing")
                || post_rope_source_classification
                    == Some("selected_post_rope_history_bucket_source_pre_rope_bucket_crossing")
            {
                "selected_qk_downstream_score_residual_key_pre_rope"
            } else if slot_probe_classification
                == Some("selected_key_dim_token_slot_probe_post_rope_bucket_crossing")
                || matches!(
                    post_rope_source_classification,
                    Some("selected_post_rope_history_bucket_source_capture_replay_mismatch")
                        | Some(
                            "selected_post_rope_history_bucket_source_projection_bucket_crossing"
                        )
                        | Some(
                            "selected_post_rope_history_bucket_source_projection_subbucket_midpoint"
                        )
                        | Some("selected_post_rope_history_bucket_source_f16_midpoint_sensitive")
                )
            {
                "selected_qk_downstream_score_residual_key_post_rope_history"
            } else if slot_probe_classification
                == Some("selected_key_dim_token_slot_probe_score_input_bucket_crossing")
            {
                "selected_qk_downstream_score_residual_key_score_input_expansion"
            } else if exact_key_boundary {
                "selected_qk_downstream_score_residual_key_exact_boundary"
            } else if mixed_qk_product {
                "selected_qk_downstream_score_residual_mixed_qk_product"
            } else if key_context_present {
                "selected_qk_downstream_score_residual_raw_score_accumulation"
            } else {
                "selected_qk_downstream_score_residual_missing_context"
            }
        }
        Some("selected_query_downstream_score_residual_raw_score_accumulation") => {
            "selected_qk_downstream_score_residual_raw_score_accumulation"
        }
        Some("selected_query_downstream_score_residual_score_history_serialization") => {
            "selected_qk_downstream_score_residual_score_history_serialization"
        }
        Some("selected_query_downstream_score_residual_softmax_probability") => {
            "selected_qk_downstream_score_residual_softmax_probability"
        }
        Some("selected_query_downstream_score_residual_value_mix") => {
            "selected_qk_downstream_score_residual_value_mix"
        }
        Some("selected_query_downstream_score_residual_clean") => {
            "selected_qk_downstream_score_residual_clean"
        }
        _ => "selected_qk_downstream_score_residual_missing_context",
    };

    json!({
        "diagnostic_only": true,
        "claim_allowed": false,
        "policy": "Selected Q/K downstream score residual frontier is diagnostic-only evidence for refining a selected query downstream score residual into key-source, mixed Q/K product, score accumulation, score-history serialization, probability, or value-mix next boundaries; it does not change RMSNorm, QK256, RoPE, F16 score-input conversion, score accumulation, softmax, value-mix, or runtime math and does not promote reference parity, A770 semantic quality, attention score residency, selected attention, resident KV, full residency, performance, or completion",
        "classification": classification,
        "selected_query_downstream_classification": downstream_classification,
        "post_fix_score_input_frontier_classification": post_fix_classification,
        "selected_key_slot_probe_classification": slot_probe_classification,
        "selected_post_rope_history_bucket_source_classification": post_rope_source_classification,
        "selected_score_mixed_qk_classification": mixed_classification,
        "selected_key_score_input_source_classification": selected_key_source_classification,
        "rust_score_input_operand_drift_classification": operand_drift_classification,
        "selected_query_head": value_u64(selected_query_downstream, "/selected_query_head"),
        "selected_query_dim": value_u64(selected_query_downstream, "/selected_query_dim"),
        "selected_query_token": value_u64(selected_query_downstream, "/selected_query_token"),
        "selected_query_key_slot": value_u64(selected_query_downstream, "/selected_query_key_slot"),
        "mixed_qk_dominant_count": value_u64(mixed_qk, "/mixed_qk_dominant_count"),
        "query_dominant_count": value_u64(mixed_qk, "/query_dominant_count"),
        "key_dominant_count": value_u64(mixed_qk, "/key_dominant_count"),
        "max_abs_product_delta": mixed_qk.pointer("/max_abs_product_delta").cloned().unwrap_or(Value::Null),
        "post_fix_max_abs_key_delta": post_fix_frontier.pointer("/max_abs_key_delta").cloned().unwrap_or(Value::Null),
        "post_fix_max_abs_product_delta": post_fix_frontier.pointer("/max_abs_product_delta").cloned().unwrap_or(Value::Null),
        "slot_probe_max_abs_stage_delta": slot_probe.pointer("/max_abs_stage_delta").cloned().unwrap_or(Value::Null),
        "first_mixed_qk_product_row": compact_selected_score_product_row(mixed_qk.pointer("/first_product_row").unwrap_or(&Value::Null)),
        "first_post_fix_row": compact_post_fix_score_input_frontier_row(post_fix_frontier.pointer("/rows/0").unwrap_or(&Value::Null)),
        "first_slot_probe_row": compact_selected_key_slot_probe_row(slot_probe.pointer("/rows/0").unwrap_or(&Value::Null)),
        "blocked_reasons": if downstream_classification.is_none() || (!key_context_present && matches!(downstream_classification, Some("selected_query_downstream_score_residual_selected_k_history") | Some("selected_query_downstream_score_residual_selected_qk_history"))) {
            json!(["selected_qk_downstream_score_residual_missing_context"])
        } else {
            json!([])
        },
        "next_diagnostic": selected_qk_downstream_score_residual_next_diagnostic(classification),
    })
}

fn selected_key_mixed_qk_frontier_next_diagnostic(classification: &str) -> &'static str {
    match classification {
        "selected_key_mixed_qk_frontier_post_rope_bucket_crossing" => {
            "localize selected post-RoPE key bucket source before changing score accumulation or softmax"
        }
        "selected_key_mixed_qk_frontier_post_rope_capture_replay_mismatch" => {
            "pin selected post-RoPE capture/replay mismatch before runtime math changes"
        }
        "selected_key_mixed_qk_frontier_post_rope_runtime_projection_pair_delta" => {
            "follow selected post-RoPE runtime replay into pre-RoPE projection pair delta before changing score accumulation"
        }
        "selected_key_mixed_qk_frontier_pre_rope_projection_pair_delta" => {
            "localize selected pre-RoPE projection pair/history source before changing K projection or RMSNorm math"
        }
        "selected_key_mixed_qk_frontier_pre_rope_attention_norm_output" => {
            "pin selected pre-RoPE attention-norm output source before production RMSNorm changes"
        }
        "selected_key_mixed_qk_frontier_f64_residual_score_history" => {
            "localize the remaining f64 score-history residual before changing RMSNorm, score accumulation, softmax, or value mix"
        }
        "selected_key_mixed_qk_frontier_query_only" => {
            "continue selected query residual attribution before following selected key runtime math"
        }
        "selected_key_mixed_qk_frontier_clean" => {
            "selected key mixed-QK frontier is clean; rerun downstream score, probability, value-mix, and logits parity"
        }
        "selected_key_mixed_qk_frontier_missing_context" => {
            "capture selected query downstream, mixed Q/K, selected key slot, post-RoPE replay, pre-RoPE projection, and f64 residual context before runtime changes"
        }
        _ => "keep selected key mixed-QK frontier diagnostic-only",
    }
}

fn compact_selected_key_mixed_qk_source_row(row: &Value) -> Value {
    if row.is_null() {
        return Value::Null;
    }
    json!({
        "classification": row.pointer("/classification").cloned().unwrap_or(Value::Null),
        "head": row.pointer("/head").cloned().unwrap_or(Value::Null),
        "kv_head": row.pointer("/kv_head").cloned().unwrap_or(Value::Null),
        "key_slot": row.pointer("/key_slot").cloned().unwrap_or(Value::Null),
        "query_token": row.pointer("/query_token").cloned().unwrap_or(Value::Null),
        "contributor_dim": row.pointer("/contributor_dim").cloned().unwrap_or(Value::Null),
        "selected_k_output_dim": row.pointer("/selected_k_output_dim").cloned().unwrap_or(Value::Null),
        "probe_dim": row.pointer("/probe_dim").cloned().unwrap_or(Value::Null),
        "blocked_reasons": row.pointer("/blocked_reasons").cloned().unwrap_or(Value::Null),
        "runtime_replay_delta": row.pointer("/runtime_replay_delta").cloned().unwrap_or(Value::Null),
        "linearized_delta_for_probe_dim": row.pointer("/linearized_delta_for_probe_dim").cloned().unwrap_or(Value::Null),
        "dominant_projection_input": row.pointer("/dominant_projection_input").cloned().unwrap_or(Value::Null),
        "dominant_projection_input_dim": row.pointer("/dominant_projection_input_dim").cloned().unwrap_or(Value::Null),
        "dominant_linearized_contribution": row.pointer("/dominant_linearized_contribution").cloned().unwrap_or(Value::Null),
        "max_input_abs_delta": row.pointer("/max_input_abs_delta").cloned().unwrap_or(Value::Null),
        "max_output_abs_delta": row.pointer("/max_output_abs_delta").cloned().unwrap_or(Value::Null),
        "baseline_max_abs_delta": row.pointer("/baseline_max_abs_delta").cloned().unwrap_or(Value::Null),
        "f64_max_abs_delta": row.pointer("/f64_max_abs_delta").cloned().unwrap_or(Value::Null),
        "f64_clears_bucket": row.pointer("/f64_clears_bucket").cloned().unwrap_or(Value::Null),
    })
}

fn attention_selected_key_mixed_qk_frontier(
    selected_query_downstream: &Value,
    base_comparison: &Value,
    selected_pre_rope_f64_residual: &Value,
) -> Value {
    let mixed_qk = base_comparison
        .pointer("/attention_selected_score_mixed_qk_contribution")
        .unwrap_or(&Value::Null);
    let slot_probe = base_comparison
        .pointer("/attention_selected_key_dim_token_slot_probe")
        .unwrap_or(&Value::Null);
    let post_rope_history = base_comparison
        .pointer("/attention_selected_post_rope_history_bucket_source")
        .unwrap_or(&Value::Null);
    let post_rope_capture = base_comparison
        .pointer("/attention_selected_post_rope_capture_replay_source")
        .unwrap_or(&Value::Null);
    let rust_post_rope_capture = base_comparison
        .pointer("/attention_selected_rust_post_rope_capture_source")
        .unwrap_or(&Value::Null);
    let post_rope_runtime = base_comparison
        .pointer("/attention_selected_post_rope_runtime_replay_source")
        .unwrap_or(&Value::Null);
    let pre_rope_pair = base_comparison
        .pointer("/attention_selected_pre_rope_projection_pair_source")
        .unwrap_or(&Value::Null);
    let pre_rope_history = base_comparison
        .pointer("/attention_selected_pre_rope_projection_history_source")
        .unwrap_or(&Value::Null);
    let pre_rope_norm = base_comparison
        .pointer("/attention_selected_pre_rope_attention_norm_history_source")
        .unwrap_or(&Value::Null);
    let pre_rope_f64_effect = base_comparison
        .pointer("/attention_selected_pre_rope_attention_norm_f64_effect")
        .unwrap_or(&Value::Null);

    let query_downstream_classification = selected_report_classification(selected_query_downstream);
    let mixed_classification = selected_report_classification(mixed_qk);
    let slot_classification = selected_report_classification(slot_probe);
    let post_rope_history_classification = selected_report_classification(post_rope_history);
    let post_rope_capture_classification = selected_report_classification(post_rope_capture);
    let rust_post_rope_capture_classification =
        selected_report_classification(rust_post_rope_capture);
    let post_rope_runtime_classification = selected_report_classification(post_rope_runtime);
    let pre_rope_pair_classification = selected_report_classification(pre_rope_pair);
    let pre_rope_history_classification = selected_report_classification(pre_rope_history);
    let pre_rope_norm_classification = selected_report_classification(pre_rope_norm);
    let pre_rope_f64_effect_classification = selected_report_classification(pre_rope_f64_effect);
    let pre_rope_f64_residual_classification =
        selected_report_classification(selected_pre_rope_f64_residual);

    let key_relevant = matches!(
        query_downstream_classification,
        Some("selected_query_downstream_score_residual_selected_k_history")
            | Some("selected_query_downstream_score_residual_selected_qk_history")
    ) || matches!(
        mixed_classification,
        Some("selected_score_drift_has_mixed_qk_contribution")
            | Some("selected_score_drift_key_dominant")
            | Some("selected_score_drift_split_query_key_contribution")
    );
    let key_context_present = [
        slot_classification,
        post_rope_history_classification,
        post_rope_capture_classification,
        rust_post_rope_capture_classification,
        post_rope_runtime_classification,
        pre_rope_pair_classification,
        pre_rope_history_classification,
        pre_rope_norm_classification,
        pre_rope_f64_effect_classification,
        pre_rope_f64_residual_classification,
    ]
    .iter()
    .any(Option::is_some);

    let classification = if query_downstream_classification.is_none() {
        "selected_key_mixed_qk_frontier_missing_context"
    } else if query_downstream_classification
        == Some("selected_query_downstream_score_residual_clean")
        && matches!(slot_classification, None | Some("selected_key_dim_token_slot_probe_clean"))
    {
        "selected_key_mixed_qk_frontier_clean"
    } else if !key_relevant
        || query_downstream_classification
            == Some("selected_query_downstream_score_residual_selected_q_history")
    {
        "selected_key_mixed_qk_frontier_query_only"
    } else if pre_rope_f64_residual_classification
        == Some("selected_pre_rope_attention_norm_f64_residual_score_history_drives_value_mix")
    {
        "selected_key_mixed_qk_frontier_f64_residual_score_history"
    } else if matches!(
        pre_rope_norm_classification,
        Some("selected_pre_rope_attention_norm_history_source_output_replay_explains_epsilon")
            | Some("selected_pre_rope_attention_norm_history_source_input_history_epsilon")
            | Some("selected_pre_rope_attention_norm_history_source_output_epsilon_unpinned")
    ) || matches!(
        pre_rope_f64_effect_classification,
        Some("selected_pre_rope_attention_norm_f64_effect_clears_bucket_with_residual")
            | Some("selected_pre_rope_attention_norm_f64_effect_clears_bucket_exact")
    ) {
        "selected_key_mixed_qk_frontier_pre_rope_attention_norm_output"
    } else if matches!(
        pre_rope_pair_classification,
        Some("selected_pre_rope_projection_pair_source_raw_projection_pair_delta")
            | Some("selected_pre_rope_projection_pair_source_projection_bucket_crossing")
    ) || pre_rope_history_classification
        == Some("selected_pre_rope_projection_history_replay_explains_pair_delta")
    {
        "selected_key_mixed_qk_frontier_pre_rope_projection_pair_delta"
    } else if post_rope_runtime_classification
        == Some("selected_post_rope_runtime_replay_source_projection_pair_delta_bucket_crossing")
    {
        "selected_key_mixed_qk_frontier_post_rope_runtime_projection_pair_delta"
    } else if matches!(
        post_rope_history_classification,
        Some("selected_post_rope_history_bucket_source_capture_replay_mismatch")
            | Some("selected_post_rope_history_bucket_source_projection_bucket_crossing")
            | Some("selected_post_rope_history_bucket_source_projection_subbucket_midpoint")
            | Some("selected_post_rope_history_bucket_source_f16_midpoint_sensitive")
    ) || post_rope_capture_classification
        == Some("selected_post_rope_capture_replay_source_mismatch")
        || rust_post_rope_capture_classification
            == Some("selected_rust_post_rope_capture_source_runtime_replay_unclean")
    {
        "selected_key_mixed_qk_frontier_post_rope_capture_replay_mismatch"
    } else if slot_classification
        == Some("selected_key_dim_token_slot_probe_post_rope_bucket_crossing")
    {
        "selected_key_mixed_qk_frontier_post_rope_bucket_crossing"
    } else if key_relevant && !key_context_present {
        "selected_key_mixed_qk_frontier_missing_context"
    } else {
        "selected_key_mixed_qk_frontier_missing_context"
    };

    let blocked_reasons = if classification == "selected_key_mixed_qk_frontier_missing_context" {
        json!(["selected_key_mixed_qk_frontier_missing_context"])
    } else {
        json!([])
    };

    let mut report = serde_json::Map::new();
    report.insert("diagnostic_only".to_string(), json!(true));
    report.insert("claim_allowed".to_string(), json!(false));
    report.insert(
        "policy".to_string(),
        json!("Selected key mixed-QK frontier is diagnostic-only evidence for summarizing the active selected key-side boundary after selected-query downstream score residual attribution; it does not change runtime math or promote reference parity, A770 semantic quality, attention score residency, softmax residency, value-mix residency, selected attention, resident KV, full residency, performance, or completion"),
    );
    report.insert("classification".to_string(), json!(classification));
    report.insert(
        "selected_query_downstream_classification".to_string(),
        json!(query_downstream_classification),
    );
    report
        .insert("selected_score_mixed_qk_classification".to_string(), json!(mixed_classification));
    report.insert("selected_key_slot_probe_classification".to_string(), json!(slot_classification));
    report.insert(
        "selected_post_rope_history_bucket_source_classification".to_string(),
        json!(post_rope_history_classification),
    );
    report.insert(
        "selected_post_rope_capture_replay_source_classification".to_string(),
        json!(post_rope_capture_classification),
    );
    report.insert(
        "selected_rust_post_rope_capture_source_classification".to_string(),
        json!(rust_post_rope_capture_classification),
    );
    report.insert(
        "selected_post_rope_runtime_replay_source_classification".to_string(),
        json!(post_rope_runtime_classification),
    );
    report.insert(
        "selected_pre_rope_projection_pair_source_classification".to_string(),
        json!(pre_rope_pair_classification),
    );
    report.insert(
        "selected_pre_rope_projection_history_source_classification".to_string(),
        json!(pre_rope_history_classification),
    );
    report.insert(
        "selected_pre_rope_attention_norm_history_source_classification".to_string(),
        json!(pre_rope_norm_classification),
    );
    report.insert(
        "selected_pre_rope_attention_norm_f64_effect_classification".to_string(),
        json!(pre_rope_f64_effect_classification),
    );
    report.insert(
        "selected_pre_rope_attention_norm_f64_residual_classification".to_string(),
        json!(pre_rope_f64_residual_classification),
    );
    report.insert(
        "selected_query_head".to_string(),
        json!(value_u64(selected_query_downstream, "/selected_query_head")),
    );
    report.insert(
        "selected_query_dim".to_string(),
        json!(value_u64(selected_query_downstream, "/selected_query_dim")),
    );
    report.insert(
        "selected_query_token".to_string(),
        json!(value_u64(selected_query_downstream, "/selected_query_token")),
    );
    report.insert(
        "selected_query_key_slot".to_string(),
        json!(value_u64(selected_query_downstream, "/selected_query_key_slot")),
    );
    report.insert("key_relevant".to_string(), json!(key_relevant));
    report.insert("key_context_present".to_string(), json!(key_context_present));
    report.insert(
        "mixed_qk_dominant_count".to_string(),
        json!(value_u64(mixed_qk, "/mixed_qk_dominant_count")),
    );
    report.insert(
        "query_dominant_count".to_string(),
        json!(value_u64(mixed_qk, "/query_dominant_count")),
    );
    report.insert(
        "key_dominant_count".to_string(),
        json!(value_u64(mixed_qk, "/key_dominant_count")),
    );
    report.insert(
        "max_abs_product_delta".to_string(),
        mixed_qk.pointer("/max_abs_product_delta").cloned().unwrap_or(Value::Null),
    );
    report.insert(
        "slot_probe_max_abs_stage_delta".to_string(),
        slot_probe.pointer("/max_abs_stage_delta").cloned().unwrap_or(Value::Null),
    );
    report.insert(
        "runtime_replay_max_abs_delta".to_string(),
        post_rope_runtime.pointer("/max_abs_runtime_replay_delta").cloned().unwrap_or(Value::Null),
    );
    report.insert(
        "pre_rope_projection_max_abs_delta".to_string(),
        pre_rope_pair.pointer("/max_abs_projection_delta").cloned().unwrap_or(Value::Null),
    );
    report.insert(
        "pre_rope_attention_norm_max_output_delta".to_string(),
        pre_rope_norm.pointer("/max_output_abs_delta").cloned().unwrap_or(Value::Null),
    );
    report.insert(
        "f64_residual_downstream_frontier".to_string(),
        selected_pre_rope_f64_residual
            .pointer("/downstream_frontier")
            .cloned()
            .unwrap_or(Value::Null),
    );
    report.insert(
        "first_mixed_qk_product_row".to_string(),
        compact_selected_score_product_row(
            mixed_qk.pointer("/first_product_row").unwrap_or(&Value::Null),
        ),
    );
    report.insert(
        "first_slot_probe_row".to_string(),
        compact_selected_key_slot_probe_row(slot_probe.pointer("/rows/0").unwrap_or(&Value::Null)),
    );
    report.insert(
        "first_post_rope_history_row".to_string(),
        compact_selected_key_mixed_qk_source_row(
            post_rope_history.pointer("/rows/0").unwrap_or(&Value::Null),
        ),
    );
    report.insert(
        "first_post_rope_capture_row".to_string(),
        compact_selected_key_mixed_qk_source_row(
            post_rope_capture.pointer("/rows/0").unwrap_or(&Value::Null),
        ),
    );
    report.insert(
        "first_rust_post_rope_capture_row".to_string(),
        compact_selected_key_mixed_qk_source_row(
            rust_post_rope_capture.pointer("/rows/0").unwrap_or(&Value::Null),
        ),
    );
    report.insert(
        "first_post_rope_runtime_row".to_string(),
        compact_selected_key_mixed_qk_source_row(
            post_rope_runtime.pointer("/rows/0").unwrap_or(&Value::Null),
        ),
    );
    report.insert(
        "first_pre_rope_projection_pair_row".to_string(),
        compact_selected_key_mixed_qk_source_row(
            pre_rope_pair.pointer("/rows/0").unwrap_or(&Value::Null),
        ),
    );
    report.insert(
        "first_pre_rope_projection_history_row".to_string(),
        compact_selected_key_mixed_qk_source_row(
            pre_rope_history.pointer("/rows/0").unwrap_or(&Value::Null),
        ),
    );
    report.insert(
        "first_pre_rope_attention_norm_row".to_string(),
        compact_selected_key_mixed_qk_source_row(
            pre_rope_norm.pointer("/rows/0").unwrap_or(&Value::Null),
        ),
    );
    report.insert(
        "first_pre_rope_f64_effect_row".to_string(),
        compact_selected_key_mixed_qk_source_row(
            pre_rope_f64_effect.pointer("/rows/0").unwrap_or(&Value::Null),
        ),
    );
    report.insert(
        "first_pre_rope_f64_residual_row".to_string(),
        compact_selected_key_mixed_qk_source_row(
            selected_pre_rope_f64_residual.pointer("/rows/0").unwrap_or(&Value::Null),
        ),
    );
    report.insert("blocked_reasons".to_string(), blocked_reasons);
    report.insert(
        "next_diagnostic".to_string(),
        json!(selected_key_mixed_qk_frontier_next_diagnostic(classification)),
    );
    Value::Object(report)
}

fn selected_key_f64_score_history_frontier_next_diagnostic(classification: &str) -> &'static str {
    match classification {
        "selected_key_f64_score_history_frontier_selected_query_history" => {
            "follow the selected query score-input history residual before changing key-side runtime math"
        }
        "selected_key_f64_score_history_frontier_selected_key_history" => {
            "localize selected key score-input history buckets before changing score accumulation, softmax, or value mix"
        }
        "selected_key_f64_score_history_frontier_selected_qk_history" => {
            "separate selected query and key score-input history buckets before changing score accumulation"
        }
        "selected_key_f64_score_history_frontier_query_history" => {
            "localize broad query score-input history drift before changing score accumulation"
        }
        "selected_key_f64_score_history_frontier_key_history" => {
            "localize broad key score-input history drift before changing score accumulation"
        }
        "selected_key_f64_score_history_frontier_qk_history" => {
            "separate broad query and key score-input history drift before changing score accumulation"
        }
        "selected_key_f64_score_history_frontier_current_key" => {
            "localize current key score-input drift before changing raw score math"
        }
        "selected_key_f64_score_history_frontier_numeric_no_bucket" => {
            "pin Q/K score-input numeric drift without bucket crossings before changing score accumulation"
        }
        "selected_key_f64_score_history_frontier_score_accumulation" => {
            "replay selected raw QK score accumulation before changing score accumulation policy"
        }
        "selected_key_f64_score_history_frontier_softmax_probability" => {
            "localize selected softmax probability formation before value-mix changes"
        }
        "selected_key_f64_score_history_frontier_value_mix" => {
            "localize selected value-cache/value-mix numeric source before changing value-mix math"
        }
        "selected_key_f64_score_history_frontier_query_only" => {
            "continue selected query-history attribution; selected key f64 score-history frontier is not active"
        }
        "selected_key_f64_score_history_frontier_clean" => {
            "selected key f64 score-history frontier is clean; rerun downstream probability, value-mix, and logits parity"
        }
        "selected_key_f64_score_history_frontier_missing_context" => {
            "capture selected key mixed-QK, f64 score-history, f64 Q/K bucket, and selected query residual context before runtime changes"
        }
        _ => "keep selected key f64 score-history frontier diagnostic-only",
    }
}

fn attention_selected_key_f64_score_history_frontier(
    selected_key_mixed_qk: &Value,
    f64_score_history_residual: &Value,
    f64_qk_score_input_bucket_residual: &Value,
    selected_query_history_residual: &Value,
) -> Value {
    let key_mixed_classification = selected_report_classification(selected_key_mixed_qk);
    let score_history_classification = selected_report_classification(f64_score_history_residual);
    let qk_bucket_classification =
        selected_report_classification(f64_qk_score_input_bucket_residual);
    let query_history_classification =
        selected_report_classification(selected_query_history_residual);

    let classification = if key_mixed_classification.is_none()
        || score_history_classification.is_none()
        || qk_bucket_classification.is_none()
        || query_history_classification.is_none()
    {
        "selected_key_f64_score_history_frontier_missing_context"
    } else if key_mixed_classification == Some("selected_key_mixed_qk_frontier_query_only") {
        "selected_key_f64_score_history_frontier_query_only"
    } else if key_mixed_classification == Some("selected_key_mixed_qk_frontier_clean")
        && score_history_classification == Some("f64_score_history_residual_clean")
        && qk_bucket_classification == Some("f64_qk_score_input_bucket_residual_clean")
    {
        "selected_key_f64_score_history_frontier_clean"
    } else {
        match score_history_classification {
            Some("f64_score_history_residual_score_input") => match qk_bucket_classification {
                Some("f64_qk_score_input_bucket_residual_selected_query_history") => {
                    "selected_key_f64_score_history_frontier_selected_query_history"
                }
                Some("f64_qk_score_input_bucket_residual_selected_key_history") => {
                    "selected_key_f64_score_history_frontier_selected_key_history"
                }
                Some("f64_qk_score_input_bucket_residual_selected_qk_history") => {
                    "selected_key_f64_score_history_frontier_selected_qk_history"
                }
                Some("f64_qk_score_input_bucket_residual_query_history") => {
                    "selected_key_f64_score_history_frontier_query_history"
                }
                Some("f64_qk_score_input_bucket_residual_key_history") => {
                    "selected_key_f64_score_history_frontier_key_history"
                }
                Some("f64_qk_score_input_bucket_residual_qk_history") => {
                    "selected_key_f64_score_history_frontier_qk_history"
                }
                Some("f64_qk_score_input_bucket_residual_current_key") => {
                    "selected_key_f64_score_history_frontier_current_key"
                }
                Some("f64_qk_score_input_bucket_residual_numeric_no_bucket") => {
                    "selected_key_f64_score_history_frontier_numeric_no_bucket"
                }
                Some("f64_qk_score_input_bucket_residual_clean") => {
                    "selected_key_f64_score_history_frontier_score_accumulation"
                }
                _ => "selected_key_f64_score_history_frontier_missing_context",
            },
            Some("f64_score_history_residual_score_accumulation") => {
                "selected_key_f64_score_history_frontier_score_accumulation"
            }
            Some("f64_score_history_residual_softmax_probability") => {
                "selected_key_f64_score_history_frontier_softmax_probability"
            }
            Some("f64_score_history_residual_value_cache_source")
            | Some("f64_score_history_residual_value_mix_numeric") => {
                "selected_key_f64_score_history_frontier_value_mix"
            }
            Some("f64_score_history_residual_clean") => {
                "selected_key_f64_score_history_frontier_clean"
            }
            _ => "selected_key_f64_score_history_frontier_missing_context",
        }
    };

    let blocked_reasons =
        if classification == "selected_key_f64_score_history_frontier_missing_context" {
            json!(["selected_key_f64_score_history_frontier_missing_context"])
        } else {
            json!([])
        };

    json!({
        "diagnostic_only": true,
        "claim_allowed": false,
        "policy": "Selected key f64 score-history frontier is diagnostic-only evidence for reconciling the selected key mixed-QK frontier with f64 score-history and Q/K score-input residual reports; it does not change runtime math or promote reference parity, A770 semantic quality, attention score residency, softmax residency, value-mix residency, selected attention, resident KV, full residency, performance, or completion",
        "classification": classification,
        "selected_key_mixed_qk_classification": key_mixed_classification,
        "f64_score_history_residual_classification": score_history_classification,
        "f64_qk_score_input_bucket_residual_classification": qk_bucket_classification,
        "selected_query_history_residual_classification": query_history_classification,
        "selected_query_head": value_u64(selected_key_mixed_qk, "/selected_query_head"),
        "selected_query_dim": value_u64(selected_key_mixed_qk, "/selected_query_dim"),
        "selected_query_token": value_u64(selected_key_mixed_qk, "/selected_query_token"),
        "selected_query_key_slot": value_u64(selected_key_mixed_qk, "/selected_query_key_slot"),
        "selected_key_context_present": value_bool(selected_key_mixed_qk, "/key_context_present"),
        "selected_key_relevant": value_bool(selected_key_mixed_qk, "/key_relevant"),
        "selected_key_next_diagnostic": selected_key_mixed_qk.pointer("/next_diagnostic").cloned().unwrap_or(Value::Null),
        "f64_score_next_diagnostic": f64_score_history_residual.pointer("/next_diagnostic").cloned().unwrap_or(Value::Null),
        "f64_qk_next_diagnostic": f64_qk_score_input_bucket_residual.pointer("/next_diagnostic").cloned().unwrap_or(Value::Null),
        "selected_query_history_next_diagnostic": selected_query_history_residual.pointer("/next_diagnostic").cloned().unwrap_or(Value::Null),
        "selected_key_first_mixed_qk_product_row": selected_key_mixed_qk.pointer("/first_mixed_qk_product_row").cloned().unwrap_or(Value::Null),
        "selected_key_first_slot_probe_row": selected_key_mixed_qk.pointer("/first_slot_probe_row").cloned().unwrap_or(Value::Null),
        "f64_score_first_material_key_history_head": f64_score_history_residual.pointer("/first_material_key_history_head").cloned().unwrap_or(Value::Null),
        "f64_score_first_material_query_history_head": f64_score_history_residual.pointer("/first_material_query_history_head").cloned().unwrap_or(Value::Null),
        "f64_qk_first_selected_key_bucket_row": f64_qk_score_input_bucket_residual.pointer("/first_selected_key_bucket_row").cloned().unwrap_or(Value::Null),
        "f64_qk_first_selected_query_bucket_row": f64_qk_score_input_bucket_residual.pointer("/first_selected_query_bucket_row").cloned().unwrap_or(Value::Null),
        "selected_query_history_first_mixed_qk_product_row": selected_query_history_residual.pointer("/first_mixed_qk_product_row").cloned().unwrap_or(Value::Null),
        "blocked_reasons": blocked_reasons,
        "next_diagnostic": selected_key_f64_score_history_frontier_next_diagnostic(classification),
    })
}

fn selected_score_residual_decision_frontier_next_diagnostic(classification: &str) -> &'static str {
    match classification {
        "selected_score_residual_decision_frontier_selected_query_history" => {
            "continue selected query history attribution or selected query raw-score operand replay before changing score accumulation"
        }
        "selected_score_residual_decision_frontier_selected_key_history" => {
            "localize selected key score-input history buckets before changing score accumulation, softmax, or value mix"
        }
        "selected_score_residual_decision_frontier_selected_qk_history" => {
            "split selected query and key score-input history buckets before changing score accumulation"
        }
        "selected_score_residual_decision_frontier_raw_score_accumulation" => {
            "replay selected raw QK score accumulation before changing score accumulation policy"
        }
        "selected_score_residual_decision_frontier_score_history_serialization" => {
            "pin score-history serialization/capture before changing score accumulation or softmax"
        }
        "selected_score_residual_decision_frontier_softmax_probability" => {
            "localize selected softmax probability formation before changing value-mix inputs"
        }
        "selected_score_residual_decision_frontier_value_mix" => {
            "localize selected value-cache/value-mix numeric source before changing value-mix runtime math"
        }
        "selected_score_residual_decision_frontier_query_only" => {
            "continue selected query residual attribution; selected key f64 frontier is not active"
        }
        "selected_score_residual_decision_frontier_clean" => {
            "selected score residual frontier is clean; rerun downstream probability, value-mix, logits, and behavior parity"
        }
        "selected_score_residual_decision_frontier_missing_context" => {
            "capture selected key f64, selected query history, raw-score operand, and Q/K downstream score residual context before runtime changes"
        }
        _ => "keep selected score residual decision frontier diagnostic-only",
    }
}

fn selected_score_residual_decision_from_query_history(
    query_history_classification: Option<&str>,
    raw_score_operand_classification: Option<&str>,
) -> &'static str {
    match query_history_classification {
        Some("selected_query_history_residual_query_score_input_source")
        | Some("selected_query_history_residual_f16_boundary")
        | Some("selected_query_history_residual_pre_score_rope")
        | Some("selected_query_history_residual_pre_rope_projection")
        | Some("selected_query_history_residual_rope_expression")
        | Some("selected_query_history_residual_projection_source")
        | Some("selected_query_history_residual_attention_norm_input")
        | Some("selected_query_history_residual_attention_norm_replay") => {
            "selected_score_residual_decision_frontier_selected_query_history"
        }
        Some("selected_query_history_residual_downstream_score_after_clean_source_chain") => {
            match raw_score_operand_classification {
                Some("selected_query_head_raw_score_operand_mixed_qk_context") => {
                    "selected_score_residual_decision_frontier_selected_qk_history"
                }
                Some("selected_query_head_raw_score_operand_key_context") => {
                    "selected_score_residual_decision_frontier_selected_key_history"
                }
                Some("selected_query_head_raw_score_operand_score_input_serialization_clean") => {
                    "selected_score_residual_decision_frontier_raw_score_accumulation"
                }
                Some("selected_query_head_raw_score_operand_query_f16_explains_score")
                | Some(
                    "selected_query_head_raw_score_operand_query_f16_explains_with_bucket_context",
                )
                | Some("selected_query_head_raw_score_operand_pre_f16_better")
                | Some("selected_query_head_raw_score_operand_unexplained") => {
                    "selected_score_residual_decision_frontier_selected_query_history"
                }
                _ => "selected_score_residual_decision_frontier_missing_context",
            }
        }
        Some("selected_query_history_residual_raw_score_accumulation") => {
            "selected_score_residual_decision_frontier_raw_score_accumulation"
        }
        Some("selected_query_history_residual_score_history_serialization") => {
            "selected_score_residual_decision_frontier_score_history_serialization"
        }
        Some("selected_query_history_residual_softmax_probability") => {
            "selected_score_residual_decision_frontier_softmax_probability"
        }
        Some("selected_query_history_residual_value_mix") => {
            "selected_score_residual_decision_frontier_value_mix"
        }
        Some("selected_query_history_residual_clean") => {
            "selected_score_residual_decision_frontier_clean"
        }
        _ => "selected_score_residual_decision_frontier_missing_context",
    }
}

fn selected_score_residual_decision_from_qk_downstream(
    qk_downstream_classification: Option<&str>,
) -> Option<&'static str> {
    match qk_downstream_classification {
        Some("selected_qk_downstream_score_residual_selected_query_history") => {
            Some("selected_score_residual_decision_frontier_selected_query_history")
        }
        Some("selected_qk_downstream_score_residual_key_pre_rope")
        | Some("selected_qk_downstream_score_residual_key_post_rope_history")
        | Some("selected_qk_downstream_score_residual_key_score_input_expansion")
        | Some("selected_qk_downstream_score_residual_key_exact_boundary") => {
            Some("selected_score_residual_decision_frontier_selected_key_history")
        }
        Some("selected_qk_downstream_score_residual_mixed_qk_product") => {
            Some("selected_score_residual_decision_frontier_selected_qk_history")
        }
        Some("selected_qk_downstream_score_residual_raw_score_accumulation") => {
            Some("selected_score_residual_decision_frontier_raw_score_accumulation")
        }
        Some("selected_qk_downstream_score_residual_score_history_serialization") => {
            Some("selected_score_residual_decision_frontier_score_history_serialization")
        }
        Some("selected_qk_downstream_score_residual_softmax_probability") => {
            Some("selected_score_residual_decision_frontier_softmax_probability")
        }
        Some("selected_qk_downstream_score_residual_value_mix") => {
            Some("selected_score_residual_decision_frontier_value_mix")
        }
        Some("selected_qk_downstream_score_residual_clean") => {
            Some("selected_score_residual_decision_frontier_clean")
        }
        _ => None,
    }
}

fn attention_selected_score_residual_decision_frontier(
    selected_key_f64_score_history: &Value,
    selected_query_history_residual: &Value,
    selected_query_raw_score_operand: &Value,
    selected_query_downstream: &Value,
    selected_qk_downstream: &Value,
) -> Value {
    let key_f64_classification = selected_report_classification(selected_key_f64_score_history);
    let query_history_classification =
        selected_report_classification(selected_query_history_residual);
    let raw_score_operand_classification =
        selected_report_classification(selected_query_raw_score_operand);
    let query_downstream_classification = selected_report_classification(selected_query_downstream);
    let qk_downstream_classification = selected_report_classification(selected_qk_downstream);
    let qk_downstream_decision =
        selected_score_residual_decision_from_qk_downstream(qk_downstream_classification);

    let classification = match key_f64_classification {
        None | Some("selected_key_f64_score_history_frontier_missing_context") => {
            "selected_score_residual_decision_frontier_missing_context"
        }
        Some("selected_key_f64_score_history_frontier_selected_query_history")
        | Some("selected_key_f64_score_history_frontier_query_history") => {
            let query_decision = selected_score_residual_decision_from_query_history(
                query_history_classification,
                raw_score_operand_classification,
            );
            if query_decision == "selected_score_residual_decision_frontier_missing_context" {
                qk_downstream_decision.unwrap_or(query_decision)
            } else {
                query_decision
            }
        }
        Some("selected_key_f64_score_history_frontier_selected_key_history")
        | Some("selected_key_f64_score_history_frontier_key_history")
        | Some("selected_key_f64_score_history_frontier_current_key") => {
            "selected_score_residual_decision_frontier_selected_key_history"
        }
        Some("selected_key_f64_score_history_frontier_selected_qk_history")
        | Some("selected_key_f64_score_history_frontier_qk_history") => {
            "selected_score_residual_decision_frontier_selected_qk_history"
        }
        Some("selected_key_f64_score_history_frontier_numeric_no_bucket")
        | Some("selected_key_f64_score_history_frontier_score_accumulation") => {
            "selected_score_residual_decision_frontier_raw_score_accumulation"
        }
        Some("selected_key_f64_score_history_frontier_softmax_probability") => {
            "selected_score_residual_decision_frontier_softmax_probability"
        }
        Some("selected_key_f64_score_history_frontier_value_mix") => {
            "selected_score_residual_decision_frontier_value_mix"
        }
        Some("selected_key_f64_score_history_frontier_query_only") => {
            match query_history_classification {
                Some("selected_query_history_residual_missing_context") | None => {
                    "selected_score_residual_decision_frontier_missing_context"
                }
                _ => "selected_score_residual_decision_frontier_query_only",
            }
        }
        Some("selected_key_f64_score_history_frontier_clean") => {
            "selected_score_residual_decision_frontier_clean"
        }
        _ => "selected_score_residual_decision_frontier_missing_context",
    };

    let blocked_reasons =
        if classification == "selected_score_residual_decision_frontier_missing_context" {
            json!(["selected_score_residual_decision_frontier_missing_context"])
        } else {
            json!([])
        };

    json!({
        "diagnostic_only": true,
        "claim_allowed": false,
        "policy": "Selected score residual decision frontier is diagnostic-only evidence for choosing the next selected score residual optic from existing selected query/key/frontier reports; it does not change runtime math or promote reference parity, A770 semantic quality, attention score residency, softmax residency, value-mix residency, selected attention, resident KV, full residency, performance, or completion",
        "classification": classification,
        "selected_key_f64_score_history_frontier_classification": key_f64_classification,
        "selected_query_history_residual_classification": query_history_classification,
        "selected_query_head_raw_score_operand_classification": raw_score_operand_classification,
        "selected_query_downstream_score_residual_classification": query_downstream_classification,
        "selected_qk_downstream_score_residual_classification": qk_downstream_classification,
        "selected_qk_downstream_decision_candidate": qk_downstream_decision,
        "selected_query_head": value_u64(selected_key_f64_score_history, "/selected_query_head")
            .or_else(|| value_u64(selected_query_history_residual, "/selected_query_head"))
            .or_else(|| value_u64(selected_query_raw_score_operand, "/head"))
            .or_else(|| value_u64(selected_query_downstream, "/selected_query_head"))
            .or_else(|| value_u64(selected_qk_downstream, "/selected_query_head")),
        "selected_query_dim": value_u64(selected_key_f64_score_history, "/selected_query_dim")
            .or_else(|| value_u64(selected_query_history_residual, "/selected_query_dim"))
            .or_else(|| value_u64(selected_query_raw_score_operand, "/selected_dim"))
            .or_else(|| value_u64(selected_query_downstream, "/selected_query_dim"))
            .or_else(|| value_u64(selected_qk_downstream, "/selected_query_dim")),
        "selected_query_token": value_u64(selected_key_f64_score_history, "/selected_query_token")
            .or_else(|| value_u64(selected_query_history_residual, "/selected_query_token"))
            .or_else(|| value_u64(selected_query_raw_score_operand, "/selected_token"))
            .or_else(|| value_u64(selected_query_downstream, "/selected_query_token"))
            .or_else(|| value_u64(selected_qk_downstream, "/selected_query_token")),
        "selected_query_key_slot": value_u64(selected_key_f64_score_history, "/selected_query_key_slot")
            .or_else(|| value_u64(selected_query_history_residual, "/selected_query_key_slot"))
            .or_else(|| value_u64(selected_query_raw_score_operand, "/key_slot"))
            .or_else(|| value_u64(selected_query_downstream, "/selected_query_key_slot"))
            .or_else(|| value_u64(selected_qk_downstream, "/selected_query_key_slot")),
        "selected_key_context_present": value_bool(selected_key_f64_score_history, "/selected_key_context_present"),
        "selected_key_relevant": value_bool(selected_key_f64_score_history, "/selected_key_relevant"),
        "selected_key_frontier_next_diagnostic": selected_key_f64_score_history.pointer("/next_diagnostic").cloned().unwrap_or(Value::Null),
        "selected_query_history_next_diagnostic": selected_query_history_residual.pointer("/next_diagnostic").cloned().unwrap_or(Value::Null),
        "selected_query_raw_score_operand_next_diagnostic": selected_query_raw_score_operand.pointer("/next_diagnostic").cloned().unwrap_or(Value::Null),
        "selected_query_downstream_next_diagnostic": selected_query_downstream.pointer("/next_diagnostic").cloned().unwrap_or(Value::Null),
        "selected_qk_downstream_next_diagnostic": selected_qk_downstream.pointer("/next_diagnostic").cloned().unwrap_or(Value::Null),
        "selected_key_first_mixed_qk_product_row": selected_key_f64_score_history.pointer("/selected_key_first_mixed_qk_product_row").cloned().unwrap_or(Value::Null),
        "selected_query_history_first_mixed_qk_product_row": selected_query_history_residual.pointer("/first_mixed_qk_product_row").cloned().unwrap_or(Value::Null),
        "selected_query_raw_score_operand_first_mixed_qk_product_row": selected_query_raw_score_operand.pointer("/first_mixed_score_position_row").cloned().unwrap_or(Value::Null),
        "selected_qk_first_mixed_qk_product_row": selected_qk_downstream.pointer("/first_mixed_qk_product_row").cloned().unwrap_or(Value::Null),
        "blocked_reasons": blocked_reasons,
        "next_diagnostic": selected_score_residual_decision_frontier_next_diagnostic(classification),
    })
}

fn selected_key_score_history_bucket_decision_next_diagnostic(
    classification: &str,
) -> &'static str {
    match classification {
        "selected_key_score_history_bucket_decision_post_rope_capture_replay" => {
            "pin selected post-RoPE trace capture versus runtime replay before changing score accumulation, softmax, or value mix"
        }
        "selected_key_score_history_bucket_decision_pre_rope_projection" => {
            "localize selected K projection input/output bucket crossing before changing RoPE or score math"
        }
        "selected_key_score_history_bucket_decision_projection_subbucket_midpoint" => {
            "localize selected K projection sub-bucket midpoint before changing RoPE or score math"
        }
        "selected_key_score_history_bucket_decision_post_rope_f16_midpoint" => {
            "decide whether selected post-RoPE F16 midpoint sensitivity is acceptable capture precision before runtime math changes"
        }
        "selected_key_score_history_bucket_decision_post_rope_runtime_replay" => {
            "pin selected post-RoPE runtime replay before changing score-input history expansion"
        }
        "selected_key_score_history_bucket_decision_attention_norm_history" => {
            "pin selected pre-RoPE attention-norm history before changing K projection or score math"
        }
        "selected_key_score_history_bucket_decision_score_input_expansion" => {
            "localize selected post-RoPE to score-input history expansion before changing score accumulation"
        }
        "selected_key_score_history_bucket_decision_exact_key_boundary" => {
            "follow the exact selected key boundary report before changing score accumulation, softmax, or value mix"
        }
        "selected_key_score_history_bucket_decision_post_rope_history" => {
            "localize selected post-RoPE history bucket source before changing score accumulation, softmax, or value mix"
        }
        "selected_key_score_history_bucket_decision_mixed_qk_product" => {
            "replay selected mixed Q/K product before changing score accumulation"
        }
        "selected_key_score_history_bucket_decision_raw_score_accumulation" => {
            "replay selected raw QK score accumulation before changing score accumulation policy"
        }
        "selected_key_score_history_bucket_decision_score_history_serialization" => {
            "pin score-history serialization/capture before changing score accumulation or softmax"
        }
        "selected_key_score_history_bucket_decision_softmax_probability" => {
            "localize selected softmax probability formation before value-mix changes"
        }
        "selected_key_score_history_bucket_decision_value_mix" => {
            "localize selected value-mix inputs before changing value-mix runtime math"
        }
        "selected_key_score_history_bucket_decision_clean" => {
            "selected key score-history bucket decision is clean; rerun downstream probability, value-mix, and logits parity"
        }
        "selected_key_score_history_bucket_decision_not_key_history" => {
            "follow the non-key selected score residual decision frontier"
        }
        "selected_key_score_history_bucket_decision_missing_context" => {
            "capture selected key slot, post-RoPE history, post-RoPE replay, and Q/K downstream context before runtime changes"
        }
        _ => "keep selected key score-history bucket decision diagnostic-only",
    }
}

fn attention_selected_key_score_history_bucket_decision_frontier(
    selected_score_decision: &Value,
    selected_qk_downstream: &Value,
    selected_key_mixed_qk: &Value,
    base_comparison: &Value,
) -> Value {
    let score_decision_classification = selected_report_classification(selected_score_decision);
    let qk_downstream_classification = selected_report_classification(selected_qk_downstream);
    let selected_key_mixed_qk_classification =
        selected_report_classification(selected_key_mixed_qk);
    let slot_probe = base_comparison
        .pointer("/attention_selected_key_dim_token_slot_probe")
        .unwrap_or(&Value::Null);
    let post_rope_source = base_comparison
        .pointer("/attention_selected_post_rope_history_bucket_source")
        .unwrap_or(&Value::Null);
    let post_rope_capture = base_comparison
        .pointer("/attention_selected_post_rope_capture_replay_source")
        .unwrap_or(&Value::Null);
    let rust_post_rope_capture = base_comparison
        .pointer("/attention_selected_rust_post_rope_capture_source")
        .unwrap_or(&Value::Null);
    let post_rope_runtime = base_comparison
        .pointer("/attention_selected_post_rope_runtime_replay_source")
        .unwrap_or(&Value::Null);
    let pre_rope_pair = base_comparison
        .pointer("/attention_selected_pre_rope_projection_pair_source")
        .unwrap_or(&Value::Null);
    let pre_rope_history = base_comparison
        .pointer("/attention_selected_pre_rope_projection_history_source")
        .unwrap_or(&Value::Null);
    let pre_rope_norm = base_comparison
        .pointer("/attention_selected_pre_rope_attention_norm_history_source")
        .unwrap_or(&Value::Null);

    let slot_probe_classification = selected_report_classification(slot_probe);
    let post_rope_source_classification = selected_report_classification(post_rope_source);
    let post_rope_capture_classification = selected_report_classification(post_rope_capture);
    let rust_post_rope_capture_classification =
        selected_report_classification(rust_post_rope_capture);
    let post_rope_runtime_classification = selected_report_classification(post_rope_runtime);
    let pre_rope_pair_classification = selected_report_classification(pre_rope_pair);
    let pre_rope_history_classification = selected_report_classification(pre_rope_history);
    let pre_rope_norm_classification = selected_report_classification(pre_rope_norm);
    let active_key_history = matches!(
        score_decision_classification,
        Some("selected_score_residual_decision_frontier_selected_key_history")
            | Some("selected_score_residual_decision_frontier_selected_qk_history")
    );
    let key_context_present = [
        qk_downstream_classification,
        selected_key_mixed_qk_classification,
        slot_probe_classification,
        post_rope_source_classification,
        post_rope_capture_classification,
        rust_post_rope_capture_classification,
        post_rope_runtime_classification,
        pre_rope_pair_classification,
        pre_rope_history_classification,
        pre_rope_norm_classification,
    ]
    .iter()
    .any(Option::is_some);

    let classification = if score_decision_classification.is_none() {
        "selected_key_score_history_bucket_decision_missing_context"
    } else if !active_key_history {
        "selected_key_score_history_bucket_decision_not_key_history"
    } else if matches!(
        qk_downstream_classification,
        Some("selected_qk_downstream_score_residual_score_history_serialization")
    ) {
        "selected_key_score_history_bucket_decision_score_history_serialization"
    } else if matches!(
        qk_downstream_classification,
        Some("selected_qk_downstream_score_residual_softmax_probability")
    ) {
        "selected_key_score_history_bucket_decision_softmax_probability"
    } else if matches!(
        qk_downstream_classification,
        Some("selected_qk_downstream_score_residual_value_mix")
    ) {
        "selected_key_score_history_bucket_decision_value_mix"
    } else if matches!(
        qk_downstream_classification,
        Some("selected_qk_downstream_score_residual_clean")
    ) {
        "selected_key_score_history_bucket_decision_clean"
    } else if matches!(
        qk_downstream_classification,
        Some("selected_qk_downstream_score_residual_raw_score_accumulation")
    ) {
        "selected_key_score_history_bucket_decision_raw_score_accumulation"
    } else if matches!(
        qk_downstream_classification,
        Some("selected_qk_downstream_score_residual_key_score_input_expansion")
    ) || slot_probe_classification
        == Some("selected_key_dim_token_slot_probe_score_input_bucket_crossing")
    {
        "selected_key_score_history_bucket_decision_score_input_expansion"
    } else if matches!(
        qk_downstream_classification,
        Some("selected_qk_downstream_score_residual_mixed_qk_product")
    ) || matches!(
        selected_key_mixed_qk_classification,
        Some("selected_key_mixed_qk_frontier_post_rope_bucket_crossing")
    ) {
        "selected_key_score_history_bucket_decision_mixed_qk_product"
    } else if matches!(
        qk_downstream_classification,
        Some("selected_qk_downstream_score_residual_key_pre_rope")
    ) || matches!(
        post_rope_source_classification,
        Some("selected_post_rope_history_bucket_source_pre_rope_bucket_crossing")
            | Some("selected_post_rope_history_bucket_source_projection_bucket_crossing")
    ) || matches!(
        pre_rope_pair_classification,
        Some("selected_pre_rope_projection_pair_source_raw_projection_pair_delta")
            | Some("selected_pre_rope_projection_pair_source_projection_bucket_crossing")
    ) || pre_rope_history_classification
        == Some("selected_pre_rope_projection_history_replay_explains_pair_delta")
    {
        "selected_key_score_history_bucket_decision_pre_rope_projection"
    } else if post_rope_source_classification
        == Some("selected_post_rope_history_bucket_source_projection_subbucket_midpoint")
    {
        "selected_key_score_history_bucket_decision_projection_subbucket_midpoint"
    } else if post_rope_source_classification
        == Some("selected_post_rope_history_bucket_source_f16_midpoint_sensitive")
    {
        "selected_key_score_history_bucket_decision_post_rope_f16_midpoint"
    } else if matches!(
        post_rope_source_classification,
        Some("selected_post_rope_history_bucket_source_capture_replay_mismatch")
    ) || matches!(
        post_rope_capture_classification,
        Some(
            "selected_post_rope_capture_replay_source_reference_capture_mismatch"
                | "selected_post_rope_capture_replay_source_rust_capture_mismatch"
                | "selected_post_rope_capture_replay_source_both_sides_mismatch"
                | "selected_post_rope_capture_replay_source_runtime_replay_delta"
        )
    ) || matches!(
        rust_post_rope_capture_classification,
        Some(
            "selected_rust_post_rope_capture_source_capture_mismatch"
                | "selected_rust_post_rope_capture_source_runtime_replay_unclean"
        )
    ) {
        "selected_key_score_history_bucket_decision_post_rope_capture_replay"
    } else if matches!(
        post_rope_runtime_classification,
        Some("selected_post_rope_runtime_replay_source_projection_pair_delta_bucket_crossing")
    ) {
        "selected_key_score_history_bucket_decision_post_rope_runtime_replay"
    } else if matches!(
        pre_rope_norm_classification,
        Some(
            "selected_pre_rope_attention_norm_history_source_output_replay_explains_epsilon"
                | "selected_pre_rope_attention_norm_history_source_input_history_epsilon"
                | "selected_pre_rope_attention_norm_history_source_output_epsilon_unpinned"
        )
    ) {
        "selected_key_score_history_bucket_decision_attention_norm_history"
    } else if matches!(
        qk_downstream_classification,
        Some("selected_qk_downstream_score_residual_key_exact_boundary")
    ) {
        "selected_key_score_history_bucket_decision_exact_key_boundary"
    } else if matches!(
        qk_downstream_classification,
        Some("selected_qk_downstream_score_residual_key_post_rope_history")
    ) || slot_probe_classification
        == Some("selected_key_dim_token_slot_probe_post_rope_bucket_crossing")
    {
        "selected_key_score_history_bucket_decision_post_rope_history"
    } else if !key_context_present {
        "selected_key_score_history_bucket_decision_missing_context"
    } else {
        "selected_key_score_history_bucket_decision_missing_context"
    };

    let blocked_reasons =
        if classification == "selected_key_score_history_bucket_decision_missing_context" {
            json!(["selected_key_score_history_bucket_decision_missing_context"])
        } else {
            json!([])
        };

    json!({
        "diagnostic_only": true,
        "claim_allowed": false,
        "policy": "Selected key score-history bucket decision frontier is diagnostic-only evidence for turning a selected-key final score decision into the next selected key bucket optic; it consumes existing key slot, post-RoPE history, post-RoPE replay, mixed-QK, and Q/K downstream reports without adding trace capture, changing runtime math, or promoting reference parity, A770 semantic quality, attention score residency, softmax residency, value-mix residency, selected attention, resident KV, full residency, performance, or completion",
        "classification": classification,
        "selected_score_residual_decision_classification": score_decision_classification,
        "selected_qk_downstream_score_residual_classification": qk_downstream_classification,
        "selected_key_mixed_qk_frontier_classification": selected_key_mixed_qk_classification,
        "selected_key_slot_probe_classification": slot_probe_classification,
        "selected_post_rope_history_bucket_source_classification": post_rope_source_classification,
        "selected_post_rope_capture_replay_source_classification": post_rope_capture_classification,
        "selected_rust_post_rope_capture_source_classification": rust_post_rope_capture_classification,
        "selected_post_rope_runtime_replay_source_classification": post_rope_runtime_classification,
        "selected_pre_rope_projection_pair_source_classification": pre_rope_pair_classification,
        "selected_pre_rope_projection_history_source_classification": pre_rope_history_classification,
        "selected_pre_rope_attention_norm_history_source_classification": pre_rope_norm_classification,
        "selected_query_head": value_u64(selected_score_decision, "/selected_query_head")
            .or_else(|| value_u64(selected_qk_downstream, "/selected_query_head"))
            .or_else(|| value_u64(selected_key_mixed_qk, "/selected_query_head")),
        "selected_query_dim": value_u64(selected_score_decision, "/selected_query_dim")
            .or_else(|| value_u64(selected_qk_downstream, "/selected_query_dim"))
            .or_else(|| value_u64(selected_key_mixed_qk, "/selected_query_dim")),
        "selected_query_token": value_u64(selected_score_decision, "/selected_query_token")
            .or_else(|| value_u64(selected_qk_downstream, "/selected_query_token"))
            .or_else(|| value_u64(selected_key_mixed_qk, "/selected_query_token")),
        "selected_query_key_slot": value_u64(selected_score_decision, "/selected_query_key_slot")
            .or_else(|| value_u64(selected_qk_downstream, "/selected_query_key_slot"))
            .or_else(|| value_u64(selected_key_mixed_qk, "/selected_query_key_slot")),
        "active_key_history": active_key_history,
        "key_context_present": key_context_present,
        "first_qk_downstream_row": selected_qk_downstream.pointer("/first_slot_probe_row").cloned().unwrap_or(Value::Null),
        "first_slot_probe_row": compact_selected_key_slot_probe_row(slot_probe.pointer("/rows/0").unwrap_or(&Value::Null)),
        "first_post_rope_history_row": compact_selected_key_mixed_qk_source_row(post_rope_source.pointer("/rows/0").unwrap_or(&Value::Null)),
        "first_post_rope_capture_row": compact_selected_key_mixed_qk_source_row(post_rope_capture.pointer("/rows/0").unwrap_or(&Value::Null)),
        "first_rust_post_rope_capture_row": compact_selected_key_mixed_qk_source_row(rust_post_rope_capture.pointer("/rows/0").unwrap_or(&Value::Null)),
        "first_post_rope_runtime_row": compact_selected_key_mixed_qk_source_row(post_rope_runtime.pointer("/rows/0").unwrap_or(&Value::Null)),
        "first_pre_rope_projection_pair_row": compact_selected_key_mixed_qk_source_row(pre_rope_pair.pointer("/rows/0").unwrap_or(&Value::Null)),
        "first_pre_rope_projection_history_row": compact_selected_key_mixed_qk_source_row(pre_rope_history.pointer("/rows/0").unwrap_or(&Value::Null)),
        "first_pre_rope_attention_norm_row": compact_selected_key_mixed_qk_source_row(pre_rope_norm.pointer("/rows/0").unwrap_or(&Value::Null)),
        "blocked_reasons": blocked_reasons,
        "next_diagnostic": selected_key_score_history_bucket_decision_next_diagnostic(classification),
    })
}

fn selected_key_score_input_bucket_source_next_diagnostic(classification: &str) -> &'static str {
    match classification {
        "selected_key_score_input_bucket_source_post_rope_history" => {
            "localize selected post-RoPE history bucket source before changing score accumulation, softmax, or value mix"
        }
        "selected_key_score_input_bucket_source_post_rope_capture_replay" => {
            "pin selected post-RoPE capture/replay before changing score-input history or score accumulation"
        }
        "selected_key_score_input_bucket_source_post_rope_runtime_replay" => {
            "pin selected post-RoPE runtime replay before changing score-input history expansion"
        }
        "selected_key_score_input_bucket_source_pre_rope_projection_pair" => {
            "localize selected K pre-RoPE projection pair before changing K projection, RoPE, or score math"
        }
        "selected_key_score_input_bucket_source_pre_rope_projection_history" => {
            "localize selected K pre-RoPE projection history before changing K projection or score math"
        }
        "selected_key_score_input_bucket_source_attention_norm_history" => {
            "pin selected K attention-norm history before changing K projection or RMSNorm math"
        }
        "selected_key_score_input_bucket_source_f64_score_history_residual" => {
            "localize f64 score-history residual before changing score accumulation, softmax, or value mix"
        }
        "selected_key_score_input_bucket_source_clean" => {
            "selected key score-input bucket source is clean; rerun downstream score, probability, value-mix, and logits parity"
        }
        "selected_key_score_input_bucket_source_missing_context" => {
            "capture selected key score-history decision, post-RoPE, pre-RoPE, attention-norm, and f64 residual context"
        }
        _ => "keep selected key score-input bucket source diagnostic-only",
    }
}

fn attention_selected_key_score_input_bucket_source_frontier(
    selected_key_decision: &Value,
    selected_pre_rope_f64_residual: &Value,
    base_comparison: &Value,
) -> Value {
    let decision_classification = selected_report_classification(selected_key_decision);
    let slot_probe = base_comparison
        .pointer("/attention_selected_key_dim_token_slot_probe")
        .unwrap_or(&Value::Null);
    let post_rope_source = base_comparison
        .pointer("/attention_selected_post_rope_history_bucket_source")
        .unwrap_or(&Value::Null);
    let post_rope_capture = base_comparison
        .pointer("/attention_selected_post_rope_capture_replay_source")
        .unwrap_or(&Value::Null);
    let rust_post_rope_capture = base_comparison
        .pointer("/attention_selected_rust_post_rope_capture_source")
        .unwrap_or(&Value::Null);
    let post_rope_runtime = base_comparison
        .pointer("/attention_selected_post_rope_runtime_replay_source")
        .unwrap_or(&Value::Null);
    let pre_rope_pair = base_comparison
        .pointer("/attention_selected_pre_rope_projection_pair_source")
        .unwrap_or(&Value::Null);
    let pre_rope_history = base_comparison
        .pointer("/attention_selected_pre_rope_projection_history_source")
        .unwrap_or(&Value::Null);
    let pre_rope_norm = base_comparison
        .pointer("/attention_selected_pre_rope_attention_norm_history_source")
        .unwrap_or(&Value::Null);

    let slot_probe_classification = selected_report_classification(slot_probe);
    let post_rope_source_classification = selected_report_classification(post_rope_source);
    let post_rope_capture_classification = selected_report_classification(post_rope_capture);
    let rust_post_rope_capture_classification =
        selected_report_classification(rust_post_rope_capture);
    let post_rope_runtime_classification = selected_report_classification(post_rope_runtime);
    let pre_rope_pair_classification = selected_report_classification(pre_rope_pair);
    let pre_rope_history_classification = selected_report_classification(pre_rope_history);
    let pre_rope_norm_classification = selected_report_classification(pre_rope_norm);
    let f64_residual_classification =
        selected_report_classification(selected_pre_rope_f64_residual);
    let active_key_history = matches!(
        decision_classification,
        Some("selected_key_score_history_bucket_decision_post_rope_history")
            | Some("selected_key_score_history_bucket_decision_post_rope_capture_replay")
            | Some("selected_key_score_history_bucket_decision_post_rope_runtime_replay")
            | Some("selected_key_score_history_bucket_decision_pre_rope_projection")
            | Some("selected_key_score_history_bucket_decision_projection_subbucket_midpoint")
            | Some("selected_key_score_history_bucket_decision_post_rope_f16_midpoint")
            | Some("selected_key_score_history_bucket_decision_attention_norm_history")
            | Some("selected_key_score_history_bucket_decision_score_input_expansion")
            | Some("selected_key_score_history_bucket_decision_exact_key_boundary")
            | Some("selected_key_score_history_bucket_decision_mixed_qk_product")
            | Some("selected_key_score_history_bucket_decision_raw_score_accumulation")
            | Some("selected_key_score_history_bucket_decision_score_history_serialization")
            | Some("selected_key_score_history_bucket_decision_softmax_probability")
            | Some("selected_key_score_history_bucket_decision_value_mix")
            | Some("selected_key_score_history_bucket_decision_clean")
    );
    let context_present = [
        decision_classification,
        slot_probe_classification,
        post_rope_source_classification,
        post_rope_capture_classification,
        rust_post_rope_capture_classification,
        post_rope_runtime_classification,
        pre_rope_pair_classification,
        pre_rope_history_classification,
        pre_rope_norm_classification,
        f64_residual_classification,
    ]
    .iter()
    .any(Option::is_some);

    let classification = if decision_classification.is_none() || !context_present {
        "selected_key_score_input_bucket_source_missing_context"
    } else if !active_key_history {
        "selected_key_score_input_bucket_source_missing_context"
    } else if decision_classification == Some("selected_key_score_history_bucket_decision_clean") {
        "selected_key_score_input_bucket_source_clean"
    } else if matches!(
        decision_classification,
        Some(
            "selected_key_score_history_bucket_decision_raw_score_accumulation"
                | "selected_key_score_history_bucket_decision_score_history_serialization"
                | "selected_key_score_history_bucket_decision_softmax_probability"
                | "selected_key_score_history_bucket_decision_value_mix"
        )
    ) {
        "selected_key_score_input_bucket_source_f64_score_history_residual"
    } else if matches!(
        decision_classification,
        Some("selected_key_score_history_bucket_decision_attention_norm_history")
    ) || matches!(
        pre_rope_norm_classification,
        Some(
            "selected_pre_rope_attention_norm_history_source_output_replay_explains_epsilon"
                | "selected_pre_rope_attention_norm_history_source_input_history_epsilon"
                | "selected_pre_rope_attention_norm_history_source_output_epsilon_unpinned"
        )
    ) {
        "selected_key_score_input_bucket_source_attention_norm_history"
    } else if matches!(
        decision_classification,
        Some("selected_key_score_history_bucket_decision_pre_rope_projection")
    ) && matches!(
        pre_rope_history_classification,
        Some(
            "selected_pre_rope_projection_history_replay_explains_pair_delta"
                | "selected_pre_rope_projection_history_source_unpinned"
        )
    ) {
        "selected_key_score_input_bucket_source_pre_rope_projection_history"
    } else if matches!(
        decision_classification,
        Some(
            "selected_key_score_history_bucket_decision_pre_rope_projection"
                | "selected_key_score_history_bucket_decision_projection_subbucket_midpoint"
        )
    ) || matches!(
        pre_rope_pair_classification,
        Some(
            "selected_pre_rope_projection_pair_source_raw_projection_pair_delta"
                | "selected_pre_rope_projection_pair_source_projection_bucket_crossing"
                | "selected_pre_rope_projection_pair_source_unpinned"
        )
    ) {
        "selected_key_score_input_bucket_source_pre_rope_projection_pair"
    } else if decision_classification
        == Some("selected_key_score_history_bucket_decision_post_rope_runtime_replay")
        || matches!(
            post_rope_runtime_classification,
            Some("selected_post_rope_runtime_replay_source_projection_pair_delta_bucket_crossing")
        )
    {
        "selected_key_score_input_bucket_source_post_rope_runtime_replay"
    } else if decision_classification
        == Some("selected_key_score_history_bucket_decision_post_rope_capture_replay")
        || matches!(
            post_rope_source_classification,
            Some("selected_post_rope_history_bucket_source_capture_replay_mismatch")
        )
        || matches!(
            post_rope_capture_classification,
            Some(
                "selected_post_rope_capture_replay_source_reference_capture_mismatch"
                    | "selected_post_rope_capture_replay_source_rust_capture_mismatch"
                    | "selected_post_rope_capture_replay_source_both_sides_mismatch"
                    | "selected_post_rope_capture_replay_source_runtime_replay_delta"
            )
        )
        || matches!(
            rust_post_rope_capture_classification,
            Some(
                "selected_rust_post_rope_capture_source_capture_mismatch"
                    | "selected_rust_post_rope_capture_source_runtime_replay_unclean"
            )
        )
    {
        "selected_key_score_input_bucket_source_post_rope_capture_replay"
    } else if matches!(
        decision_classification,
        Some(
            "selected_key_score_history_bucket_decision_post_rope_history"
                | "selected_key_score_history_bucket_decision_post_rope_f16_midpoint"
                | "selected_key_score_history_bucket_decision_score_input_expansion"
                | "selected_key_score_history_bucket_decision_exact_key_boundary"
                | "selected_key_score_history_bucket_decision_mixed_qk_product"
        )
    ) || matches!(
        post_rope_source_classification,
        Some(
            "selected_post_rope_history_bucket_source_projection_bucket_crossing"
                | "selected_post_rope_history_bucket_source_projection_subbucket_midpoint"
                | "selected_post_rope_history_bucket_source_f16_midpoint_sensitive"
                | "selected_post_rope_history_bucket_source_unpinned"
        )
    ) || slot_probe_classification
        == Some("selected_key_dim_token_slot_probe_post_rope_bucket_crossing")
    {
        "selected_key_score_input_bucket_source_post_rope_history"
    } else {
        "selected_key_score_input_bucket_source_missing_context"
    };

    let blocked_reasons =
        if classification == "selected_key_score_input_bucket_source_missing_context" {
            json!(["selected_key_score_input_bucket_source_missing_context"])
        } else {
            json!([])
        };

    json!({
        "diagnostic_only": true,
        "claim_allowed": false,
        "policy": "Selected key score-input bucket source frontier is diagnostic-only evidence for routing the selected-key score-history decision to the next exact source boundary; it consumes existing key slot, post-RoPE history, post-RoPE replay, runtime replay, pre-RoPE projection, attention-norm, and f64 residual reports without adding trace capture, changing runtime math, or promoting reference parity, A770 semantic quality, attention score residency, softmax residency, value-mix residency, selected attention, resident KV, full residency, performance, or completion",
        "classification": classification,
        "selected_key_score_history_bucket_decision_classification": decision_classification,
        "selected_key_slot_probe_classification": slot_probe_classification,
        "selected_post_rope_history_bucket_source_classification": post_rope_source_classification,
        "selected_post_rope_capture_replay_source_classification": post_rope_capture_classification,
        "selected_rust_post_rope_capture_source_classification": rust_post_rope_capture_classification,
        "selected_post_rope_runtime_replay_source_classification": post_rope_runtime_classification,
        "selected_pre_rope_projection_pair_source_classification": pre_rope_pair_classification,
        "selected_pre_rope_projection_history_source_classification": pre_rope_history_classification,
        "selected_pre_rope_attention_norm_history_source_classification": pre_rope_norm_classification,
        "selected_pre_rope_attention_norm_f64_residual_classification": f64_residual_classification,
        "selected_query_head": value_u64(selected_key_decision, "/selected_query_head"),
        "selected_query_dim": value_u64(selected_key_decision, "/selected_query_dim"),
        "selected_query_token": value_u64(selected_key_decision, "/selected_query_token"),
        "selected_query_key_slot": value_u64(selected_key_decision, "/selected_query_key_slot"),
        "active_key_history": active_key_history,
        "context_present": context_present,
        "first_slot_probe_row": compact_selected_key_slot_probe_row(slot_probe.pointer("/rows/0").unwrap_or(&Value::Null)),
        "first_post_rope_history_row": compact_selected_key_mixed_qk_source_row(post_rope_source.pointer("/rows/0").unwrap_or(&Value::Null)),
        "first_post_rope_capture_row": compact_selected_key_mixed_qk_source_row(post_rope_capture.pointer("/rows/0").unwrap_or(&Value::Null)),
        "first_rust_post_rope_capture_row": compact_selected_key_mixed_qk_source_row(rust_post_rope_capture.pointer("/rows/0").unwrap_or(&Value::Null)),
        "first_post_rope_runtime_row": compact_selected_key_mixed_qk_source_row(post_rope_runtime.pointer("/rows/0").unwrap_or(&Value::Null)),
        "first_pre_rope_projection_pair_row": compact_selected_key_mixed_qk_source_row(pre_rope_pair.pointer("/rows/0").unwrap_or(&Value::Null)),
        "first_pre_rope_projection_history_row": compact_selected_key_mixed_qk_source_row(pre_rope_history.pointer("/rows/0").unwrap_or(&Value::Null)),
        "first_pre_rope_attention_norm_row": compact_selected_key_mixed_qk_source_row(pre_rope_norm.pointer("/rows/0").unwrap_or(&Value::Null)),
        "first_pre_rope_f64_residual_row": compact_selected_key_mixed_qk_source_row(selected_pre_rope_f64_residual.pointer("/rows/0").unwrap_or(&Value::Null)),
        "blocked_reasons": blocked_reasons,
        "next_diagnostic": selected_key_score_input_bucket_source_next_diagnostic(classification),
    })
}

fn selected_query_history_residual_next_diagnostic(classification: &str) -> &'static str {
    match classification {
        "selected_query_history_residual_query_score_input_source" => {
            "pin selected query score-input source before following downstream score residual"
        }
        "selected_query_history_residual_f16_boundary" => {
            "pin selected query F16 score-input conversion before changing score accumulation or softmax"
        }
        "selected_query_history_residual_pre_score_rope" => {
            "pin selected query pre-score RoPE source before changing query projection or RoPE math"
        }
        "selected_query_history_residual_pre_rope_projection" => {
            "pin selected query pre-RoPE projection epsilon before changing query projection math"
        }
        "selected_query_history_residual_rope_expression" => {
            "pin selected query RoPE expression policy before changing query RoPE runtime math"
        }
        "selected_query_history_residual_projection_source" => {
            "pin selected query projection epsilon source before changing QK256 or attention-norm math"
        }
        "selected_query_history_residual_attention_norm_input" => {
            "pin selected query attention-norm input-history epsilon before changing RMSNorm runtime math"
        }
        "selected_query_history_residual_attention_norm_replay" => {
            "pin selected query attention RMSNorm replay policy before changing RMSNorm runtime math"
        }
        "selected_query_history_residual_downstream_score_after_clean_source_chain" => {
            "replay selected query score-position residual or score accumulation before changing upstream query source, softmax, or value mix"
        }
        "selected_query_history_residual_raw_score_accumulation" => {
            "pin selected raw-score accumulation residual before changing score accumulation policy"
        }
        "selected_query_history_residual_score_history_serialization" => {
            "pin score-history serialization/capture before changing score accumulation or softmax"
        }
        "selected_query_history_residual_softmax_probability" => {
            "localize selected softmax probability formation before value-mix changes"
        }
        "selected_query_history_residual_value_mix" => {
            "localize selected value-mix inputs before changing value-mix runtime math"
        }
        "selected_query_history_residual_clean" => {
            "selected query history residual is clean; rerun downstream probability, value-mix, and logits parity"
        }
        "selected_query_history_residual_missing_context" => {
            "capture selected query score frontier, downstream residual, Q/K downstream frontier, and f64 score residual context before changing runtime math"
        }
        _ => "keep selected query history residual diagnostic-only",
    }
}

fn attention_selected_query_history_residual_frontier(
    selected_qk_downstream: &Value,
    selected_query_frontier: &Value,
    selected_query_downstream: &Value,
    f64_score_history_residual: &Value,
    f64_qk_score_input_bucket_residual: &Value,
) -> Value {
    let qk_downstream_classification = selected_report_classification(selected_qk_downstream);
    let query_frontier_classification = selected_report_classification(selected_query_frontier);
    let query_downstream_classification = selected_report_classification(selected_query_downstream);
    let f64_score_history_residual_classification =
        selected_report_classification(f64_score_history_residual);
    let f64_qk_score_input_bucket_residual_classification =
        selected_report_classification(f64_qk_score_input_bucket_residual);

    let score_input_source_classification = selected_query_frontier
        .pointer("/score_input_source_classification")
        .and_then(Value::as_str);
    let f16_frontier_classification =
        selected_query_frontier.pointer("/f16_frontier_classification").and_then(Value::as_str);
    let pre_score_rope_source_classification = selected_query_frontier
        .pointer("/pre_score_rope_source_classification")
        .and_then(Value::as_str);
    let pre_rope_projection_materiality_classification = selected_query_frontier
        .pointer("/pre_rope_projection_materiality_classification")
        .and_then(Value::as_str);
    let rope_expression_policy_classification = selected_query_frontier
        .pointer("/rope_expression_policy_classification")
        .and_then(Value::as_str);
    let projection_epsilon_source_classification = selected_query_frontier
        .pointer("/projection_epsilon_source_classification")
        .and_then(Value::as_str);
    let attention_norm_input_history_epsilon_classification = selected_query_frontier
        .pointer("/attention_norm_input_history_epsilon_classification")
        .and_then(Value::as_str);
    let attention_norm_replay_policy_classification = selected_query_frontier
        .pointer("/attention_norm_replay_policy_classification")
        .and_then(Value::as_str);

    let score_raw_history_material_count =
        value_u64(selected_query_downstream, "/score_raw_history_material_count").unwrap_or(0).max(
            value_u64(f64_score_history_residual, "/score_raw_history_material_count").unwrap_or(0),
        );
    let score_raw_live_material_count =
        value_u64(selected_query_downstream, "/score_raw_live_material_count").unwrap_or(0).max(
            value_u64(f64_score_history_residual, "/score_raw_live_material_count").unwrap_or(0),
        );
    let probability_history_material_count =
        value_u64(selected_query_downstream, "/probability_history_material_count")
            .unwrap_or(0)
            .max(
                value_u64(f64_score_history_residual, "/probability_history_material_count")
                    .unwrap_or(0),
            );
    let probability_source_drift =
        value_bool(selected_query_downstream, "/probability_source_drift_present").unwrap_or(false)
            || value_bool(f64_score_history_residual, "/probability_source_drift_present")
                .unwrap_or(false);
    let value_cache_source_drift =
        value_bool(selected_query_downstream, "/value_cache_source_drift_present").unwrap_or(false)
            || value_bool(f64_score_history_residual, "/value_cache_source_drift_present")
                .unwrap_or(false);
    let rust_self_recompute_drift =
        value_bool(selected_query_downstream, "/rust_self_recompute_drift_present")
            .unwrap_or(false)
            || value_bool(f64_score_history_residual, "/rust_self_recompute_drift_present")
                .unwrap_or(false);
    let rust_self_recompute_explained =
        value_bool(selected_query_downstream, "/rust_self_recompute_explained_by_numeric_variants")
            .unwrap_or(false)
            || value_bool(
                f64_score_history_residual,
                "/rust_self_recompute_explained_by_numeric_variants",
            )
            .unwrap_or(false);
    let missing_context = [
        qk_downstream_classification,
        query_frontier_classification,
        query_downstream_classification,
        f64_score_history_residual_classification,
    ]
    .iter()
    .any(Option::is_none);

    let upstream_chain_classification = if query_frontier_classification
        != Some("selected_query_score_frontier_downstream_score_residual_after_clean_norm_replay")
    {
        if score_input_source_classification
            != Some("selected_query_score_input_bucket_source_reference_to_rope")
        {
            Some("selected_query_history_residual_query_score_input_source")
        } else if f16_frontier_classification
            != Some("selected_query_score_input_f16_frontier_not_f16_boundary")
        {
            Some("selected_query_history_residual_f16_boundary")
        } else if pre_score_rope_source_classification
            != Some("selected_query_pre_score_rope_source_pre_rope_projection_epsilon")
        {
            Some("selected_query_history_residual_pre_score_rope")
        } else if pre_rope_projection_materiality_classification
            != Some("selected_query_pre_rope_projection_epsilon_explains_rope_bucket")
        {
            Some("selected_query_history_residual_pre_rope_projection")
        } else if rope_expression_policy_classification
            != Some("selected_query_rope_expression_policy_same_expression_input_epsilon_bucket")
        {
            Some("selected_query_history_residual_rope_expression")
        } else if projection_epsilon_source_classification
            != Some("selected_query_projection_epsilon_source_attention_norm_input_history")
        {
            Some("selected_query_history_residual_projection_source")
        } else if attention_norm_input_history_epsilon_classification
            != Some(
                "selected_query_attention_norm_input_history_epsilon_rmsnorm_replay_explains_output",
            )
        {
            Some("selected_query_history_residual_attention_norm_input")
        } else if attention_norm_replay_policy_classification
            != Some("selected_query_attention_norm_replay_policy_clean")
        {
            Some("selected_query_history_residual_attention_norm_replay")
        } else {
            Some("selected_query_history_residual_missing_context")
        }
    } else {
        None
    };

    let classification = if missing_context {
        "selected_query_history_residual_missing_context"
    } else if let Some(upstream_chain_classification) = upstream_chain_classification {
        upstream_chain_classification
    } else {
        match qk_downstream_classification {
            Some("selected_qk_downstream_score_residual_selected_query_history") => {
                if query_downstream_classification
                    != Some("selected_query_downstream_score_residual_selected_q_history")
                {
                    match query_downstream_classification {
                        Some("selected_query_downstream_score_residual_raw_score_accumulation") => {
                            "selected_query_history_residual_raw_score_accumulation"
                        }
                        Some(
                            "selected_query_downstream_score_residual_score_history_serialization",
                        ) => "selected_query_history_residual_score_history_serialization",
                        Some("selected_query_downstream_score_residual_softmax_probability") => {
                            "selected_query_history_residual_softmax_probability"
                        }
                        Some("selected_query_downstream_score_residual_value_mix") => {
                            "selected_query_history_residual_value_mix"
                        }
                        Some("selected_query_downstream_score_residual_clean") => {
                            "selected_query_history_residual_clean"
                        }
                        _ => "selected_query_history_residual_missing_context",
                    }
                } else if f64_score_history_residual_classification
                    == Some("f64_score_history_residual_score_accumulation")
                {
                    if score_raw_history_material_count > 0
                        && score_raw_live_material_count == 0
                        && probability_history_material_count == 0
                    {
                        "selected_query_history_residual_score_history_serialization"
                    } else {
                        "selected_query_history_residual_raw_score_accumulation"
                    }
                } else if f64_score_history_residual_classification
                    == Some("f64_score_history_residual_softmax_probability")
                    || probability_history_material_count > 0
                    || probability_source_drift
                {
                    "selected_query_history_residual_softmax_probability"
                } else if value_cache_source_drift
                    || f64_score_history_residual_classification
                        == Some("f64_score_history_residual_value_cache_source")
                    || f64_score_history_residual_classification
                        == Some("f64_score_history_residual_value_mix_numeric")
                    || (rust_self_recompute_drift && rust_self_recompute_explained)
                {
                    "selected_query_history_residual_value_mix"
                } else if f64_score_history_residual_classification
                    == Some("f64_score_history_residual_clean")
                    && f64_qk_score_input_bucket_residual_classification
                        == Some("f64_qk_score_input_bucket_residual_clean")
                {
                    "selected_query_history_residual_clean"
                } else {
                    "selected_query_history_residual_downstream_score_after_clean_source_chain"
                }
            }
            Some("selected_qk_downstream_score_residual_raw_score_accumulation") => {
                "selected_query_history_residual_raw_score_accumulation"
            }
            Some("selected_qk_downstream_score_residual_score_history_serialization") => {
                "selected_query_history_residual_score_history_serialization"
            }
            Some("selected_qk_downstream_score_residual_softmax_probability") => {
                "selected_query_history_residual_softmax_probability"
            }
            Some("selected_qk_downstream_score_residual_value_mix") => {
                "selected_query_history_residual_value_mix"
            }
            Some("selected_qk_downstream_score_residual_clean") => {
                "selected_query_history_residual_clean"
            }
            _ => "selected_query_history_residual_missing_context",
        }
    };

    json!({
        "diagnostic_only": true,
        "claim_allowed": false,
        "policy": "Selected query-history residual frontier is diagnostic-only evidence for refining a selected Q/K downstream score residual that now points back to selected query history; it does not change RMSNorm, QK256, RoPE, F16 score-input conversion, score accumulation, softmax, value-mix, or runtime math and does not promote reference parity, A770 semantic quality, attention score residency, selected attention, resident KV, full residency, performance, or completion",
        "classification": classification,
        "selected_qk_downstream_classification": qk_downstream_classification,
        "selected_query_frontier_classification": query_frontier_classification,
        "selected_query_downstream_classification": query_downstream_classification,
        "f64_score_history_residual_classification": f64_score_history_residual_classification,
        "f64_qk_score_input_bucket_residual_classification": f64_qk_score_input_bucket_residual_classification,
        "score_input_source_classification": score_input_source_classification,
        "f16_frontier_classification": f16_frontier_classification,
        "pre_score_rope_source_classification": pre_score_rope_source_classification,
        "pre_rope_projection_materiality_classification": pre_rope_projection_materiality_classification,
        "rope_expression_policy_classification": rope_expression_policy_classification,
        "projection_epsilon_source_classification": projection_epsilon_source_classification,
        "attention_norm_input_history_epsilon_classification": attention_norm_input_history_epsilon_classification,
        "attention_norm_replay_policy_classification": attention_norm_replay_policy_classification,
        "selected_query_head": value_u64(selected_qk_downstream, "/selected_query_head").or_else(|| value_u64(selected_query_frontier, "/head")),
        "selected_query_dim": value_u64(selected_qk_downstream, "/selected_query_dim").or_else(|| value_u64(selected_query_frontier, "/selected_dim")),
        "selected_query_token": value_u64(selected_qk_downstream, "/selected_query_token").or_else(|| value_u64(selected_query_frontier, "/selected_token")),
        "selected_query_key_slot": value_u64(selected_qk_downstream, "/selected_query_key_slot").or_else(|| value_u64(selected_query_frontier, "/key_slot")),
        "score_raw_history_material_count": score_raw_history_material_count,
        "score_raw_live_material_count": score_raw_live_material_count,
        "probability_history_material_count": probability_history_material_count,
        "probability_source_drift_present": probability_source_drift,
        "value_cache_source_drift_present": value_cache_source_drift,
        "rust_self_recompute_drift_present": rust_self_recompute_drift,
        "rust_self_recompute_explained_by_numeric_variants": rust_self_recompute_explained,
        "first_mixed_qk_product_row": selected_qk_downstream.pointer("/first_mixed_qk_product_row").cloned().unwrap_or(Value::Null),
        "selected_qk_bucket_row": selected_query_frontier.pointer("/selected_qk_bucket_row").cloned().unwrap_or(Value::Null),
        "blocked_reasons": if missing_context || classification == "selected_query_history_residual_missing_context" {
            json!(["selected_query_history_residual_missing_context"])
        } else {
            json!([])
        },
        "next_diagnostic": selected_query_history_residual_next_diagnostic(classification),
    })
}

