fn attention_value_projection_input_history(
    reference_records: &[ReferenceTraceRecord],
    rust_records: &BTreeMap<String, RustTraceRecord>,
) -> Value {
    let reference = reference_records
        .iter()
        .find(|record| record.stage == "attn_norm_history_ref_layout")
        .filter(|record| record.values_available && !record.first_values.is_empty());
    let rust = rust_records
        .get("attention_v_input_history_ref_layout")
        .filter(|record| !record.first_values.is_empty());
    let delta = reference.zip(rust).map(|(reference, rust)| {
        let dim_count = reference.shape.first().and_then(|dim| usize::try_from(*dim).ok());
        let token_count = reference.shape.get(1).and_then(|dim| usize::try_from(*dim).ok());
        match (dim_count, token_count) {
            (Some(dim_count), Some(token_count)) if dim_count > 0 && token_count > 0 => {
                dim_major_token_value_delta(
                    &reference.first_values,
                    &rust.first_values,
                    dim_count,
                    token_count,
                )
            }
            _ => compare_vectors(&reference.first_values, &rust.first_values),
        }
    });
    let mut blocked_reasons = Vec::<String>::new();
    if reference.is_none() {
        blocked_reasons.push("reference_attn_norm_history_ref_layout_missing".to_string());
    }
    if rust.is_none() {
        blocked_reasons.push("rust_attention_v_input_history_ref_layout_missing".to_string());
    }
    if delta.is_none() {
        blocked_reasons.push("value_projection_input_history_delta_unavailable".to_string());
    }

    json!({
        "diagnostic_only": true,
        "claim_allowed": false,
        "policy": "value-projection input history comparison is diagnostic-only evidence for whether V-cache bucket drift is already present in the pre-V-projection attention-norm history; it does not promote reference parity, A770 semantic quality, value mix residency, resident KV, selected attention, or any support claim",
        "reference_stage": "attn_norm_history_ref_layout",
        "rust_stage": "attention_v_input_history_ref_layout",
        "reference_present": reference.is_some(),
        "rust_present": rust.is_some(),
        "delta": delta,
        "current_blocked_reasons": blocked_reasons,
    })
}

fn attention_norm_history_delta(
    reference_records: &[ReferenceTraceRecord],
    rust_records: &BTreeMap<String, RustTraceRecord>,
) -> Value {
    let reference_current = reference_records
        .iter()
        .find(|record| record.stage == "attn_norm" && record.layer == Some(0))
        .filter(|record| record.values_available && !record.first_values.is_empty());
    let reference_history = reference_records
        .iter()
        .find(|record| record.stage == "attn_norm_history_ref_layout")
        .filter(|record| record.values_available && !record.first_values.is_empty());
    let rust_current =
        rust_records.get("attn_norm").filter(|record| !record.first_values.is_empty());
    let rust_history = rust_records
        .get("attention_v_input_history_ref_layout")
        .filter(|record| !record.first_values.is_empty());

    let reference_sampled_token_index = reference_current.and_then(reference_sampled_token_index);
    let rust_current_seq = rust_current.and_then(|record| record.seq.map(|seq| seq as u64));
    let rust_history_seq = rust_history.and_then(|record| record.seq.map(|seq| seq as u64));
    let selected_token = reference_sampled_token_index.or(rust_history_seq).or(rust_current_seq);

    let reference_history_token =
        selected_token.and_then(|token| usize::try_from(token).ok()).and_then(|token| {
            reference_history.and_then(|record| reference_dim_major_token(record, token).ok())
        });
    let rust_history_token = selected_token
        .and_then(|token| usize::try_from(token).ok())
        .and_then(|token| rust_history.and_then(|record| rust_dim_major_token(record, token).ok()));

    let reference_current_vs_history_token = reference_current
        .zip(reference_history_token.as_ref())
        .map(|(current, history)| compare_vectors(&current.first_values, history));
    let rust_current_vs_history_token = rust_current
        .zip(rust_history_token.as_ref())
        .map(|(current, history)| compare_vectors(&current.first_values, history));
    let reference_current_vs_rust_current = reference_current
        .zip(rust_current)
        .map(|(reference, rust)| compare_vectors(&reference.first_values, &rust.first_values));
    let reference_history_token_vs_rust_history_token = reference_history_token
        .as_ref()
        .zip(rust_history_token.as_ref())
        .map(|(reference, rust)| compare_vectors(reference, rust));
    let reference_history_token_vs_rust_history_token_f16 = reference_history_token
        .as_ref()
        .zip(rust_history_token.as_ref())
        .map(|(reference, rust)| f16_bucket_delta(reference, rust));

    let mut scope_failures = Vec::<Value>::new();
    if let (Some(reference), Some(rust)) = (reference_sampled_token_index, rust_current_seq)
        && reference != rust
    {
        scope_failures.push(json!({
            "reason": "reference_sampled_token_index_does_not_match_rust_attn_norm_seq",
            "reference_sampled_token_index": reference,
            "rust_seq": rust,
        }));
    }
    if let (Some(reference), Some(rust)) = (reference_sampled_token_index, rust_history_seq)
        && reference != rust
    {
        scope_failures.push(json!({
            "reason": "reference_sampled_token_index_does_not_match_rust_history_seq",
            "reference_sampled_token_index": reference,
            "rust_history_seq": rust,
        }));
    }
    if let (Some(current), Some(history)) = (rust_current_seq, rust_history_seq)
        && current != history
    {
        scope_failures.push(json!({
            "reason": "rust_attn_norm_seq_does_not_match_rust_history_seq",
            "rust_seq": current,
            "rust_history_seq": history,
        }));
    }

    let mut blocked_reasons = Vec::<String>::new();
    if reference_current.is_none() {
        blocked_reasons.push("reference_attn_norm_current_missing".to_string());
    }
    if reference_history.is_none() {
        blocked_reasons.push("reference_attn_norm_history_ref_layout_missing".to_string());
    }
    if rust_current.is_none() {
        blocked_reasons.push("rust_attn_norm_current_missing".to_string());
    }
    if rust_history.is_none() {
        blocked_reasons.push("rust_attention_v_input_history_ref_layout_missing".to_string());
    }
    if selected_token.is_none() {
        blocked_reasons.push("attention_norm_selected_token_unavailable".to_string());
    }
    if reference_history_token.is_none() {
        blocked_reasons.push("reference_attn_norm_history_token_unavailable".to_string());
    }
    if rust_history_token.is_none() {
        blocked_reasons.push("rust_attention_v_input_history_token_unavailable".to_string());
    }
    if !scope_failures.is_empty() {
        blocked_reasons.push("attention_norm_trace_scope_mismatch".to_string());
    }

    let classification = classify_attention_norm_history_delta(
        !scope_failures.is_empty(),
        reference_current_vs_history_token.as_ref(),
        rust_current_vs_history_token.as_ref(),
        reference_current_vs_rust_current.as_ref(),
        reference_history_token_vs_rust_history_token_f16.as_ref(),
    );
    blocked_reasons.extend(classification.iter().map(|reason| (*reason).to_string()));
    blocked_reasons.sort_unstable();
    blocked_reasons.dedup();

    json!({
        "diagnostic_only": true,
        "claim_allowed": false,
        "policy": "attention-norm history delta is diagnostic-only evidence for whether value-projection input drift enters through RMSNorm/current-token computation, history serialization, or trace scope; it does not promote reference parity, A770 semantic quality, selected attention, value mix residency, resident KV, full residency, performance, or completion",
        "reference_current_stage": "attn_norm",
        "reference_history_stage": "attn_norm_history_ref_layout",
        "rust_current_stage": "attn_norm",
        "rust_history_stage": "attention_v_input_history_ref_layout",
        "reference_current_present": reference_current.is_some(),
        "reference_history_present": reference_history.is_some(),
        "rust_current_present": rust_current.is_some(),
        "rust_history_present": rust_history.is_some(),
        "scope": {
            "reference_sampled_token_index": reference_sampled_token_index,
            "rust_current_seq": rust_current_seq,
            "rust_history_seq": rust_history_seq,
            "selected_token": selected_token,
            "scope_mismatch": !scope_failures.is_empty(),
            "failures": scope_failures,
        },
        "reference_current_vs_reference_history_token": reference_current_vs_history_token,
        "rust_current_vs_rust_history_token": rust_current_vs_history_token,
        "reference_current_vs_rust_current": reference_current_vs_rust_current,
        "reference_history_token_vs_rust_history_token": reference_history_token_vs_rust_history_token,
        "reference_history_token_vs_rust_history_token_f16": reference_history_token_vs_rust_history_token_f16,
        "current_blocked_reasons": blocked_reasons,
    })
}

fn attention_norm_input_history_delta(
    reference_records: &[ReferenceTraceRecord],
    rust_records: &BTreeMap<String, RustTraceRecord>,
) -> Value {
    let reference = reference_records
        .iter()
        .find(|record| record.stage == "attn_norm_input_history_ref_layout")
        .filter(|record| record.values_available && !record.first_values.is_empty());
    let rust = rust_records
        .get("attention_norm_input_history_ref_layout")
        .filter(|record| !record.first_values.is_empty());

    let delta = reference.zip(rust).and_then(|(reference, rust)| {
        let dim_count = dim_major_dim_count(reference).ok()?;
        let token_count = dim_major_token_count(reference).ok()?;
        Some(dim_major_token_value_delta(
            &reference.first_values,
            &rust.first_values,
            dim_count,
            token_count,
        ))
    });

    let mut blocked_reasons = Vec::<String>::new();
    if reference.is_none() {
        blocked_reasons.push("reference_attn_norm_input_history_ref_layout_missing".to_string());
    }
    if rust.is_none() {
        blocked_reasons.push("rust_attention_norm_input_history_ref_layout_missing".to_string());
    }
    if reference.is_some() && rust.is_some() && delta.is_none() {
        blocked_reasons.push("attention_norm_input_history_delta_unavailable".to_string());
    }
    if delta.as_ref().is_some_and(delta_has_material_numeric_delta) {
        blocked_reasons.push("attention_norm_input_history_delta_present".to_string());
    }

    json!({
        "diagnostic_only": true,
        "claim_allowed": false,
        "policy": "attention-norm input history delta is diagnostic-only evidence for whether layer input history already differs before attention RMSNorm; it does not promote reference parity, A770 semantic quality, selected attention, value mix residency, resident KV, full residency, performance, or completion",
        "reference_stage": "attn_norm_input_history_ref_layout",
        "rust_stage": "attention_norm_input_history_ref_layout",
        "reference_present": reference.is_some(),
        "rust_present": rust.is_some(),
        "reference": reference.map(reference_record_summary).unwrap_or(Value::Null),
        "rust": rust.map(rust_record_summary).unwrap_or(Value::Null),
        "delta": delta.unwrap_or(Value::Null),
        "current_blocked_reasons": blocked_reasons,
    })
}

fn reference_dim_major_token(record: &ReferenceTraceRecord, token: usize) -> Result<Vec<f32>> {
    let dim_count = dim_major_dim_count(record)?;
    let token_count = dim_major_token_count(record)?;
    slice_dim_major_token(&record.first_values, dim_count, token_count, token)
}

fn rust_dim_major_token(record: &RustTraceRecord, token: usize) -> Result<Vec<f32>> {
    let dim_count = record.shape.first().copied().filter(|dim| *dim > 0).with_context(|| {
        format!("{} has unusable dim-major shape {:?}", record.name, record.shape)
    })?;
    let token_count = record.shape.get(1).copied().filter(|dim| *dim > 0).with_context(|| {
        format!("{} has unusable token count shape {:?}", record.name, record.shape)
    })?;
    slice_dim_major_token(&record.first_values, dim_count, token_count, token)
}

fn classify_attention_norm_history_delta(
    scope_mismatch: bool,
    reference_current_vs_history_token: Option<&Value>,
    rust_current_vs_history_token: Option<&Value>,
    reference_current_vs_rust_current: Option<&Value>,
    reference_history_token_vs_rust_history_token_f16: Option<&Value>,
) -> Vec<&'static str> {
    if scope_mismatch {
        return vec!["attention_norm_trace_scope_mismatch"];
    }
    if reference_current_vs_history_token.is_some_and(delta_has_material_numeric_delta) {
        return vec!["reference_attn_norm_history_serialization_delta"];
    }
    if rust_current_vs_history_token.is_some_and(delta_has_material_numeric_delta) {
        return vec!["rust_attention_v_input_history_serialization_delta"];
    }
    if reference_current_vs_rust_current.is_some_and(delta_has_any_numeric_delta) {
        let mut reasons = vec!["attention_norm_current_token_delta"];
        if reference_history_token_vs_rust_history_token_f16
            .and_then(|delta| delta.pointer("/f16_bucket_mismatch_count").and_then(Value::as_u64))
            .is_some_and(|count| count > 0)
        {
            reasons.push("attention_norm_delta_crosses_f16_bucket_boundary");
        }
        return reasons;
    }
    Vec::new()
}

fn delta_has_material_numeric_delta(delta: &Value) -> bool {
    delta_metric(delta, "/max_abs_delta") > 1.0e-6
        || !delta.pointer("/count_match").and_then(Value::as_bool).unwrap_or(false)
}

fn delta_has_any_numeric_delta(delta: &Value) -> bool {
    delta_metric(delta, "/max_abs_delta") > 0.0
        || !delta.pointer("/count_match").and_then(Value::as_bool).unwrap_or(false)
}

fn attention_value_projection_output_history(
    reference_records: &[ReferenceTraceRecord],
    rust_records: &BTreeMap<String, RustTraceRecord>,
) -> Value {
    let reference = reference_records
        .iter()
        .find(|record| record.stage == "vcur_history_ref_layout")
        .filter(|record| record.values_available && !record.first_values.is_empty());
    let rust_heads = rust_records
        .iter()
        .filter_map(|(stage, record)| {
            parse_stage_head(stage, "attention_v_before_cache_store_kv_head")
                .map(|head| (head, record))
        })
        .filter(|(_, record)| !record.first_values.is_empty())
        .collect::<BTreeMap<_, _>>();

    let mut rows = Vec::new();
    let mut compared_head_count = 0usize;
    let mut missing_head_count = 0usize;
    let mut total_bucket_mismatch_count = 0usize;
    let mut max_bucket_mismatch_count = 0usize;
    let mut max_abs_delta = 0.0f64;
    let mut max_rms_delta = 0.0f64;
    let mut expected_head_count = 0usize;
    let mut blocked_reasons = Vec::<String>::new();

    if reference.is_none() {
        blocked_reasons.push("reference_vcur_history_ref_layout_missing".to_string());
    }
    if rust_heads.is_empty() {
        blocked_reasons.push("rust_attention_v_before_cache_store_heads_missing".to_string());
    }

    if let Some(reference) = reference {
        let total_dim_count = reference.shape.first().and_then(|dim| usize::try_from(*dim).ok());
        let token_count = reference.shape.get(1).and_then(|dim| usize::try_from(*dim).ok());
        let rust_head_dim = rust_heads
            .values()
            .find_map(|record| record.shape.first().copied().filter(|dim| *dim > 0))
            .or_else(|| {
                let token_count = token_count.filter(|count| *count > 0)?;
                rust_heads.values().find_map(|record| {
                    if record.first_values.len().is_multiple_of(token_count) {
                        Some(record.first_values.len() / token_count)
                    } else {
                        None
                    }
                })
            });
        match (total_dim_count, token_count, rust_head_dim) {
            (Some(total_dim_count), Some(token_count), Some(rust_head_dim))
                if total_dim_count > 0 && token_count > 0 && rust_head_dim > 0 =>
            {
                if !total_dim_count.is_multiple_of(rust_head_dim) {
                    blocked_reasons.push(format!(
                        "reference_vcur_dim_count_not_divisible_by_rust_head_dim:{total_dim_count}:{rust_head_dim}"
                    ));
                } else {
                    let head_dim = rust_head_dim;
                    expected_head_count = total_dim_count / head_dim;
                    if rust_heads
                        .keys()
                        .next_back()
                        .is_some_and(|head| *head >= expected_head_count)
                    {
                        blocked_reasons.push(format!(
                            "rust_head_index_exceeds_expected_count:{expected_head_count}"
                        ));
                    }
                    for head in 0..expected_head_count {
                        if let Some(rust) = rust_heads.get(&head) {
                            let reference_head = slice_dim_major_head(
                                &reference.first_values,
                                head,
                                head_dim,
                                token_count,
                            );
                            let delta = f16_bucket_delta_dim_major(
                                &reference_head,
                                &rust.first_values,
                                head_dim,
                                token_count,
                            );
                            let bucket_mismatch_count = delta
                                .pointer("/f16_bucket_mismatch_count")
                                .and_then(Value::as_u64)
                                .unwrap_or(0)
                                as usize;
                            total_bucket_mismatch_count += bucket_mismatch_count;
                            max_bucket_mismatch_count =
                                max_bucket_mismatch_count.max(bucket_mismatch_count);
                            max_abs_delta =
                                max_abs_delta.max(delta_metric(&delta, "/max_abs_delta"));
                            max_rms_delta =
                                max_rms_delta.max(delta_metric(&delta, "/rms_abs_delta"));
                            compared_head_count += 1;
                            rows.push(json!({
                                "head": head,
                                "status": "compared",
                                "delta": delta,
                            }));
                        } else {
                            missing_head_count += 1;
                            rows.push(json!({
                                "head": head,
                                "status": "missing_rust_before_cache_store_head",
                            }));
                        }
                    }
                }
            }
            (Some(_), Some(_), None) if !rust_heads.is_empty() => {
                blocked_reasons
                    .push("rust_attention_v_before_cache_store_head_dim_unusable".to_string());
            }
            _ => {
                blocked_reasons.push("reference_vcur_history_shape_unusable".to_string());
            }
        }
    }
    json!({
        "diagnostic_only": true,
        "claim_allowed": false,
        "policy": "value-projection output history comparison is diagnostic-only evidence for whether all-token V projection output already differs before cache write; it does not promote reference parity, A770 semantic quality, value mix residency, resident KV, selected attention, or any support claim",
        "reference_stage": "vcur_history_ref_layout",
        "rust_stage_prefix": "attention_v_before_cache_store_kv_head",
        "reference_present": reference.is_some(),
        "rust_head_count": rust_heads.len(),
        "expected_head_count": expected_head_count,
        "compared_head_count": compared_head_count,
        "missing_head_count": missing_head_count,
        "total_f16_bucket_mismatch_count": total_bucket_mismatch_count,
        "max_head_f16_bucket_mismatch_count": max_bucket_mismatch_count,
        "max_abs_delta": max_abs_delta,
        "max_rms_delta": max_rms_delta,
        "all_compared": reference.is_some() && expected_head_count > 0 && compared_head_count == expected_head_count && missing_head_count == 0,
        "current_blocked_reasons": blocked_reasons,
        "rows": rows,
    })
}

fn attention_value_projection_to_cache_layout_bridge(
    reference_records: &[ReferenceTraceRecord],
    rust_records: &BTreeMap<String, RustTraceRecord>,
) -> Value {
    let reference_projection = reference_records
        .iter()
        .find(|record| record.stage == "vcur_history_ref_layout")
        .filter(|record| record.values_available && !record.first_values.is_empty());
    let reference_cache_heads = reference_records
        .iter()
        .filter_map(|record| {
            parse_stage_head(&record.stage, "v_cache_rust_layout_head").map(|head| (head, record))
        })
        .filter(|(_, record)| record.values_available && !record.first_values.is_empty())
        .collect::<BTreeMap<_, _>>();
    let rust_before_store_heads = rust_records
        .iter()
        .filter_map(|(stage, record)| {
            parse_stage_head(stage, "attention_v_before_cache_store_kv_head")
                .map(|head| (head, record))
        })
        .filter(|(_, record)| !record.first_values.is_empty())
        .collect::<BTreeMap<_, _>>();

    let mut rows = Vec::new();
    let mut compared_projection_cache_count = 0usize;
    let mut compared_projection_rust_count = 0usize;
    let mut compared_cache_rust_count = 0usize;
    let mut total_projection_cache_bucket_mismatch_count = 0usize;
    let mut total_projection_rust_bucket_mismatch_count = 0usize;
    let mut total_cache_rust_bucket_mismatch_count = 0usize;
    let mut max_projection_cache_bucket_mismatch_count = 0usize;
    let mut max_projection_rust_bucket_mismatch_count = 0usize;
    let mut max_cache_rust_bucket_mismatch_count = 0usize;
    let mut incomplete_projection_head_count = 0usize;
    let mut expected_head_count = 0usize;
    let mut blocked_reasons = Vec::<String>::new();

    if reference_projection.is_none() {
        blocked_reasons.push("reference_vcur_history_ref_layout_missing".to_string());
    }
    if reference_cache_heads.is_empty() {
        blocked_reasons.push("reference_v_cache_rust_layout_heads_missing".to_string());
    }
    if rust_before_store_heads.is_empty() {
        blocked_reasons.push("rust_attention_v_before_cache_store_heads_missing".to_string());
    }

    if let Some(reference_projection) = reference_projection {
        let total_dim_count =
            reference_projection.shape.first().and_then(|dim| usize::try_from(*dim).ok());
        let token_count =
            reference_projection.shape.get(1).and_then(|dim| usize::try_from(*dim).ok());
        let head_dim = reference_cache_heads
            .values()
            .find_map(|record| record.shape.first().and_then(|dim| usize::try_from(*dim).ok()))
            .or_else(|| {
                rust_before_store_heads
                    .values()
                    .find_map(|record| record.shape.first().copied().filter(|dim| *dim > 0))
            });

        match (total_dim_count, token_count, head_dim) {
            (Some(total_dim_count), Some(token_count), Some(head_dim))
                if total_dim_count > 0 && token_count > 0 && head_dim > 0 =>
            {
                if !total_dim_count.is_multiple_of(head_dim) {
                    blocked_reasons.push(format!(
                        "reference_vcur_dim_count_not_divisible_by_head_dim:{total_dim_count}:{head_dim}"
                    ));
                } else {
                    expected_head_count = total_dim_count / head_dim;
                    for head in 0..expected_head_count {
                        let projection_head = slice_dim_major_head(
                            &reference_projection.first_values,
                            head,
                            head_dim,
                            token_count,
                        );
                        let projection_head_required_count = head_dim.saturating_mul(token_count);
                        let projection_head_complete =
                            projection_head.len() == projection_head_required_count;
                        let reference_cache = reference_cache_heads.get(&head).copied();
                        let rust_before_store = rust_before_store_heads.get(&head);

                        let projection_history_slice_vs_reference_cache_layout =
                            projection_head_complete.then_some(reference_cache).flatten().map(
                                |record| {
                                    f16_bucket_delta_dim_major(
                                        &projection_head,
                                        &record.first_values,
                                        head_dim,
                                        token_count,
                                    )
                                },
                            );
                        let projection_history_slice_vs_rust_before_cache_store =
                            projection_head_complete.then_some(rust_before_store).flatten().map(
                                |record| {
                                    f16_bucket_delta_dim_major(
                                        &projection_head,
                                        &record.first_values,
                                        head_dim,
                                        token_count,
                                    )
                                },
                            );
                        let reference_cache_layout_vs_rust_before_cache_store =
                            reference_cache.zip(rust_before_store).map(|(reference, rust)| {
                                f16_bucket_delta_dim_major(
                                    &reference.first_values,
                                    &rust.first_values,
                                    head_dim,
                                    token_count,
                                )
                            });

                        if let Some(delta) = &projection_history_slice_vs_reference_cache_layout {
                            let count = f16_bucket_mismatch_count(delta);
                            total_projection_cache_bucket_mismatch_count += count;
                            max_projection_cache_bucket_mismatch_count =
                                max_projection_cache_bucket_mismatch_count.max(count);
                            compared_projection_cache_count += 1;
                        }
                        if let Some(delta) = &projection_history_slice_vs_rust_before_cache_store {
                            let count = f16_bucket_mismatch_count(delta);
                            total_projection_rust_bucket_mismatch_count += count;
                            max_projection_rust_bucket_mismatch_count =
                                max_projection_rust_bucket_mismatch_count.max(count);
                            compared_projection_rust_count += 1;
                        }
                        if let Some(delta) = &reference_cache_layout_vs_rust_before_cache_store {
                            let count = f16_bucket_mismatch_count(delta);
                            total_cache_rust_bucket_mismatch_count += count;
                            max_cache_rust_bucket_mismatch_count =
                                max_cache_rust_bucket_mismatch_count.max(count);
                            compared_cache_rust_count += 1;
                        }

                        let mut missing = Vec::<&str>::new();
                        if !projection_head_complete {
                            incomplete_projection_head_count += 1;
                            missing.push("reference_projection_history_head_sample_incomplete");
                        }
                        if reference_cache.is_none() {
                            missing.push("reference_cache_layout_head");
                        }
                        if rust_before_store.is_none() {
                            missing.push("rust_before_cache_store_head");
                        }

                        rows.push(json!({
                            "kv_head": head,
                            "status": if missing.is_empty() { "compared" } else { "missing_input" },
                            "missing": missing,
                            "projection_head_first_values_count": projection_head.len(),
                            "projection_head_required_values_count": projection_head_required_count,
                            "projection_history_slice_vs_reference_cache_layout":
                                projection_history_slice_vs_reference_cache_layout.unwrap_or(Value::Null),
                            "projection_history_slice_vs_rust_before_cache_store":
                                projection_history_slice_vs_rust_before_cache_store.unwrap_or(Value::Null),
                            "reference_cache_layout_vs_rust_before_cache_store":
                                reference_cache_layout_vs_rust_before_cache_store.unwrap_or(Value::Null),
                        }));
                    }
                }
            }
            (Some(_), Some(_), None) => {
                blocked_reasons.push("value_projection_cache_bridge_head_dim_unusable".to_string());
            }
            _ => {
                blocked_reasons.push("reference_vcur_history_shape_unusable".to_string());
            }
        }
    }
    if incomplete_projection_head_count > 0 {
        blocked_reasons.push("reference_projection_history_head_samples_incomplete".to_string());
    }

    json!({
        "diagnostic_only": true,
        "claim_allowed": false,
        "policy": "value-projection to cache-layout bridge is diagnostic-only evidence for whether the reference V projection history, reference V cache layout, and Rust before-cache-store history agree in the same head/token/dim scope; it does not promote reference parity, A770 semantic quality, resident KV, value mix residency, selected attention, or any support claim",
        "reference_projection_stage": "vcur_history_ref_layout",
        "reference_cache_stage_prefix": "v_cache_rust_layout_head",
        "rust_before_cache_store_stage_prefix": "attention_v_before_cache_store_kv_head",
        "reference_projection_present": reference_projection.is_some(),
        "reference_cache_head_count": reference_cache_heads.len(),
        "rust_before_cache_store_head_count": rust_before_store_heads.len(),
        "expected_head_count": expected_head_count,
        "compared_projection_cache_count": compared_projection_cache_count,
        "compared_projection_rust_count": compared_projection_rust_count,
        "compared_cache_rust_count": compared_cache_rust_count,
        "total_projection_cache_f16_bucket_mismatch_count": total_projection_cache_bucket_mismatch_count,
        "total_projection_rust_f16_bucket_mismatch_count": total_projection_rust_bucket_mismatch_count,
        "total_cache_rust_f16_bucket_mismatch_count": total_cache_rust_bucket_mismatch_count,
        "max_projection_cache_head_f16_bucket_mismatch_count": max_projection_cache_bucket_mismatch_count,
        "max_projection_rust_head_f16_bucket_mismatch_count": max_projection_rust_bucket_mismatch_count,
        "max_cache_rust_head_f16_bucket_mismatch_count": max_cache_rust_bucket_mismatch_count,
        "incomplete_projection_head_count": incomplete_projection_head_count,
        "all_compared": expected_head_count > 0
            && compared_projection_cache_count == expected_head_count
            && compared_projection_rust_count == expected_head_count
            && compared_cache_rust_count == expected_head_count,
        "current_blocked_reasons": blocked_reasons,
        "rows": rows,
    })
}

fn f16_bucket_mismatch_count(delta: &Value) -> usize {
    delta.pointer("/f16_bucket_mismatch_count").and_then(Value::as_u64).unwrap_or(0) as usize
}

fn slice_dim_major_head(
    values: &[f32],
    head: usize,
    head_dim: usize,
    token_count: usize,
) -> Vec<f32> {
    let mut out = Vec::with_capacity(head_dim.saturating_mul(token_count));
    for dim in 0..head_dim {
        let source_dim = head.saturating_mul(head_dim).saturating_add(dim);
        for token in 0..token_count {
            let index = source_dim.saturating_mul(token_count).saturating_add(token);
            if let Some(value) = values.get(index) {
                out.push(*value);
            }
        }
    }
    out
}

fn dim_major_token_value_delta(
    left: &[f32],
    right: &[f32],
    dim_count: usize,
    token_count: usize,
) -> Value {
    let mut delta = compare_vectors(left, right);
    let compared_count = left.len().min(right.len()).min(dim_count.saturating_mul(token_count));
    let mut token_mismatch_counts = vec![0usize; token_count];
    let mut token_max_abs_delta = vec![0.0f64; token_count];
    let mut first_layout_mismatch = Value::Null;

    for index in 0..compared_count {
        let abs_delta = (left[index] as f64 - right[index] as f64).abs();
        if abs_delta > 1.0e-6 {
            let dim = index / token_count;
            let token = index % token_count;
            if let Some(count) = token_mismatch_counts.get_mut(token) {
                *count += 1;
            }
            if let Some(max_delta) = token_max_abs_delta.get_mut(token) {
                *max_delta = max_delta.max(abs_delta);
            }
            if first_layout_mismatch.is_null() {
                first_layout_mismatch = json!({
                    "index": index,
                    "dim": dim,
                    "token": token,
                    "left": left[index],
                    "right": right[index],
                    "abs_delta": abs_delta,
                });
            }
        }
    }

    let token_rows = token_mismatch_counts
        .iter()
        .enumerate()
        .filter_map(|(token, count)| {
            if *count == 0 {
                None
            } else {
                Some(json!({
                    "token": token,
                    "mismatch_count": count,
                    "max_abs_delta": token_max_abs_delta[token],
                }))
            }
        })
        .collect::<Vec<_>>();

    if let Some(object) = delta.as_object_mut() {
        object.insert("layout".to_string(), json!("dim_major_token_minor"));
        object.insert("dim_count".to_string(), json!(dim_count));
        object.insert("token_count".to_string(), json!(token_count));
        object.insert("first_mismatch_layout".to_string(), first_layout_mismatch);
        object.insert("token_mismatch_counts".to_string(), json!(token_rows));
    }

    delta
}

fn value_cache_boundary_kv_section(
    reference_cache_heads: &BTreeMap<usize, &ReferenceTraceRecord>,
    rust_records: &BTreeMap<String, RustTraceRecord>,
    rust_stage_prefix: &str,
    boundary: &str,
) -> Value {
    let rust_heads = rust_records
        .iter()
        .filter_map(|(stage, record)| {
            parse_stage_head(stage, rust_stage_prefix).map(|head| (head, record))
        })
        .filter(|(_, record)| !record.first_values.is_empty())
        .collect::<BTreeMap<_, _>>();

    let mut rows = Vec::new();
    let mut compared_head_count = 0usize;
    let mut missing_head_count = 0usize;
    let mut total_bucket_mismatch_count = 0usize;
    let mut max_bucket_mismatch_count = 0usize;
    let mut max_abs_delta = 0.0f64;
    let mut max_rms_delta = 0.0f64;

    for (&head, reference) in reference_cache_heads {
        if let Some(rust) = rust_heads.get(&head) {
            let delta = value_cache_dim_major_delta(reference, rust);
            let bucket_mismatch_count =
                delta.pointer("/f16_bucket_mismatch_count").and_then(Value::as_u64).unwrap_or(0)
                    as usize;
            total_bucket_mismatch_count += bucket_mismatch_count;
            max_bucket_mismatch_count = max_bucket_mismatch_count.max(bucket_mismatch_count);
            max_abs_delta = max_abs_delta.max(delta_metric(&delta, "/max_abs_delta"));
            max_rms_delta = max_rms_delta.max(delta_metric(&delta, "/rms_abs_delta"));
            compared_head_count += 1;
            rows.push(json!({
                "head": head,
                "status": "compared",
                "delta": delta,
            }));
        } else {
            missing_head_count += 1;
            rows.push(json!({
                "head": head,
                "status": "missing_rust_boundary_stage",
            }));
        }
    }

    json!({
        "diagnostic_only": true,
        "claim_allowed": false,
        "boundary": boundary,
        "rust_stage_prefix": rust_stage_prefix,
        "reference_head_count": reference_cache_heads.len(),
        "rust_head_count": rust_heads.len(),
        "compared_head_count": compared_head_count,
        "missing_head_count": missing_head_count,
        "total_f16_bucket_mismatch_count": total_bucket_mismatch_count,
        "max_head_f16_bucket_mismatch_count": max_bucket_mismatch_count,
        "max_abs_delta": max_abs_delta,
        "max_rms_delta": max_rms_delta,
        "all_compared": !reference_cache_heads.is_empty() && missing_head_count == 0,
        "rows": rows,
    })
}

fn value_cache_boundary_expanded_section(
    reference_cache_heads: &BTreeMap<usize, &ReferenceTraceRecord>,
    rust_records: &BTreeMap<String, RustTraceRecord>,
) -> Value {
    let rust_stage_prefix = "attention_v_cache_expanded_for_value_mix_head";
    let rust_heads = rust_records
        .iter()
        .filter_map(|(stage, record)| {
            parse_stage_head(stage, rust_stage_prefix).map(|head| (head, record))
        })
        .filter(|(_, record)| !record.first_values.is_empty())
        .collect::<BTreeMap<_, _>>();
    let group_size = if reference_cache_heads.is_empty()
        || rust_heads.is_empty()
        || !rust_heads.len().is_multiple_of(reference_cache_heads.len())
    {
        None
    } else {
        Some(rust_heads.len() / reference_cache_heads.len())
    };

    let mut rows = Vec::new();
    let mut compared_head_count = 0usize;
    let mut missing_head_count = 0usize;
    let mut total_bucket_mismatch_count = 0usize;
    let mut max_bucket_mismatch_count = 0usize;
    let mut max_abs_delta = 0.0f64;
    let mut max_rms_delta = 0.0f64;

    for (&head, rust) in &rust_heads {
        let kv_head = group_size.map(|group_size| head / group_size);
        if let Some(reference) = kv_head.and_then(|kv_head| reference_cache_heads.get(&kv_head)) {
            let delta = value_cache_dim_major_delta(reference, rust);
            let bucket_mismatch_count =
                delta.pointer("/f16_bucket_mismatch_count").and_then(Value::as_u64).unwrap_or(0)
                    as usize;
            total_bucket_mismatch_count += bucket_mismatch_count;
            max_bucket_mismatch_count = max_bucket_mismatch_count.max(bucket_mismatch_count);
            max_abs_delta = max_abs_delta.max(delta_metric(&delta, "/max_abs_delta"));
            max_rms_delta = max_rms_delta.max(delta_metric(&delta, "/rms_abs_delta"));
            compared_head_count += 1;
            rows.push(json!({
                "head": head,
                "kv_head": kv_head,
                "status": "compared",
                "delta": delta,
            }));
        } else {
            missing_head_count += 1;
            rows.push(json!({
                "head": head,
                "kv_head": kv_head,
                "status": "missing_reference_value_cache",
            }));
        }
    }

    json!({
        "diagnostic_only": true,
        "claim_allowed": false,
        "boundary": "expanded_for_value_mix",
        "rust_stage_prefix": rust_stage_prefix,
        "reference_head_count": reference_cache_heads.len(),
        "rust_head_count": rust_heads.len(),
        "group_size": group_size,
        "compared_head_count": compared_head_count,
        "missing_head_count": missing_head_count,
        "total_f16_bucket_mismatch_count": total_bucket_mismatch_count,
        "max_head_f16_bucket_mismatch_count": max_bucket_mismatch_count,
        "max_abs_delta": max_abs_delta,
        "max_rms_delta": max_rms_delta,
        "all_compared": !rust_heads.is_empty() && missing_head_count == 0,
        "rows": rows,
    })
}

fn value_cache_dim_major_delta(reference: &ReferenceTraceRecord, rust: &RustTraceRecord) -> Value {
    let dim_count = reference.shape.first().and_then(|dim| usize::try_from(*dim).ok());
    let token_count = reference.shape.get(1).and_then(|dim| usize::try_from(*dim).ok());
    match (dim_count, token_count) {
        (Some(dim_count), Some(token_count)) if dim_count > 0 && token_count > 0 => {
            f16_bucket_delta_dim_major(
                &reference.first_values,
                &rust.first_values,
                dim_count,
                token_count,
            )
        }
        _ => f16_bucket_delta(&reference.first_values, &rust.first_values),
    }
}

fn head_lane_best_matches(
    reference_records: &[ReferenceTraceRecord],
    rust_records: &BTreeMap<String, RustTraceRecord>,
    reference_prefix: &str,
    rust_prefix: &str,
    policy: &str,
) -> Value {
    let reference_heads = reference_records
        .iter()
        .filter_map(|record| {
            parse_current_stage_head(&record.stage, reference_prefix).map(|head| (head, record))
        })
        .filter(|(_, record)| record.values_available && !record.first_values.is_empty())
        .collect::<BTreeMap<_, _>>();
    let rust_heads = rust_records
        .iter()
        .filter_map(|(stage, record)| {
            parse_current_stage_head(stage, rust_prefix).map(|head| (head, record))
        })
        .filter(|(_, record)| !record.first_values.is_empty())
        .collect::<BTreeMap<_, _>>();

    let mut rows = Vec::new();
    let mut identity_best_count = 0usize;
    let mut non_identity_best_count = 0usize;
    let mut missing_identity_count = 0usize;

    for (&reference_head, reference) in &reference_heads {
        let mut candidates = rust_heads
            .iter()
            .map(|(rust_head, rust)| {
                head_lane_delta(
                    reference_head,
                    *rust_head,
                    &reference.first_values,
                    &rust.first_values,
                )
            })
            .collect::<Vec<_>>();
        candidates.sort_by(head_lane_delta_order);

        let best = candidates.first().copied();
        let identity =
            candidates.iter().copied().find(|candidate| candidate.rust_head == reference_head);
        let identity_rank = identity.and_then(|identity| {
            candidates.iter().position(|candidate| {
                candidate.rust_head == identity.rust_head
                    && candidate.reference_head == identity.reference_head
            })
        });

        if let Some(best) = best {
            if best.rust_head == reference_head {
                identity_best_count += 1;
            } else {
                non_identity_best_count += 1;
            }
        }
        if identity.is_none() {
            missing_identity_count += 1;
        }

        rows.push(json!({
            "reference_head": reference_head,
            "best_rust_head": best.map(|best| best.rust_head),
            "identity_rust_head": reference_head,
            "identity_is_best": best.is_some_and(|best| best.rust_head == reference_head),
            "identity_rank": identity_rank.map(|rank| rank + 1),
            "best_delta": best.map(head_lane_delta_summary),
            "identity_delta": identity.map(head_lane_delta_summary),
            "candidate_count": candidates.len(),
        }));
    }

    json!({
        "diagnostic_only": true,
        "claim_allowed": false,
        "policy": policy,
        "reference_stage_prefix": reference_prefix,
        "rust_stage_prefix": rust_prefix,
        "reference_head_count": reference_heads.len(),
        "rust_head_count": rust_heads.len(),
        "identity_best_count": identity_best_count,
        "non_identity_best_count": non_identity_best_count,
        "missing_identity_count": missing_identity_count,
        "all_identity_best": !reference_heads.is_empty()
            && reference_heads.len() == identity_best_count
            && missing_identity_count == 0,
        "rows": rows,
    })
}

fn parse_stage_head(stage: &str, prefix: &str) -> Option<usize> {
    let suffix = stage.strip_prefix(prefix)?;
    let digit_count = suffix.chars().take_while(|ch| ch.is_ascii_digit()).count();
    if digit_count == 0 {
        return None;
    }
    let rest = &suffix[digit_count..];
    if !rest.is_empty() && !rest.starts_with('_') {
        return None;
    }
    suffix[..digit_count].parse::<usize>().ok()
}

fn parse_current_stage_head(stage: &str, prefix: &str) -> Option<usize> {
    if stage.ends_with("_history_ref_layout") {
        return None;
    }
    parse_stage_head(stage, prefix)
}

fn parse_exact_stage_head(stage: &str, prefix: &str) -> Option<usize> {
    let suffix = stage.strip_prefix(prefix)?;
    if suffix.is_empty() || !suffix.chars().all(|ch| ch.is_ascii_digit()) {
        return None;
    }
    suffix.parse::<usize>().ok()
}

fn head_lane_delta(
    reference_head: usize,
    rust_head: usize,
    reference: &[f32],
    rust: &[f32],
) -> HeadLaneDelta {
    let compared_count = reference.len().min(rust.len());
    let mut max_abs_delta = 0.0f64;
    let mut sum_sq_delta = 0.0f64;
    for i in 0..compared_count {
        let delta = (reference[i] as f64 - rust[i] as f64).abs();
        max_abs_delta = max_abs_delta.max(delta);
        sum_sq_delta += delta * delta;
    }
    HeadLaneDelta {
        reference_head,
        rust_head,
        compared_count,
        max_abs_delta,
        rms_abs_delta: if compared_count == 0 {
            f64::INFINITY
        } else {
            (sum_sq_delta / compared_count as f64).sqrt()
        },
    }
}

fn head_lane_delta_order(left: &HeadLaneDelta, right: &HeadLaneDelta) -> std::cmp::Ordering {
    left.rms_abs_delta
        .total_cmp(&right.rms_abs_delta)
        .then_with(|| left.max_abs_delta.total_cmp(&right.max_abs_delta))
        .then_with(|| left.rust_head.cmp(&right.rust_head))
}

fn head_lane_delta_summary(delta: HeadLaneDelta) -> Value {
    json!({
        "reference_head": delta.reference_head,
        "rust_head": delta.rust_head,
        "compared_count": delta.compared_count,
        "max_abs_delta": delta.max_abs_delta,
        "rms_abs_delta": delta.rms_abs_delta,
    })
}

fn trace_scope_mismatch(
    reference: Option<&ReferenceTraceRecord>,
    rust: Option<&RustTraceRecord>,
) -> Option<Value> {
    let reference = reference?;
    let rust = rust?;
    if let Some(scope) = reference_key_cache_head0_scope(reference, rust)
        .or_else(|| reference_key_cache_kv_live_scope(reference, rust))
        .or_else(|| reference_value_cache_head0_scope(reference, rust))
        .or_else(|| reference_value_cache_kv_live_scope(reference, rust))
        .or_else(|| reference_value_mix_merged_scope(reference, rust))
    {
        return Some(scope);
    }
    let reference_sampled_token_index = reference_sampled_token_index(reference)?;
    let rust_seq = rust.seq.map(|seq| seq as u64);
    if rust_seq == Some(reference_sampled_token_index) {
        return attention_row_padded_tail_scope(reference, rust);
    }
    Some(json!({
        "reason": "reference_sampled_prompt_token_does_not_match_rust_trace_seq",
        "reference_sampled_token_index": reference_sampled_token_index,
        "reference_sample_offset": reference.sample_offset,
        "reference_token_axis": reference.token_axis,
        "rust_seq": rust_seq,
        "policy": "stage summaries with mismatched trace scope are diagnostic alignment blockers, not stable numeric divergence evidence",
    }))
}

fn reference_key_cache_head0_scope(
    reference: &ReferenceTraceRecord,
    rust: &RustTraceRecord,
) -> Option<Value> {
    if reference.stage != "k"
        || rust.stage.as_deref() != Some("attention_k_cache_head0_ref_layout_padded")
    {
        return None;
    }
    let reference_nelements = usize::try_from(reference.nelements).ok()?;
    let rust_nelements = rust.num_elements;
    let reference_values_unavailable =
        !reference.values_available || reference.first_values.is_empty();
    let reference_contains_all_kv_heads = reference_nelements > rust_nelements;
    if !reference_values_unavailable && !reference_contains_all_kv_heads {
        return None;
    }
    let reason = if reference_values_unavailable {
        "reference_key_cache_values_unavailable_for_numeric_compare"
    } else {
        "reference_key_cache_contains_all_kv_heads_rust_trace_samples_head0_reference_layout"
    };
    Some(json!({
        "reason": reason,
        "reference_nelements": reference.nelements,
        "rust_num_elements": rust.num_elements,
        "reference_values_available": reference.values_available,
        "reference_first_values_count": reference.first_values.len(),
        "compared_head0_prefix_count": rust.num_elements,
        "reference_sampled_token_index": reference_sampled_token_index(reference),
        "reference_sample_offset": reference.sample_offset,
        "reference_token_axis": reference.token_axis,
        "rust_seq": rust.seq,
        "policy": "reference cached-key tensors include all KV heads; the Rust diagnostic samples head0 in reference padded layout, so prefix deltas are layout-scope evidence, not full-cache equality claims",
    }))
}

fn reference_key_cache_kv_live_scope(
    reference: &ReferenceTraceRecord,
    rust: &RustTraceRecord,
) -> Option<Value> {
    parse_stage_head(&reference.stage, "k_kv_head")?;
    let rust_stage = rust.stage.as_deref()?;
    parse_stage_head(rust_stage, "attention_k_cache_kv_head")?;
    Some(json!({
        "reason": "reference_key_cache_live_head_token_major_not_direct_rust_dim_major_layout",
        "reference_stage": reference.stage,
        "rust_stage": rust_stage,
        "reference_shape": reference.shape,
        "rust_shape": rust.shape,
        "reference_nelements": reference.nelements,
        "rust_num_elements": rust.num_elements,
        "reference_dtype": reference.dtype,
        "rust_dtype": rust.dtype,
        "reference_values_available": reference.values_available,
        "reference_first_values_count": reference.first_values.len(),
        "rust_first_values_count": rust.first_values.len(),
        "policy": "reference key-cache live KV heads emit token-major samples while Rust diagnostic key-cache records use dim-major [head_dim, tokens] order; use attention_key_cache_dim_major_f16_roundtrip_best_matches for material evidence",
    }))
}

fn reference_value_cache_head0_scope(
    reference: &ReferenceTraceRecord,
    rust: &RustTraceRecord,
) -> Option<Value> {
    if reference.stage != "v"
        || rust.stage.as_deref() != Some("attention_v_cache_head0_ref_layout_padded")
    {
        return None;
    }
    let reference_nelements = usize::try_from(reference.nelements).ok()?;
    let rust_nelements = usize::try_from(rust.num_elements).ok()?;
    let reference_values_unavailable =
        !reference.values_available || reference.first_values.is_empty();
    let reference_contains_all_kv_heads = reference_nelements > rust_nelements;
    if !reference_values_unavailable && !reference_contains_all_kv_heads {
        return None;
    }
    let reason = if reference_values_unavailable {
        "reference_value_cache_values_unavailable_for_numeric_compare"
    } else {
        "reference_value_cache_contains_all_kv_heads_rust_trace_samples_head0_reference_layout"
    };
    Some(json!({
        "reason": reason,
        "reference_nelements": reference.nelements,
        "rust_num_elements": rust.num_elements,
        "reference_values_available": reference.values_available,
        "reference_first_values_count": reference.first_values.len(),
        "compared_head0_prefix_count": rust.num_elements,
        "reference_sampled_token_index": reference_sampled_token_index(reference),
        "reference_sample_offset": reference.sample_offset,
        "reference_token_axis": reference.token_axis,
        "rust_seq": rust.seq,
        "policy": "reference cached-value tensors include all KV heads; the Rust diagnostic samples head0 in reference key-padded layout, so prefix deltas are head0 evidence but not full-cache equality claims",
    }))
}

fn reference_value_cache_kv_live_scope(
    reference: &ReferenceTraceRecord,
    rust: &RustTraceRecord,
) -> Option<Value> {
    parse_stage_head(&reference.stage, "v_kv_head")?;
    let rust_stage = rust.stage.as_deref()?;
    parse_stage_head(rust_stage, "attention_v_cache_kv_head")?;
    let reference_shape0 = reference.shape.first().copied();
    let rust_shape0 = rust.shape.first().copied().map(|dim| dim as i64);
    let element_count_match = reference.nelements == rust.num_elements as u64;
    let head_dim_match =
        reference_shape0.is_some() && rust_shape0.is_some() && reference_shape0 == rust_shape0;
    if element_count_match && head_dim_match {
        return None;
    }
    Some(json!({
        "reason": "reference_value_cache_live_head_layout_not_direct_rust_kv_head_layout",
        "reference_stage": reference.stage,
        "rust_stage": rust_stage,
        "reference_shape": reference.shape,
        "rust_shape": rust.shape,
        "reference_nelements": reference.nelements,
        "rust_num_elements": rust.num_elements,
        "reference_dtype": reference.dtype,
        "rust_dtype": rust.dtype,
        "reference_values_available": reference.values_available,
        "reference_first_values_count": reference.first_values.len(),
        "rust_first_values_count": rust.first_values.len(),
        "policy": "reference value-cache live KV heads use the llama.cpp cache representation and are diagnostic layout evidence, not direct Rust KV-head numeric parity evidence until the value-cache layout transform is named",
    }))
}

fn reference_value_mix_merged_scope(
    reference: &ReferenceTraceRecord,
    rust: &RustTraceRecord,
) -> Option<Value> {
    if reference.stage != "kqv_merged"
        || rust.stage.as_deref() != Some("attention_value_mix_merged")
    {
        return None;
    }
    let reference_nelements = usize::try_from(reference.nelements).ok()?;
    let rust_nelements = usize::try_from(rust.num_elements).ok()?;
    let reference_values_unavailable =
        !reference.values_available || reference.first_values.is_empty();
    let reference_contains_all_tokens = reference_nelements > rust_nelements;
    if !reference_values_unavailable && !reference_contains_all_tokens {
        return None;
    }
    Some(json!({
        "reason": "reference_value_mix_merged_noncontiguous_all_tokens_scope_not_direct_numeric_compare",
        "reference_nelements": reference.nelements,
        "rust_num_elements": rust.num_elements,
        "reference_values_available": reference.values_available,
        "reference_first_values_count": reference.first_values.len(),
        "reference_sampled_token_index": reference_sampled_token_index(reference),
        "reference_sample_offset": reference.sample_offset,
        "reference_token_axis": reference.token_axis,
        "rust_seq": rust.seq,
        "policy": "reference kqv_merged is a non-contiguous all-token/all-head view in this trace; compare the contiguous attn_value_mix record against Rust attention_value_mix_merged for material evidence",
    }))
}

fn attention_row_padded_tail_scope(
    reference: &ReferenceTraceRecord,
    rust: &RustTraceRecord,
) -> Option<Value> {
    if !is_attention_row_stage(&reference.stage) {
        return None;
    }
    let reference_nelements = usize::try_from(reference.nelements).ok()?;
    let rust_nelements = usize::try_from(rust.num_elements).ok()?;
    if reference_nelements <= rust_nelements || reference.first_values.len() <= rust_nelements {
        return None;
    }
    let tail = &reference.first_values[rust_nelements..];
    if tail.iter().any(|value| value.abs() > 1.0e-12) {
        return None;
    }
    Some(json!({
        "reason": "reference_attention_row_includes_padded_zero_tail_not_emitted_by_rust",
        "reference_nelements": reference.nelements,
        "rust_num_elements": rust.num_elements,
        "compared_live_prefix_count": rust.num_elements,
        "reference_zero_tail_count": reference_nelements.saturating_sub(rust_nelements),
        "reference_sampled_zero_tail_count": tail.len(),
        "reference_sampled_token_index": reference_sampled_token_index(reference),
        "reference_sample_offset": reference.sample_offset,
        "reference_token_axis": reference.token_axis,
        "rust_seq": rust.seq,
        "policy": "attention score/probability row summaries with reference KV-cache padding are diagnostic scope differences; live-prefix deltas remain useful evidence",
    }))
}

fn is_attention_row_stage(stage: &str) -> bool {
    stage == "kq"
        || stage == "kq_soft_max_ext"
        || parse_stage_head(stage, "kq_head").is_some()
        || parse_stage_head(stage, "kq_soft_max_ext_head").is_some()
}

fn reference_sampled_token_index(record: &ReferenceTraceRecord) -> Option<u64> {
    let axis = record.token_axis?;
    if axis < 0 {
        return None;
    }
    let axis = usize::try_from(axis).ok()?;
    let shape = if record.full_shape.is_empty() { &record.shape } else { &record.full_shape };
    if axis >= shape.len() {
        return None;
    }
    let offset = record.sample_offset?;
    let stride = shape.iter().take(axis).try_fold(1u64, |acc, dim| {
        let dim = u64::try_from(*dim).ok()?;
        acc.checked_mul(dim)
    })?;
    if stride == 0 || offset % stride != 0 {
        return None;
    }
    let axis_dim = u64::try_from(shape[axis]).ok()?;
    if axis_dim == 0 {
        return None;
    }
    Some((offset / stride) % axis_dim)
}

fn reference_record_summary(record: &ReferenceTraceRecord) -> Value {
    json!({
        "name": record.name,
        "stage": record.stage,
        "graph_index": record.graph_index,
        "layer": record.layer,
        "graph_op": record.graph_op,
        "graph_sources": record.graph_sources,
        "view_source": record.view_source,
        "view_offset": record.view_offset,
        "full_shape": record.full_shape,
        "sample_offset": record.sample_offset,
        "token_axis": record.token_axis,
        "sampled_token_index": reference_sampled_token_index(record),
        "shape": record.shape,
        "dtype": record.dtype,
        "nelements": record.nelements,
        "rms": record.rms,
        "first_values": record.first_values,
        "values_available": record.values_available,
    })
}

fn rust_record_summary(record: &RustTraceRecord) -> Value {
    json!({
        "name": record.name,
        "stage": record.stage,
        "seq": record.seq,
        "layer": record.layer,
        "shape": record.shape,
        "dtype": record.dtype,
        "num_elements": record.num_elements,
        "rms": record.rms,
        "first_values": record.first_values,
    })
}

fn build_plan(args: &LayerTracePlanArgs) -> Result<Value> {
    let cpp_root = normalize_path(&args.cpp_root)?;
    let rust_transformer_path = normalize_path(&args.rust_transformer)?;
    let llama_cpp = read_source(cpp_root.join("src/llama.cpp"));
    let rust_transformer = read_source(rust_transformer_path);
    let reference_anchors = anchor_status(&llama_cpp.text, REFERENCE_REQUIRED_ANCHORS);
    let rust_anchors = anchor_status(&rust_transformer.text, RUST_REQUIRED_ANCHORS);

    let mut blocked_reasons = Vec::<String>::new();
    if !cpp_root.is_dir() {
        blocked_reasons.push("reference_llama_cpp_root_missing".to_string());
    }
    for source in [&llama_cpp, &rust_transformer] {
        if !source.exists {
            blocked_reasons.push(format!("source_missing:{}", path_to_string(&source.path)));
        } else if !source.read_ok {
            blocked_reasons.push(format!("source_read_failed:{}", path_to_string(&source.path)));
        }
    }
    for anchor in missing_anchor_names(&reference_anchors) {
        blocked_reasons.push(format!("reference_anchor_missing:{anchor}"));
    }
    for anchor in missing_anchor_names(&rust_anchors) {
        blocked_reasons.push(format!("rust_trace_anchor_missing:{anchor}"));
    }
    blocked_reasons.push("reference_layer_trace_patch_not_applied".to_string());
    blocked_reasons.sort_unstable();
    blocked_reasons.dedup();

    let source_anchors_ready =
        blocked_reasons.iter().all(|reason| reason == "reference_layer_trace_patch_not_applied");

    let mut stage_mapping = vec![
        json!({"reference": "inp_embd", "rust": "embeddings", "scope": "prompt embedding"}),
        json!({"reference": "attn_norm", "rust": "attn_norm", "scope": "layer0"}),
        json!({"reference": "Qcur", "rust": "attention_q", "scope": "layer0"}),
        json!({"reference": "Kcur", "rust": "attention_k", "scope": "layer0"}),
        json!({"reference": "Vcur", "rust": "attention_v", "scope": "layer0"}),
        json!({"reference": "kq", "rust": "attention_scores_raw_head0", "scope": "layer0 head0 sampled-query scores before scale/mask"}),
        json!({"reference": "kq_soft_max_ext", "rust": "attn_scores_softmax_head0", "scope": "layer0 head0 sampled-query probabilities"}),
        json!({"reference": "k", "rust": "attention_k_cache_head0_ref_layout_padded", "scope": "layer0 head0 cached key matrix in reference padded layout"}),
        json!({"reference": "v", "rust": "attention_v_cache_head0_ref_layout_padded", "scope": "layer0 head0 cached value matrix in reference padded layout"}),
        json!({"reference": "kqv", "rust": "attention_value_mix_head0", "scope": "layer0 head0 value-mix output before head merge"}),
    ];
    for head in 0..20 {
        stage_mapping.push(json!({
            "reference": format!("kq_head{head}"),
            "rust": format!("attention_scores_raw_head{head}"),
            "scope": format!("layer0 sampled-query score row head{head}"),
        }));
    }
    for head in 0..20 {
        stage_mapping.push(json!({
            "reference": format!("kq_soft_max_ext_head{head}"),
            "rust": format!("attn_scores_softmax_head{head}"),
            "scope": format!("layer0 sampled-query probability row head{head}"),
        }));
    }
    for kv_head in 0..5 {
        stage_mapping.push(json!({
            "reference": format!("k_kv_head{kv_head}_live"),
            "rust": format!("attention_k_cache_kv_head{kv_head}_live_ref_layout"),
            "scope": format!("layer0 live key-cache matrix KV head{kv_head} in reference layout"),
        }));
    }
    for kv_head in 0..5 {
        stage_mapping.push(json!({
            "reference": format!("v_kv_head{kv_head}_live"),
            "rust": format!("attention_v_cache_kv_head{kv_head}_live_ref_layout"),
            "scope": format!("layer0 live value-cache matrix KV head{kv_head} in reference layout"),
        }));
    }
    for kv_head in 0..5 {
        stage_mapping.push(json!({
            "reference": format!("v_cache_rust_layout_head{kv_head}_live"),
            "rust": format!("attention_v_cache_f16_roundtrip_kv_head{kv_head}_live_ref_layout"),
            "scope": format!("layer0 live value-cache matrix KV head{kv_head} transposed into Rust diagnostic layout after Rust F16 roundtrip"),
        }));
    }
    for head in 0..20 {
        stage_mapping.push(json!({
            "reference": format!("kqv_head{head}"),
            "rust": format!("attention_value_mix_head{head}"),
            "scope": format!("layer0 value-mix sampled token head{head}"),
        }));
    }
    for head in 0..20 {
        stage_mapping.push(json!({
            "reference": format!("kqv_head{head}_history_ref_layout"),
            "rust": format!("attention_value_mix_head{head}_history_ref_layout"),
            "scope": format!("layer0 full-prefix value-mix history head{head}"),
        }));
    }
    stage_mapping.extend([
        json!({"reference": "kqv_merged", "rust": "attention_value_mix_merged", "scope": "layer0 non-contiguous all-token value-mix merge view"}),
        json!({"reference": "attn_value_mix", "rust": "attention_value_mix_merged", "scope": "layer0 contiguous merged value-mix before subnorm"}),
        json!({"reference": "attn_sub_norm", "rust": "post_attention_subnorm", "scope": "layer0"}),
        json!({"reference": "attn_o_out", "rust": "post_o_proj", "scope": "layer0"}),
        json!({"reference": "ffn_inp", "rust": "post_attention_residual", "scope": "layer0"}),
        json!({"reference": "attn_value_mix_history_ref_layout", "rust": "attention_value_mix_merged_history_ref_layout", "scope": "layer0 full-prefix merged value-mix history"}),
        json!({"reference": "attn_sub_norm_history_ref_layout", "rust": "post_attention_subnorm_history_ref_layout", "scope": "layer0 full-prefix attention subnorm history"}),
        json!({"reference": "attn_o_out_history_ref_layout", "rust": "post_o_proj_history_ref_layout", "scope": "layer0 full-prefix attention output projection history"}),
        json!({"reference": "ffn_norm", "rust": "post_ffn_norm", "scope": "layer0"}),
        json!({"reference": "ffn_up", "rust": "post_ffn_up_proj", "scope": "layer0"}),
        json!({"reference": "ffn_gate", "rust": "post_ffn_gate_proj", "scope": "layer0"}),
        json!({"reference": "ffn_sqr(relu)", "rust": "post_ffn_gate_activation", "scope": "layer0"}),
        json!({"reference": "ffn_gate_par", "rust": "post_swiglu", "scope": "layer0"}),
        json!({"reference": "ffn_out", "rust": "post_swiglu", "scope": "layer0"}),
        json!({"reference": "ffn_sub_norm", "rust": "post_ffn_subnorm", "scope": "layer0"}),
        json!({"reference": "ffn_down", "rust": "post_down_proj", "scope": "layer0"}),
        json!({"reference": "l_out", "rust": "post_layer", "scope": "layer0"}),
        json!({"reference": "attn_norm_history_ref_layout", "rust": "attention_v_input_history_ref_layout", "scope": "layer0 full-prefix attention norm output history"}),
        json!({"reference": "ffn_inp_history_ref_layout", "rust": "post_attention_residual_history_ref_layout", "scope": "layer0 full-prefix attention residual history"}),
        json!({"reference": "ffn_norm_history_ref_layout", "rust": "post_ffn_norm_history_ref_layout", "scope": "layer0 full-prefix FFN norm output history"}),
        json!({"reference": "ffn_up_history_ref_layout", "rust": "post_ffn_up_proj_history_ref_layout", "scope": "layer0 full-prefix FFN up projection history"}),
        json!({"reference": "ffn_gate_history_ref_layout", "rust": "post_ffn_gate_proj_history_ref_layout", "scope": "layer0 full-prefix FFN gate projection history"}),
        json!({"reference": "ffn_relu_sqr_history_ref_layout", "rust": "post_ffn_gate_activation_history_ref_layout", "scope": "layer0 full-prefix FFN ReLU squared activation history"}),
        json!({"reference": "ffn_gate_par_history_ref_layout", "rust": "post_swiglu_history_ref_layout", "scope": "layer0 full-prefix FFN parallel product history"}),
        json!({"reference": "ffn_out_history_ref_layout", "rust": "post_swiglu_history_ref_layout", "scope": "layer0 full-prefix FFN SwiGLU output history"}),
        json!({"reference": "ffn_sub_norm_history_ref_layout", "rust": "post_ffn_subnorm_history_ref_layout", "scope": "layer0 full-prefix FFN subnorm output history"}),
        json!({"reference": "ffn_down_history_ref_layout", "rust": "post_down_proj_history_ref_layout", "scope": "layer0 full-prefix FFN down projection history"}),
        json!({"reference": "l_out_history_ref_layout", "rust": "post_layer_history_ref_layout", "scope": "layer0 full-prefix layer output history"}),
        json!({"reference": "result_norm", "rust": "final_norm", "scope": "final token"}),
        json!({"reference": "result_output", "rust": "logits", "scope": "final token"}),
    ]);

    Ok(json!({
        "schema_version": 1,
        "diagnostic": "bitnet_reference_layer_trace_plan",
        "diagnostic_only": true,
        "promotion_allowed": false,
        "claim_allowed": false,
        "classification": "diagnostic_only",
        "producer": "cargo xtask bitnet-reference-layer-trace-plan",
        "created_at": chrono::Utc::now().to_rfc3339(),
        "inputs": {
            "cpp_root": path_to_string(&cpp_root),
            "llama_cpp": source_receipt(&llama_cpp),
            "rust_transformer": source_receipt(&rust_transformer),
        },
        "source_capability": {
            "reference_graph_callback_labels": reference_anchors,
            "rust_trace_labels": rust_anchors,
            "source_anchors_ready_for_target_local_patch": source_anchors_ready,
            "reason": "reference llama.cpp names the BitNet b1.58 graph stages through llm_build_cb while Rust already exposes comparable layer-0 trace labels behind the trace feature",
        },
        "stage_mapping": stage_mapping,
        "instrumentation_plan": {
            "target_local_only": true,
            "target_files": [
                "target/external/BitNet-reference/3rdparty/llama.cpp/src/llama.cpp"
            ],
            "environment_variable": "BITNET_RS_REFERENCE_LAYER_TRACE",
            "receipt_type_when_applied": "bitnet_reference_layer_trace",
            "captures": [
                "prompt identity inherited from matched reference plan",
                "BitNet b1.58 stage name",
                "layer index",
                "shape",
                "dtype",
                "rms",
                "vector hash when a CPU-readable tensor buffer is available",
                "first-values sample when safe to extract"
            ],
            "next_action": "add a target-local reference graph-callback instrumentation patch, run the matched prompt, and compare stage mapping against Rust trace output before changing Rust model math",
            "not_claim": "layer trace localizes first numeric divergence only; it does not prove semantic quality, A770 support, or residency",
        },
        "decision": {
            "reference_layer_trace_available": false,
            "source_anchors_ready_for_target_local_patch": source_anchors_ready,
            "current_blocked_reasons": blocked_reasons,
            "next_action": "add target-local reference layer trace instrumentation, then compare reference trace stages against Rust CPU and strict A770 traces",
        },
        "not_claims": CRITICAL_NOT_CLAIMS,
    }))
}

fn anchor_status(text: &str, anchors: &[(&str, &str)]) -> Vec<Value> {
    anchors
        .iter()
        .map(|(name, needle)| {
            json!({
                "name": name,
                "needle": needle,
                "present": text.contains(needle),
            })
        })
        .collect()
}

fn missing_anchor_names(anchors: &[Value]) -> Vec<String> {
    anchors
        .iter()
        .filter(|anchor| anchor.pointer("/present").and_then(Value::as_bool) != Some(true))
        .filter_map(|anchor| anchor.pointer("/name").and_then(Value::as_str).map(str::to_string))
        .collect()
}

fn read_source(path: PathBuf) -> SourceText {
    let exists = path.is_file();
    let read = fs::read(&path);
    let read_ok = read.is_ok();
    let bytes = read.unwrap_or_default();
    let sha256 = read_ok.then(|| sha256_bytes(&bytes));
    let text = String::from_utf8_lossy(&bytes).into_owned();
    SourceText { path, exists, read_ok, sha256, text }
}

fn source_receipt(source: &SourceText) -> Value {
    json!({
        "path": path_to_string(&source.path),
        "exists": source.exists,
        "read_ok": source.read_ok,
        "sha256": source.sha256,
    })
}

fn read_json(path: &Path) -> Result<Value> {
    let text = fs::read_to_string(path).with_context(|| format!("reading {}", path.display()))?;
    serde_json::from_str(&text).with_context(|| format!("parsing {}", path.display()))
}

fn read_jsonl_values(path: &Path) -> Result<Vec<Value>> {
    let text = fs::read_to_string(path).with_context(|| format!("reading {}", path.display()))?;
    text.lines()
        .enumerate()
        .filter(|(_, line)| !line.trim().is_empty())
        .map(|(index, line)| {
            serde_json::from_str(line)
                .with_context(|| format!("parsing {} line {}", path.display(), index + 1))
        })
        .collect()
}

fn reference_argv(plan: &Value) -> Result<Vec<String>> {
    plan.pointer("/reference/command_argv")
        .and_then(Value::as_array)
        .context("plan missing /reference/command_argv")?
        .iter()
        .map(|item| {
            item.as_str().map(ToOwned::to_owned).context("command_argv item is not a string")
        })
        .collect()
}

fn rust_command_argv(plan: &Value, key: &str) -> Result<Vec<String>> {
    let pointer = format!("/rust_commands/{key}");
    plan.pointer(&pointer)
        .and_then(Value::as_array)
        .with_context(|| format!("plan missing {pointer}"))?
        .iter()
        .map(|item| item.as_str().map(ToOwned::to_owned).context("rust argv item is not a string"))
        .collect()
}

fn preferred_rust_trace_argv(
    plan: &Value,
    preferred_key: &'static str,
    fallback_key: &'static str,
) -> (Option<Vec<String>>, Option<&'static str>) {
    if let Ok(argv) = rust_command_argv(plan, preferred_key) {
        return (Some(argv), Some(preferred_key));
    }
    match rust_command_argv(plan, fallback_key) {
        Ok(argv) => (Some(argv), Some(fallback_key)),
        Err(_) => (None, None),
    }
}

fn rust_trace_target_seq_from_plan(plan: &Value) -> Option<usize> {
    let token_count =
        plan.pointer("/prompt_identity/prompt_token_count").and_then(Value::as_u64)?;
    usize::try_from(token_count.checked_sub(1)?).ok()
}

fn ensure_trace_feature(argv: &[String]) -> (Vec<String>, bool) {
    let mut argv = argv.to_vec();
    let Some(features_index) = argv.iter().position(|arg| arg == "--features") else {
        argv.push("--features".to_string());
        argv.push("trace".to_string());
        return (argv, true);
    };
    let Some(features) = argv.get_mut(features_index + 1) else {
        argv.push("trace".to_string());
        return (argv, true);
    };
    let has_trace = features
        .split([',', ' '])
        .filter(|feature| !feature.trim().is_empty())
        .any(|feature| feature.trim() == "trace");
    if has_trace {
        return (argv, false);
    }
    if features.trim().is_empty() {
        *features = "trace".to_string();
    } else {
        features.push_str(",trace");
    }
    (argv, true)
}

fn apply_windows_reference_compatibility_fixes(reference_root: &Path) -> Result<Vec<Value>> {
    let mut applied = Vec::new();
    applied.push(replace_file_text(
        &reference_root.join("src/ggml-bitnet-mad.cpp"),
        "        int8_t * y_col = y + col * by;",
        "        const int8_t * y_col = y + col * by;",
        "windows_const_compatibility",
    )?);
    applied.push(insert_after_if_missing(
        &reference_root.join("3rdparty/llama.cpp/common/common.cpp"),
        "#include <ctime>",
        "#include <chrono>",
        "windows_common_chrono_include",
    )?);
    applied.push(insert_after_if_missing(
        &reference_root.join("3rdparty/llama.cpp/common/log.cpp"),
        "#include <condition_variable>",
        "#include <chrono>",
        "windows_log_chrono_include",
    )?);
    Ok(applied)
}

fn replace_file_text(path: &Path, before: &str, after: &str, fix_id: &str) -> Result<Value> {
    let content =
        fs::read_to_string(path).with_context(|| format!("reading {}", path.display()))?;
    if content.contains(before) {
        fs::write(path, content.replace(before, after))
            .with_context(|| format!("writing {}", path.display()))?;
        return Ok(json!({
            "fix_id": fix_id,
            "path": path_to_string(path),
            "applied": true,
            "already_present": false,
        }));
    }
    if content.contains(after) {
        return Ok(json!({
            "fix_id": fix_id,
            "path": path_to_string(path),
            "applied": false,
            "already_present": true,
        }));
    }
    bail!("expected compatibility fix target not found in {}", path.display())
}

fn insert_after_if_missing(path: &Path, anchor: &str, insert: &str, fix_id: &str) -> Result<Value> {
    let content =
        fs::read_to_string(path).with_context(|| format!("reading {}", path.display()))?;
    if content.contains(insert) {
        return Ok(json!({
            "fix_id": fix_id,
            "path": path_to_string(path),
            "applied": false,
            "already_present": true,
        }));
    }
    if !content.contains(anchor) {
        bail!("expected compatibility include anchor not found in {}", path.display());
    }
    fs::write(path, content.replace(anchor, &format!("{anchor}\n{insert}")))
        .with_context(|| format!("writing {}", path.display()))?;
    Ok(json!({
        "fix_id": fix_id,
        "path": path_to_string(path),
        "applied": true,
        "already_present": false,
    }))
}

fn run_reference_kernel_codegen(reference_root: &Path) -> Result<CommandCapture> {
    run_command(Command::new("python").current_dir(reference_root).args([
        "utils/codegen_tl2.py",
        "--model",
        "bitnet_b1_58-3B",
        "--BM",
        "160,320,320",
        "--BK",
        "96,96,96",
        "--bm",
        "32,32,32",
    ]))
}

fn build_reference_cli(reference_root: &Path, build_dir: &Path) -> Result<CommandCapture> {
    if cfg!(windows) {
        let vsdevcmd = find_vsdevcmd();
        let Some(vsdevcmd) = vsdevcmd else {
            return Ok(CommandCapture {
                status_code: None,
                success: false,
                stdout: String::new(),
                stderr: "Visual Studio developer command prompt not found".to_string(),
            });
        };
        let script = reference_root.join("build_bitnet_rs_layer_trace_reference.cmd");
        let lines = [
            "@echo off".to_string(),
            format!("call {} -arch=x64 -host_arch=x64 || exit /b 1", cmd_quote(&vsdevcmd)),
            format!(
                "cmake --build {} --config Release --target llama-cli || exit /b 1",
                cmd_quote(build_dir)
            ),
        ];
        fs::write(&script, lines.join("\r\n"))
            .with_context(|| format!("writing {}", script.display()))?;
        let capture =
            run_command(Command::new("cmd.exe").args(["/d", "/c"]).arg(path_to_string(&script)))?;
        let _ = fs::remove_file(&script);
        Ok(capture)
    } else {
        run_command(Command::new("cmake").args([
            "--build",
            &path_to_string(build_dir),
            "--config",
            "Release",
            "--target",
            "llama-cli",
        ]))
    }
}

fn find_vsdevcmd() -> Option<PathBuf> {
    let program_files_x86 = std::env::var_os("ProgramFiles(x86)")?;
    let vswhere =
        PathBuf::from(program_files_x86).join("Microsoft Visual Studio/Installer/vswhere.exe");
    if !vswhere.is_file() {
        return None;
    }
    let output = Command::new(vswhere)
        .args([
            "-latest",
            "-products",
            "*",
            "-requires",
            "Microsoft.VisualStudio.Component.VC.Tools.x86.x64",
            "-property",
            "installationPath",
        ])
        .stdin(Stdio::null())
        .output()
        .ok()?;
    if !output.status.success() {
        return None;
    }
    let path = String::from_utf8_lossy(&output.stdout).trim().to_string();
    if path.is_empty() {
        return None;
    }
    let vsdevcmd = PathBuf::from(path).join("Common7/Tools/VsDevCmd.bat");
    vsdevcmd.is_file().then_some(vsdevcmd)
}

fn run_reference_with_sidecar(
    argv: &[String],
    sidecar: &Path,
    trace_layer: Option<usize>,
    first_values_limit: Option<usize>,
    rope_scalar_trace: Option<&ReferenceRopeScalarTraceArgs>,
) -> Result<CommandCapture> {
    let executable = argv.first().context("empty reference command")?;
    let mut command = Command::new(executable);
    command.args(&argv[1..]).env("BITNET_RS_REFERENCE_LAYER_TRACE", sidecar).stdin(Stdio::null());
    if let Some(trace_layer) = trace_layer {
        command.env("BITNET_RS_REFERENCE_LAYER_TRACE_LAYER", trace_layer.to_string());
    }
    if let Some(first_values_limit) = first_values_limit {
        command.env(
            "BITNET_RS_REFERENCE_LAYER_TRACE_FIRST_VALUES_LIMIT",
            first_values_limit.to_string(),
        );
    }
    if let Some(rope_scalar_trace) = rope_scalar_trace {
        if let Some(parent) =
            rope_scalar_trace.path.parent().filter(|parent| !parent.as_os_str().is_empty())
        {
            fs::create_dir_all(parent).with_context(|| format!("creating {}", parent.display()))?;
        }
        if rope_scalar_trace.path.exists() {
            fs::remove_file(&rope_scalar_trace.path)
                .with_context(|| format!("removing stale {}", rope_scalar_trace.path.display()))?;
        }
        command
            .env("BITNET_RS_REFERENCE_ROPE_SCALAR_TRACE", &rope_scalar_trace.path)
            .env("BITNET_RS_REFERENCE_ROPE_SCALAR_TRACE_LAYER", rope_scalar_trace.layer.to_string())
            .env(
                "BITNET_RS_REFERENCE_ROPE_SCALAR_TRACE_KV_HEAD",
                rope_scalar_trace.kv_head.to_string(),
            )
            .env("BITNET_RS_REFERENCE_ROPE_SCALAR_TRACE_TOKEN", rope_scalar_trace.token.to_string())
            .env("BITNET_RS_REFERENCE_ROPE_SCALAR_TRACE_DIM", rope_scalar_trace.dim.to_string());
    }
    run_command(&mut command)
}

fn run_rust_trace_capture(
    label: &str,
    argv: &[String],
    trace_dir: &Path,
    trace_target_seq: Option<usize>,
    trace_layer: Option<usize>,
    first_values_limit: Option<usize>,
    diag_rmsnorm_f64_accum: bool,
) -> Result<Value> {
    let executable = argv.first().context("empty Rust trace command")?;
    let mut command = Command::new(executable);
    command
        .args(&argv[1..])
        .env("BITNET_TRACE_DIR", trace_dir)
        .env("BITNET_DETERMINISTIC", "1")
        .env("BITNET_SEED", "0")
        .stdin(Stdio::null());
    if diag_rmsnorm_f64_accum {
        command.env("BITNET_DIAG_RMSNORM_F64_ACCUM", "1");
    }
    if let Some(trace_target_seq) = trace_target_seq {
        command.env("BITNET_TRACE_TARGET_SEQ", trace_target_seq.to_string());
    }
    if let Some(trace_layer) = trace_layer {
        command.env("BITNET_TRACE_LAYER", trace_layer.to_string());
    }
    if let Some(first_values_limit) = first_values_limit {
        command.env("BITNET_TRACE_FIRST_VALUES_LIMIT", first_values_limit.to_string());
    }
    let capture = run_command(&mut command)?;
    let trace = summarize_rust_trace_dir(trace_dir);
    Ok(json!({
        "label": label,
        "attempted": true,
        "trace_dir": path_to_string(trace_dir),
        "trace_target_seq": trace_target_seq,
        "trace_target_source": trace_target_seq.map(|_| "prompt_identity.prompt_token_count_minus_one"),
        "trace_layer": trace_layer,
        "trace_layer_env": trace_layer.map(|layer| format!("BITNET_TRACE_LAYER={layer}")),
        "first_values_limit": first_values_limit,
        "first_values_limit_env": first_values_limit
            .map(|limit| format!("BITNET_TRACE_FIRST_VALUES_LIMIT={limit}")),
        "diag_rmsnorm_f64_accum": diag_rmsnorm_f64_accum,
        "diag_rmsnorm_f64_accum_env": diag_rmsnorm_f64_accum
            .then_some("BITNET_DIAG_RMSNORM_F64_ACCUM=1"),
        "argv": argv,
        "command": capture_json(Some(&capture)),
        "trace": trace,
    }))
}

fn skipped_rust_trace_capture(label: &str, argv: Option<&[String]>, trace_dir: &Path) -> Value {
    json!({
        "label": label,
        "attempted": false,
        "trace_dir": path_to_string(trace_dir),
        "argv": argv.unwrap_or(&[]),
        "command": Value::Null,
        "trace": summarize_rust_trace_dir(trace_dir),
    })
}

fn append_trace_capture_blockers(prefix: &str, capture: &Value, blocked_reasons: &mut Vec<String>) {
    if capture.pointer("/attempted").and_then(Value::as_bool) == Some(true)
        && capture.pointer("/command/success").and_then(Value::as_bool) != Some(true)
    {
        blocked_reasons.push(format!("{prefix}_trace_command_failed"));
    }
    if capture.pointer("/trace/record_count").and_then(Value::as_u64).unwrap_or(0) == 0 {
        blocked_reasons.push(format!("{prefix}_trace_dir_no_trace_files"));
    }
}

fn prepare_trace_dir(dir: &Path, overwrite: bool) -> Result<Value> {
    if dir.exists() && !dir.is_dir() {
        return Ok(json!({
            "trace_dir": path_to_string(dir),
            "ready": false,
            "blocked_reason": "path_is_not_directory",
        }));
    }
    fs::create_dir_all(dir).with_context(|| format!("creating {}", dir.display()))?;
    let entries = fs::read_dir(dir)
        .with_context(|| format!("reading {}", dir.display()))?
        .collect::<Result<Vec<_>, _>>()
        .with_context(|| format!("reading entries in {}", dir.display()))?;
    let mut removed_trace_files = Vec::<String>::new();
    let mut non_trace_entries = Vec::<String>::new();
    for entry in entries {
        let path = entry.path();
        if path.is_file() && path.extension().and_then(|ext| ext.to_str()) == Some("trace") {
            if overwrite {
                fs::remove_file(&path).with_context(|| format!("removing {}", path.display()))?;
                removed_trace_files.push(path_to_string(&path));
            }
        } else {
            non_trace_entries.push(path_to_string(&path));
        }
    }
    let trace_files_after = count_trace_files(dir)?;
    let blocked_reason = if !non_trace_entries.is_empty() {
        Some("contains_non_trace_entries")
    } else if trace_files_after > 0 && !overwrite {
        Some("contains_existing_trace_files")
    } else {
        None
    };
    Ok(json!({
        "trace_dir": path_to_string(dir),
        "ready": blocked_reason.is_none(),
        "overwrite": overwrite,
        "removed_trace_files": removed_trace_files,
        "existing_trace_files_after_prepare": trace_files_after,
        "non_trace_entries": non_trace_entries,
        "blocked_reason": blocked_reason,
    }))
}

fn summarize_rust_trace_dir(dir: &Path) -> Value {
    if !dir.exists() {
        return json!({
            "exists": false,
            "record_count": 0,
            "stages": [],
            "read_error": "trace_dir_missing",
        });
    }
    match read_rust_trace_dir(dir) {
        Ok(records) => json!({
            "exists": true,
            "record_count": records.len(),
            "stages": records
                .iter()
                .map(|(stage, record)| json!({
                    "stage": stage,
                    "name": record.name,
                    "layer": record.layer,
                    "shape": record.shape,
                    "dtype": record.dtype,
                    "num_elements": record.num_elements,
                    "rms": record.rms,
                }))
                .collect::<Vec<_>>(),
            "read_error": Value::Null,
        }),
        Err(error) => json!({
            "exists": dir.exists(),
            "record_count": 0,
            "stages": [],
            "read_error": error.to_string(),
        }),
    }
}

fn count_trace_files(dir: &Path) -> Result<usize> {
    if !dir.exists() {
        return Ok(0);
    }
    let mut count = 0usize;
    for entry in fs::read_dir(dir).with_context(|| format!("reading {}", dir.display()))? {
        let entry = entry.with_context(|| format!("reading entry in {}", dir.display()))?;
        let path = entry.path();
        if path.is_file() && path.extension().and_then(|ext| ext.to_str()) == Some("trace") {
            count += 1;
        }
    }
    Ok(count)
}

fn cleanup_reference_sources(
    reference_root: &Path,
    cpp_root: &Path,
    generated_lut_header: &Path,
    generated_lut_header_existed_before: bool,
    generated_kernel_config: &Path,
    generated_kernel_config_existed_before: bool,
) -> Result<CommandCapture> {
    let mut capture = run_git(reference_root, &["restore", "--", "src/ggml-bitnet-mad.cpp"])?;
    let cpp_capture = run_git(
        cpp_root,
        &[
            "restore",
            "--",
            "common/common.cpp",
            "common/log.cpp",
            "src/llama.cpp",
            "ggml/src/ggml.c",
        ],
    )?;
    if !generated_lut_header_existed_before && generated_lut_header.exists() {
        fs::remove_file(generated_lut_header)
            .with_context(|| format!("removing {}", generated_lut_header.display()))?;
    }
    if !generated_kernel_config_existed_before && generated_kernel_config.exists() {
        fs::remove_file(generated_kernel_config)
            .with_context(|| format!("removing {}", generated_kernel_config.display()))?;
    }
    capture.success = capture.success && cpp_capture.success;
    capture.status_code = if capture.status_code == Some(0) && cpp_capture.status_code == Some(0) {
        Some(0)
    } else {
        cpp_capture.status_code.or(capture.status_code)
    };
    if !cpp_capture.stdout.is_empty() {
        capture.stdout.push_str(&cpp_capture.stdout);
    }
    if !cpp_capture.stderr.is_empty() {
        capture.stderr.push_str(&cpp_capture.stderr);
    }
    Ok(capture)
}

fn run_command(command: &mut Command) -> Result<CommandCapture> {
    let output = command.output().with_context(|| format!("running command {:?}", command))?;
    Ok(CommandCapture {
        status_code: output.status.code(),
        success: output.status.success(),
        stdout: String::from_utf8_lossy(&output.stdout).to_string(),
        stderr: String::from_utf8_lossy(&output.stderr).to_string(),
    })
}

fn git_status(path: &Path) -> Option<CommandCapture> {
    path.is_dir().then(|| run_git(path, &["status", "--porcelain"]).ok()).flatten()
}

fn run_git(cwd: &Path, args: &[&str]) -> Result<CommandCapture> {
    let output = Command::new("git")
        .current_dir(cwd)
        .args(args)
        .stdin(Stdio::null())
        .output()
        .with_context(|| format!("running git {} in {}", args.join(" "), cwd.display()))?;
    Ok(CommandCapture {
        status_code: output.status.code(),
        success: output.status.success(),
        stdout: String::from_utf8_lossy(&output.stdout).to_string(),
        stderr: String::from_utf8_lossy(&output.stderr).to_string(),
    })
}

fn capture_success_empty(capture: &Option<CommandCapture>) -> bool {
    capture.as_ref().is_some_and(|capture| capture.success && capture.stdout.trim().is_empty())
}

fn capture_json(capture: Option<&CommandCapture>) -> Value {
    match capture {
        Some(capture) => json!({
            "success": capture.success,
            "exit_code": capture.status_code,
            "stdout": capture.stdout.trim(),
            "stderr": capture.stderr.trim(),
        }),
        None => Value::Null,
    }
}

fn exe_name(stem: &str) -> String {
    if cfg!(windows) { format!("{stem}.exe") } else { stem.to_string() }
}

fn cmd_quote(path: &Path) -> String {
    format!("\"{}\"", path_to_string(path).replace('"', "\"\""))
}

fn normalize_path(path: &Path) -> Result<PathBuf> {
    if path.exists() {
        path.canonicalize().with_context(|| format!("canonicalizing {}", path.display()))
    } else if path.is_absolute() {
        Ok(path.to_path_buf())
    } else {
        Ok(std::env::current_dir()?.join(path))
    }
}

fn sha256_bytes(bytes: &[u8]) -> String {
    let mut hasher = Sha256::new();
    hasher.update(bytes);
    format!("{:x}", hasher.finalize())
}

fn path_to_string(path: &Path) -> String {
    let path = path.to_string_lossy().replace('\\', "/");
    path.strip_prefix("//?/").unwrap_or(&path).to_string()
}

fn emit_report(report: &Value, format: &str) -> Result<()> {
    match format {
        "json" => println!("{}", serde_json::to_string_pretty(report)?),
        "human" => {
            let receipt_type = report
                .pointer("/receipt_type")
                .and_then(Value::as_str)
                .unwrap_or("bitnet_reference_layer_trace_plan");
            if receipt_type == "bitnet_reference_layer_trace_run" {
                let available = report
                    .pointer("/decision/reference_layer_trace_available")
                    .and_then(Value::as_bool)
                    .unwrap_or(false);
                let record_count =
                    report.pointer("/sidecar/record_count").and_then(Value::as_u64).unwrap_or(0);
                let reasons = report
                    .pointer("/decision/current_blocked_reasons")
                    .and_then(Value::as_array)
                    .cloned()
                    .unwrap_or_default();
                println!(
                    "bitnet reference layer trace run: diagnostic_only=true claim_allowed=false available={available} records={record_count}"
                );
                if !reasons.is_empty() {
                    println!("blocked_reasons:");
                    for reason in reasons {
                        println!("  - {}", reason.as_str().unwrap_or("<non-string>"));
                    }
                }
                return Ok(());
            }
            if receipt_type == "bitnet_reference_layer_trace_compare" {
                let first = report
                    .pointer("/cpu/first_material_mismatch/status")
                    .and_then(Value::as_str)
                    .unwrap_or("none");
                let stage = report
                    .pointer("/cpu/first_material_mismatch/reference_stage")
                    .and_then(Value::as_str)
                    .unwrap_or("none");
                let mismatches = report
                    .pointer("/cpu/material_mismatch_count")
                    .and_then(Value::as_u64)
                    .unwrap_or(0);
                let layer1_boundary = report
                    .pointer("/cpu/layer_1_operation_boundary_delta/first_material_stage/boundary")
                    .and_then(Value::as_str)
                    .unwrap_or("none");
                let layer1_status = report
                    .pointer("/cpu/layer_1_operation_boundary_delta/first_material_stage/status")
                    .and_then(Value::as_str)
                    .unwrap_or("none");
                println!(
                    "bitnet reference layer trace compare: diagnostic_only=true claim_allowed=false cpu_first_mismatch={stage}:{first} cpu_mismatches={mismatches} layer1_first_boundary={layer1_boundary}:{layer1_status}"
                );
                return Ok(());
            }
            if receipt_type == "bitnet_reference_layer_trace_rust_capture" {
                let ready = report
                    .pointer("/decision/compare_ready")
                    .and_then(Value::as_bool)
                    .unwrap_or(false);
                let cpu_records =
                    report.pointer("/cpu/trace/record_count").and_then(Value::as_u64).unwrap_or(0);
                let a770_records =
                    report.pointer("/a770/trace/record_count").and_then(Value::as_u64).unwrap_or(0);
                let reasons = report
                    .pointer("/decision/current_blocked_reasons")
                    .and_then(Value::as_array)
                    .cloned()
                    .unwrap_or_default();
                println!(
                    "bitnet reference layer trace rust capture: diagnostic_only=true claim_allowed=false compare_ready={ready} cpu_records={cpu_records} a770_records={a770_records}"
                );
                if !reasons.is_empty() {
                    println!("blocked_reasons:");
                    for reason in reasons {
                        println!("  - {}", reason.as_str().unwrap_or("<non-string>"));
                    }
                }
                return Ok(());
            }
            if receipt_type == "bitnet_reference_embedding_row_authority" {
                let ready = report
                    .pointer("/decision/embedding_row_authority_ready")
                    .and_then(Value::as_bool)
                    .unwrap_or(false);
                let ref_match = report
                    .pointer("/decision/reference_row_matches_trace_sample")
                    .and_then(Value::as_bool)
                    .unwrap_or(false);
                let rust_match = report
                    .pointer("/decision/rust_loaded_matches_reference_row")
                    .and_then(Value::as_bool)
                    .unwrap_or(false);
                let reasons = report
                    .pointer("/decision/current_blocked_reasons")
                    .and_then(Value::as_array)
                    .cloned()
                    .unwrap_or_default();
                println!(
                    "bitnet reference embedding row authority: diagnostic_only=true claim_allowed=false ready={ready} reference_trace_match={ref_match} rust_loaded_match={rust_match}"
                );
                if !reasons.is_empty() {
                    println!("blocked_reasons:");
                    for reason in reasons {
                        println!("  - {}", reason.as_str().unwrap_or("<non-string>"));
                    }
                }
                return Ok(());
            }
            if receipt_type == "bitnet_reference_attn_output_same_input_parity" {
                let available = report
                    .pointer("/decision/same_input_projection_available")
                    .and_then(Value::as_bool)
                    .unwrap_or(false);
                let matches = report
                    .pointer("/decision/same_input_projection_matches_reference")
                    .and_then(Value::as_bool)
                    .unwrap_or(false);
                let max_delta = report
                    .pointer("/projection/rust_same_input_vs_reference_target/max_abs_delta")
                    .and_then(Value::as_f64);
                let reasons = report
                    .pointer("/decision/current_blocked_reasons")
                    .and_then(Value::as_array)
                    .cloned()
                    .unwrap_or_default();
                println!(
                    "bitnet reference attn-output same-input parity: diagnostic_only=true claim_allowed=false available={available} matches_reference={matches} max_abs_delta={}",
                    max_delta.map(|value| value.to_string()).unwrap_or_else(|| "n/a".to_string())
                );
                if !reasons.is_empty() {
                    println!("blocked_reasons:");
                    for reason in reasons {
                        println!("  - {}", reason.as_str().unwrap_or("<non-string>"));
                    }
                }
                return Ok(());
            }
            if receipt_type == "bitnet_reference_attn_subnorm_replay" {
                let layer = report.pointer("/decision/selected_layer").and_then(Value::as_u64);
                let best_reference_delta =
                    report.pointer("/decision/best_reference_delta").and_then(Value::as_f64);
                let best_rust_delta =
                    report.pointer("/decision/best_rust_delta").and_then(Value::as_f64);
                let reasons = report
                    .pointer("/decision/current_blocked_reasons")
                    .and_then(Value::as_array)
                    .cloned()
                    .unwrap_or_default();
                println!(
                    "bitnet reference attn-subnorm replay: diagnostic_only=true claim_allowed=false layer={} best_reference_delta={} best_rust_delta={}",
                    layer.map(|value| value.to_string()).unwrap_or_else(|| "n/a".to_string()),
                    best_reference_delta
                        .map(|value| value.to_string())
                        .unwrap_or_else(|| "n/a".to_string()),
                    best_rust_delta
                        .map(|value| value.to_string())
                        .unwrap_or_else(|| "n/a".to_string())
                );
                if !reasons.is_empty() {
                    println!("blocked_reasons:");
                    for reason in reasons {
                        println!("  - {}", reason.as_str().unwrap_or("<non-string>"));
                    }
                }
                return Ok(());
            }
            if receipt_type == "bitnet_reference_ffn_norm_prefix_replay" {
                let layer = report.pointer("/decision/selected_layer").and_then(Value::as_u64);
                let token = report.pointer("/decision/token").and_then(Value::as_u64);
                let best_reference_delta =
                    report.pointer("/decision/best_reference_delta").and_then(Value::as_f64);
                let best_rust_delta =
                    report.pointer("/decision/best_rust_delta").and_then(Value::as_f64);
                let reasons = report
                    .pointer("/decision/current_blocked_reasons")
                    .and_then(Value::as_array)
                    .cloned()
                    .unwrap_or_default();
                println!(
                    "bitnet reference ffn-norm prefix replay: diagnostic_only=true claim_allowed=false layer={} token={} best_reference_delta={} best_rust_delta={}",
                    layer.map(|value| value.to_string()).unwrap_or_else(|| "n/a".to_string()),
                    token.map(|value| value.to_string()).unwrap_or_else(|| "n/a".to_string()),
                    best_reference_delta
                        .map(|value| value.to_string())
                        .unwrap_or_else(|| "n/a".to_string()),
                    best_rust_delta
                        .map(|value| value.to_string())
                        .unwrap_or_else(|| "n/a".to_string())
                );
                if !reasons.is_empty() {
                    println!("blocked_reasons:");
                    for reason in reasons {
                        println!("  - {}", reason.as_str().unwrap_or("<non-string>"));
                    }
                }
                return Ok(());
            }
            if receipt_type == "bitnet_reference_final_norm_replay" {
                let block_count = report.pointer("/model/block_count").and_then(Value::as_u64);
                let expected_final_layer =
                    report.pointer("/model/expected_final_layer").and_then(Value::as_u64);
                let best_reference_delta =
                    report.pointer("/decision/best_reference_delta").and_then(Value::as_f64);
                let best_rust_delta =
                    report.pointer("/decision/best_rust_delta").and_then(Value::as_f64);
                let reasons = report
                    .pointer("/decision/current_blocked_reasons")
                    .and_then(Value::as_array)
                    .cloned()
                    .unwrap_or_default();
                println!(
                    "bitnet reference final-norm replay: diagnostic_only=true claim_allowed=false block_count={} expected_final_layer={} best_reference_delta={} best_rust_delta={}",
                    block_count.map(|value| value.to_string()).unwrap_or_else(|| "n/a".to_string()),
                    expected_final_layer
                        .map(|value| value.to_string())
                        .unwrap_or_else(|| "n/a".to_string()),
                    best_reference_delta
                        .map(|value| value.to_string())
                        .unwrap_or_else(|| "n/a".to_string()),
                    best_rust_delta
                        .map(|value| value.to_string())
                        .unwrap_or_else(|| "n/a".to_string())
                );
                if !reasons.is_empty() {
                    println!("blocked_reasons:");
                    for reason in reasons {
                        println!("  - {}", reason.as_str().unwrap_or("<non-string>"));
                    }
                }
                return Ok(());
            }
            let ready = report
                .pointer("/decision/source_anchors_ready_for_target_local_patch")
                .and_then(Value::as_bool)
                .unwrap_or(false);
            let reasons = report
                .pointer("/decision/current_blocked_reasons")
                .and_then(Value::as_array)
                .cloned()
                .unwrap_or_default();
            println!(
                "bitnet reference layer trace plan: diagnostic_only=true claim_allowed=false source_anchors_ready={ready}"
            );
            if !reasons.is_empty() {
                println!("blocked_reasons:");
                for reason in reasons {
                    println!("  - {}", reason.as_str().unwrap_or("<non-string>"));
                }
            }
        }
        other => bail!("unsupported bitnet-reference-layer-trace-plan output format: {other}"),
    }
    Ok(())
}
